@app.route(
    '/api/events/<int:event_id>/workforce/transport/<booking_id>/company-invoice',
    methods=['POST', 'PUT'],
)
@require_admin
def update_transport_company_invoice(event_id, booking_id):
    if event_id not in data_manager.events:
        return jsonify({'error': 'Event not found'}), 404
    saved = None
    queued_record_id = ''
    data_folder = ''
    try:
        manager = _current_data_manager_object()
        data_folder = _workforce_folder(manager)
        with mutate_workforce(data_folder) as workforce:
            groups = transport_company_groups(event_bookings(workforce, event_id), workforce.get('transportVendors', []))
            group = next((group for group in groups if any(
                str(row.get('id')) == str(booking_id) for row in group['bookings']
            )), None)
            if not group:
                return jsonify({'error': 'Transport booking not found'}), 404
            if group['isFleet']:
                return jsonify({'error': 'Company invoices apply to external transport'}), 400
            owner = next(
                (row for row in group['bookings']
                 if transport_company_invoices(row)),
                group['bookings'][0],
            )
            if request.method == 'PUT':
                company_invoices = group.get('invoices', [])
                if not company_invoices:
                    return jsonify({'error': 'Upload the company invoice first'}), 400
                record = company_invoices[-1]
                amount = money((request.get_json(silent=True) or {}).get('amount'))
                if amount is None or amount < 0:
                    return jsonify({'error': 'Enter a valid invoice amount'}), 400
                record.update({'amount': amount, 'updatedAt': now_iso()})
            else:
                uploaded = request.files.get('file')
                if not uploaded or not uploaded.filename:
                    return jsonify({'error': 'Choose an invoice file'}), 400
                saved = save_upload(data_folder, uploaded, event_id,
                                    f'transport-company-{owner["id"]}', 'transport', allow_spreadsheets=True)
                record = {
                    **saved, 'id': new_id('transport_invoice'),
                    'submittedAt': now_iso(), 'amount': None,
                    'company': group['company'], 'scope': 'company',
                    'status': 'Pending Review', 'reviewHistory': [],
                    'processingState': 'Queued', 'submissionStage': 'Queued',
                }
                _set_transport_company_invoices(
                    owner, transport_company_invoices(owner) + [record]
                )
                queued_record_id = record['id']
            owner['updatedAt'] = now_iso()
        log_action(f'Added transport company invoice for {group["company"]} in event {event_id}')
        _workforce_changed(event_id, 'transport-company-invoice-updated')
        if queued_record_id:
            _queue_worker_submission_processing((
                manager, data_folder, event_id, '', queued_record_id, 'transport'
            ))
        return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})
    except ValueError as exc:
        if saved:
            delete_upload(data_folder or _workforce_folder(), saved)
        return jsonify({'error': str(exc)}), 400


def _find_submission_record(workforce, submission_id):
    for event_id, event_rows in (workforce.get('submissions') or {}).items():
        if not isinstance(event_rows, dict):
            continue
        for freelancer_id, rows in event_rows.items():
            if not isinstance(rows, dict):
                continue
            for kind in ('invoices', 'claims'):
                for record in rows.get(kind, []) if isinstance(rows.get(kind), list) else []:
                    if (
                        isinstance(record, dict)
                        and str(record.get('id')) == str(submission_id)
                    ):
                        return {
                            'eventId': int(event_id),
                            'freelancerId': str(freelancer_id),
                            'kind': kind[:-1],
                            'record': record,
                            'container': rows[kind],
                        }
    for event_id, bookings in (workforce.get('transportBookings') or {}).items():
        for booking in bookings if isinstance(bookings, list) else []:
            if not isinstance(booking, dict):
                continue
            invoice = booking.get('invoice')
            if isinstance(invoice, dict) and str(invoice.get('id')) == str(submission_id):
                return {
                    'eventId': int(event_id),
                    'freelancerId': '',
                    'kind': 'transport',
                    'record': invoice,
                    'container': booking,
                    'invoiceField': 'invoice',
                }
            for invoice in transport_company_invoices(booking):
                if str(invoice.get('id')) == str(submission_id):
                    return {
                        'eventId': int(event_id),
                        'freelancerId': '',
                        'kind': 'transport',
                        'record': invoice,
                        'container': booking,
                        'invoiceField': 'companyInvoices',
                    }
            for claim in booking.get('claims', []) if isinstance(booking.get('claims'), list) else []:
                if isinstance(claim, dict) and str(claim.get('id')) == str(submission_id):
                    return {
                        'eventId': int(event_id),
                        'freelancerId': '',
                        'kind': 'transport',
                        'submissionKind': 'claim',
                        'record': claim,
                        'container': booking,
                        'invoiceField': 'claims',
                    }
    return None


@app.route('/api/workforce/submissions', methods=['GET'])
@require_admin
def list_workforce_submissions():
    """List this company's worker and vendor invoices and claims."""
    event_id = request.args.get('eventId', type=int)
    if not _current_user_can_view_all_invoice_claims():
        if not event_id:
            return jsonify({
                'error': 'Admin privileges are required to view all invoices and claims'
            }), 403
        event = data_manager.events.get(event_id) if data_manager else None
        if not event:
            return jsonify({'error': 'Event not found'}), 404
        if not _current_user_can_access_event(event):
            return _event_access_denied_response()

    rows = _admin_submission_rows()
    include_full_time = str(
        request.args.get('includeFullTime') or ''
    ).strip().lower() in {'1', 'true', 'yes', 'on'}
    scoped_rows = [
        row for row in rows
        if (
            (not event_id or int(row['event']['id']) == event_id)
            and (
                include_full_time
                or str((row.get('subject') or {}).get('type') or '') != 'app-user'
            )
        )
    ]
    status_counts = {
        key: 0 for key in (
            'awaiting-upload', 'to-review', 'to-pay', 'awaiting-confirmation',
            'paid', 'payment-confirmed', 'denied', 'queued', 'processing',
            'details-required',
        )
    }
    kind_counts = {'invoice': 0, 'claim': 0}
    for row in scoped_rows:
        status_key = row.get('statusKey')
        if status_key:
            status_counts[status_key] = status_counts.get(status_key, 0) + 1
        if (
            str(row.get('status') or '') == 'Paid'
            and not row.get('paymentConfirmedAt')
        ):
            status_counts['paid'] += 1
        kind = row.get('kind')
        if kind in kind_counts and not row.get('isAwaitingUpload'):
            kind_counts[kind] += 1

    total_uploads = sum(
        1 for row in scoped_rows if not row.get('isAwaitingUpload')
    )

    requested_statuses = _query_values('status')
    if not requested_statuses:
        requested_statuses = {'to-review', 'to-pay'}
    show_all_statuses = 'all' in requested_statuses
    requested_kinds = _query_values('kind')
    if not requested_kinds or 'all' in requested_kinds:
        requested_kinds = {'invoice', 'claim'}
    search = str(request.args.get('search') or '').strip().casefold()
    sort_by = str(request.args.get('sort') or 'event').strip().lower()
    if sort_by not in {'event', 'uploader', 'submitted', 'status'}:
        sort_by = 'event'
    default_sort_direction = (
        'asc' if sort_by in {'uploader', 'status'} else 'desc'
    )
    sort_direction = str(
        request.args.get('direction') or default_sort_direction
    ).strip().lower()
    if sort_direction not in {'asc', 'desc'}:
        sort_direction = default_sort_direction

    filtered = []
    for row in scoped_rows:
        if not show_all_statuses:
            filter_keys = {str(row.get('statusKey') or '')}
            if (
                str(row.get('status') or '') == 'Paid'
                and not row.get('paymentConfirmedAt')
            ):
                filter_keys.add('paid')
            if filter_keys.isdisjoint(requested_statuses):
                continue
        if row.get('kind') not in requested_kinds:
            continue
        if search:
            search_text = ' '.join((
                str(row.get('originalName') or ''),
                str(row.get('category') or ''),
                str(row.get('description') or row.get('notes') or ''),
                str(row['subject'].get('name') or ''),
                str(row['subject'].get('company') or ''),
                str(row['subject'].get('phone') or ''),
                ' '.join(
                    role
                    for department in row.get('departmentDetails') or []
                    for role in department.get('roles') or []
                ),
                str(row['event'].get('id') or ''),
                str(row['event'].get('name') or ''),
                str(row['event'].get('location') or ''),
                ' '.join(row.get('departments') or []),
            )).casefold()
            if search not in search_text:
                continue
        filtered.append(row)

    display_rows = _sort_admin_submission_display_rows(
        _group_admin_claim_rows(scoped_rows, filtered),
        sort_by,
        sort_direction,
    )
    page = max(1, request.args.get('page', default=1, type=int) or 1)
    page_size = min(
        100,
        max(10, request.args.get('pageSize', default=50, type=int) or 50),
    )
    total = len(display_rows)
    page_count = max(1, (total + page_size - 1) // page_size)
    page = min(page, page_count)
    start = (page - 1) * page_size
    return jsonify({
        'success': True,
        'data': {
            'rows': display_rows[start:start + page_size],
            'total': total,
            'page': page,
            'pageSize': page_size,
            'pageCount': page_count,
            'statusCounts': status_counts,
            'kindCounts': kind_counts,
            'totalItems': len(scoped_rows),
            'totalUploads': total_uploads,
            'attentionTotal': (
                status_counts.get('to-review', 0)
                + status_counts.get('to-pay', 0)
            ),
            'includeFullTime': include_full_time,
            'sortBy': sort_by,
            'sortDirection': sort_direction,
        },
    })


@app.route(
    '/api/workforce/submissions/<submission_id>/extract',
    methods=['POST'],
)
@require_admin
def reextract_workforce_invoice_amount(submission_id):
    with mutate_workforce(_workforce_folder()) as workforce:
        found = _find_submission_record(workforce, submission_id)
        if not found:
            return jsonify({'error': 'Submission not found'}), 404
        if found['kind'] not in {'invoice', 'transport'}:
            return jsonify({'error': 'OCR is only available for invoices'}), 400
        record = found['record']
        path = upload_absolute_path(
            _workforce_folder(), record.get('storedPath')
        )
        if not path or not os.path.isfile(path):
            return jsonify({'error': 'Invoice file not found'}), 404
        extraction = extract_invoice_amount(path, data_folder=_workforce_folder())
        detected_amount = extraction.get('amount')
        if detected_amount is not None:
            record['amount'] = detected_amount
        record.update({
            'ocrConfidence': extraction.get('confidence', 'Low'),
            'ocrSource': extraction.get('source', ''),
            'ocrMatchedText': extraction.get('matchedText', ''),
            'ocrUsed': bool(extraction.get('ocrUsed')),
            'ocrRetriedAt': now_iso(),
        })
        event_id = found['eventId']
    log_action(f"Re-ran invoice OCR for event {event_id}")
    return jsonify({
        'success': True,
        'data': _admin_workforce_payload(event_id),
    })


@app.route('/api/workforce/submissions/bulk-status', methods=['PUT'])
@require_admin
def update_workforce_claim_group_status():
    """Update reviewed claims for one person and event as one atomic action."""
    payload = request.get_json(silent=True) or {}
    submission_ids = list(dict.fromkeys(
        str(value or '').strip()
        for value in payload.get('submissionIds', [])
        if str(value or '').strip()
    ))
    requested_status = str(payload.get('status') or '').strip()
    allowed_statuses = {'Pending Review', 'Approved', 'Paid', 'Payment Confirmed'}
    if len(submission_ids) < 2:
        return jsonify({'error': 'Choose at least two claims'}), 400
    if len(submission_ids) > 50:
        return jsonify({'error': 'A maximum of 50 claims can be updated together'}), 400
    if requested_status not in allowed_statuses:
        return jsonify({'error': 'Choose a valid group claim status'}), 400

    manager = _current_data_manager_object()
    status_changes = []
    with mutate_workforce(_workforce_folder(manager)) as workforce:
        found_rows = []
        for submission_id in submission_ids:
            found = _find_submission_record(workforce, submission_id)
            if not found:
                return jsonify({'error': 'One or more claims could not be found'}), 404
            found_rows.append(found)

        group_keys = {
            (found['eventId'], found['freelancerId'], found['kind'])
            for found in found_rows
        }
        if len(group_keys) != 1 or next(iter(group_keys))[2] != 'claim':
            return jsonify({
                'error': 'Claims must belong to the same person and event'
            }), 400
        if any(not found['record'].get('verifiedAt') for found in found_rows):
            return jsonify({
                'error': 'Review every claim individually before updating them together'
            }), 409
        if requested_status != 'Pending Review' and any(
            money(found['record'].get('amount')) is None
            or not str(found['record'].get('claimDate') or '').strip()
            or not str(found['record'].get('category') or '').strip()
            for found in found_rows
        ):
            return jsonify({
                'error': 'Every claim needs a verified amount, date and category'
            }), 409

        event_id, freelancer_id, _kind = next(iter(group_keys))
        actor = session.get('user', '')
        changed = 0
        for found in found_rows:
            record = found['record']
            old_status = str(record.get('status') or 'Pending Review')
            previous_notification_status = _submission_notification_status(record)
            admin_confirming_payment = requested_status == 'Payment Confirmed'
            stored_status = 'Paid' if admin_confirming_payment else requested_status
            already_matching = (
                old_status == stored_status
                and bool(record.get('paymentConfirmedAt')) == admin_confirming_payment
            )
            if already_matching:
                continue
            record.update({
                'status': stored_status,
                'denialReason': '',
                'reviewedAt': now_iso(),
                'reviewedBy': actor,
            })
            if admin_confirming_payment:
                record['paymentConfirmedAt'] = now_iso()
                record['paymentConfirmedByAdmin'] = actor
                record['paymentConfirmedByWorker'] = False
            else:
                record.pop('paymentConfirmedAt', None)
                record.pop('paymentConfirmedByWorker', None)
                record.pop('paymentConfirmedByAdmin', None)
            record.setdefault('reviewHistory', []).append({
                'at': now_iso(),
                'by': actor,
                'from': old_status,
                'to': stored_status,
                'amount': money(record.get('amount')),
                'groupUpdate': True,
            })
            status_changes.append((
                _submission_subject_display_name(
                    manager, workforce, found['freelancerId']
                ),
                previous_notification_status,
                _submission_notification_status(record),
                found['freelancerId'],
                str(record.get('id') or ''),
                _submission_worker_recipient_ids(
                    workforce, found['freelancerId'], record
                ),
            ))
            changed += 1

    log_action(
        f"Changed {changed} claims to {requested_status} for event {event_id}"
    )
    _workforce_changed(event_id, 'submission-group-status')
    for (
        worker_name, previous_status, new_status, subject_id,
        submission_id, worker_recipient_ids
    ) in status_changes:
        _queue_workforce_status_change_notification(
            manager=manager,
            worker_name=worker_name,
            event_id=event_id,
            kind='claim',
            previous_status=previous_status,
            new_status=new_status,
            changed_by=actor,
            subject_id=subject_id,
            submission_id=submission_id,
            worker_recipient_ids=worker_recipient_ids,
        )
    return jsonify({
        'success': True,
        'data': _admin_workforce_payload(event_id),
        'updatedCount': changed,
        'freelancerId': freelancer_id,
    })


@app.route('/api/workforce/submissions/<submission_id>', methods=['PUT'])
@require_admin
def review_workforce_submission(submission_id):
    payload = request.get_json(silent=True) or {}
    manager = _current_data_manager_object()
    with mutate_workforce(_workforce_folder(manager)) as workforce:
        found = _find_submission_record(workforce, submission_id)
        if not found:
            return jsonify({'error': 'Submission not found'}), 404
        record = found['record']
        submission_kind = found.get(
            'submissionKind',
            'invoice' if found['kind'] == 'transport' else found['kind'],
        )
        previous_notification_status = _submission_notification_status(record)
        status = str(payload.get('status', record.get('status', 'Pending Review')))
        if status not in VALID_STATUSES:
            return jsonify({'error': 'Invalid status'}), 400
        old_status = record.get('status', 'Pending Review')
        admin_confirming_payment = bool(payload.get('adminConfirmPayment'))
        if admin_confirming_payment:
            status = 'Paid'
        confirming_review = bool(payload.get('confirmReview'))
        already_verified = bool(record.get('verifiedAt'))
        if (
            not already_verified
            and status != 'Pending Review'
            and not confirming_review
        ):
            return jsonify({
                'error': 'Review and confirm the submission amount first'
            }), 409
        can_edit_details = confirming_review or not already_verified
        amount = (
            money(payload.get('amount', record.get('amount')))
            if can_edit_details
            else money(record.get('amount'))
        )
        if amount is None and status != 'Denied':
            return jsonify({'error': 'Enter a valid amount'}), 400
        if amount is None:
            amount = record.get('amount')
        allocations = (
            payload.get('allocations', record.get('allocations', []))
            if can_edit_details
            else record.get('allocations', [])
        )
        if submission_kind == 'invoice':
            if not isinstance(allocations, list):
                return jsonify({'error': 'Invalid department allocation'}), 400
            clean_allocations = []
            allocated_total = 0.0
            for row in allocations:
                if not isinstance(row, dict):
                    continue
                department = str(row.get('department') or '').strip()
                allocation_amount = money(row.get('amount'))
                if not department or allocation_amount is None:
                    continue
                allocated_total += allocation_amount
                clean_allocations.append({
                    'department': department,
                    'amount': allocation_amount,
                })
            if not clean_allocations and amount is not None:
                departments = []
                for assignment in event_assignments(
                    workforce, found['eventId']
                ):
                    if (
                        isinstance(assignment, dict)
                        and str(assignment.get('freelancerId') or '')
                        == found['freelancerId']
                    ):
                        department = str(
                            assignment.get('department') or ''
                        ).strip()
                        if department and department not in departments:
                            departments.append(department)
                if departments:
                    total_cents = int(round(float(amount) * 100))
                    cents_each, remainder = divmod(
                        total_cents, len(departments)
                    )
                    clean_allocations = [
                        {
                            'department': department,
                            'amount': (
                                cents_each + (1 if index < remainder else 0)
                            ) / 100,
                        }
                        for index, department in enumerate(departments)
                    ]
                    allocated_total = sum(
                        row['amount'] for row in clean_allocations
                    )
            if clean_allocations and amount is not None and abs(allocated_total - amount) > 0.01:
                return jsonify({
                    'error': 'Department allocations must equal the invoice amount'
                }), 400
            record['allocations'] = clean_allocations
        if (
            submission_kind == 'claim'
            and can_edit_details
            and payload.get('department') is not None
        ):
            record['department'] = str(payload.get('department') or '').strip()
        if submission_kind == 'claim' and can_edit_details:
            claim_date = str(
                payload.get('claimDate', record.get('claimDate') or '')
                or ''
            ).strip()
            category = str(
                payload.get('category', record.get('category') or '')
                or ''
            ).strip()
            category = _normalise_claim_category(category)
            if confirming_review and status != 'Denied' and (
                not claim_date or not category
            ):
                return jsonify({
                    'error': 'Claim date and category are required'
                }), 400
            if claim_date:
                record['claimDate'] = claim_date
            if category:
                record['category'] = category
            if payload.get('notes') is not None:
                notes = str(payload.get('notes') or '').strip()
                record['description'] = notes
                record['notes'] = notes
            if confirming_review and status != 'Denied':
                record['detailsComplete'] = True
                record['submissionStage'] = 'Submitted'
                record['detailsCompletedAt'] = now_iso()
                record['detailsCompletedByAdmin'] = session.get('user', '')
        record.update({
            'amount': amount,
            'status': status,
            'denialReason': (
                str(payload.get('denialReason') or '').strip()
                if status == 'Denied'
                else ''
            ),
            'reviewedAt': now_iso(),
            'reviewedBy': session.get('user', ''),
        })
        if confirming_review:
            record['verifiedAt'] = now_iso()
            record['verifiedBy'] = session.get('user', '')
            record['processingState'] = 'Complete'
            record['processingError'] = ''
        if admin_confirming_payment:
            record['paymentConfirmedAt'] = now_iso()
            record['paymentConfirmedByAdmin'] = session.get('user', '')
            record['paymentConfirmedByWorker'] = False
        elif record.get('paymentConfirmedAt') and (
            status != 'Paid'
            or bool(payload.get('clearPaymentConfirmation'))
        ):
            record.pop('paymentConfirmedAt', None)
            record.pop('paymentConfirmedByWorker', None)
            record.pop('paymentConfirmedByAdmin', None)
        record.setdefault('reviewHistory', []).append({
            'at': now_iso(),
            'by': session.get('user', ''),
            'from': old_status,
            'to': status,
            'amount': amount,
        })
        event_id = found['eventId']
        is_transport_submission = found['kind'] == 'transport'
        worker_name = (
            str(
                record.get('company')
                or found['container'].get('company')
                or 'Transport provider'
            )
            if is_transport_submission
            else _submission_subject_display_name(
                manager, workforce, found['freelancerId']
            )
        )
        new_notification_status = _submission_notification_status(record)
        subject_id = found['freelancerId']
        worker_recipient_ids = (
            [] if is_transport_submission
            else _submission_worker_recipient_ids(
                workforce, subject_id, record
            )
        )
    log_action(
        f"Changed {found['kind']} {submission_id} from {old_status} to {status} for event {event_id}"
    )
    _workforce_changed(event_id, 'submission-reviewed')
    _queue_workforce_status_change_notification(
        manager=manager,
        worker_name=worker_name,
        event_id=event_id,
        kind=submission_kind,
        previous_status=previous_notification_status,
        new_status=new_notification_status,
        changed_by=str(session.get('user') or ''),
        subject_id=subject_id,
        submission_id=submission_id,
        worker_recipient_ids=worker_recipient_ids,
    )
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


@app.route('/api/workforce/submissions/<submission_id>', methods=['DELETE'])
@require_admin
def delete_workforce_submission(submission_id):
    with mutate_workforce(_workforce_folder()) as workforce:
        found = _find_submission_record(workforce, submission_id)
        if not found:
            return jsonify({'error': 'Submission not found'}), 404
        delete_upload(_workforce_folder(), found['record'])
        if found['kind'] == 'transport':
            if found.get('invoiceField') == 'companyInvoices':
                remaining = [
                    record
                    for record in transport_company_invoices(found['container'])
                    if str(record.get('id')) != str(submission_id)
                ]
                _set_transport_company_invoices(found['container'], remaining)
            elif found.get('invoiceField') == 'claims':
                found['container']['claims'] = [
                    record
                    for record in found['container'].get('claims', [])
                    if str(record.get('id')) != str(submission_id)
                ]
            else:
                found['container'][found.get('invoiceField', 'invoice')] = None
        else:
            found['container'].remove(found['record'])
        event_id = found['eventId']
    log_action(f"Deleted {found['kind']} upload from event {event_id}")
    _workforce_changed(event_id, 'submission-deleted')
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


