@app.route('/api/events/<int:event_id>/workforce/download/<kind>', methods=['GET'])
@require_admin
def download_event_workforce_files(event_id, kind):
    if kind not in {'invoices', 'claims'}:
        return jsonify({'error': 'Invalid download type'}), 400
    workforce = load_workforce(_workforce_folder())
    records = []
    event_rows = (workforce.get('submissions') or {}).get(str(event_id), {}) or {}
    for freelancer_id, rows in event_rows.items():
        if _workforce_subject_is_hidden_owner(freelancer_id):
            continue
        freelancer, _subject_type = _workforce_subject(
            workforce, freelancer_id
        )
        freelancer = freelancer or {}
        worker_name = sanitize_filename(str(freelancer.get('name') or freelancer_id))
        for record in rows.get(kind, []) if isinstance(rows, dict) else []:
            if not isinstance(record, dict):
                continue
            copy = dict(record)
            copy['originalName'] = f"{worker_name} - {record.get('originalName', 'upload')}"
            records.append(copy)
    archive = build_zip(_workforce_folder(), records)
    return send_file(
        archive,
        mimetype='application/zip',
        as_attachment=True,
        download_name=f"event-{event_id}-{kind}.zip",
    )


def _maintenance_log_permission(asset, log_index, allow_admin=True):
    """Return (allowed, message) for editing/deleting a maintenance log.

    Normal users may only edit logs they recorded, and only within 7 days of
    the log date. Admins may edit/delete any maintenance log. For older logs,
    the attributed user is also the recorder.
    """
    username = session.get('user')
    if not username:
        return False, 'Not authenticated'

    logs = getattr(asset, 'maintenance_logs', []) or []
    if log_index < 0 or log_index >= len(logs):
        return False, 'Invalid log index'

    original_log = normalize_maintenance_log(logs[log_index])
    if (original_log.get('source') or {}).get('kind') == CONTAINER_MAINTENANCE_SOURCE:
        return False, 'Container maintenance logs are managed from the container history'

    if allow_admin and _current_user_is_admin():
        return True, ''

    source = original_log.get('source') or {}
    original_user = str(source.get('recordedBy') or original_log.get('user') or '').strip()

    if original_user != username:
        return False, 'You can only modify maintenance logs that you wrote'

    log_date = parse_maintenance_log_date(original_log)
    if not log_date:
        return False, 'This maintenance log has an invalid date and cannot be modified by a normal user'

    today = datetime.now().date()
    age_days = (today - log_date).days
    if age_days < 0 or age_days > 7:
        return False, 'Normal users can only modify their own maintenance logs within 7 days'

    return True, ''

def _event_activity_category(action):
    action_lower = str(action or '').lower()
    manpower_terms = (
        'worker',
        'workforce',
        'invoice',
        'claim',
        'transport',
        'vendor',
        'submission',
        'freelancer',
    )
    if any(term in action_lower for term in manpower_terms):
        return 'manpower'

    if 'return' in action_lower or 'closed event' in action_lower:
        return 'return'

    prepare_terms = (
        'prepared',
        'unprepared',
        'assigned to event',
        'assigned specific asset',
        'assigned custom asset',
        'assigned asset',
        'unassigned',
        'collected loan',
        'uncollected loan',
        'promoted prepared extra asset',
        'completely removed asset',
    )
    if any(term in action_lower for term in prepare_terms):
        return 'prepare'

    return 'details'


def _system_log_category(action):
    """Return the operational area represented by a system-log action."""
    action_lower = str(action or '').lower()
    if re.search(r'log(?:ged)? in|log(?:ged)? out|password|login attempt|user\s', action_lower):
        return 'access'
    if re.search(r'asset|inventory|container|maintenance|transfer|prepare|return', action_lower):
        return 'inventory'
    if re.search(r'event|planning|quotation|delivery order|packing list', action_lower):
        return 'events'
    if re.search(r'worker|vendor|manpower|transport|personnel', action_lower):
        return 'workforce'
    if re.search(r'invoice|claim|expense|payment|commission|finance', action_lower):
        return 'finance'
    if re.search(r'company|department|settings|logo|pdf', action_lower):
        return 'settings'
    return 'other'


_LOG_DETAIL_LABELS = {
    'applyto': 'Scope',
    'updatedassets': 'Assets updated',
    'eventsupdated': 'Events updated',
    'containersupdated': 'Containers updated',
    'systemlogs': 'System logs updated',
    'eventlogs': 'Event logs updated',
    'maintenancelogs': 'Maintenance records updated',
    'financedocuments': 'Finance documents updated',
}


def _log_detail_label(value):
    key = re.sub(r'[^a-z0-9]', '', str(value or '').lower())
    if key in _LOG_DETAIL_LABELS:
        return _LOG_DETAIL_LABELS[key]
    spaced = re.sub(r'(?<!^)(?=[A-Z])', ' ', str(value or '').strip())
    return spaced.replace('_', ' ').strip().capitalize()


def _log_detail_value(key, value):
    clean_value = str(value or '').strip()
    if re.sub(r'[^a-z0-9]', '', str(key or '').lower()) == 'applyto':
        return {
            'single': 'This asset',
            'model': 'All assets of this model',
            'all': 'All matching assets',
        }.get(clean_value.lower(), clean_value)
    return clean_value


def _log_action_presentation(action, actor=''):
    """Split an audit action into a concise heading and preserved detail."""
    raw_action = humanize_custom_asset_references(action).strip()
    text = raw_action.replace('\u2192', '->').replace('â†’', '->')
    text = re.sub(r'\s+', ' ', text).strip()
    actor = str(actor or '').strip()

    login_match = re.fullmatch(
        r'User\s+(.+?)\s+(logged in|logged out)(?:\s+(?:via|from)\s+(.+))?',
        text,
        flags=re.IGNORECASE,
    )
    if login_match:
        verb = login_match.group(2).lower()
        source = str(login_match.group(3) or '').strip()
        return {
            'summary': 'Logged in' if verb == 'logged in' else 'Logged out',
            'details': source.capitalize() if source else '',
            'category': 'access',
        }

    failed_login_match = re.fullmatch(
        r'Failed login attempt for username:\s*(.+)',
        text,
        flags=re.IGNORECASE,
    )
    if failed_login_match:
        return {
            'summary': 'Failed login attempt',
            'details': f"Username: {failed_login_match.group(1).strip()}",
            'category': 'access',
        }

    if actor:
        text = re.sub(
            rf'^User\s+{re.escape(actor)}\s+',
            '',
            text,
            count=1,
            flags=re.IGNORECASE,
        )

    details = []
    if re.search(r'\s+(?:via|from)\s+web interface$', text, flags=re.IGNORECASE):
        text = re.sub(
            r'\s+(?:via|from)\s+web interface$',
            '',
            text,
            flags=re.IGNORECASE,
        )
        details.append('Web interface')

    segments = [segment.strip() for segment in text.split(';') if segment.strip()]
    head = segments.pop(0) if segments else text
    if ':' in head:
        possible_summary, possible_detail = head.split(':', 1)
        if possible_summary.strip() and possible_detail.strip():
            head = possible_summary.strip()
            details.insert(0, possible_detail.strip())

    for segment in segments:
        key_value = re.fullmatch(r'([A-Za-z][A-Za-z0-9_]*)\s*=\s*(.+)', segment)
        if key_value:
            key, value = key_value.groups()
            details.append(
                f"{_log_detail_label(key)}: {_log_detail_value(key, value)}"
            )
        else:
            details.append(segment)

    summary = re.sub(
        r'\bevent\s+(\d+)\b',
        r'event #\1',
        head.strip(),
        flags=re.IGNORECASE,
    )
    return {
        'summary': summary or 'Activity recorded',
        'details': '; '.join(detail for detail in details if detail),
        'category': _system_log_category(text),
    }


def _log_user_display_name(manager, username):
    username = str(username or '').strip()
    if not username or username.lower() == 'system':
        return 'System'
    user = getattr(manager, 'users', {}).get(username) if manager else None
    return str(getattr(user, 'name', '') or username).strip()


def _log_record_for_response(record, manager, category=None):
    action = str(record.get('action') or '')
    username = str(record.get('user') or '').strip()
    presentation = _log_action_presentation(action, username)
    return {
        **record,
        **presentation,
        'category': category or presentation['category'],
        'username': username,
        'userDisplayName': _log_user_display_name(manager, username),
    }


def _audit_change_details(before, after, fields, sensitive_fields=None):
    """Describe changed fields without copying sensitive values into logs."""
    sensitive_fields = set(sensitive_fields or ())
    changes = []
    for key, label in fields:
        previous = before.get(key)
        current = after.get(key)
        if previous == current:
            continue
        if key in sensitive_fields:
            changes.append(f'{label} updated')
            continue
        if isinstance(previous, (list, tuple, set)) or isinstance(current, (list, tuple, set)):
            previous_count = len(previous or [])
            current_count = len(current or [])
            changes.append(f'{label}: {previous_count} -> {current_count}')
            continue
        if isinstance(previous, bool) or isinstance(current, bool):
            previous_text = 'Yes' if bool(previous) else 'No'
            current_text = 'Yes' if bool(current) else 'No'
        else:
            previous_text = str(previous or '-').strip() or '-'
            current_text = str(current or '-').strip() or '-'
        changes.append(f'{label}: {previous_text} -> {current_text}')
    return '; '.join(changes) or 'No field values changed'


def _event_activity_logs_for_response(event):
    if not _current_user_can_view_logs():
        return []
    records = data_manager.normalize_event_logs(
        getattr(event, 'event_logs', [])
    )
    result = []
    for record in records:
        if _owner_identity_is_hidden(record.get('user')):
            continue
        category = _event_activity_category(record.get('action'))
        if category == 'manpower' and not _current_user_is_admin():
            continue
        result.append(
            _log_record_for_response(record, data_manager, category=category)
        )
    return result


def _user_presence_realtime_details_from_log_action(action):
    text = str(action or '').strip()
    match = re.match(
        r'^User\s+(.+?)\s+(logged in via web interface|logged out from web interface)$',
        text,
    )
    if not match:
        return None

    status_text = match.group(2)
    return {
        'action': text,
        'username': match.group(1),
        'status': 'login' if status_text.startswith('logged in') else 'logout',
    }


def log_action(
    action,
    user=None,
    event_meta=None,
    include_system_log=False,
    system_log_only=False,
    persist_event=True,
):
    """Helper function to log actions."""
    try:
        if has_request_context():
            g.action_logged = True
        actor = (
            str(user).strip()
            if user is not None and str(user).strip()
            else session.get('user', 'system')
        )
        if (
            (has_request_context() and _current_user_is_owner())
            or _is_owner_username(actor)
        ):
            return

        log_entry = LogEntry(
            timestamp=datetime.now().strftime("%Y/%m/%d %H:%M:%S"),
            user=actor,
            action=action
        )

        event_ids = []
        if (
            not system_log_only
            and data_manager
            and hasattr(data_manager, 'event_ids_from_log_action')
        ):
            event_ids = [
                event_id
                for event_id in data_manager.event_ids_from_log_action(action)
                if event_id in data_manager.events
            ]

        if event_ids:
            for event_id in event_ids:
                event = data_manager.events[event_id]
                event_record = log_entry
                if isinstance(event_meta, dict):
                    event_record = {
                        'timestamp': log_entry.timestamp,
                        'user': log_entry.user,
                        'action': log_entry.action,
                        **event_meta,
                        'eventId': event_id,
                    }
                data_manager.append_event_log(event, event_record)
                if persist_event:
                    data_manager.save_event(event)
            mark_realtime_change('event-log', {'eventIds': event_ids, 'action': action})
        if system_log_only or not event_ids or include_system_log:
            data_manager.logs.append(log_entry)
            data_manager.save_logs()
            presence_details = _user_presence_realtime_details_from_log_action(action)
            if presence_details:
                mark_realtime_change('user-presence', presence_details)
            else:
                mark_realtime_change('activity-log', {'action': action})

        mark_data_snapshot_current()
        logger.info(f"Action logged: {action}")
    except Exception as e:
        logger.error(f"Failed to log action: {e}")


def _asset_log_label(asset):
    if not asset:
        return ''
    parts = []
    for value in (
        getattr(asset, 'brand', ''),
        getattr(asset, 'model_number', ''),
        getattr(asset, 'description', ''),
    ):
        value = str(value or '').strip()
        if value and value.lower() not in {part.lower() for part in parts}:
            parts.append(value)
    return ' - '.join(parts)


def _custom_asset_log_label(custom):
    if not isinstance(custom, dict):
        return 'Custom item'
    name = str(custom.get('name') or 'Custom item').strip()
    item_type = _normalise_custom_type(custom.get('type'))
    company = str(custom.get('company') or '').strip()
    description = str(custom.get('description') or '').strip()
    if item_type == 'LOAN' and company:
        return f'{name} (loan from {company})'
    if description:
        return f'{name} ({description})'
    return f"{name} ({item_type.lower()} item)"


def _event_asset_log_item(asset_ref='', quantity=None, group=None):
    if isinstance(group, dict):
        label = _asset_log_label(SimpleNamespace(
            brand=group.get('brand', ''),
            model_number=group.get('model', ''),
            description=group.get('description', ''),
        ))
        return {
            'assetId': '',
            'label': label or 'Unnamed asset',
            'quantity': max(1, _safe_int(quantity, 1)),
            'itemType': 'model',
        }

    asset_ref = str(asset_ref or '').strip()
    bulk = _parse_bulk_marker(asset_ref)
    if bulk:
        asset = data_manager.inventory.get(bulk.get('bulkId'))
        return {
            # Bulk IDs are internal implementation details. Group and display
            # these log entries by the user-facing inventory name instead.
            'assetId': '',
            'label': _asset_log_label(asset) or 'Bulk asset',
            'quantity': max(1, _safe_int(quantity, bulk.get('quantity') or 1)),
            'itemType': 'bulk',
        }

    custom = _parse_custom_marker(asset_ref)
    if custom:
        return {
            'assetId': '',
            'label': _custom_asset_log_label(custom),
            'quantity': max(1, _safe_int(quantity, custom.get('quantity') or 1)),
            'itemType': 'custom',
        }

    asset = data_manager.inventory.get(asset_ref)
    return {
        'assetId': asset_ref,
        'label': _asset_log_label(asset) or asset_ref or 'Unknown asset',
        'quantity': max(1, _safe_int(quantity, 1)),
        'itemType': 'asset',
    }


_EVENT_ASSET_LOG_ACTIONS = {
    'prepare': ('Prepared', 'for'),
    'assign': ('Assigned', 'to'),
    'collect': ('Collected', 'for'),
    'unprepare': ('Unprepared', 'from'),
    'unassign': ('Unassigned and unprepared', 'from'),
    'uncollect': ('Uncollected', 'from'),
    'return': ('Returned', 'from'),
    'restore': ('Restored', 'to'),
    'remove': ('Removed', 'from'),
}


def _log_event_asset_action(
    event_id,
    operation,
    items,
    persist_event=True,
):
    action_label, preposition = _EVENT_ASSET_LOG_ACTIONS.get(
        operation,
        ('Updated', 'for'),
    )
    cleaned_items = [item for item in (items or []) if isinstance(item, dict)]
    meta = {
        'groupKey': f'event-asset:{event_id}:{operation}',
        'actionLabel': action_label,
        'preposition': preposition,
        'eventId': event_id,
        'items': cleaned_items,
        'groupCount': 1,
    }
    action = data_manager.format_event_asset_log_action(meta)
    log_action(action, event_meta=meta, persist_event=persist_event)

def log_asset_change(event_id, asset_id, action, details=""):
    """Log all asset changes for debugging"""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_message = f"[ASSET_CHANGE] {timestamp} - Event {event_id}: {action} asset {asset_id} {details}"
    logger.warning(log_message)

def _asset_group_from_item(asset):
    return {
        'department': (asset.department_code or '').strip().upper(),
        'brand': (asset.brand or '').strip(),
        'model': (asset.model_number or '').strip(),
        'description': (asset.description or '').strip()
    }


def _asset_matches_group(asset, group):
    return (
        (asset.department_code or '').strip().upper() == group['department'] and
        (asset.brand or '').strip() == group['brand'] and
        (asset.model_number or '').strip() == group['model'] and
        (asset.description or '').strip() ==
        str(group.get('description') or '').strip()
    )


def _is_real_asset_ref(value):
    if not isinstance(value, str):
        return False

    blocked_prefixes = (
        '[MODEL]',
        PREPARED_MODEL_PREFIX,
        '[CUSTOM]',
        '[LOAN]',
        '[MISC]',
        'loan|',
        'misc|'
    )

    return not value.startswith(blocked_prefixes)


def _replace_asset_ids_in_list(values, asset_id_mapping):
    """Replace several asset IDs in one pass so overlapping renames stay safe."""
    if not isinstance(values, list) or not asset_id_mapping:
        return 0

    changed = 0

    for index, value in enumerate(values):
        replacement = asset_id_mapping.get(value)
        if replacement is not None and replacement != value:
            values[index] = replacement
            changed += 1
            continue

        marker = _parse_bulk_marker(value)
        if not marker:
            continue

        replacement = asset_id_mapping.get(marker.get('bulkId'))
        if replacement is not None and replacement != marker.get('bulkId'):
            values[index] = _bulk_marker(
                replacement,
                marker.get('quantity', 1),
                marker.get('subprojectId', ''),
            )
            changed += 1

    return changed


def _replace_asset_ids_in_container(container, asset_id_mapping):
    """Cascade an ID mapping through every live container reference."""
    if not container or not asset_id_mapping:
        return 0
    changed = _replace_asset_ids_in_list(
        getattr(container, 'asset_ids', []),
        asset_id_mapping,
    )
    changed += _replace_container_bulk_item_ids(container, asset_id_mapping)
    return changed


def _replace_asset_ids_in_event(event, asset_id_mapping):
    """Cascade an ID mapping through every operational event reference.

    Event activity text remains a historical snapshot of what users saw at
    the time. The live preparation/return references are updated so event and
    inventory history lookup continue to follow the renamed physical asset.
    """
    if not event or not asset_id_mapping:
        return 0

    changed = 0
    for attr in (
        'prepared_items',
        'returned_items',
        'actually_prepared',
        'extra_assets',
    ):
        changed += _replace_asset_ids_in_list(
            getattr(event, attr, []),
            asset_id_mapping,
        )

    for subproject in getattr(event, 'subprojects', []) or []:
        if not isinstance(subproject, dict):
            continue
        changed += _replace_asset_ids_in_list(
            subproject.get('extraRefs', []),
            asset_id_mapping,
        )
        for item in subproject.get('items') or []:
            if not isinstance(item, dict):
                continue
            changed += _replace_asset_ids_in_list(
                item.get('assetRefs', []),
                asset_id_mapping,
            )
    return changed


def _display_model_description(group):
    return f"[{group['department']}] {group['brand']} {group['model']} {group['description']}".strip()


def _model_marker_matches_group(marker, group):
    return bool(marker and _event_model_groups_match(marker, group))


def _set_event_subproject_item_group(item, group):
    """Update a planned room row's inventory identity without losing metadata."""
    item['department'] = group['department']
    item['departmentCode'] = group['department']
    item['brand'] = group['brand']
    item['model'] = group['model']
    item['description'] = group.get('description') or ''


def _update_event_subproject_model_group_references(event, old_group, new_group):
    """Rename a model group in every room and merge destination duplicates."""
    changed = 0
    for subproject in getattr(event, 'subprojects', []) or []:
        if not isinstance(subproject, dict):
            continue
        # Quotation-derived room rows historically stored the full display
        # text (``brand model description``), while inventory stores the raw
        # description. Accept that spelling only for identifying the source;
        # destination quantity lookup remains exact to avoid double-counting
        # the same row during canonicalisation.
        matches = [
            item for item in subproject.get('items') or []
            if _event_model_groups_match(
                _event_subproject_item_group(item),
                old_group,
            )
        ]
        if not matches:
            continue
        destination_quantity = _event_subproject_required_quantity(
            subproject, new_group
        )
        total_quantity = sum(
            max(0, _safe_int(round(_safe_float(item.get('quantity'), 0)), 0))
            for item in matches
        )
        for item in matches:
            _set_event_subproject_item_group(item, new_group)
            changed += 1
        # This folds a pre-existing destination row while preserving room line
        # IDs, prepared counters, and physical asset references.
        _event_subproject_set_group_quantity(
            subproject, new_group, total_quantity + destination_quantity
        )
    return changed


def _move_event_subproject_model_group_quantity(
    event,
    old_group,
    new_group,
    quantity_to_move=1,
    asset_id='',
):
    """Move part of a room requirement when one physical asset is renamed."""
    remaining = max(1, _safe_int(quantity_to_move, 1))
    changed = 0
    asset_id = str(asset_id or '').strip()
    subprojects = [
        row for row in (getattr(event, 'subprojects', []) or [])
        if isinstance(row, dict)
    ]

    def room_priority(subproject):
        for item in _event_subproject_group_items(subproject, old_group):
            for ref in item.get('assetRefs') or []:
                marker = _parse_bulk_marker(ref)
                if ref == asset_id or (marker and marker.get('bulkId') == asset_id):
                    return 0
        return 1

    for subproject in sorted(subprojects, key=room_priority):
        if remaining <= 0:
            break
        source_items = list(_event_subproject_group_items(subproject, old_group))
        if not source_items:
            continue
        source_quantity = sum(
            max(0, _safe_int(round(_safe_float(item.get('quantity'), 0)), 0))
            for item in source_items
        )
        move_quantity = min(source_quantity, remaining)
        if move_quantity <= 0:
            continue

        moved_refs = []
        for item in source_items:
            retained_refs = []
            for ref in item.get('assetRefs') or []:
                marker = _parse_bulk_marker(ref)
                if ref == asset_id or (marker and marker.get('bulkId') == asset_id):
                    moved_refs.append(ref)
                else:
                    retained_refs.append(ref)
            if moved_refs or 'assetRefs' in item:
                item['assetRefs'] = retained_refs

        destination_quantity = _event_subproject_required_quantity(
            subproject, new_group
        )
        _event_subproject_set_group_quantity(
            subproject, old_group, source_quantity - move_quantity
        )
        _event_subproject_set_group_quantity(
            subproject, new_group, destination_quantity + move_quantity
        )
        destination_items = _event_subproject_group_items(subproject, new_group)
        if destination_items and moved_refs:
            destination_refs = destination_items[0].setdefault('assetRefs', [])
            for ref in moved_refs:
                if ref not in destination_refs:
                    destination_refs.append(ref)
        remaining -= move_quantity
        changed += 1

    return changed


def _update_event_model_group_references(event, old_group, new_group):
    """
    Updates event-level model requirement rows when admin chooses
    to update all assets of the same model type.
    """
    changed = 0

    # Room rows are the source of truth in the current planning workflow.
    has_subprojects = bool(getattr(event, 'subprojects', []) or [])
    if has_subprojects:
        changed += _update_event_subproject_model_group_references(
            event, old_group, new_group
        )
        if changed:
            _sync_event_model_markers_from_subprojects(event)

    # Events without room rows store requirements directly in prepared_items.
    if (
        not has_subprojects
        and hasattr(event, 'prepared_items')
        and isinstance(event.prepared_items, list)
    ):
        for index, item in enumerate(event.prepared_items):
            marker = _parse_model_marker(item)

            if _model_marker_matches_group(marker, old_group):
                event.prepared_items[index] = _make_model_marker(new_group, marker['quantity'])
                changed += 1

    # Anonymous prepared quantities are mirrored both as room counters and as
    # [PREPARED] references for consolidated state/return calculations. Keep
    # those references on the renamed group as well; otherwise Prepare can show
    # the room as complete while the event state still sees the old model name.
    for list_name in ('actually_prepared', 'returned_items', 'extra_assets'):
        values = getattr(event, list_name, None)
        if not isinstance(values, list):
            continue
        for index, value in enumerate(values):
            marker = _parse_prepared_model_marker(value)
            if not _model_marker_matches_group(marker, old_group):
                continue
            values[index] = _prepared_model_marker(new_group, marker['quantity'])
            changed += 1

    # Older saved events may still use asset_models rows with model_description.
    old_display = _display_model_description(old_group)
    new_display = _display_model_description(new_group)

    if hasattr(event, 'asset_models') and isinstance(event.asset_models, list):
        for model_row in event.asset_models:
            if not isinstance(model_row, dict):
                continue

            current_description = str(model_row.get('model_description', '')).strip()

            if current_description == old_display:
                model_row['model_description'] = new_display
                changed += 1

    return changed

def _event_reference_lists(event):
    return (
        getattr(event, 'prepared_items', []) or [],
        getattr(event, 'actually_prepared', []) or [],
        getattr(event, 'returned_items', []) or [],
        getattr(event, 'extra_assets', []) or []
    )


def _event_asset_reference_quantity(event, asset_id):
    if not event or not asset_id:
        return 0

    asset = data_manager.inventory.get(asset_id) if data_manager else None

    if asset and _is_bulk_asset(asset):
        quantity = 0
        seen_markers = set()
        has_direct_reference = False

        reference_lists = list(_event_reference_lists(event))
        reference_lists.extend(
            item.get('assetRefs') or []
            for subproject in (getattr(event, 'subprojects', []) or [])
            if isinstance(subproject, dict)
            for item in (subproject.get('items') or [])
            if isinstance(item, dict)
        )
        for values in reference_lists:
            if not isinstance(values, list):
                continue

            for value in values:
                if value == asset_id:
                    has_direct_reference = True
                    continue

                marker = _parse_bulk_marker(value)
                if not marker or marker.get('bulkId') != asset_id:
                    continue

                if value in seen_markers:
                    continue

                seen_markers.add(value)
                quantity += max(1, _safe_int(marker.get('quantity'), 1))

        return quantity or (1 if has_direct_reference else 0)

    lists_to_check = list((
        getattr(event, 'prepared_items', []) or [],
        getattr(event, 'actually_prepared', []) or [],
        getattr(event, 'returned_items', []) or [],
        getattr(event, 'extra_assets', []) or []
    ))
    lists_to_check.extend(
        item.get('assetRefs') or []
        for subproject in (getattr(event, 'subprojects', []) or [])
        if isinstance(subproject, dict)
        for item in (subproject.get('items') or [])
        if isinstance(item, dict)
    )

    return 1 if any(asset_id in values for values in lists_to_check if isinstance(values, list)) else 0


_ASSET_MODEL_GROUP_AUDIT_FIELDS = {
    'department', 'brand', 'model', 'description',
}


def _asset_historical_ids(asset, current_id=''):
    """Return every Asset ID recorded for the same durable inventory row."""
    asset_ids = {
        str(current_id or getattr(asset, 'asset_id', '') or '').strip(),
    }
    for audit_record in getattr(asset, 'change_history', []) or []:
        if not isinstance(audit_record, dict):
            continue
        for change in audit_record.get('changes') or []:
            if (
                not isinstance(change, dict)
                or str(change.get('field') or '').strip() != 'asset_id'
            ):
                continue
            asset_ids.update({
                str(change.get('old') or '').strip(),
                str(change.get('new') or '').strip(),
            })
    return {asset_id for asset_id in asset_ids if asset_id}


def _inventory_historical_asset_id_mapping(
    inventory,
    destination_ids=None,
):
    """Map unambiguous retired IDs to the current or newly assigned ID.

    A retired ID is ignored when it is currently owned by another inventory
    row or is about to become another row's new ID. This makes the mapping safe
    for overlapping bulk renumbers and for Asset IDs which were later reused.
    """
    inventory = inventory or {}
    live_ids = {
        str(asset_id or '').strip()
        for asset_id in inventory
        if str(asset_id or '').strip()
    }
    destinations = {
        str(current_id or '').strip(): str(new_id or '').strip()
        for current_id, new_id in (destination_ids or {}).items()
        if (
            str(current_id or '').strip() in inventory
            and str(new_id or '').strip()
        )
    }
    if not destinations:
        destinations = {asset_id: asset_id for asset_id in live_ids}
    reserved_new_ids = set(destinations.values())
    alias_candidates = {}
    for current_id, destination_id in destinations.items():
        asset = inventory.get(current_id)
        if not asset:
            continue
        for historical_id in _asset_historical_ids(asset, current_id):
            if (
                historical_id == current_id
                or historical_id in live_ids
                or historical_id in reserved_new_ids
            ):
                continue
            alias_candidates.setdefault(historical_id, set()).add(destination_id)
    return {
        historical_id: next(iter(destination_set))
        for historical_id, destination_set in alias_candidates.items()
        if len(destination_set) == 1
    }


def _asset_historical_model_groups(asset, additional_groups=None):
    """Return the current and former inventory groups for one physical asset."""
    current = _asset_group_from_item(asset)
    # The current inventory description is already canonical.  The expanded
    # ``brand model description`` spelling is only a compatibility alias for
    # historical quotation/event rows; treating every current group as an
    # alias would rewrite unrelated, valid quotation display text.
    groups = [(current, False)]
    state = dict(current)

    for audit_record in reversed(getattr(asset, 'change_history', []) or []):
        touched_group = False
        for change in reversed(audit_record.get('changes') or []):
            field = str(change.get('field') or '').strip()
            if field not in _ASSET_MODEL_GROUP_AUDIT_FIELDS:
                continue
            state[field] = str(change.get('old') or '').strip()
            touched_group = True
        if touched_group and all(
            state.get(field) for field in ('department', 'brand', 'model')
        ):
            groups.append((dict(state), True))

    for group in additional_groups or []:
        if isinstance(group, dict) and all(
            str(group.get(field) or '').strip()
            for field in ('department', 'brand', 'model')
        ):
            groups.append(({
                'department': str(group.get('department') or '').strip().upper(),
                'brand': str(group.get('brand') or '').strip(),
                'model': str(group.get('model') or '').strip(),
                'description': str(group.get('description') or '').strip(),
            }, True))

    unique = []
    seen = set()
    for group, is_historical in groups:
        descriptions = {str(group.get('description') or '').strip()}
        if is_historical:
            descriptions.add(' '.join(filter(None, (
                str(group.get('brand') or '').strip(),
                str(group.get('model') or '').strip(),
                str(group.get('description') or '').strip(),
            ))))
        for description in descriptions:
            candidate = {**group, 'description': description}
            key = _event_model_group_key(candidate)
            if key in seen:
                continue
            seen.add(key)
            unique.append(candidate)
    return unique


def _rewrite_event_model_marker_group_labels(
    event,
    alias_destinations,
    destination_groups,
):
    """Canonicalise renamed marker labels without changing their quantities.

    Aggregate marker quantities can intentionally differ from room totals
    (for example, when spare units were added at event level). A historical
    rename repair must therefore relabel the marker in place instead of
    rebuilding it from the subproject requirements.
    """
    changed = 0
    prepared_items = getattr(event, 'prepared_items', None)
    if not isinstance(prepared_items, list):
        return changed

    for index, value in enumerate(prepared_items):
        marker = _parse_model_marker(value)
        if not marker:
            continue
        source_key = _event_model_group_key(marker)
        destinations = alias_destinations.get(source_key) or set()
        if len(destinations) != 1:
            continue
        destination_key = next(iter(destinations))
        destination_group = destination_groups.get(destination_key)
        if destination_key == source_key or not destination_group:
            continue
        prepared_items[index] = _make_model_marker(
            destination_group,
            marker['quantity'],
        )
        changed += 1
    return changed


def _event_inventory_asset_references(event, inventory):
    """Collect immutable inventory IDs referenced anywhere in an event."""
    references = {}

    def remember(value):
        if not isinstance(value, str):
            return
        marker = _parse_bulk_marker(value)
        asset_id = (
            str(marker.get('bulkId') or '').strip()
            if marker else value.strip()
        )
        if asset_id in inventory:
            references.setdefault(asset_id, []).append(value)

    for values in _event_reference_lists(event):
        for value in values if isinstance(values, list) else []:
            remember(value)

    for subproject in getattr(event, 'subprojects', []) or []:
        if not isinstance(subproject, dict):
            continue
        for value in subproject.get('extraRefs') or []:
            remember(value)
        for item in subproject.get('items') or []:
            if not isinstance(item, dict):
                continue
            for value in item.get('assetRefs') or []:
                remember(value)

    return references


def _event_model_group_family_key(group):
    """Return the stable part of an event inventory group.

    Description is editable display text. Older events can therefore retain a
    description which no longer exists in inventory even when department,
    brand, and model still identify one unambiguous live inventory group.
    """
    if not isinstance(group, dict):
        return None
    return (
        _normalise_department_code(group.get('department')) or '',
        str(group.get('brand') or '').strip(),
        str(group.get('model') or '').strip(),
    )


def _link_unowned_event_asset_refs_to_subprojects(
    event,
    inventory,
    candidate_asset_ids=None,
):
    """Attach unowned prepared IDs to matching open room requirements.

    Legacy event files can have a real asset ID at event level but no matching
    ``assetRefs`` entry in a room. The inventory ID is the durable link, so an
    active prepared/returned unit should fill an open requirement for its live
    inventory group before it remains classified as an event-level extra.
    """
    rooms = [
        room for room in (getattr(event, 'subprojects', []) or [])
        if isinstance(room, dict)
    ]
    if not rooms:
        return 0

    candidates = None
    if candidate_asset_ids is not None:
        candidates = {
            str(asset_id or '').strip()
            for asset_id in candidate_asset_ids
            if str(asset_id or '').strip()
        }

    all_active_ref_values = {
        value
        for value in [
            *(getattr(event, 'actually_prepared', []) or []),
            *(getattr(event, 'returned_items', []) or []),
        ]
        if isinstance(value, str)
    }
    active_refs = []
    seen_refs = set()
    for value in [
        *(getattr(event, 'actually_prepared', []) or []),
        *(getattr(event, 'returned_items', []) or []),
    ]:
        if not isinstance(value, str) or value in seen_refs:
            continue
        seen_refs.add(value)
        # Bulk markers carry room and quantity ownership in the marker itself;
        # their existing reconciliation path remains authoritative.
        if _parse_bulk_marker(value):
            continue
        asset_id = value.strip()
        if (
            asset_id not in inventory
            or (candidates is not None and asset_id not in candidates)
        ):
            continue
        active_refs.append((value, asset_id))

    room_owned_refs = set()
    for room in rooms:
        room_owned_refs.update(room.get('extraRefs') or [])
        for item in room.get('items') or []:
            if isinstance(item, dict):
                room_owned_refs.update(item.get('assetRefs') or [])

    changed = 0
    for asset_ref, asset_id in active_refs:
        if asset_ref in room_owned_refs:
            continue
        asset = inventory.get(asset_id)
        if not asset:
            continue
        current_key = _event_model_group_key(_asset_group_from_item(asset))

        linked = False
        for room in rooms:
            for item in room.get('items') or []:
                group = _event_subproject_item_group(item)
                if not group or _event_model_group_key(group) != current_key:
                    continue

                required = max(
                    0,
                    _safe_int(round(_safe_float(item.get('quantity'), 0)), 0),
                )
                occupied = (
                    max(0, _safe_int(item.get('preparedQuantity'), 0))
                    + max(0, _safe_int(
                        item.get('returnedPreparedQuantity'), 0,
                    ))
                )
                for existing_ref in item.get('assetRefs') or []:
                    if existing_ref not in all_active_ref_values:
                        continue
                    if (
                        _event_physical_ref_group_key(existing_ref, inventory)
                        == current_key
                    ):
                        occupied += _event_subproject_ref_quantity(existing_ref)
                if occupied >= required:
                    continue

                item.setdefault('assetRefs', []).append(asset_ref)
                room_owned_refs.add(asset_ref)
                changed += 1
                linked = True
                break
            if linked:
                break
    return changed


def _repair_prepared_event_asset_group_links(
    event,
    inventory,
    candidate_asset_ids=None,
    previous_groups_by_asset=None,
):
    """Keep prepared physical IDs paired with their live inventory group.

    Model labels are editable, while a physical asset ID is the durable link.
    This reconciler uses that ID to repair stale room rows after a rename. It
    only rewrites an entire historical group when every inventory asset from
    that former group now resolves to the same destination; split groups move
    only the quantities belonging to the specifically referenced assets.
    """
    subprojects = [
        row for row in (getattr(event, 'subprojects', []) or [])
        if isinstance(row, dict)
    ]

    event_references = _event_inventory_asset_references(event, inventory)
    if candidate_asset_ids is None:
        candidates = set(event_references)
    else:
        candidates = {
            str(asset_id or '').strip()
            for asset_id in candidate_asset_ids
            if str(asset_id or '').strip() in inventory
        }
    previous_groups_by_asset = previous_groups_by_asset or {}
    current_groups = {}
    destination_groups = {}
    historical_groups = {}
    alias_destinations = {}
    family_destinations = {}
    repair_whole_groups = candidate_asset_ids is None

    # A historical audit needs every inventory row so a partial rename cannot
    # be mistaken for a whole-group rename. The live rename path passes its
    # exact candidate IDs and stays proportional to the edited group size.
    inventory_rows = (
        inventory.items()
        if repair_whole_groups
        else (
            (asset_id, inventory[asset_id])
            for asset_id in candidates
            if asset_id in inventory
        )
    )
    for asset_id, asset in inventory_rows:
        asset_id = str(asset_id or '').strip()
        current_group = _asset_group_from_item(asset)
        current_key = _event_model_group_key(current_group)
        extras = previous_groups_by_asset.get(asset_id) or []
        if isinstance(extras, dict):
            extras = [extras]
        groups = _asset_historical_model_groups(asset, extras)
        group_keys = {_event_model_group_key(group) for group in groups}
        current_groups[asset_id] = current_group
        destination_groups[current_key] = current_group
        historical_groups[asset_id] = group_keys
        family_destinations.setdefault(
            _event_model_group_family_key(current_group), set()
        ).add(current_key)
        for group_key in group_keys:
            alias_destinations.setdefault(group_key, set()).add(current_key)

    changed = 0
    repair_group_families = set()

    # Whole-group renames preserve the complete planned quantity, including
    # units which have not been prepared yet.
    if repair_whole_groups:
        event_groups = {}
        for subproject in subprojects:
            for item in subproject.get('items') or []:
                group = _event_subproject_item_group(item)
                if group:
                    event_groups[_event_model_group_key(group)] = group
        if not subprojects:
            for value in getattr(event, 'prepared_items', []) or []:
                group = _parse_model_marker(value)
                if group:
                    event_groups[_event_model_group_key(group)] = group

        for source_key, source_group in list(event_groups.items()):
            destinations = alias_destinations.get(source_key) or set()
            if not destinations:
                # Pre-audit event files have no recorded old description. A
                # unique live description for the same department/brand/model
                # is still sufficient evidence to restore the inventory link.
                destinations = family_destinations.get(
                    _event_model_group_family_key(source_group), set()
                )
                if len(destinations) == 1:
                    alias_destinations[source_key] = set(destinations)
            if len(destinations) != 1:
                continue
            destination_key = next(iter(destinations))
            if destination_key == source_key:
                continue
            evidence_id = next((
                asset_id for asset_id in current_groups
                if (
                    source_key in historical_groups.get(asset_id, set())
                    or _event_model_group_family_key(source_group)
                    == _event_model_group_family_key(current_groups[asset_id])
                )
                and _event_model_group_key(current_groups[asset_id])
                == destination_key
            ), None)
            if not evidence_id:
                continue
            if subprojects:
                group_changes = _update_event_subproject_model_group_references(
                    event,
                    source_group,
                    current_groups[evidence_id],
                )
            else:
                group_changes = _update_event_model_group_references(
                    event,
                    source_group,
                    current_groups[evidence_id],
                )
            changed += group_changes

        # Historical repairs should update the stale marker's identity while
        # retaining its exact quantity. Rebuilding from room rows here can
        # silently discard deliberate event-level spares or adjustments.
        changed += _rewrite_event_model_marker_group_labels(
            event,
            alias_destinations,
            destination_groups,
        )

    # A single-asset rename creates a split group. Move its room ownership and
    # quantity without disturbing the remaining assets in the source group.
    for asset_id in sorted(candidates):
        current_group = current_groups.get(asset_id)
        if not current_group:
            continue
        current_key = _event_model_group_key(current_group)
        owners = []
        for subproject in subprojects:
            for item in subproject.get('items') or []:
                item_group = _event_subproject_item_group(item)
                if not item_group:
                    continue
                for ref in item.get('assetRefs') or []:
                    marker = _parse_bulk_marker(ref)
                    ref_id = (
                        str(marker.get('bulkId') or '').strip()
                        if marker else ref
                    )
                    if ref_id == asset_id:
                        owners.append((item_group, ref))

        mismatched_owners = [
            (group, ref) for group, ref in owners
            if _event_model_group_key(group) != current_key
        ]
        for source_group, ref in mismatched_owners:
            marker = _parse_bulk_marker(ref)
            quantity = (
                max(1, _safe_int(marker.get('quantity'), 1))
                if marker else 1
            )
            group_changes = _move_event_subproject_model_group_quantity(
                event,
                source_group,
                current_group,
                quantity,
                asset_id,
            )
            changed += group_changes
            if group_changes:
                repair_group_families.add(frozenset(
                    set(historical_groups.get(asset_id, set()))
                    | {
                        _event_model_group_key(source_group),
                        current_key,
                    }
                ))

        if owners:
            continue

        # Older event files can contain the prepared ID only at event level.
        # When a whole-group rewrite was ambiguous, move just this asset's
        # quantity from the one matching historical room row.
        matching_source_groups = []
        for subproject in subprojects:
            for item in subproject.get('items') or []:
                source_group = _event_subproject_item_group(item)
                if not source_group:
                    continue
                source_key = _event_model_group_key(source_group)
                if (
                    source_key != current_key
                    and (
                        source_key in historical_groups.get(asset_id, set())
                        or (
                            repair_whole_groups
                            and _event_model_group_family_key(source_group)
                            == _event_model_group_family_key(current_group)
                        )
                    )
                ):
                    matching_source_groups.append(source_group)
        unique_sources = {
            _event_model_group_key(group): group
            for group in matching_source_groups
        }
        if len(unique_sources) != 1:
            continue
        source_group = next(iter(unique_sources.values()))
        quantity = 1
        for ref in event_references.get(asset_id) or []:
            marker = _parse_bulk_marker(ref)
            if marker:
                quantity = max(
                    quantity,
                    max(1, _safe_int(marker.get('quantity'), 1)),
                )
        group_changes = _move_event_subproject_model_group_quantity(
            event,
            source_group,
            current_group,
            quantity,
            asset_id,
        )
        changed += group_changes
        if group_changes:
            repair_group_families.add(frozenset(
                set(historical_groups.get(asset_id, set()))
                | {
                    _event_model_group_key(source_group),
                    current_key,
                }
            ))

    if subprojects and repair_group_families:
        before_markers = list(getattr(event, 'prepared_items', []) or [])
        for family_keys in repair_group_families:
            has_existing_marker = any(
                _event_model_group_key(marker) in family_keys
                for value in getattr(event, 'prepared_items', []) or []
                for marker in [_parse_model_marker(value)]
                if marker
            )
            if has_existing_marker:
                _sync_event_model_markers_from_subprojects(
                    event,
                    family_keys,
                )
        if event.prepared_items != before_markers:
            changed += 1

    # Plan room requirements are authoritative for preparation. A physical
    # asset may have been classified as an extra only because its saved model
    # label no longer matched inventory before the rename repair. Once the
    # identity is repaired, immediately consume matching active extras into
    # open room requirements so the UI cannot show both "needed" and "spare"
    # for the same available unit.
    should_reconcile_rooms = bool(
        repair_whole_groups
        or changed
        or candidates.intersection(event_references)
    )
    if subprojects and should_reconcile_rooms:
        linked_refs = _link_unowned_event_asset_refs_to_subprojects(
            event,
            inventory,
            candidates,
        )
        changed += linked_refs
        room_reconciliation = _reconcile_event_subproject_extras(
            event,
            inventory,
        )
        if room_reconciliation['changed']:
            changed += 1
    return changed


def _repair_all_prepared_event_asset_group_links(manager):
    """Persist every safe event/inventory link repair for one company."""
    if not manager:
        return 0
    repaired_events = 0
    for event in list((getattr(manager, 'events', {}) or {}).values()):
        try:
            changes = _repair_prepared_event_asset_group_links(
                event,
                getattr(manager, 'inventory', {}) or {},
            )
            if not changes:
                continue
            manager.save_event(event)
            repaired_events += 1
        except Exception as exc:
            logger.warning(
                "Unable to repair inventory links for event %s: %s",
                getattr(event, 'event_id', ''),
                exc,
            )
    return repaired_events


def _event_has_model_group_reference(event, group):
    if not event or not group:
        return False

    for item in getattr(event, 'prepared_items', []) or []:
        if _model_marker_matches_group(_parse_model_marker(item), group):
            return True

    old_display = _display_model_description(group)

    for row in getattr(event, 'asset_models', []) or []:
        if not isinstance(row, dict):
            continue

        if str(row.get('model_description', '')).strip() == old_display:
            return True

    return False


def _event_has_specific_group_asset_reference(event, group):
    if not event or not group:
        return False

    seen = set()

    for values in _event_reference_lists(event):
        if not isinstance(values, list):
            continue

        for value in values:
            if not isinstance(value, str) or value in seen:
                continue
            seen.add(value)

            marker = _parse_bulk_marker(value)
            if marker:
                asset = data_manager.inventory.get(marker.get('bulkId')) if data_manager else None
            elif value.startswith('[MODEL]') or _is_prepared_model_ref(value) or _is_custom_ref(value):
                continue
            else:
                asset = data_manager.inventory.get(value) if data_manager else None

            if asset and _asset_matches_group(asset, group):
                return True

    return False


def _add_or_increment_model_marker(prepared_items, group, quantity_to_add=1):
    """
    Add quantity to an existing [MODEL] marker if it already exists.
    Otherwise append a new [MODEL] marker.
    """
    for index, item in enumerate(prepared_items):
        marker = _parse_model_marker(item)

        if _model_marker_matches_group(marker, group):
            try:
                current_qty = int(marker['quantity'])
            except Exception:
                current_qty = 0

            prepared_items[index] = _make_model_marker(group, current_qty + quantity_to_add)
            return 1

    prepared_items.append(_make_model_marker(group, quantity_to_add))
    return 1


def _add_or_increment_asset_model_row(asset_models, group, quantity_to_add=1):
    """
    Add quantity to an existing legacy asset_models row if it already exists.
    Otherwise append a new row.
    """
    new_display = _display_model_description(group)

    for row in asset_models:
        if not isinstance(row, dict):
            continue

        if str(row.get('model_description', '')).strip() == new_display:
            try:
                row['quantity'] = int(row.get('quantity', 0)) + quantity_to_add
            except Exception:
                row['quantity'] = quantity_to_add
            return 1

    asset_models.append({
        'model_description': new_display,
        'quantity': quantity_to_add
    })
    return 1




def _ensure_event_has_model_requirement_for_asset(event, asset, quantity_to_add=1):
    """Ensure the event has a [MODEL] requirement row for this asset's type.

    This is used when preparing/scanning a container: if a container contains an
    asset type that was not originally requested for the event, the event should
    gain a real model requirement row instead of only showing the asset as an
    unrelated extra item.
    """
    if not event or not asset:
        return 0

    if not hasattr(event, 'prepared_items') or event.prepared_items is None:
        event.prepared_items = []
    if not hasattr(event, 'asset_models') or event.asset_models is None:
        event.asset_models = []

    group = _asset_group_from_item(asset)
    changed = _add_or_increment_model_marker(event.prepared_items, group, quantity_to_add)
    changed += _add_or_increment_asset_model_row(event.asset_models, group, quantity_to_add)
    return changed


def _event_model_requirement_quantity_for_group(event, group):
    """Return the required [MODEL] quantity for one exact asset group."""
    if not event or not group:
        return 0

    total = 0
    for item in getattr(event, 'prepared_items', []) or []:
        marker = _parse_model_marker(item)
        if not _model_marker_matches_group(marker, group):
            continue
        try:
            total += int(marker.get('quantity') or 0)
        except Exception:
            continue
    return max(0, total)


def _event_real_asset_count_for_group(event, group):
    """Count non-extra real physical assets from this exact group already tied to the event.

    Manual over-prepared assets stay in event.extra_assets and should not make a
    later container scan raise the model requirement for those earlier manual
    extras. Container scans still raise the requirement for the container asset
    currently being processed.
    """
    if not event or not group:
        return 0

    extra_assets = set(getattr(event, 'extra_assets', []) or [])
    seen = set()
    for values in (
        getattr(event, 'actually_prepared', []) or [],
        getattr(event, 'returned_items', []) or [],
    ):
        for asset_id in values:
            if asset_id in extra_assets:
                continue
            if not _is_real_asset_ref(asset_id):
                continue
            if asset_id in seen:
                continue
            asset = data_manager.inventory.get(asset_id) if data_manager else None
            if asset and _asset_matches_group(asset, group):
                seen.add(asset_id)

    return len(seen)


def _event_model_requirement_remaining_for_asset(event, asset):
    """Return open requirement slots for this exact asset model group.

    This deliberately excludes event.extra_assets so a manual over-prepared
    asset does not consume a required slot or cause the requirement to grow.
    """
    if not event or not asset:
        return 0

    group = _asset_group_from_item(asset)
    required = _event_model_requirement_quantity_for_group(event, group)
    if required <= 0:
        return 0

    non_extra_prepared_or_returned = _event_real_asset_count_for_group(event, group)
    return max(required - non_extra_prepared_or_returned, 0)


def _promote_matching_extra_assets(event):
    """Use matching extras to fill model slots opened by an asset removal."""
    if not event:
        return []

    if getattr(event, 'subprojects', []) or []:
        return _reconcile_event_subproject_extras(event)['promoted']

    if not getattr(event, 'extra_assets', None):
        return []

    assigned_refs = set(getattr(event, 'actually_prepared', []) or [])
    assigned_refs.update(getattr(event, 'returned_items', []) or [])
    promoted = []
    for asset_id in list(event.extra_assets):
        if asset_id not in assigned_refs or not _is_real_asset_ref(asset_id):
            continue
        asset = data_manager.inventory.get(asset_id) if data_manager else None
        if not asset or _event_model_requirement_remaining_for_asset(event, asset) <= 0:
            continue
        event.extra_assets.remove(asset_id)
        _remove_direct_asset_ref_from_prepared_items(event, asset_id)
        promoted.append(asset_id)

    return promoted


def _ensure_event_model_requirement_covers_asset(event, asset, additional_quantity=1):
    """Top up the event's model requirement so prepared container contents do not show as extra.

    When scanning a container, each asset is processed one at a time. The old
    logic only added 1x for the first new model type, then stopped increasing
    the requirement because the type already existed. This helper compares the
    model requirement against the number of prepared/returned physical assets of
    that same type, then increments the [MODEL] row only by the missing amount.
    """
    if not event or not asset:
        return 0

    if not hasattr(event, 'prepared_items') or event.prepared_items is None:
        event.prepared_items = []
    if not hasattr(event, 'asset_models') or event.asset_models is None:
        event.asset_models = []

    group = _asset_group_from_item(asset)
    current_required = _event_model_requirement_quantity_for_group(event, group)
    existing_physical_count = _event_real_asset_count_for_group(event, group)
    minimum_required = existing_physical_count + max(1, _safe_int(additional_quantity, 1))

    if current_required >= minimum_required:
        return 0

    delta = minimum_required - current_required
    _add_or_increment_model_marker(event.prepared_items, group, delta)
    _add_or_increment_asset_model_row(event.asset_models, group, delta)
    return delta


def _ensure_quick_add_model_requirement(event, subproject, asset, additional_quantity=1):
    """Add scanned demand to the active room without consuming its extras.

    Event-wide demand can include an unfilled requirement in another room. Use
    the active room's own prepared count so that quick-add still creates demand
    where the asset was scanned. Existing room extras are deliberately excluded
    by ``_event_subproject_prepared_quantity`` and remain extras.
    """
    if not subproject:
        return _ensure_event_model_requirement_covers_asset(
            event,
            asset,
            additional_quantity,
        )

    group = _asset_group_from_item(asset)
    current_required = _event_subproject_required_quantity(subproject, group)
    prepared_quantity = _event_subproject_prepared_quantity(
        event,
        subproject,
        group,
    )
    minimum_required = prepared_quantity + max(
        1,
        _safe_int(additional_quantity, 1),
    )
    if current_required >= minimum_required:
        return 0

    delta = minimum_required - current_required
    _event_subproject_set_group_quantity(
        subproject,
        group,
        current_required + delta,
    )
    _sync_event_model_markers_from_subprojects(event)
    return delta


def _move_model_marker_quantity(prepared_items, old_group, new_group, quantity_to_move=1):
    if not isinstance(prepared_items, list):
        return 0

    remaining = max(1, _safe_int(quantity_to_move, 1))
    moved = 0
    changed = 0
    rebuilt_items = []

    for item in prepared_items:
        marker = _parse_model_marker(item)

        if remaining <= 0 or not _model_marker_matches_group(marker, old_group):
            rebuilt_items.append(item)
            continue

        old_qty = max(0, _safe_int(marker.get('quantity'), 1))
        move_qty = min(old_qty, remaining)

        if move_qty <= 0:
            rebuilt_items.append(item)
            continue

        leftover_qty = old_qty - move_qty
        if leftover_qty > 0:
            rebuilt_items.append(_make_model_marker(old_group, leftover_qty))

        moved += move_qty
        remaining -= move_qty
        changed += 1

    if moved:
        prepared_items[:] = rebuilt_items
        changed += _add_or_increment_model_marker(prepared_items, new_group, moved)

    return changed


def _move_asset_model_row_quantity(asset_models, old_group, new_group, quantity_to_move=1):
    if not isinstance(asset_models, list):
        return 0

    old_display = _display_model_description(old_group)
    remaining = max(1, _safe_int(quantity_to_move, 1))
    moved = 0
    changed = 0

    for row in list(asset_models):
        if remaining <= 0:
            break

        if not isinstance(row, dict):
            continue

        if str(row.get('model_description', '')).strip() != old_display:
            continue

        old_qty = max(0, _safe_int(row.get('quantity'), 1))
        move_qty = min(old_qty, remaining)

        if move_qty <= 0:
            continue

        leftover_qty = old_qty - move_qty
        if leftover_qty > 0:
            row['quantity'] = leftover_qty
        else:
            asset_models.remove(row)

        moved += move_qty
        remaining -= move_qty
        changed += 1

    if moved:
        changed += _add_or_increment_asset_model_row(asset_models, new_group, moved)

    return changed


def _update_single_asset_event_model_references(
    event,
    old_group,
    new_group,
    quantity_to_move=1,
    asset_id='',
):
    """
    For a single asset edit, update only the referenced quantity of the old
    model requirement inside events where that exact asset was
    assigned, prepared, or returned before.

    Example:
    Old event has:
        [MODEL]AX|Yamaha|QL5|2|Console

    One prepared asset later changes to:
        Yamaha DM7 Compact

    Event becomes:
        [MODEL]AX|Yamaha|QL5|1|Console
        [MODEL]AX|Yamaha|DM7 Compact|1|Console

    Bulk quantity assets may move more than one unit. This preserves total
    requirement quantity and does not affect return logic.
    """
    changed = 0

    has_subprojects = bool(getattr(event, 'subprojects', []) or [])
    if has_subprojects:
        changed += _move_event_subproject_model_group_quantity(
            event,
            old_group,
            new_group,
            quantity_to_move,
            asset_id,
        )
        if changed:
            _sync_event_model_markers_from_subprojects(event)
    else:
        prepared_items = getattr(event, 'prepared_items', []) or []
        changed += _move_model_marker_quantity(
            prepared_items, old_group, new_group, quantity_to_move
        )

    # Older saved events may still contain display rows in asset_models.
    asset_models = getattr(event, 'asset_models', []) or []
    changed += _move_asset_model_row_quantity(asset_models, old_group, new_group, quantity_to_move)

    return changed

def validate_event_data(data, require_location=False):
    """Validate event data"""
    errors = []

    if not data.get('name', '').strip():
        errors.append('Event name is required')

    if len(data.get('name', '')) > 100:
        errors.append('Event name must be less than 100 characters')

    location = str(data.get('location') or '').strip()
    tag = str(data.get('tag') or 'events').strip().lower()
    if require_location and tag != 'dry hire' and not location:
        errors.append('Location is required for events')
    if len(location) > 200:
        errors.append('Location must be less than 200 characters')

    try:
        start_date = datetime.strptime(data['startDate'], '%Y-%m-%d')
        end_date = datetime.strptime(data['endDate'], '%Y-%m-%d')
        if end_date < start_date:
            errors.append('End date must be after start date')
    except (KeyError, ValueError):
        errors.append('Invalid date format')

    return errors


def _next_available_event_id(events=None):
    """Return the lowest positive event ID not currently in use."""
    source = data_manager.events if events is None else events
    used = {
        _safe_int(event_id, 0)
        for event_id in source.keys()
        if _safe_int(event_id, 0) > 0
    }
    candidate = 1
    while candidate in used:
        candidate += 1
    return candidate


def _create_event_with_available_id(factory, attempts=3):
    """Create an event in the first free ID slot, retrying database races."""
    manager = _current_data_manager_object()
    if manager is None:
        raise RuntimeError('Data manager is not initialized')

    last_error = None
    for _attempt in range(max(1, attempts)):
        with _event_creation_lock:
            event_id = _next_available_event_id(manager.events)
            event = factory(event_id)
            manager.events[event_id] = event
            try:
                manager.save_event(event)
                return event
            except ConcurrentDataChangeError as error:
                last_error = error
                if manager.events.get(event_id) is event:
                    manager.events.pop(event_id, None)
                continue
            except Exception:
                if manager.events.get(event_id) is event:
                    manager.events.pop(event_id, None)
                raise

    raise last_error or ConcurrentDataChangeError(
        'An event was created concurrently; try again'
    )


def get_deployed_asset_quantity(events_to_check=None):
    """Physical inventory prepared for events and not yet returned.

    Regular assets are de-duplicated across events, bulk markers contribute
    their prepared quantity, and custom/misc/loan rows are deliberately
    excluded from this operational statistic.
    """
    manager = _current_data_manager_object()
    if manager is None or not getattr(manager, 'events', None):
        return 0

    regular_asset_ids = set()
    bulk_quantity = 0

    source_events = events_to_check if events_to_check is not None else manager.events.values()
    for event in source_events:
        returned = set(getattr(event, 'returned_items', []) or [])
        seen_bulk_refs = set()
        for ref in getattr(event, 'actually_prepared', []) or []:
            if not isinstance(ref, str) or not ref or ref in returned:
                continue
            if _is_custom_ref(ref) or _is_prepared_model_ref(ref) or ref.startswith('[MODEL]'):
                continue

            bulk = _parse_bulk_marker(ref)
            if bulk:
                if ref not in seen_bulk_refs:
                    bulk_quantity += max(1, _safe_int(bulk.get('quantity'), 1))
                    seen_bulk_refs.add(ref)
                continue

            if ref in getattr(manager, 'inventory', {}):
                regular_asset_ids.add(ref)

    return len(regular_asset_ids) + bulk_quantity

def get_assigned_assets():
    """Get all assets currently assigned to events (with caching)"""
    try:
        manager = _current_data_manager_object()
        if manager is None:
            logger.error("get_assigned_assets: data_manager is None")
            return set()
            
        if not hasattr(manager, 'events') or manager.events is None:
            logger.error("get_assigned_assets: data_manager.events is None")
            return set()

        cache = _current_manager_cache()

        # Cache for 30 seconds
        now = datetime.now().timestamp()
        if (cache['assigned_assets'] is not None and
            cache['cache_timestamp'] is not None and
                now - cache['cache_timestamp'] < 30):
            logger.debug("get_assigned_assets: returning cached result")
            return cache['assigned_assets']

        logger.debug(f"get_assigned_assets: processing {len(manager.events)} events")
        
        assigned_assets = set()
        for event in manager.events.values():
            try:
                assigned_assets.update(_active_physical_asset_refs_for_event(event))
                        
            except Exception as e:
                logger.error(f"Error processing event {getattr(event, 'event_id', 'unknown')}: {e}")
                continue

        logger.debug(f"get_assigned_assets: found {len(assigned_assets)} assigned assets")
        
        cache['assigned_assets'] = assigned_assets
        cache['cache_timestamp'] = now
        return assigned_assets
        
    except Exception as e:
        logger.error(f"Error in get_assigned_assets: {e}")
        import traceback
        logger.error(f"get_assigned_assets traceback: {traceback.format_exc()}")
        return set()  # Return empty set on error

def _event_is_last_day(event, current_date=None):
    """Return display-only final-day context without creating another state."""
    today = str(current_date or datetime.now().strftime('%Y%m%d'))
    return (
        normalize_event_state(getattr(event, 'state', 'New')) == 'Ongoing'
        and str(getattr(event, 'end_date', '') or '') == today
    )


def update_event_state(event, workforce=None, changed_by=''):
    """Update the state of an event based on model, bulk, regular, and custom preparation."""
    previous_state = normalize_event_state(getattr(event, 'state', 'New'))
    event.state = previous_state
    state_update_succeeded = True
    try:
        if getattr(event, 'force_state_override', False):
            logger.debug(f"Event {event.event_id} has forced state override, skipping automatic update")
            return

        _ensure_event_custom_lists(event)

        current_date = datetime.now().strftime('%Y%m%d')
        has_model_assignments = any(
            isinstance(item, str) and item.startswith('[MODEL]')
            for item in event.prepared_items
        )

        required_total = 0
        prepared_active_total = 0
        prepared_ever_total = 0
        returned_total = 0
        started_total = 0

        extra_asset_ids = set(getattr(event, 'extra_assets', []) or [])

        if has_model_assignments:
            for item_id in event.prepared_items:
                if not (isinstance(item_id, str) and item_id.startswith('[MODEL]')):
                    continue

                try:
                    parts = item_id[7:].split('|')
                    if len(parts) < 4:
                        continue

                    dept = parts[0]
                    brand = parts[1]
                    model = parts[2]
                    required_quantity = max(0, _safe_int(parts[3], 0))
                    description = '|'.join(parts[4:]) if len(parts) > 4 else ''
                    group_key = _model_key_from_parts(dept, brand, model, description)

                    required_total += required_quantity

                    prepared_group = {
                        'department': dept,
                        'brand': brand,
                        'model': model,
                        'description': description,
                    }
                    assigned_to_this_model = (
                        _bulk_quantity_in_values_for_key(event.actually_prepared, group_key)
                        + _event_prepared_slot_quantity(event, prepared_group)
                        + _event_returned_prepared_slot_quantity(event, prepared_group)
                    )
                    returned_for_this_model = (
                        _bulk_quantity_in_values_for_key(event.returned_items, group_key)
                        + _event_returned_prepared_slot_quantity(event, prepared_group)
                    )

                    all_assigned_assets = set(event.actually_prepared + event.returned_items)
                    for specific_asset_id in all_assigned_assets:
                        if specific_asset_id in extra_asset_ids:
                            continue
                        if (
                            _is_bulk_ref(specific_asset_id)
                            or _is_prepared_model_ref(specific_asset_id)
                            or _is_custom_ref(specific_asset_id)
                        ):
                            continue

                        specific_asset = data_manager.inventory.get(specific_asset_id)
                        if (specific_asset and
                            specific_asset.brand == brand and
                            specific_asset.model_number == model and
                            specific_asset.department_code == dept):

                            assigned_to_this_model += 1
                            if specific_asset_id in event.returned_items:
                                returned_for_this_model += 1

                    prepared_ever_total += assigned_to_this_model
                    returned_total += returned_for_this_model
                    prepared_active_total += max(assigned_to_this_model - returned_for_this_model, 0)
                    if assigned_to_this_model > 0:
                        started_total += assigned_to_this_model

                except Exception as e:
                    logger.error(f"Error parsing model assignment {item_id}: {e}")
                    continue
        else:
            specific_counts = _event_specific_counts(event)
            required_total += specific_counts['required']
            prepared_active_total += specific_counts['preparedActive']
            prepared_ever_total += specific_counts['preparedEver']
            returned_total += specific_counts['returned']
            started_total += specific_counts['preparedEver']

        custom_counts = _custom_counts_for_event(event, exclude_delivered=True)
        required_total += custom_counts['required']
        prepared_active_total += custom_counts['preparedActive']
        prepared_ever_total += custom_counts['preparedEver']
        returned_total += custom_counts['returned']
        started_total += custom_counts['started']

        returned_refs = set(getattr(event, 'returned_items', []) or [])
        has_active_prepared_item = any(
            isinstance(ref, str)
            and ref
            and (
                _is_prepared_model_ref(ref)
                or ref not in returned_refs
            )
            for ref in (getattr(event, 'actually_prepared', []) or [])
        )

        logger.debug(
            f"Event {event.event_id} state calculation - "
            f"required={required_total}, activePrepared={prepared_active_total}, "
            f"everPrepared={prepared_ever_total}, returned={returned_total}, started={started_total}"
        )

        returnable_counts = _event_returnable_counts(event)
        returned_any = returnable_counts['returned'] > 0
        all_returnable_assets_returned = (
            returned_any and
            returnable_counts['returnable'] == 0
        )
        is_ready = required_total > 0 and prepared_active_total >= required_total
        is_active_event_day = event.start_date <= current_date <= event.end_date
        closure_workforce = workforce if isinstance(workforce, dict) else None
        has_workforce_assignments = False
        if (
            required_total == 0
            and not has_active_prepared_item
            and current_date > event.end_date
        ):
            closure_workforce = (
                closure_workforce or load_workforce(_workforce_folder())
            )
            has_workforce_assignments = bool(
                event_assignments(closure_workforce, event.event_id)
            )

        # 1. Every asset that actually left the store is back. Requirements
        # that were never prepared remain visible as a preparation shortfall,
        # but they are not outstanding returns.
        if all_returnable_assets_returned:
            event.state = (
                'Closed'
                if _workforce_financial_closure_complete(
                    event.event_id, event=event, workforce=workforce
                )
                else 'Pending Closure'
            )

        # 2. Once any asset has been returned, the event is in the return flow.
        elif returned_any:
            event.state = 'Returning'

        # 3. Overdue: event ended with prepared, unreturned items.
        elif prepared_ever_total > returned_total and current_date > event.end_date:
            event.state = 'Overdue'

        # 4. Manpower-only events enter financial closure after the event ends.
        elif (
            required_total == 0
            and not has_active_prepared_item
            and current_date > event.end_date
            and has_workforce_assignments
        ):
            event.state = (
                'Closed'
                if _workforce_financial_closure_complete(
                    event.event_id,
                    event=event,
                    workforce=closure_workforce,
                )
                else 'Pending Closure'
            )

        # 5. No requirements at all. A prepared extra still starts preparation,
        # without counting towards completion of any requirement.
        elif required_total == 0:
            event.state = 'Preparing' if has_active_prepared_item else 'New'

        # 6. Requirements exist, but nothing has been collected/prepared yet.
        elif started_total == 0 and not has_active_prepared_item:
            event.state = 'Planning'

        # 7. Some collection/preparation happened, but requirements are not fully prepared.
        elif prepared_active_total < required_total and returned_total == 0:
            event.state = 'Preparing'

        # 8. Required quantity is fully prepared and none returned yet.
        elif is_ready and returned_total == 0:
            if is_active_event_day:
                event.state = 'Ongoing'
            else:
                event.state = 'Ready'

        else:
            logger.debug(f"Event {event.event_id} fell through state calculation; keeping {event.state}")

    except Exception as e:
        state_update_succeeded = False
        logger.error(f"Error updating event state for event {event.event_id}: {e}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")

    current_state = normalize_event_state(getattr(event, 'state', 'New'))
    if state_update_succeeded and current_state != previous_state:
        _queue_event_state_notification(
            manager=_current_data_manager_object(),
            event=event,
            previous_state=previous_state,
            new_state=current_state,
            changed_by=changed_by,
        )


def _event_vendor_management_state_rows(event, finance_data):
    """Return the finance-backed vendor choices needed by event state logic.

    Vendor fulfilment is edited on the linked costing, while event state is
    deliberately calculated from the event record so scans stay fast. Older
    events may therefore be missing the event-side mirror. Rebuild that small
    mirror from the effective Plan/Prepare vendor rows before recalculating the
    state.
    """
    if not isinstance(finance_data, dict):
        return None

    linked_quotations = [
        document
        for document in finance_data.get('documents') or []
        if isinstance(document, dict)
        and document.get('type') == 'quotation'
        and _safe_int(document.get('eventId'), 0) == int(event.event_id)
    ]
    linked_quotations.sort(
        key=lambda row: (row.get('updatedAt', ''), row.get('number', '')),
        reverse=True,
    )
    linked_costing = (
        _linked_costing_for_quotation(finance_data, linked_quotations[0])
        if linked_quotations
        else None
    )
    effective_rows = _event_vendor_management(event, linked_costing)

    rows = []
    seen = set()
    for source in effective_rows:
        if not isinstance(source, dict):
            continue
        vendor_name = str(source.get('vendorName') or '').strip()
        key = str(source.get('key') or _costing_vendor_key(
            vendor_name,
            source.get('vendorType'),
            source.get('vendorId'),
        )).strip()
        mode = str(source.get('mode') or '').strip().lower()
        identity = key or _finance_vendor_company_key(vendor_name)
        if not identity or identity in seen or mode not in {'dry-hire', 'outsourced'}:
            continue
        seen.add(identity)
        rows.append({
            'key': key,
            'vendorId': str(source.get('vendorId') or '').strip(),
            'vendorType': str(source.get('vendorType') or 'vendor').strip(),
            'vendorName': vendor_name,
            'mode': mode,
        })
    return rows


def _refresh_event_vendor_management_mirror(event, finance_data):
    """Synchronise costing vendor fulfilment into the event state mirror."""
    rows = _event_vendor_management_state_rows(event, finance_data)
    if rows is None:
        return False

    current = []
    for source in getattr(event, 'vendor_management', []) or []:
        if not isinstance(source, dict):
            continue
        current.append({
            'key': str(source.get('key') or '').strip(),
            'vendorId': str(source.get('vendorId') or '').strip(),
            'vendorType': str(source.get('vendorType') or 'vendor').strip(),
            'vendorName': str(source.get('vendorName') or '').strip(),
            'mode': str(source.get('mode') or '').strip().lower(),
        })
    if current == rows:
        return False
    event.vendor_management = rows
    return True


def refresh_event_states_for_read(
    events_to_check=None,
    sync_vendor_management=True,
    workforce=None,
    finance_data=None,
):
    """Keep automatically calculated event states current before read responses."""
    manager = _current_data_manager_object()
    if manager is None:
        return []

    # A GET request can overlap a shared-data reload. Keep the manager's event
    # objects stable for the full calculation/save cycle so a stale reference
    # cannot be mistaken for an event with no financial requirements.
    with _data_reload_lock_for(manager):
        return _refresh_event_states_for_read_locked(
            manager,
            events_to_check=events_to_check,
            sync_vendor_management=sync_vendor_management,
            workforce=workforce,
            finance_data=finance_data,
        )


def _refresh_event_states_for_read_locked(
    manager,
    events_to_check=None,
    sync_vendor_management=True,
    workforce=None,
    finance_data=None,
):
    """Refresh event states while the manager's reload lock is held."""

    now = time.monotonic()
    refresh_window_seconds = 15
    cache = _current_manager_cache()
    refreshed_at = cache.setdefault('event_state_refreshes', {})
    updated_events = []
    source_events = (
        events_to_check
        if events_to_check is not None
        else manager.events.values()
    )
    source_events = [
        manager.events.get(int(getattr(event, 'event_id', 0)))
        for event in list(source_events)
        if event
        and manager.events.get(int(getattr(event, 'event_id', 0))) is not None
        and now - refreshed_at.get(event.event_id, 0) >= refresh_window_seconds
    ]
    if not source_events:
        return []

    closure_workforce = (
        workforce
        if isinstance(workforce, dict)
        else load_workforce(_workforce_folder(manager))
    )
    if sync_vendor_management and not isinstance(finance_data, dict):
        try:
            finance_data = _load_finance_data()
        except Exception as finance_error:
            logger.warning(
                "Unable to refresh event vendor fulfilment choices: %s",
                finance_error,
            )

    saved_any = False
    for event in source_events:
        old_state = normalize_event_state(getattr(event, 'state', 'New'))
        event.state = old_state
        vendor_management_changed = bool(
            sync_vendor_management
            and _refresh_event_vendor_management_mirror(event, finance_data)
        )
        update_event_state(
            event,
            workforce=closure_workforce,
            changed_by='Showbase automatic update',
        )

        state_changed = getattr(event, 'state', 'New') != old_state
        if not state_changed and not vendor_management_changed:
            continue

        manager.save_event(event)
        saved_any = True
        if not state_changed:
            continue
        updated_events.append({
            'eventId': event.event_id,
            'name': event.name,
            'oldState': old_state,
            'newState': event.state
        })
        logger.info("Event %s state refreshed for read: %s -> %s", event.event_id, old_state, event.state)

    if saved_any:
        reset_cache()
        mark_data_snapshot_current()
    if updated_events:
        mark_realtime_change('event-state', {'updatedEvents': updated_events[-20:]})

    refreshed_at = _current_manager_cache().setdefault('event_state_refreshes', {})
    refreshed_at.update({event.event_id: now for event in source_events})

    return updated_events

def schedule_ongoing_check():
    """Run the ongoing event check in a background thread"""
    logger.info("Background thread started - checking events every 5 minutes")
    
    while get_default_data_manager() is None:
        logger.info("Background thread: Waiting for data_manager to be initialized...")
        time.sleep(5)
    
    logger.info("Background thread: data_manager is ready, starting checks")
    
    while True:
        try:
            managers = []
            seen_manager_ids = set()
            for company_code in _all_company_records():
                manager = _get_company_data_manager(company_code)
                if id(manager) in seen_manager_ids:
                    continue
                seen_manager_ids.add(id(manager))
                managers.append((company_code, manager))

            for company_code, manager in managers:
                token = _request_data_manager.set(manager)
                try:
                    if hasattr(manager, 'acquire_write_request'):
                        manager.acquire_write_request()
                    try:
                        with _data_reload_lock_for(manager):
                            refresh_shared_data_if_changed()
                            logger.info(
                                "Background thread: checking event states for company %s",
                                company_code,
                            )
                            check_and_update_ongoing_events()
                    finally:
                        if hasattr(manager, 'release_write_request'):
                            manager.release_write_request()
                finally:
                    _request_data_manager.reset(token)
            
            time.sleep(300)
        except Exception as e:
            logger.error(f"Background thread error: {e}")
            import traceback
            logger.error(f"Background thread traceback: {traceback.format_exc()}")
            time.sleep(300)

def start_background_thread():
    """Start the background thread for event checking"""
    global _background_thread_started
    if _background_thread_started:
        logger.info("Background event checker already running")
        return True

    try:
        ongoing_thread = threading.Thread(target=schedule_ongoing_check, daemon=True)
        ongoing_thread.start()
        _background_thread_started = True
        logger.info("Background thread for event checking started successfully")
        return True
    except Exception as e:
        logger.error(f"Failed to start background thread: {e}")
        return False

def init_data_manager():
    """Initialize the data manager with the configured data folder"""
    manager = get_default_data_manager()
    if manager is not None:
        return manager

    with _data_manager_init_lock:
        manager = get_default_data_manager()
        if manager is not None:
            return manager

        try:
            registry = _load_company_registry()
            company_code = registry.get('defaultCompany', DEFAULT_COMPANY_CODE)
            manager = _activate_company(company_code)
            logger.info(
                "Data manager initialized for company %s with folder: %s",
                _active_company_code,
                getattr(manager, 'data_folder', '')
            )
            
            # Start the background thread AFTER data_manager is initialized
            background_started = start_background_thread()
            if not background_started:
                logger.warning("Background thread failed to start - automatic event updates disabled")
            else:
                logger.info("Background thread started successfully after data_manager initialization")
            if not app.config.get('TESTING'):
                if start_telegram_update_poller(_process_telegram_connection_update):
                    logger.info('Telegram admin connection listener started')
                elif telegram_notifications_configured():
                    logger.warning('Telegram admin connection listener did not start')
                
        except Exception as e:
            logger.error(f"Failed to initialize data manager: {e}")
            raise

    return manager


@app.before_request
def ensure_web_runtime_ready():
    """Lazy init for hosted WSGI imports where __main__ is never executed."""
    if request.endpoint == 'health':
        return None
    if get_default_data_manager() is None:
        init_data_manager()
    if request.endpoint != 'static':
        manager = _activate_company_for_session()
        company_code = _user_management_company_for_request(
            _current_company_code()
        )
        if company_code != _normalise_company_code(
            _current_company_code(), DEFAULT_COMPANY_CODE
        ):
            manager = _get_company_data_manager(company_code)
        _bind_request_data_manager(manager)
        if (
            request.method in {'POST', 'PUT', 'PATCH', 'DELETE'}
            and hasattr(manager, 'acquire_write_request')
        ):
            manager.acquire_write_request()
            locks = getattr(g, 'data_manager_write_locks', None)
            if locks is None:
                locks = []
                g.data_manager_write_locks = locks
            locks.append(manager)
        refresh_shared_data_if_changed()


@app.teardown_request
def release_request_data_manager(_error=None):
    """Restore context-local manager bindings after every request."""
    for manager in reversed(getattr(g, 'data_manager_write_locks', [])):
        manager.release_write_request()
    for token in reversed(getattr(g, 'data_manager_tokens', [])):
        _request_data_manager.reset(token)

