@app.route('/login', methods=['GET', 'POST'])
def login():
    """Handle user authentication"""
    if request.method == 'GET':
        if 'user' in session:
            return redirect('/events')
        return render_template(
            'login.html',
            login_js_version=_static_asset_version('js/login.js'),
            login_css_version=_static_asset_version('css/login.css'),
            custom_select_js_version=_static_asset_version('js/custom-select.js'),
            custom_select_css_version=_static_asset_version('css/custom-select.css'),
        )

    try:
        data = request.get_json()
        username = data.get('username', '').strip()
        password = data.get('password', '')

        if not username or not password:
            return jsonify({'success': False, 'message': 'Username and password required'}), 400

        requested_company = _normalise_company_code(data.get('companyCode'))
        matching_companies = _user_company_codes(username)
        if _is_super_admin_username(username):
            registry = _load_company_registry()
            primary_company = _normalise_company_code(
                registry.get('userCompanies', {}).get(username),
                registry.get('defaultCompany', DEFAULT_COMPANY_CODE),
            )
            matching_companies = [primary_company]
        if len(matching_companies) > 1 and requested_company not in matching_companies:
            return jsonify({
                'success': False,
                'message': 'This username exists in more than one company. Select your company.',
                'requiresCompany': True,
                'companies': [
                    {
                        'code': code,
                        'name': _company_payload(code).get('name') or code,
                    }
                    for code in matching_companies
                ],
            }), 409

        login_scope = _user_management_company_for_request(_current_company_code())
        if login_scope == SYSTEM_LOG_COMPANY_CODE:
            log_action(f"Failed login attempt for username: {username}", user=username)
            return jsonify({'success': False, 'message': 'Invalid credentials'}), 401

        if username in data_manager.users:
            user = data_manager.users[username]

            if not getattr(user, 'is_active', True):
                log_action(f"Inactive login attempt for username: {username}", user=username)
                return jsonify({
                    'success': False,
                    'message': 'This account is inactive. Please contact an admin.'
                }), 403

            hashed_input = hash_password(password, user.salt)

            if hashed_input == user.password_hash:
                session['user'] = username
                if _is_super_admin_username(username) and not getattr(user, 'is_admin', False):
                    user.is_admin = True
                _sync_user_role_flags(user)
                user.last_online = datetime.now().astimezone().isoformat(timespec='seconds')
                data_manager.save_users()
                if not app.config.get('TESTING'):
                    _reload_users_for_all_company_managers()
                effective_role = _effective_user_role(user)
                session['role'] = effective_role
                session['is_admin'] = user_role_is_adminish(effective_role)
                session['is_super_admin'] = effective_role == 'owner'
                session['has_sales_access'] = _user_has_sales_access(user)
                session['is_active'] = getattr(user, 'is_active', True)
                session.pop('self_user_changes_pending', None)
                session['company_code'] = _user_assigned_company_code(username)
                _activate_company_for_session()

                log_action(f"User {username} logged in via web interface")
                return jsonify({
                    'success': True,
                    'message': 'Login successful',
                    'redirect': '/events'
                })

        log_action(f"Failed login attempt for username: {username}", user=username)
        return jsonify({'success': False, 'message': 'Invalid credentials'}), 401

    except Exception as e:
        logger.error(f"Login error: {e}")
        return jsonify({'success': False, 'message': 'Login failed'}), 500

@app.route('/logout')
def logout():
    """Handle user logout"""
    if 'user' in session:
        username = session['user']
        log_action(f"User {username} logged out from web interface")
        session.clear()

    return redirect(url_for('login'))


@app.route('/api/realtime/stream', methods=['GET'])
@require_auth
def realtime_stream():
    """Stream shared-data change notices to the logged-in browser."""
    subscriber_id = secrets.token_urlsafe(16)
    subscriber_queue = queue.Queue(maxsize=100)
    client_id = _client_id_from_request()
    subscriber_company_code = _normalise_company_code(
        _current_company_code(),
        DEFAULT_COMPANY_CODE,
    )

    with _realtime_subscribers_lock:
        _realtime_subscribers[subscriber_id] = {
            'queue': subscriber_queue,
            'companyCode': subscriber_company_code,
        }

    def sse_message(event_name, payload):
        payload = payload or {}
        data = json.dumps(payload, ensure_ascii=False)
        event_id = payload.get('id', '')
        id_line = f"id: {event_id}\n" if event_id else ""
        return f"{id_line}event: {event_name}\ndata: {data}\n\n"

    @stream_with_context
    def event_stream():
        requested_last_id = (
            request.headers.get('Last-Event-ID')
            or request.args.get('lastEventId')
            or ''
        )
        current_state = _read_realtime_state() or {}
        current_state_id = str(current_state.get('id') or '')
        last_seen_realtime_id = str(requested_last_id or current_state_id)
        last_heartbeat_at = time.time()

        try:
            yield sse_message('connected', {
                'id': last_seen_realtime_id,
                'topic': 'connected',
                'clientId': client_id,
                'timestamp': datetime.now().isoformat(timespec='seconds')
            })

            while True:
                payload = None
                try:
                    payload = subscriber_queue.get(timeout=1)
                except queue.Empty:
                    payload = None

                if payload and _realtime_payload_matches_company(
                    payload,
                    subscriber_company_code,
                ):
                    last_seen_realtime_id = str(payload.get('id') or last_seen_realtime_id)
                    yield sse_message('inventory-update', payload)
                    continue

                shared_payloads = _read_realtime_events_after(
                    last_seen_realtime_id
                )
                if shared_payloads:
                    for shared_payload in shared_payloads:
                        if not _realtime_payload_matches_company(
                            shared_payload,
                            subscriber_company_code,
                        ):
                            continue
                        shared_payload_id = str(
                            (shared_payload or {}).get('id') or ''
                        )
                        if not shared_payload_id:
                            continue
                        last_seen_realtime_id = shared_payload_id
                        yield sse_message('inventory-update', shared_payload)
                    continue

                if time.time() - last_heartbeat_at >= 25:
                    last_heartbeat_at = time.time()
                    yield ": heartbeat\n\n"
        finally:
            with _realtime_subscribers_lock:
                _realtime_subscribers.pop(subscriber_id, None)

    return Response(
        event_stream(),
        mimetype='text/event-stream',
        headers={
            'Cache-Control': 'no-cache',
            'X-Accel-Buffering': 'no',
        }
    )


@app.route('/api/current-user', methods=['GET'])
@require_auth
def get_current_user():
    """Get the currently logged-in user"""
    user = _current_user_obj()

    if not user:
        return jsonify({'error': 'User not found'}), 404

    payload = _user_payload(user, reveal_owner=_current_user_is_owner())
    internal_role = (
        session.get('role', _effective_user_role(user))
        if session.get('self_user_changes_pending')
        else _effective_user_role(user)
    )
    public_role = internal_role
    payload.update({
        'role': public_role,
        'isAdmin': _current_user_effective_is_admin(),
        'isSuperAdmin': _current_user_is_owner(),
        'hasSalesAccess': _current_user_has_sales_access(),
        'isSales': _current_user_has_sales_access(),
        'isActive': _current_user_effective_is_active(),
        'company': _company_payload(_current_company_code()),
        'assignedCompanyCode': _user_assigned_company_code(user.username),
        'canManageRoles': _current_user_can_manage_roles(),
        'hasPendingSelfChanges': bool(session.get('self_user_changes_pending')),
    })
    payload['roleLabel'] = _role_label(public_role)

    return jsonify({'success': True, 'data': payload})


@app.route('/api/current-user/password', methods=['PUT'])
@require_auth
def change_current_user_password():
    """Allow the signed-in user to change their own password."""
    try:
        username = session.get('user')
        user = data_manager.users.get(username)

        if not user:
            return jsonify({'error': 'User not found'}), 404

        data = request.get_json() or {}
        current_password = data.get('currentPassword') or ''
        new_password = data.get('newPassword') or ''

        if not current_password:
            return jsonify({'error': 'Current password is required'}), 400

        if not new_password:
            return jsonify({'error': 'New password is required'}), 400

        if hash_password(current_password, user.salt) != user.password_hash:
            return jsonify({'error': 'Current password is incorrect'}), 403

        user.salt = secrets.token_hex(16)
        user.password_hash = hash_password(new_password, user.salt)

        data_manager.save_users()
        _reload_users_for_all_company_managers()
        log_action("Changed own password")

        return jsonify({'success': True, 'message': 'Password changed successfully'})

    except Exception as e:
        logger.error(f"Error changing password for current user: {e}")
        return jsonify({'error': 'Failed to change password'}), 500


@app.route('/api/companies', methods=['GET'])
@require_super_admin
def list_companies():
    """Owner: list companies and user assignments."""
    try:
        registry = _load_company_registry()
        companies = []
        users_by_company = defaultdict(dict)
        test_manager = app.config.get('TEST_DATA_MANAGER')
        if app.config.get('TESTING') and test_manager is not None:
            # CSV-backed tests retain the historical global user collection.
            for username, user in data_manager.users.items():
                code = (
                    registry.get('userCompanies', {}).get(username)
                    or registry.get('defaultCompany', DEFAULT_COMPANY_CODE)
                )
                users_by_company[code][username] = user
        else:
            # PostgreSQL users are company-scoped, so each company manager is
            # authoritative for its own membership list.
            for code in registry.get('companies', {}):
                manager = (
                    _current_data_manager_object()
                    if code == _current_company_code()
                    else _get_company_data_manager(code)
                )
                for username, user in manager.users.items():
                    users_by_company[code][username] = user

        for code, record in sorted(registry['companies'].items(), key=lambda item: item[0]):
            payload = _company_payload(code)
            company_users = users_by_company.get(code, {})
            company_usernames = [
                username for username in company_users
                if not _is_owner_username(username)
            ]
            role_counts = {'admin': 0, 'manager': 0, 'user': 0}
            sales_personnel_count = 0
            active_user_count = 0
            for username in company_usernames:
                user = company_users.get(username)
                role = _effective_user_role(user or username)
                role_counts[role if role in role_counts else 'user'] += 1
                if user and getattr(user, 'is_active', False):
                    active_user_count += 1
                if user and getattr(user, 'has_sales_access', False):
                    sales_personnel_count += 1

            storage = _company_storage_usage(code)
            payload['userCount'] = len(company_usernames)
            payload['activeUserCount'] = active_user_count
            payload['roleCounts'] = role_counts
            payload['salesPersonnelCount'] = sales_personnel_count
            payload['users'] = sorted(company_usernames, key=lambda value: value.lower())
            payload['storageBytes'] = storage['totalBytes']
            payload['storageFileCount'] = storage['fileCount']
            payload['storageRecordCount'] = storage['recordCount']
            payload['isActive'] = code == _current_company_code()
            companies.append(payload)

        return jsonify({'success': True, 'data': companies})
    except Exception as e:
        logger.error(f"Error listing companies: {e}", exc_info=True)
        return jsonify({'error': 'Failed to list companies'}), 500


