@app.route('/api/pdf-settings', methods=['PUT'])
@require_admin
def update_pdf_settings():
    """Update company identity, billing, tax, logo-footer and finance defaults."""
    try:
        data = request.get_json() or {}
        settings = _load_pdf_settings()
        previous_settings = copy.deepcopy(settings)
        text_fields = (
            'footerText', 'companyName', 'registrationNumber', 'billingAddress',
            'phone', 'email', 'website', 'bankName', 'bankAccountName',
            'bankAccountNumber', 'paynowUen', 'currency', 'taxLabel',
            'quotationPrefix', 'invoicePrefix', 'defaultPaymentTerms',
            'defaultTerms', 'themeColor', 'fontFamily', 'letterheadText',
            'paymentDetailsText', 'letterheadHtml', 'footerHtml',
            'defaultTermsHtml', 'paymentDetailsHtml',
        )
        for key in text_fields:
            if key not in data:
                continue
            value = str(data.get(key) or '')
            max_length = 20000 if key.endswith('Html') else 5000 if key == 'defaultTerms' else 2000
            if len(value) > max_length:
                return jsonify({'error': f'{key} is too long'}), 400
            settings[key] = value

        for text_key, html_key in (
            ('letterheadText', 'letterheadHtml'),
            ('footerText', 'footerHtml'),
            ('defaultTerms', 'defaultTermsHtml'),
            ('paymentDetailsText', 'paymentDetailsHtml'),
        ):
            if text_key in data and html_key not in data:
                settings[html_key] = ''

        typography_fields = (
            'letterheadTypography',
            'footerTypography',
            'termsTypography',
            'paymentDetailsTypography',
        )
        for key in typography_fields:
            if key in data:
                settings[key] = data.get(key) if isinstance(data.get(key), dict) else {}

        if 'letterheadText' in data:
            settings['letterheadEnabled'] = bool(
                str(data.get('letterheadText') or '').strip()
            )
        if 'letterheadEnabled' in data:
            settings['letterheadEnabled'] = bool(data.get('letterheadEnabled'))

        if 'paymentDetailsText' in data:
            settings['paymentDetailsEnabled'] = bool(
                str(data.get('paymentDetailsText') or '').strip()
            )
        if 'paymentDetailsEnabled' in data:
            settings['paymentDetailsEnabled'] = bool(data.get('paymentDetailsEnabled'))

        if 'taxRate' in data:
            settings['taxRate'] = _safe_float(data.get('taxRate'), 0)
        if 'defaultValidityDays' in data:
            settings['defaultValidityDays'] = _safe_int(data.get('defaultValidityDays'), 30)

        settings['updatedAt'] = datetime.now().isoformat(timespec='seconds')
        saved = _save_pdf_settings(settings)
        _mark_company_branding_setup_complete()

        company_detail_fields = tuple(
            (key, re.sub(r'(?<!^)(?=[A-Z])', ' ', key).capitalize())
            for key in (
                *text_fields,
                'letterheadEnabled',
                'paymentDetailsEnabled',
                'taxRate',
                'defaultValidityDays',
                *typography_fields,
            )
            if key in data
        )
        company_changes = _audit_change_details(
            previous_settings,
            saved,
            company_detail_fields,
            sensitive_fields={
                'bankAccountNumber',
                'letterheadText',
                'paymentDetailsText',
                'defaultTerms',
                'letterheadHtml',
                'footerHtml',
                'defaultTermsHtml',
                'paymentDetailsHtml',
            },
        )
        log_action(f"Updated company details: {company_changes}")

        return jsonify({'success': True, 'data': _pdf_settings_payload(saved)})
    except Exception as e:
        logger.error(f"Error updating PDF settings: {e}", exc_info=True)
        return jsonify({'error': 'Failed to update PDF settings'}), 500


