@app.route('/api/departments', methods=['GET'])
@require_auth
def get_departments():
    """Return the configurable department list used by filters and badges."""
    try:
        departments = _load_departments()
        usage_counts = defaultdict(int)

        for asset in data_manager.inventory.values():
            if _is_disposed(asset):
                continue
            code = _normalise_department_code(getattr(asset, 'department_code', 'UN')) or 'UN'
            usage_counts[code] += _asset_inventory_quantity(asset)

        data = []
        for code in sorted(departments.keys()):
            dept = _department_payload(code, departments)
            data.append({
                'code': dept['code'],
                'name': dept['name'],
                'color': dept['color'],
                'textColor': dept['textColor'],
                'assetCount': usage_counts.get(code, 0)
            })

        return jsonify({'success': True, 'data': data})
    except Exception as e:
        logger.error(f"Error loading departments: {e}", exc_info=True)
        return jsonify({'error': 'Failed to load departments'}), 500


@app.route('/api/departments', methods=['POST'])
@require_admin
def create_department():
    """Admin: create a new department code/name/colour."""
    try:
        data = request.get_json() or {}
        code = _normalise_department_code(data.get('code'))
        name = str(data.get('name') or '').strip()
        colour = _normalise_hex_colour(data.get('color'))

        if not code:
            return jsonify({'error': 'Department code is required'}), 400

        departments = _load_departments()
        if code in departments:
            return jsonify({'error': f'Department {code} already exists'}), 409

        departments[code] = _department_record(code, name or code, colour)
        _save_departments(departments)
        mark_realtime_change('departments', {
            'action': 'created',
            'department': departments[code],
        })

        log_action(f"Created department {code} ({name or code})")

        return jsonify({'success': True, 'message': 'Department created successfully', 'data': departments[code]})
    except Exception as e:
        logger.error(f"Error creating department: {e}", exc_info=True)
        return jsonify({'error': 'Failed to create department'}), 500


@app.route('/api/departments/<path:department_code>', methods=['PUT'])
@require_admin
def update_department(department_code):
    """Admin: rename a department code, change display name, or change colour.

    If the code changes, all inventory rows and model requirement markers in event
    CSV files are updated so old events remain linked correctly.
    """
    try:
        old_code = _normalise_department_code(unquote_plus(department_code))
        data = request.get_json() or {}
        new_code = _normalise_department_code(data.get('code') or old_code)
        raw_name = data.get('name')
        raw_colour = data.get('color')

        if not old_code:
            return jsonify({'error': 'Department code is required'}), 400

        if not new_code:
            return jsonify({'error': 'New department code is required'}), 400

        departments = _load_departments()
        if old_code not in departments:
            # Allow repair of legacy codes that exist in inventory but not in Departments.csv.
            if not any(_normalise_department_code(getattr(a, 'department_code', '')) == old_code for a in data_manager.inventory.values()):
                return jsonify({'error': f'Department {old_code} not found'}), 404
            departments[old_code] = _department_record(old_code)

        if new_code != old_code and new_code in departments:
            return jsonify({'error': f'Department {new_code} already exists'}), 409

        previous = departments.pop(old_code)
        name = str(raw_name if raw_name is not None else previous.get('name', new_code)).strip() or new_code
        colour = _normalise_hex_colour(raw_colour, previous.get('color', '#e2e3e5'))
        departments[new_code] = _department_record(new_code, name, colour, _best_text_colour(colour))
        _save_departments(departments)

        assets_updated = 0
        events_updated = 0
        model_markers_updated = 0
        asset_model_rows_updated = 0

        if new_code != old_code:
            for asset in data_manager.inventory.values():
                if _normalise_department_code(getattr(asset, 'department_code', '')) == old_code:
                    asset.department_code = new_code
                    assets_updated += 1

            for event in data_manager.events.values():
                changed = 0

                custom_replacements = {}

                if isinstance(getattr(event, 'prepared_items', None), list):
                    for index, item in enumerate(list(event.prepared_items)):
                        replacement, did_change = _replace_department_in_model_marker(item, old_code, new_code)
                        if did_change:
                            event.prepared_items[index] = replacement
                            changed += 1
                            model_markers_updated += 1
                            continue

                        replacement, did_change = _replace_department_in_custom_marker(item, old_code, new_code)
                        if did_change:
                            event.prepared_items[index] = replacement
                            custom_replacements[item] = replacement
                            changed += 1

                if custom_replacements:
                    for list_name in ('actually_prepared', 'returned_items', 'extra_assets', 'custom_collected'):
                        values = getattr(event, list_name, None)
                        if not isinstance(values, list):
                            continue
                        for i, value in enumerate(list(values)):
                            if value in custom_replacements:
                                values[i] = custom_replacements[value]

                if isinstance(getattr(event, 'asset_models', None), list):
                    for row in event.asset_models:
                        if not isinstance(row, dict):
                            continue
                        replacement, did_change = _replace_department_in_model_description(
                            str(row.get('model_description', '')),
                            old_code,
                            new_code
                        )
                        if did_change:
                            row['model_description'] = replacement
                            changed += 1
                            asset_model_rows_updated += 1

                if changed:
                    update_event_state(event)
                    data_manager.save_event(event)
                    events_updated += 1

            if assets_updated:
                data_manager.save_inventory()

        invalidate_cache()
        mark_realtime_change('departments', {
            'action': 'updated',
            'oldCode': old_code,
            'department': departments[new_code],
        })

        log_action(
            f"Updated department {old_code} -> {new_code}; "
            f"name='{previous.get('name')}' -> '{name}'; "
            f"assetsUpdated={assets_updated}; eventsUpdated={events_updated}"
        )

        return jsonify({
            'success': True,
            'message': 'Department updated successfully',
            'data': {
                'department': departments[new_code],
                'assetsUpdated': assets_updated,
                'eventsUpdated': events_updated,
                'modelMarkersUpdated': model_markers_updated,
                'assetModelRowsUpdated': asset_model_rows_updated
            }
        })
    except Exception as e:
        logger.error(f"Error updating department {department_code}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to update department'}), 500


@app.route('/api/departments/<path:department_code>', methods=['DELETE'])
@require_admin
def delete_department(department_code):
    """Admin: delete an unused department tag."""
    try:
        code = _normalise_department_code(unquote_plus(department_code))
        if not code:
            return jsonify({'error': 'Department code is required'}), 400

        departments = _load_departments()
        if code not in departments:
            return jsonify({'error': f'Department {code} not found'}), 404

        asset_count = 0
        for asset in data_manager.inventory.values():
            if _normalise_department_code(getattr(asset, 'department_code', '')) != code:
                continue
            asset_count += max(1, _safe_int(getattr(asset, 'quantity', 1), 1)) if _is_bulk_asset(asset) else 1

        if asset_count:
            return jsonify({
                'error': f'Department {code} cannot be deleted because it still has {asset_count} asset(s). Move or delete those assets first.',
                'assetCount': asset_count,
            }), 409

        removed = departments.pop(code)
        _save_departments(departments)
        invalidate_cache()
        mark_realtime_change('departments', {
            'action': 'deleted',
            'departmentCode': code,
        })
        log_action(f"Deleted department {code} ({removed.get('name') or code})")

        return jsonify({'success': True, 'message': 'Department deleted successfully'})
    except Exception as e:
        logger.error(f"Error deleting department {department_code}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to delete department'}), 500


@app.route('/api/maintenance/users', methods=['GET'])
@require_auth
def get_maintenance_user_options():
    """List active company users available for maintenance attribution."""
    current_company = _normalise_company_code(
        _current_company_code(),
        DEFAULT_COMPANY_CODE,
    )
    rows = []
    for user in data_manager.users.values():
        username = str(getattr(user, 'username', '') or '').strip()
        if not username or not getattr(user, 'is_active', True):
            continue
        if _owner_identity_is_hidden(username):
            continue
        assigned_company = _normalise_company_code(
            _user_assigned_company_code(username),
            DEFAULT_COMPANY_CODE,
        )
        if assigned_company != current_company:
            continue
        display_name = str(getattr(user, 'name', '') or '').strip() or username
        rows.append({
            'username': username,
            'name': display_name,
        })

    rows.sort(key=lambda row: (row['name'].lower(), row['username'].lower()))
    return jsonify({'success': True, 'data': rows})


@app.route('/api/users', methods=['GET'])
@require_admin
def get_users():
    """Admin: list users"""
    users_data = []
    can_see_owners = _current_user_is_owner()
    can_see_all_companies = _current_user_is_super_admin()
    current_company_code = _normalise_company_code(_current_company_code(), DEFAULT_COMPANY_CODE)
    current_username = str(session.get('user') or '').strip()
    registry = _load_company_registry()

    if can_see_all_companies:
        # PostgreSQL stores users inside each company boundary. Owners need one
        # global view, with shared identities such as the owner deduplicated.
        global_users = {}
        for company_code in sorted(registry.get('companies', {})):
            manager = (
                _current_data_manager_object()
                if company_code == current_company_code
                else _get_company_data_manager(company_code)
            )
            for user in manager.users.values():
                username = str(user.username or '').strip()
                if not username:
                    continue
                identity_key = (
                    ('owner', username.casefold())
                    if _is_owner_username(username)
                    else (company_code, username.casefold())
                )
                existing = global_users.get(identity_key)
                assigned_company = _normalise_company_code(
                    _user_assigned_company_code(username),
                    DEFAULT_COMPANY_CODE,
                )
                if existing is None or company_code == assigned_company:
                    global_users[identity_key] = (user, company_code)
        user_rows = global_users.values()
    else:
        user_rows = (
            (user, _user_assigned_company_code(user.username))
            for user in data_manager.users.values()
        )

    for user, company_code in sorted(
        user_rows,
        key=lambda row: row[0].username.lower(),
    ):
        if not can_see_owners and _is_owner_username(user.username):
            continue
        if (
            not can_see_all_companies
            and user.username != current_username
            and _normalise_company_code(company_code, DEFAULT_COMPANY_CODE) != current_company_code
        ):
            continue

        payload = _user_payload(user, reveal_owner=can_see_owners)
        payload['companyCode'] = company_code
        payload['companyName'] = _company_payload(company_code).get('name')
        notification_manager = (
            _current_data_manager_object()
            if _normalise_company_code(company_code, DEFAULT_COMPANY_CODE)
            == current_company_code
            else _get_company_data_manager(company_code)
        )
        telegram_profile = public_admin_telegram_profile(
            notification_manager,
            user.username,
        )
        payload['telegramConnected'] = bool(telegram_profile.get('connected'))
        payload['telegramUsername'] = str(
            telegram_profile.get('telegramUsername') or ''
        )
        users_data.append(payload)

    return jsonify({'success': True, 'data': users_data})


@app.route('/api/users', methods=['POST'])
@require_admin
def create_user():
    """Admin: create user"""
    try:
        data = request.get_json() or {}

        username = (data.get('username') or '').strip()
        name = (data.get('name') or '').strip()
        raw_phone = str(data.get('phone') or '').strip()
        phone = format_user_phone(raw_phone)
        password = data.get('password') or ''
        is_active = bool(data.get('isActive', True))
        requested_company = _normalise_company_code(data.get('companyCode') or _current_company_code(), DEFAULT_COMPANY_CODE)
        role_fields = {'role', 'isAdmin', 'isOwner', 'isSuperAdmin', 'hasSalesAccess', 'isSales'}
        role_payload_present = any(field in data for field in role_fields)
        requested_role = _requested_role_from_payload(data) if role_payload_present else 'user'
        has_sales_access = bool(data.get('hasSalesAccess', data.get('isSales', False)))

        if not username:
            return jsonify({'error': 'Username is required'}), 400

        if not password:
            return jsonify({'error': 'Password is required'}), 400

        if raw_phone and not phone:
            return jsonify({'error': 'Enter a valid phone number with country code'}), 400

        if username in data_manager.users:
            return jsonify({'error': 'User already exists'}), 409

        history_counts = _username_history_reference_counts(data_manager, username)
        if history_counts.get('total', 0) and not bool(data.get('inheritHistory')):
            return jsonify({
                'error': (
                    f'Prior logs or quotations exist for {username} in this company. '
                    'Creating the account will transfer ownership of those records to it.'
                ),
                'requiresHistoryInheritanceConfirmation': True,
                'historyCounts': history_counts,
            }), 409

        if (
            role_payload_present
            and not _current_user_can_assign_user_role(requested_role)
        ):
            return jsonify({
                'error': 'You cannot create a user with this access level'
            }), 403

        if data.get('companyCode') and not _current_user_is_owner():
            return jsonify({'error': 'You do not have permission to assign users to companies'}), 403

        if requested_role == 'owner' and not _current_user_is_owner():
            return jsonify({'error': 'You do not have permission to grant this access level'}), 403

        if requested_company not in _all_company_records():
            return jsonify({'error': 'Company not found'}), 404

        if (
            not _active_company_admin_usernames(requested_company)
            and not _current_user_is_owner()
            and (
                requested_role != 'admin'
                or not is_active
                or _is_owner_username(username)
            )
        ):
            return jsonify({
                'error': (
                    f'{_company_payload(requested_company).get("name") or requested_company} '
                    'does not have an active admin. Create this user as an active admin first.'
                )
            }), 409

        salt = secrets.token_hex(16)
        password_hash = hash_password(password, salt)

        data_manager.users[username] = User(
            username=username,
            password_hash=password_hash,
            salt=salt,
            is_admin=user_role_is_adminish(requested_role),
            is_active=is_active,
            role=requested_role,
            has_sales_access=has_sales_access,
            name=name,
            phone=phone,
        )

        data_manager.save_users()
        if requested_role == 'owner':
            _set_user_super_admin(username, True)
        _reload_users_for_all_company_managers()
        _assign_user_to_company(username, requested_company)
        log_action(f"Created user {username}")
        notification_manager = (
            data_manager
            if _normalise_company_code(requested_company, DEFAULT_COMPANY_CODE)
            == _current_company_code()
            else _get_company_data_manager(requested_company)
        )
        _queue_access_control_notification(
            manager=notification_manager,
            action='User account created',
            target_user=username,
            detail=(
                f'Access level: {requested_role}; '
                f'Active: {"Yes" if is_active else "No"}'
            ),
        )

        return jsonify({
            'success': True,
            'message': 'User created successfully',
            'inheritedHistory': history_counts,
        })

    except Exception as e:
        logger.error(f"Error creating user: {e}")
        return jsonify({'error': 'Failed to create user'}), 500


@app.route('/api/users/<username>', methods=['PUT'])
@require_admin
def update_user(username):
    """Admin: update username, privilege, and active state"""
    try:
        old_username = unquote_plus(username)
        was_self_update = old_username == session.get('user')

        user = data_manager.users.get(old_username)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        if not _current_user_can_manage_user(old_username):
            return jsonify({
                'error': 'You cannot manage this user or access level'
            }), 403

        target_role = _effective_user_role(user)
        user_audit_before = {
            'name': str(getattr(user, 'name', '') or ''),
            'phone': str(getattr(user, 'phone', '') or ''),
            'role': target_role,
            'hasSalesAccess': bool(getattr(user, 'has_sales_access', False)),
            'isActive': bool(getattr(user, 'is_active', True)),
        }
        if target_role == 'owner' and not _current_user_is_owner():
            return jsonify({'error': 'This protected account cannot be changed'}), 403

        data = request.get_json() or {}
        username_changed = False
        renamed_from = old_username
        renamed_to = old_username
        history_company_code = _normalise_company_code(
            data.get('sourceCompanyCode')
            or getattr(data_manager, 'company_code', None)
            or _user_assigned_company_code(old_username),
            DEFAULT_COMPANY_CODE,
        )
        rename_counts = None
        requested_company = None
        requested_role = None
        requested_sales_access = None
        role_fields = {'role', 'isAdmin', 'isOwner', 'isSuperAdmin', 'hasSalesAccess', 'isSales'}
        role_payload_present = any(field in data for field in role_fields)

        if role_payload_present and not _current_user_can_manage_users():
            return jsonify({'error': 'You cannot change user permissions'}), 403

        if 'companyCode' in data:
            if not _current_user_is_owner():
                return jsonify({'error': 'You do not have permission to assign users to companies'}), 403
            requested_company = _normalise_company_code(data.get('companyCode'), DEFAULT_COMPANY_CODE)
            if requested_company not in _all_company_records():
                return jsonify({'error': 'Company not found'}), 404

        if role_payload_present:
            requested_role = _requested_role_from_payload(data, target_role)
            if (
                requested_role
                and not _current_user_can_assign_user_role(requested_role)
            ):
                return jsonify({
                    'error': 'You cannot grant this access level'
                }), 403
            if requested_role == 'owner' and not _current_user_is_owner():
                return jsonify({'error': 'You do not have permission to grant this access level'}), 403
            if 'hasSalesAccess' in data or 'isSales' in data:
                requested_sales_access = bool(data.get('hasSalesAccess', data.get('isSales', False)))

        source_company = _normalise_company_code(
            history_company_code,
            DEFAULT_COMPANY_CODE,
        )
        proposed_company = _normalise_company_code(
            requested_company or source_company,
            DEFAULT_COMPANY_CODE,
        )
        proposed_role = requested_role or target_role
        proposed_active = (
            bool(data.get('isActive'))
            if 'isActive' in data
            else getattr(user, 'is_active', True)
        )
        removes_active_admin = (
            target_role == 'admin'
            and getattr(user, 'is_active', True)
            and (
                proposed_role != 'admin'
                or not proposed_active
                or proposed_company != source_company
            )
        )
        if (
            removes_active_admin
            and not _current_user_is_owner()
            and len(_active_company_admin_usernames(source_company)) <= 1
        ):
            return jsonify({
                'error': _last_company_admin_error(
                    source_company,
                    self_update=was_self_update,
                )
            }), 409

        if 'name' in data:
            user.name = (data.get('name') or '').strip()

        if 'phone' in data:
            raw_phone = str(data.get('phone') or '').strip()
            phone = format_user_phone(raw_phone)
            if raw_phone and not phone:
                return jsonify({'error': 'Enter a valid phone number with country code'}), 400
            user.phone = phone

        # Rename user
        if 'username' in data:
            new_username = (data.get('username') or '').strip()

            if not new_username:
                return jsonify({'error': 'Username cannot be empty'}), 400

            if new_username != old_username and new_username in data_manager.users:
                return jsonify({'error': 'Username already exists'}), 409

            if new_username != old_username:
                del data_manager.users[old_username]
                user.username = new_username
                data_manager.users[new_username] = user
                username_changed = True
                renamed_to = new_username

                # If admin renamed themselves, keep session valid
                if session.get('user') == old_username:
                    session['user'] = new_username

                rename_counts = _update_username_history_references(
                    old_username,
                    new_username,
                    history_company_code,
                )

        if requested_role:
            user.role = requested_role
            user.is_admin = user_role_is_adminish(requested_role)

        if requested_sales_access is not None:
            user.has_sales_access = requested_sales_access

        # Update active state
        if 'isActive' in data:
            new_is_active = bool(data.get('isActive'))

            user.is_active = new_is_active

        if username_changed:
            _unassign_user_from_company(renamed_from, history_company_code)
            _assign_user_to_company(renamed_to, history_company_code)
            _rename_super_admin_reference(renamed_from, renamed_to)

        try:
            if requested_role == 'owner':
                user.is_admin = True
                _set_user_super_admin(user.username, True)
            elif requested_role and target_role == 'owner':
                _set_user_super_admin(user.username, False)
        except ValueError as e:
            return jsonify({'error': str(e)}), 400

        _sync_user_role_flags(user)
        data_manager.save_users()

        if requested_company:
            source_company = _normalise_company_code(
                history_company_code,
                DEFAULT_COMPANY_CODE,
            )
            target_company = _normalise_company_code(
                requested_company,
                DEFAULT_COMPANY_CODE,
            )
            if (
                target_company != source_company
                and _effective_user_role(user) != 'owner'
            ):
                move_user = getattr(data_manager, 'move_user_to_company', None)
                if callable(move_user):
                    try:
                        move_user(user.username, target_company, user)
                    except ValueError as error:
                        return jsonify({'error': str(error)}), 409
                _unassign_user_from_company(user.username, source_company)
            _assign_user_to_company(user.username, target_company)

        notification_manager = _current_data_manager_object()
        if username_changed:
            rename_admin_telegram(
                notification_manager,
                renamed_from,
                renamed_to,
            )
        final_role = normalize_user_role(
            getattr(user, 'role', None),
            getattr(user, 'is_admin', False),
        )
        moved_company = bool(
            requested_company
            and _normalise_company_code(requested_company, DEFAULT_COMPANY_CODE)
            != _normalise_company_code(history_company_code, DEFAULT_COMPANY_CODE)
        )
        if not getattr(user, 'is_active', True) or moved_company:
            disconnect_admin_telegram(notification_manager, user.username)

        _reload_users_for_all_company_managers()

        if was_self_update:
            session['self_user_changes_pending'] = True

        if username_changed:
            if rename_counts is None:
                rename_counts = {}
            maintenance_reference_count = (
                rename_counts.get('maintenanceLogs', 0)
                + rename_counts.get('containerMaintenanceLogs', 0)
            )
            log_action(
                f"Renamed user {renamed_from} -> {renamed_to}; "
                f"updated {rename_counts.get('systemLogs', 0)} system log(s), "
                f"{rename_counts.get('eventLogs', 0)} event log(s), "
                f"{maintenance_reference_count} maintenance record(s), "
                f"{rename_counts.get('financeDocuments', 0)} quotation(s)"
            )
            if maintenance_reference_count:
                invalidate_cache()
        else:
            user_audit_after = {
                'name': str(getattr(user, 'name', '') or ''),
                'phone': str(getattr(user, 'phone', '') or ''),
                'role': _effective_user_role(user),
                'hasSalesAccess': bool(getattr(user, 'has_sales_access', False)),
                'isActive': bool(getattr(user, 'is_active', True)),
            }
            user_changes = _audit_change_details(
                user_audit_before,
                user_audit_after,
                (
                    ('name', 'Name'),
                    ('phone', 'Phone'),
                    ('role', 'Access level'),
                    ('hasSalesAccess', 'Sales access'),
                    ('isActive', 'Active'),
                ),
            )
            log_action(f"Updated user {user.username}: {user_changes}")

        access_action = 'User account renamed' if username_changed else 'User account updated'
        access_detail = (
            f'{renamed_from} → {renamed_to}'
            if username_changed
            else user_changes
        )
        source_notification_manager = notification_manager
        _queue_access_control_notification(
            manager=source_notification_manager,
            action=access_action,
            target_user=user.username,
            detail=access_detail,
        )
        if moved_company:
            target_notification_manager = _get_company_data_manager(requested_company)
            if target_notification_manager is not source_notification_manager:
                _queue_access_control_notification(
                    manager=target_notification_manager,
                    action='User assigned to company',
                    target_user=user.username,
                    detail=f'Access level: {final_role}',
                )

        response_user = _user_payload(
            user,
            reveal_owner=_current_user_is_owner(),
        )
        response_notification_manager = (
            _get_company_data_manager(requested_company)
            if moved_company
            else notification_manager
        )
        telegram_profile = public_admin_telegram_profile(
            response_notification_manager,
            user.username,
        )
        response_user['telegramConnected'] = bool(
            telegram_profile.get('connected')
        )
        response_user['telegramUsername'] = str(
            telegram_profile.get('telegramUsername') or ''
        )
        return jsonify({
            'success': True,
            'message': 'User updated successfully',
            'data': {
                **response_user,
                'selfChangesPending': was_self_update,
            }
        })

    except Exception as e:
        logger.error(f"Error updating user {username}: {e}")
        return jsonify({'error': 'Failed to update user'}), 500


@app.route('/api/users/<username>/password', methods=['PUT'])
@require_admin
def reset_user_password(username):
    """Admin: reset user password"""
    try:
        username = unquote_plus(username)

        user = data_manager.users.get(username)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        if not _current_user_can_manage_user(username):
            return jsonify({
                'error': 'You cannot manage this user or access level'
            }), 403

        if _is_owner_username(username) and not _current_user_is_owner():
            return jsonify({'error': 'This protected account cannot be managed'}), 403

        data = request.get_json() or {}
        new_password = data.get('password') or ''

        if not new_password:
            return jsonify({'error': 'New password is required'}), 400

        user.salt = secrets.token_hex(16)
        user.password_hash = hash_password(new_password, user.salt)

        data_manager.save_users()
        _reload_users_for_all_company_managers()
        log_action(f"Reset password for user {username}")
        _queue_access_control_notification(
            manager=_current_data_manager_object(),
            action='User password reset',
            target_user=username,
        )

        return jsonify({'success': True, 'message': 'Password reset successfully'})

    except Exception as e:
        logger.error(f"Error resetting password for user {username}: {e}")
        return jsonify({'error': 'Failed to reset password'}), 500
