@app.route('/api/users/<username>', methods=['DELETE'])
@require_admin
def delete_user(username):
    """Admin: delete user"""
    try:
        username = unquote_plus(username)

        if username == session.get('user'):
            return jsonify({'error': 'You cannot delete your own account'}), 400

        user = data_manager.users.get(username)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        if not _current_user_can_manage_user(username):
            return jsonify({
                'error': 'You cannot manage this user or access level'
            }), 403

        if _is_owner_username(username) and not _current_user_is_owner():
            return jsonify({'error': 'This protected account cannot be deleted'}), 403

        company_code = _normalise_company_code(
            _user_assigned_company_code(username),
            DEFAULT_COMPANY_CODE,
        )
        if (
            _effective_user_role(user) == 'admin'
            and getattr(user, 'is_active', True)
            and not _current_user_is_owner()
            and len(_active_company_admin_usernames(company_code)) <= 1
        ):
            return jsonify({
                'error': _last_company_admin_error(company_code)
            }), 409

        try:
            if _is_owner_username(username):
                _set_user_super_admin(username, False)
        except ValueError as e:
            return jsonify({'error': str(e)}), 400

        del data_manager.users[username]
        data_manager.save_users()
        _reload_users_for_all_company_managers()
        registry = _load_company_registry()
        _unassign_user_from_company(username, company_code)

        log_action(f"Deleted user {username}")
        notification_manager = _current_data_manager_object()
        disconnect_admin_telegram(notification_manager, username)
        _queue_access_control_notification(
            manager=notification_manager,
            action='User account deleted',
            target_user=username,
        )

        return jsonify({
            'success': True,
            'message': 'User deleted successfully'
        })

    except Exception as e:
        logger.error(f"Error deleting user {username}: {e}")
        return jsonify({'error': 'Failed to delete user'}), 500


def _uploaded_file_size(uploaded_file):
    """Return an uploaded file's byte size without consuming its stream."""
    stream = getattr(uploaded_file, 'stream', None)
    if stream is None:
        return None
    try:
        position = stream.tell()
        stream.seek(0, os.SEEK_END)
        size = stream.tell()
        stream.seek(position)
        return size
    except (AttributeError, OSError):
        return getattr(uploaded_file, 'content_length', None)


def _validate_uploaded_file_size(uploaded_file, max_bytes, label):
    size = _uploaded_file_size(uploaded_file)
    if size is not None and size > max_bytes:
        max_mb = max_bytes // MEBIBYTE
        raise ValueError(
            f'{label} "{uploaded_file.filename}" is larger than {max_mb} MB'
        )


def _safe_event_upload_filename(filename):
    raw_name = str(filename or '').replace('\\', '/')
    basename = os.path.basename(raw_name).strip()
    cleaned = sanitize_filename(basename)
    cleaned = re.sub(r'\s+', ' ', cleaned).strip().strip('.')

    if not cleaned:
        cleaned = f"upload-{secrets.token_hex(6)}"

    if len(cleaned) > 180:
        base, ext = os.path.splitext(cleaned)
        ext = ext[:20]
        cleaned = f"{base[:180 - len(ext)]}{ext}"

    return cleaned


def _unique_event_upload_path(folder, filename):
    base, ext = os.path.splitext(filename)
    candidate = os.path.join(folder, filename)
    counter = 2

    while os.path.exists(candidate):
        candidate = os.path.join(folder, f"{base}_{counter}{ext}")
        counter += 1

    return candidate


def _event_files_for_response(event_id):
    folder = data_manager.get_event_folder(event_id) if data_manager else None
    if not folder or not os.path.isdir(folder):
        return []

    files = []
    try:
        with os.scandir(folder) as entries:
            for entry in entries:
                if not entry.is_file():
                    continue
                try:
                    stat = entry.stat()
                except OSError:
                    continue

                mime_type, preview_kind = _event_file_preview_details(entry.name)
                encoded_name = quote(entry.name)
                files.append({
                    'name': entry.name,
                    'size': stat.st_size,
                    'modifiedAt': datetime.fromtimestamp(stat.st_mtime).isoformat(timespec='seconds'),
                    'downloadUrl': f"/api/events/{event_id}/files/{encoded_name}",
                    'previewUrl': (
                        f"/api/events/{event_id}/files/{encoded_name}?preview=1"
                        if preview_kind else ''
                    ),
                    'previewKind': preview_kind,
                    'mimeType': mime_type,
                })
    except OSError as e:
        logger.warning("Failed to list files for event %s: %s", event_id, e)
        return []

    files.sort(key=lambda item: item['name'].lower())
    return files


def _event_file_preview_details(filename):
    mime_type = str(mimetypes.guess_type(str(filename or ''))[0] or '')
    if mime_type == 'application/pdf':
        return mime_type, 'pdf'
    if mime_type in {'image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/bmp'}:
        return mime_type, 'image'
    if mime_type.startswith('video/'):
        return mime_type, 'video'
    if mime_type.startswith('audio/'):
        return mime_type, 'audio'
    if mime_type in {'text/plain', 'text/csv', 'application/json'}:
        return mime_type, 'text'
    return mime_type or 'application/octet-stream', ''


def _event_files_total_size(event_id):
    return sum(
        max(0, _safe_int(file_info.get('size'), 0))
        for file_info in _event_files_for_response(event_id)
    )


def _event_file_path(event_id, filename):
    if not filename or '/' in filename or '\\' in filename:
        return None

    folder = data_manager.get_event_folder(event_id) if data_manager else None
    if not folder:
        return None

    base = os.path.abspath(folder)
    target = os.path.abspath(os.path.join(base, filename))

    if not target.startswith(base + os.sep):
        return None

    return target


MAINTENANCE_IMAGE_EXTENSIONS = {
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.png': 'image/png',
}
MAINTENANCE_VIDEO_EXTENSIONS = {
    '.mp4': 'video/mp4',
    '.mov': 'video/quicktime',
}
CONVERTIBLE_IMAGE_EXTENSIONS = {
    '.bmp', '.gif', '.heic', '.heif', '.tif', '.tiff', '.webp'
}
CONVERTIBLE_VIDEO_EXTENSIONS = {
    '.3gp', '.avi', '.m4v', '.mkv', '.mpeg', '.mpg', '.webm', '.wmv'
}


def _maintenance_request_payload():
    if request.form:
        return request.form.to_dict(flat=True)
    data = request.get_json(silent=True)
    return data if isinstance(data, dict) else {}


def _uploaded_maintenance_media_files():
    files = []
    for key in ('media', 'maintenanceMedia', 'maintenanceMediaFiles', 'files', 'file', 'photos', 'videos'):
        files.extend(request.files.getlist(key))
    return [file for file in files if file and file.filename]


def _maintenance_media_root(create=False):
    if not data_manager or not getattr(data_manager, 'data_folder', ''):
        return None
    media_folder = getattr(data_manager, 'media_folder', data_manager.data_folder)
    folder = os.path.join(media_folder, 'maintenance_media')
    if create:
        os.makedirs(folder, exist_ok=True)
    return folder


def _safe_maintenance_media_name(filename, target_ext):
    raw_name = str(filename or '').replace('\\', '/')
    basename = os.path.basename(raw_name).strip()
    base, _ = os.path.splitext(basename)
    cleaned = sanitize_filename(base)
    cleaned = re.sub(r'\s+', ' ', cleaned).strip().strip('.')
    if not cleaned:
        cleaned = 'maintenance-media'

    target_ext = target_ext if target_ext.startswith('.') else f'.{target_ext}'
    if len(cleaned) + len(target_ext) > 180:
        cleaned = cleaned[:180 - len(target_ext)].rstrip()

    return f"{cleaned}{target_ext}"


def _maintenance_upload_target(uploaded_file):
    filename = str(uploaded_file.filename or '')
    _, ext = os.path.splitext(filename)
    ext = ext.lower()
    mime_type = (uploaded_file.mimetype or '').lower()

    if ext in MAINTENANCE_IMAGE_EXTENSIONS:
        target_ext = '.jpg' if ext == '.jpeg' else ext
        return 'image', target_ext, False, MAINTENANCE_IMAGE_EXTENSIONS[ext]
    if mime_type in ('image/jpeg', 'image/jpg'):
        return 'image', '.jpg', False, 'image/jpeg'
    if mime_type == 'image/png':
        return 'image', '.png', False, 'image/png'
    if mime_type.startswith('image/') or ext in CONVERTIBLE_IMAGE_EXTENSIONS:
        return 'image', '.png', True, 'image/png'

    if ext in MAINTENANCE_VIDEO_EXTENSIONS:
        return 'video', ext, False, MAINTENANCE_VIDEO_EXTENSIONS[ext]
    if mime_type == 'video/mp4':
        return 'video', '.mp4', False, 'video/mp4'
    if mime_type in ('video/quicktime', 'video/mov'):
        return 'video', '.mov', False, 'video/quicktime'
    if mime_type.startswith('video/') or ext in CONVERTIBLE_VIDEO_EXTENSIONS:
        return 'video', '.mp4', True, 'video/mp4'

    raise ValueError(f"Unsupported media file: {filename or 'unnamed file'}")


def _convert_image_upload(uploaded_file, target_path):
    try:
        from PIL import Image, ImageOps
    except ImportError:
        return False

    try:
        uploaded_file.stream.seek(0)
        with Image.open(uploaded_file.stream) as image:
            image = ImageOps.exif_transpose(image)
            if getattr(image, 'is_animated', False):
                image.seek(0)
            if image.mode not in ('RGB', 'RGBA', 'L', 'LA'):
                image = image.convert('RGBA')
            elif image.mode in ('L', 'LA'):
                image = image.convert('RGBA')
            image.save(target_path, format='PNG')
        return True
    except Exception as e:
        logger.warning("Failed to convert image upload %s: %s", uploaded_file.filename, e)
        return False


def _convert_video_upload(uploaded_file, target_path):
    ffmpeg = shutil.which('ffmpeg')
    if not ffmpeg:
        return False

    _, ext = os.path.splitext(str(uploaded_file.filename or ''))
    ext = ext if ext else '.upload'

    try:
        with tempfile.TemporaryDirectory() as temp_dir:
            input_path = os.path.join(temp_dir, f"input{ext}")
            uploaded_file.stream.seek(0)
            uploaded_file.save(input_path)
            result = subprocess.run(
                [
                    ffmpeg,
                    '-y',
                    '-i',
                    input_path,
                    '-c:v',
                    'libx264',
                    '-c:a',
                    'aac',
                    '-movflags',
                    '+faststart',
                    target_path,
                ],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=180,
                check=False,
            )
            if result.returncode != 0:
                logger.warning(
                    "ffmpeg could not convert maintenance video %s: %s",
                    uploaded_file.filename,
                    result.stderr.decode('utf-8', errors='ignore')[-1000:],
                )
                return False
        return os.path.exists(target_path) and os.path.getsize(target_path) > 0
    except Exception as e:
        logger.warning("Failed to convert video upload %s: %s", uploaded_file.filename, e)
        return False


def _maintenance_media_abs_path(media):
    root = _maintenance_media_root(create=False)
    if not root:
        return None

    relative_path = str((media or {}).get('path') or '').strip().replace('\\', '/')
    if not relative_path:
        return None

    parts = [part for part in relative_path.split('/') if part]
    if relative_path.startswith('/') or '..' in parts:
        return None

    media_folder = os.path.abspath(
        getattr(data_manager, 'media_folder', data_manager.data_folder)
    )
    target = os.path.abspath(os.path.join(media_folder, *parts))
    base = os.path.abspath(root)
    if target != base and not target.startswith(base + os.sep):
        return None
    if not os.path.isfile(target) and media_folder != os.path.abspath(data_manager.data_folder):
        legacy_target = os.path.abspath(os.path.join(data_manager.data_folder, *parts))
        legacy_root = os.path.abspath(os.path.join(data_manager.data_folder, 'maintenance_media'))
        if legacy_target.startswith(legacy_root + os.sep) and os.path.isfile(legacy_target):
            return legacy_target
    return target


def _cleanup_empty_maintenance_media_folder(path):
    root = _maintenance_media_root(create=False)
    if not root or not path:
        return

    folder = os.path.abspath(os.path.dirname(path))
    root = os.path.abspath(root)
    if folder == root or not folder.startswith(root + os.sep):
        return

    try:
        if os.path.isdir(folder) and not os.listdir(folder):
            os.rmdir(folder)
    except OSError:
        pass


def _delete_maintenance_media_files(log_entry):
    deleted = 0
    record = normalize_maintenance_log(log_entry)
    if (record.get('source') or {}).get('kind') == CONTAINER_MAINTENANCE_SOURCE:
        # Container media can be referenced by the container record and several
        # propagated asset records. Deleting one asset must not break the rest.
        return 0
    for media in record.get('media', []) or []:
        target_path = _maintenance_media_abs_path(media)
        if not target_path:
            continue
        try:
            if os.path.isfile(target_path):
                os.remove(target_path)
                deleted += 1
            _cleanup_empty_maintenance_media_folder(target_path)
        except OSError as e:
            logger.warning("Failed to delete maintenance media %s: %s", target_path, e)
    return deleted


def _remove_maintenance_media_references(media_id):
    """Remove one media record everywhere it is referenced.

    Container maintenance records are copied into each member asset's history,
    so deleting by media ID must update both the source container and every
    durable asset copy.
    """
    media_id = str(media_id or '').strip()
    result = {
        'media': None,
        'referenceCount': 0,
        'inventoryChanged': False,
        'containersChanged': False,
    }
    if not media_id or not data_manager:
        return result

    owner_groups = (
        (data_manager.inventory.values(), 'inventoryChanged'),
        (data_manager.containers.values(), 'containersChanged'),
    )
    for owners, changed_key in owner_groups:
        for owner in owners:
            logs = getattr(owner, 'maintenance_logs', []) or []
            for index, log_entry in enumerate(logs):
                record = normalize_maintenance_log(log_entry)
                retained_media = []
                removed_from_log = 0
                for media in record.get('media', []) or []:
                    if str(media.get('id') or '').strip() == media_id:
                        if result['media'] is None:
                            result['media'] = dict(media)
                        removed_from_log += 1
                    else:
                        retained_media.append(media)

                if removed_from_log:
                    record['media'] = retained_media
                    logs[index] = record
                    result['referenceCount'] += removed_from_log
                    result[changed_key] = True

    return result


def _save_maintenance_media_files(log_entry, uploaded_files):
    incoming_files = [file for file in (uploaded_files or []) if file and file.filename]
    if not incoming_files:
        return []

    for uploaded_file in incoming_files:
        kind, _target_ext, _should_convert, _mime_type = _maintenance_upload_target(uploaded_file)
        max_bytes = (
            MAINTENANCE_VIDEO_MAX_BYTES
            if kind == 'video'
            else MAINTENANCE_IMAGE_MAX_BYTES
        )
        _validate_uploaded_file_size(
            uploaded_file,
            max_bytes,
            'Maintenance video' if kind == 'video' else 'Maintenance image',
        )

    root = _maintenance_media_root(create=True)
    if not root:
        raise ValueError('Maintenance media folder could not be created')

    log_id = (log_entry.get('id') or '').strip()
    if not log_id:
        log_id = make_maintenance_log_id()
        log_entry['id'] = log_id

    log_folder = os.path.join(root, log_id)
    os.makedirs(log_folder, exist_ok=True)

    media_records = []
    saved_paths = []
    try:
        for uploaded_file in incoming_files:
            kind, target_ext, should_convert, mime_type = _maintenance_upload_target(uploaded_file)
            media_id = secrets.token_hex(10)
            target_path = os.path.join(log_folder, f"{media_id}{target_ext}")
            display_name = _safe_maintenance_media_name(uploaded_file.filename, target_ext)

            if should_convert:
                converted = (
                    _convert_image_upload(uploaded_file, target_path)
                    if kind == 'image'
                    else _convert_video_upload(uploaded_file, target_path)
                )
                if not converted:
                    if kind == 'image':
                        raise ValueError(f"Could not convert {uploaded_file.filename} to PNG")
                    raise ValueError(f"Could not convert {uploaded_file.filename} to MP4")
            else:
                uploaded_file.stream.seek(0)
                uploaded_file.save(target_path)

            if not os.path.isfile(target_path):
                raise ValueError(f"Could not save {uploaded_file.filename}")

            saved_paths.append(target_path)
            media_folder = getattr(data_manager, 'media_folder', data_manager.data_folder)
            relative_path = os.path.relpath(target_path, media_folder).replace(os.sep, '/')
            media_records.append({
                'id': media_id,
                'name': display_name,
                'path': relative_path,
                'kind': kind,
                'mimeType': mime_type or mimetypes.guess_type(display_name)[0] or '',
                'size': os.path.getsize(target_path),
            })
    except Exception:
        for path in saved_paths:
            try:
                if os.path.isfile(path):
                    os.remove(path)
                _cleanup_empty_maintenance_media_folder(path)
            except OSError:
                pass
        raise

    return media_records


def _maintenance_media_for_response(media):
    item = dict(media or {})
    media_id = str(item.get('id') or '').strip()
    if media_id:
        item['url'] = f"/api/maintenance-media/{quote(media_id)}"
    return item


def _maintenance_log_for_response(log_entry):
    record = normalize_maintenance_log(log_entry)
    record['userDisplayName'] = _user_display_name(record.get('user'))
    record['media'] = [
        _maintenance_media_for_response(media)
        for media in (record.get('media') or [])
    ]
    return record


def _find_maintenance_media(media_id):
    media_id = str(media_id or '').strip()
    if not media_id:
        return None, None, None

    for asset in (data_manager.inventory.values() if data_manager else []):
        for log_entry in getattr(asset, 'maintenance_logs', []) or []:
            record = normalize_maintenance_log(log_entry)
            for media in record.get('media', []) or []:
                if str(media.get('id') or '').strip() == media_id:
                    return asset, record, media

    for container in (data_manager.containers.values() if data_manager else []):
        for log_entry in getattr(container, 'maintenance_logs', []) or []:
            record = normalize_maintenance_log(log_entry)
            for media in record.get('media', []) or []:
                if str(media.get('id') or '').strip() == media_id:
                    return container, record, media

    return None, None, None


@app.route('/api/maintenance-media/<media_id>', methods=['GET'])
@require_auth
def download_maintenance_media(media_id):
    """View media attached to a maintenance log."""
    try:
        asset, record, media = _find_maintenance_media(media_id)
        if not asset or not record or not media:
            return jsonify({'error': 'Media not found'}), 404

        target_path = _maintenance_media_abs_path(media)
        if not target_path or not os.path.isfile(target_path):
            return jsonify({'error': 'Media file not found'}), 404

        return send_file(
            target_path,
            as_attachment=False,
            download_name=media.get('name') or os.path.basename(target_path),
            mimetype=media.get('mimeType') or mimetypes.guess_type(target_path)[0] or 'application/octet-stream'
        )
    except Exception as e:
        logger.error(f"Error downloading maintenance media {media_id}: {e}")
        return jsonify({'error': 'Failed to load maintenance media'}), 500


@app.route('/api/maintenance-media/<media_id>', methods=['DELETE'])
@require_auth
@with_inventory_action_lock
def delete_maintenance_media(media_id):
    """Permanently remove one maintenance attachment and all of its references."""
    try:
        if not _current_user_is_admin():
            return jsonify({'error': 'Admin privileges required to remove maintenance media'}), 403

        media_id = unquote_plus(str(media_id or '')).strip()
        removal = _remove_maintenance_media_references(media_id)
        media = removal.get('media')
        if not media:
            return jsonify({'error': 'Media not found'}), 404

        if removal['inventoryChanged']:
            data_manager.save_inventory()
        if removal['containersChanged']:
            data_manager.save_containers()

        target_path = _maintenance_media_abs_path(media)
        file_deleted = False
        if target_path:
            try:
                if os.path.isfile(target_path):
                    os.remove(target_path)
                    file_deleted = True
                _cleanup_empty_maintenance_media_folder(target_path)
            except OSError as exc:
                logger.error("Failed to permanently delete maintenance media %s: %s", target_path, exc)
                return jsonify({
                    'error': 'Media was removed from maintenance logs, but its stored file could not be deleted'
                }), 500

        invalidate_cache()
        log_action(
            f"Removed maintenance media {media.get('name') or media_id} "
            f"from {removal['referenceCount']} record(s) (deleted by {session['user']})"
        )
        return jsonify({
            'success': True,
            'message': 'Maintenance media permanently deleted',
            'deletedReferenceCount': removal['referenceCount'],
            'fileDeleted': file_deleted,
        })
    except Exception as exc:
        logger.error("Error deleting maintenance media %s: %s", media_id, exc, exc_info=True)
        return jsonify({'error': f'Failed to delete maintenance media: {str(exc)}'}), 500


def _event_workflow_progress_payload(
    event,
    total_required,
    total_prepared,
    total_returned,
    workforce=None,
    finance_data=None,
    prepare_required=None,
):
    """Build the shared progress state used by every event overview."""
    event_id = int(event.event_id)
    required = max(0, _safe_int(total_required, 0))
    prepared = max(0, _safe_int(total_prepared, 0))
    returned = max(0, _safe_int(total_returned, 0))
    prepare_required = max(
        0,
        _safe_int(required if prepare_required is None else prepare_required, 0),
    )
    returnable_counts = _event_returnable_counts(event)
    return_total = max(0, _safe_int(returnable_counts.get('total'), 0))
    return_remaining = max(0, _safe_int(returnable_counts.get('returnable'), 0))
    return_done = max(0, _safe_int(returnable_counts.get('returned'), 0))
    # Keep aggregate-only callers useful even when they do not populate the
    # event's operational reference lists.
    if return_total <= 0 and returned > 0:
        return_total = max(prepared, returned)
        return_done = returned
        return_remaining = max(0, return_total - return_done)
    workforce = workforce if isinstance(workforce, dict) else {
        'assignments': {}, 'transportBookings': {}, 'submissions': {},
    }

    assignments = [
        row for row in event_assignments(workforce, event_id)
        if isinstance(row, dict)
    ]
    bookings = [
        row for row in event_bookings(workforce, event_id)
        if isinstance(row, dict) and str(row.get('status') or '') != 'Denied'
    ]
    has_depart = any(
        bool(row.get('twoWay'))
        or str(row.get('tripType') or 'depart').strip().lower() != 'return'
        for row in bookings
    )
    has_return = any(
        bool(row.get('twoWay'))
        or str(row.get('tripType') or '').strip().lower() == 'return'
        for row in bookings
    )

    def quantity_state(done, total):
        if total <= 0 or done <= 0:
            return 'neutral'
        return 'green' if done >= total else 'orange'

    plan_health = _event_plan_asset_health(event)
    if plan_health['status'] == 'red':
        shortage = plan_health['shortageQuantity']
        plan_status = 'red'
        plan_label = (
            f'Plan: shortage of {shortage} asset unit'
            f'{"s" if shortage != 1 else ""}'
        )
    elif plan_health['status'] == 'orange':
        degraded = plan_health['degradedQuantity']
        plan_status = 'orange'
        plan_label = (
            f'Plan: {degraded} degraded asset unit'
            f'{"s" if degraded != 1 else ""} required'
        )
    else:
        plan_status = 'green' if required > 0 else 'neutral'
        plan_label = (
            f'Plan: {required} asset requirement'
            f'{"s" if required != 1 else ""} added'
            if required > 0 else 'Plan: no assets added'
        )

    progress = {
        'plan': {
            'status': plan_status,
            'label': plan_label,
        },
        'manpower': {
            'status': 'green' if assignments else 'neutral',
            'label': (
                f'Crew & Vendors: {len(assignments)} assignment'
                f'{"s" if len(assignments) != 1 else ""}'
                if assignments else 'Crew & Vendors: no assignments'
            ),
        },
        'transport': {
            'status': (
                'green' if has_depart and has_return
                else 'orange' if has_depart or has_return
                else 'neutral'
            ),
            'label': (
                'Transport: depart and return scheduled'
                if has_depart and has_return
                else 'Transport: depart scheduled, return missing'
                if has_depart
                else 'Transport: return scheduled, depart missing'
                if has_return
                else 'Transport: no trips scheduled'
            ),
        },
        'prepare': {
            'status': quantity_state(prepared, prepare_required),
            'label': (
                f'Prepare: {min(prepared, prepare_required)}/'
                f'{prepare_required} assets prepared'
            ),
        },
        'return': {
            'status': (
                'green' if return_total > 0 and return_remaining == 0
                else 'orange' if return_done > 0
                else 'neutral'
            ),
            'label': f'Return: {min(return_done, return_total)}/{return_total} assets returned',
        },
        'finance': None,
    }

    finance_data = finance_data if isinstance(finance_data, dict) else {}
    current_username = str(session.get('user') or '').strip()
    effective_role = _effective_user_role(current_username)
    admin_finance_access = effective_role in {'owner', 'admin'}
    sales_finance_access = _current_user_has_sales_access()
    owned_quotations = [
        document for document in (finance_data.get('documents') or [])
        if isinstance(document, dict)
        and document.get('type') == 'quotation'
        and _safe_int(document.get('eventId'), 0) == event_id
        and _finance_document_owner_username(document).casefold()
        == current_username.casefold()
    ]
    if not admin_finance_access and not (
        sales_finance_access and owned_quotations
    ):
        return progress

    subject_ids = {
        _workforce_assignment_subject_id(row)
        for row in assignments
        if _workforce_assignment_subject_id(row)
    }
    event_submission_rows = (
        (workforce.get('submissions') or {}).get(str(event_id), {}) or {}
    )
    subject_ids.update(
        str(subject_id) for subject_id in event_submission_rows
        if str(subject_id or '').strip()
    )
    payable_rows = []
    awaiting_invoice_count = 0
    for subject_id in subject_ids:
        if _workforce_subject_is_full_time(subject_id, assignments):
            continue
        rows = worker_submissions(workforce, event_id, subject_id)
        invoices = [
            row for row in rows.get('invoices', [])
            if isinstance(row, dict) and str(row.get('status') or '') != 'Denied'
        ]
        claims = [
            row for row in rows.get('claims', [])
            if isinstance(row, dict) and str(row.get('status') or '') != 'Denied'
        ]
        if (
            _worker_upload_limits(
                workforce, event_id, subject_id
            )['invoiceLimit'] > 0
            and not invoices
        ):
            awaiting_invoice_count += 1
        payable_rows.extend(invoices)
        payable_rows.extend(claims)

    needs_payment = [
        row for row in payable_rows
        if str(row.get('status') or '') == 'Approved'
    ]
    needs_review = [
        row for row in payable_rows
        if str(row.get('status') or 'Pending Review') == 'Pending Review'
    ]
    all_paid = bool(payable_rows) and all(
        str(row.get('status') or '') == 'Paid' for row in payable_rows
    )
    if needs_payment:
        finance_status = 'red'
        finance_label = (
            f'Finance: {len(needs_payment)} '
            f'{"invoice or claim" if len(needs_payment) == 1 else "invoices or claims"} '
            f'{"needs" if len(needs_payment) == 1 else "need"} payment'
        )
    elif needs_review:
        finance_status = 'orange'
        finance_label = (
            f'Finance: {len(needs_review)} '
            f'{"invoice or claim" if len(needs_review) == 1 else "invoices or claims"} '
            f'{"needs" if len(needs_review) == 1 else "need"} review'
        )
    elif awaiting_invoice_count:
        finance_status = 'blue'
        finance_label = (
            f'Finance: {awaiting_invoice_count} invoice'
            f'{"s" if awaiting_invoice_count != 1 else ""} awaiting upload'
        )
    elif all_paid:
        finance_status = 'green'
        finance_label = 'Finance: all invoices and claims paid'
    else:
        finance_status = 'neutral'
        finance_label = 'Finance: open invoices and claims'
    progress['finance'] = {
        'status': finance_status,
        'label': finance_label,
        'quotationId': str(
            owned_quotations[0].get('id') or ''
        ) if owned_quotations else '',
    }
    return progress


@app.route('/api/events', methods=['GET'])
@require_auth
def get_events():
    """Get all events"""
    try:
        visible_events = [
            event for event in data_manager.events.values()
            if _current_user_can_access_event(event)
        ]

        view_mode = request.args.get('view', '').strip().lower()
        calendar_view = view_mode == 'calendar'
        summary_view = view_mode in {'summary', 'options', 'calendar'}
        options_view = view_mode == 'options'
        include_returnable = str(
            request.args.get('includeReturnable', '1')
        ).strip().lower() not in {'0', 'false', 'no'}
        range_start_raw = request.args.get('rangeStart', '').strip()
        range_end_raw = request.args.get('rangeEnd', '').strip()
        range_start = _parse_any_date(range_start_raw)
        range_end = _parse_any_date(range_end_raw)
        if calendar_view and bool(range_start_raw) != bool(range_end_raw):
            return jsonify({'error': 'Both rangeStart and rangeEnd are required'}), 400
        if calendar_view and range_start_raw and (not range_start or not range_end):
            return jsonify({'error': 'Calendar range dates are invalid'}), 400
        if calendar_view and range_start and range_end and range_end < range_start:
            return jsonify({'error': 'rangeEnd cannot be before rangeStart'}), 400
        query = request.args.get('query', '').strip().lower()
        state_filter = request.args.get('state', '').strip().lower()
        tag_filter = request.args.get('tag', '').strip().lower()
        event_id_filter = request.args.get('eventId', type=int)
        overview_scope = request.args.get('scope', '').strip().lower()
        active_scope = overview_scope == 'active'

        state_counts = {}
        state_counts_by_tag = {}
        for event in visible_events:
            state = str(getattr(event, 'state', '') or 'New')
            state_counts[state] = state_counts.get(state, 0) + 1
            raw_event_tag = str(
                getattr(event, 'tag', 'events') or 'events'
            ).strip().lower()
            event_tag = 'dry hire' if raw_event_tag == 'dry hire' else 'events'
            tag_counts = state_counts_by_tag.setdefault(event_tag, {})
            tag_counts[state] = tag_counts.get(state, 0) + 1

        filtered_events = []
        for event in visible_events:
            if active_scope and str(
                getattr(event, 'state', '') or 'New'
            ).strip().lower() in {'closed', 'pending closure'}:
                continue
            if calendar_view and range_start and range_end and not _ranges_overlap(
                getattr(event, 'start_date', ''),
                getattr(event, 'end_date', ''),
                range_start,
                range_end,
            ):
                continue
            if event_id_filter is not None and event.event_id != event_id_filter:
                continue
            if query and not (
                query in str(getattr(event, 'name', '') or '').lower()
                or query in str(getattr(event, 'location', '') or '').lower()
                or query in str(event.event_id).lower()
            ):
                continue
            if state_filter and str(getattr(event, 'state', '') or '').lower() != state_filter:
                continue
            if tag_filter and str(getattr(event, 'tag', '') or '').lower() != tag_filter:
                continue
            filtered_events.append(event)

        sort_by = request.args.get('sort', '').strip().lower()
        sort_direction = request.args.get('direction', '').strip().lower()
        reverse = sort_direction != 'asc'
        if sort_by in {'startdate', 'start-date'}:
            filtered_events.sort(
                key=lambda event: (str(getattr(event, 'start_date', '') or ''), event.event_id),
                reverse=reverse,
            )
        elif sort_by in {'enddate', 'end-date'}:
            filtered_events.sort(
                key=lambda event: (str(getattr(event, 'end_date', '') or ''), event.event_id),
                reverse=reverse,
            )
        elif sort_by == 'name':
            filtered_events.sort(
                key=lambda event: (str(getattr(event, 'name', '') or '').casefold(), event.event_id),
                reverse=reverse,
            )
        else:
            filtered_events.sort(key=lambda event: event.event_id, reverse=reverse)

        total = len(filtered_events)
        offset = max(0, request.args.get('offset', type=int) or 0)
        requested_limit = request.args.get('limit', type=int)
        limit = min(max(1, requested_limit), 500) if requested_limit else None
        page_events = filtered_events[
            offset:offset + limit if limit is not None else None
        ] if (offset or limit is not None) else filtered_events

        # Summary/full cards need the same workforce and finance documents for
        # both automatic state refresh and workflow badges. Load each once per
        # request and pass it through instead of reading the files twice.
        workflow_workforce = None
        workflow_finance = None
        if not options_view and not calendar_view:
            try:
                workflow_workforce = load_workforce(_workforce_folder())
            except Exception as workforce_error:
                logger.warning(
                    "Unable to load event workflow progress: %s",
                    workforce_error,
                )
                workflow_workforce = {}
            try:
                workflow_finance = _load_finance_data()
            except Exception as finance_error:
                logger.warning(
                    "Unable to load event finance progress: %s",
                    finance_error,
                )
                workflow_finance = {}
        refresh_event_states_for_read(
            page_events,
            sync_vendor_management=not options_view,
            workforce=workflow_workforce,
            finance_data=workflow_finance,
        )

        if calendar_view:
            events_data = [
                {
                    'id': event.event_id,
                    'name': event.name,
                    'location': getattr(event, 'location', '') or '',
                    'startDate': format_date_output(event.start_date),
                    'endDate': format_date_output(event.end_date),
                    'state': event.state,
                    'tag': getattr(event, 'tag', 'events'),
                }
                for event in page_events
            ]
            return jsonify({
                'success': True,
                'data': events_data,
                'meta': {
                    'total': total,
                    'offset': offset,
                    'limit': limit,
                    'hasMore': offset + len(events_data) < total,
                    'nextOffset': (
                        offset + len(events_data)
                        if offset + len(events_data) < total
                        else None
                    ),
                    'stateCounts': state_counts,
                    'stateCountsByTag': state_counts_by_tag,
                    'view': 'calendar',
                    'rangeStart': range_start.isoformat() if range_start else '',
                    'rangeEnd': range_end.isoformat() if range_end else '',
                },
            })

        events_data = []
        workflow_workforce = workflow_workforce or {}
        workflow_finance = workflow_finance or {}
        for event in page_events:
            # Initialize actually_prepared if missing
            if not hasattr(event, 'actually_prepared'):
                event.actually_prepared = []
            if not hasattr(event, 'extra_assets'):
                event.extra_assets = []

            if options_view:
                event_option = {
                    'id': event.event_id,
                    'name': event.name,
                    'location': getattr(event, 'location', '') or '',
                    'startDate': format_date_output(event.start_date),
                    'endDate': format_date_output(event.end_date),
                    'state': event.state,
                    'tag': getattr(event, 'tag', 'events'),
                }
                if include_returnable:
                    returnable_counts = _event_returnable_counts(event)
                    event_option.update({
                        'returnableCount': returnable_counts['returnable'],
                        'returnableTotalCount': returnable_counts['total'],
                    })
                events_data.append(event_option)
                continue

            extra_asset_ids = set(getattr(event, 'extra_assets', []) or [])

            # Build model groups for this event
            model_groups = {}
            has_model_assignments = False
            
            for asset_id in event.prepared_items:
                if asset_id.startswith('[MODEL]'):
                    has_model_assignments = True
                    try:
                        parts = asset_id[7:].split('|')
                        if len(parts) >= 4:
                            dept = parts[0]
                            brand = parts[1]
                            model = parts[2]
                            quantity = int(parts[3])
                            description = '|'.join(parts[4:]) if len(parts) > 4 else ''
                            
                            model_key = '|'.join(
                                _model_key_from_parts(dept, brand, model, description)
                            )
                            
                            if model_key not in model_groups:
                                model_groups[model_key] = {
                                    'department': dept,
                                    'brand': brand,
                                    'model': model,
                                    'description': description,
                                    'requiredQuantity': quantity,
                                    'assignedAssets': [],
                                    'status': 'pending'
                                }
                            else:
                                model_groups[model_key]['requiredQuantity'] += quantity
                            
                            # Find assigned specific assets for this model.
                            # Extras are included in assignedAssets so model cards can show
                            # values like 5/3 assigned (+2 extra), but they are flagged and
                            # excluded later from event/department readiness totals.
                            all_model_asset_ids = set(event.actually_prepared or []) | set(event.returned_items or [])
                            for specific_asset_id in all_model_asset_ids:
                                is_extra_asset = specific_asset_id in extra_asset_ids
                                specific_asset = data_manager.inventory.get(specific_asset_id)
                                if (specific_asset and 
                                    specific_asset.brand == brand and 
                                    specific_asset.model_number == model and
                                    specific_asset.department_code == dept and
                                    str(specific_asset.description or '').strip().casefold() ==
                                        description.strip().casefold()):
                                    
                                    asset_status = 'returned' if specific_asset_id in event.returned_items else 'prepared'
                                    
                                    assignment = {
                                        'id': specific_asset_id,
                                        'status': asset_status,
                                        'quantity': 1,
                                        'isExtra': is_extra_asset,
                                    }
                                    if not summary_view:
                                        assignment.update({
                                            'serial': specific_asset.serial_number,
                                            'serial2': getattr(specific_asset, 'secondary_serial_number', ''),
                                            'tags': normalize_asset_tags(getattr(specific_asset, 'tags', [])),
                                            'location': specific_asset.current_location,
                                        })
                                    model_groups[model_key]['assignedAssets'].append(assignment)
                            
                            # Determine overall model status - FIXED LOGIC
                            assigned_count = len(model_groups[model_key]['assignedAssets'])
                            returned_count = len([a for a in model_groups[model_key]['assignedAssets'] if a['status'] == 'returned'])
                            
                            if returned_count == assigned_count and returned_count == quantity:
                                model_groups[model_key]['status'] = 'returned'
                            elif assigned_count >= quantity:
                                model_groups[model_key]['status'] = 'ready'
                            elif assigned_count > 0:
                                model_groups[model_key]['status'] = 'partial'
                            else:
                                model_groups[model_key]['status'] = 'pending'
                                
                    except Exception as e:
                        logger.error(f"Error parsing model assignment {asset_id}: {e}")
                        continue

            _append_bulk_assignments_to_model_groups(
                model_groups,
                event,
                include_asset_details=not summary_view,
            )
            _append_prepared_slots_to_model_groups(model_groups, event)
            _append_orphan_extra_assignments_to_model_groups(
                model_groups,
                event,
                include_asset_details=not summary_view,
            )
            _refresh_model_group_statuses(
                model_groups,
                include_inventory_metadata=not summary_view,
            )

            # Calculate totals including custom item quantities.
            custom_counts = _custom_counts_for_event(event)
            if has_model_assignments:
                total_required = 0
                total_prepared = 0
                total_returned = 0

                for model_group in model_groups.values():
                    required_quantity = max(0, _safe_int(model_group.get('requiredQuantity', 0), 0))
                    total_required += required_quantity

                    prepared_assets_count = max(0, _safe_int(model_group.get('countablePreparedEverQuantity', 0), 0))
                    returned_assets_count = max(0, _safe_int(model_group.get('countableReturnedQuantity', 0), 0))

                    total_prepared += min(prepared_assets_count, required_quantity) if required_quantity > 0 else prepared_assets_count
                    total_returned += min(returned_assets_count, required_quantity) if required_quantity > 0 else returned_assets_count

                total_required += custom_counts['required']
                total_prepared += custom_counts['preparedEver']
                total_returned += custom_counts['returned']
            else:
                specific_counts = _event_specific_counts(event)
                total_required = specific_counts['required'] + custom_counts['required']
                total_prepared = specific_counts['preparedEver'] + custom_counts['preparedEver']
                total_returned = specific_counts['returned'] + custom_counts['returned']

            returnable_counts = _event_returnable_counts(event)

            event_payload = {
                'id': event.event_id,
                'name': event.name,
                'location': getattr(event, 'location', '') or '',
                'startDate': format_date_output(event.start_date),
                'endDate': format_date_output(event.end_date),
                'state': event.state,  # Keep original state, don't force update
                'isLastDay': _event_is_last_day(event),
                'tag': getattr(event, 'tag', 'events'), 
                'assetCount': total_required,
                'preparedCount': total_prepared,
                'preparationTotal': _event_prepare_required_total(event, total_required, custom_counts),
                'preparationCount': max(0, total_prepared - custom_counts['preparedEver']
                                        + _custom_counts_for_event(event, exclude_delivered=True)['preparedEver']),
                'returnedCount': total_returned,
                'extraCount': _event_extra_asset_quantity(event),
                'returnableCount': returnable_counts['returnable'],
                'returnableTotalCount': returnable_counts['total'],
                'hasModelAssignments': has_model_assignments,  # Flag to know which logic to use
                'forceStateOverride': getattr(event, 'force_state_override', False),
                'hasNotes': bool((getattr(event, 'notes', '') or '').strip()),
                'assignedUsernames': _event_assigned_usernames_for_response(event),
                'assignedUsers': _event_assignee_payloads(event),
                'departmentProgress': _event_department_progress_payload(
                    event,
                    model_groups,
                    has_model_assignments,
                ),
                'workflowProgress': _event_workflow_progress_payload(
                    event,
                    total_required,
                    max(0, total_prepared - custom_counts['preparedEver']
                        + _custom_counts_for_event(event, exclude_delivered=True)['preparedEver']),
                    total_returned,
                    workflow_workforce,
                    workflow_finance,
                    prepare_required=_event_prepare_required_total(
                        event,
                        total_required,
                        custom_counts,
                    ),
                ),
            }
            if not summary_view:
                event_payload.update({
                    'fileCount': len(_event_files_for_response(event.event_id)),
                    'assetModels': event.asset_models,
                    'preparedItems': event.prepared_items,
                    'actuallyPrepared': event.actually_prepared,
                    'returnedItems': event.returned_items,
                    'customCollected': getattr(event, 'custom_collected', []),
                    'returnableRefs': returnable_counts['refs'],
                    'modelGroups': model_groups,
                    'subprojects': getattr(event, 'subprojects', []) or [],
                })
            events_data.append(event_payload)

        return jsonify({
            'success': True,
            'data': events_data,
            'meta': {
                'total': total,
                'offset': offset,
                'limit': limit,
                'hasMore': offset + len(events_data) < total,
                'nextOffset': offset + len(events_data) if offset + len(events_data) < total else None,
                'stateCounts': state_counts,
                'stateCountsByTag': state_counts_by_tag,
                'scope': 'active' if active_scope else 'all',
                'view': view_mode if summary_view else 'full',
            },
        })
    except Exception as e:
        logger.error(f"Error getting events: {e}")
        return jsonify({'error': 'Failed to retrieve events'}), 500

@app.route('/api/events/<int:event_id>', methods=['GET'])
@require_auth
@require_event_access
def get_event(event_id):
    """Get a specific event with detailed asset information"""
    try:
        detail_view = request.args.get('view', '').strip().lower()
        workspace_view = detail_view in {'plan', 'prepare', 'return'}
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        if not _current_user_can_access_event(event):
            return _event_access_denied_response()

        refresh_event_states_for_read(
            [event],
            sync_vendor_management=not workspace_view,
        )

        # Initialize lists if they don't exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []
        if not hasattr(event, 'extra_assets'):
            event.extra_assets = []
        extra_asset_ids = set(getattr(event, 'extra_assets', []) or [])

        # Get detailed asset information grouped by department
        assets_by_department = defaultdict(list)
        assigned_assets = []
        prepared_assets = []
        returned_assets = []

        # Process ALL items in prepared_items (including model assignments)
        for asset_id in event.prepared_items:
            asset_info = None

            custom = _parse_custom_marker(asset_id)
            if custom:
                # Structured or legacy custom item. Legacy [LOAN]/[MISC] rows default to UN.
                dept = custom.get('department') or 'UN'
                status = _custom_status(event, asset_id)
                is_collected = asset_id in getattr(event, 'custom_collected', [])
                asset_info = {
                    'id': asset_id,
                    'name': _custom_display_name(custom),
                    'displayName': _custom_display_name(custom),
                    'brand': '',
                    'model': custom.get('name', ''),
                    'description': (
                        f"From {custom.get('company', '')}"
                        if custom.get('type') == 'LOAN' and custom.get('company')
                        else custom.get('description', '')
                    ),
                    'serial': '',
                    'department': dept,
                    'company': custom.get('company', ''),
                    'customDescription': custom.get('description', ''),
                    'quantity': custom.get('quantity', 1),
                    'status': status,
                    'customType': custom.get('type'),
                    'isCustom': True,
                    'isLoanOrMisc': True,
                    'isCollected': is_collected,
                    'needsCollection': custom.get('type') == 'LOAN',
                    'isExtra': asset_id in event.extra_assets
                }
            elif asset_id.startswith('[MODEL]'):
                    continue
            else:
                # Handle regular assets
                asset = data_manager.inventory.get(asset_id)
                if asset:
                    dept = asset.department_code

                    # Determine status
                    if asset_id in event.returned_items:
                        status = 'returned'
                    elif asset_id in event.actually_prepared:
                        status = 'prepared'
                    else:
                        status = 'assigned'

                    # Keep the explicit extra marker. A manual over-prepared asset
                    # may match an existing model row, but it should still display
                    # as extra unless a container scan intentionally raised the
                    # requirement and removed it from event.extra_assets.
                    is_extra = asset_id in event.extra_assets

                    asset_info = {
                        'id': asset.asset_id,
                        'name': f"{asset.brand} {asset.model_number} - {asset.description}",
                        'brand': asset.brand,
                        'model': asset.model_number,
                        'description': asset.description,
                        'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
                        'serial': asset.serial_number,
                        'serial2': getattr(asset, 'secondary_serial_number', ''),
                        'status': status,
                        'location': asset.current_location,
                        'isMissing': asset.is_missing,
                        'isOOC': asset.is_ooc,
                        'isUntagged': _is_untagged(asset),
                        'isLoanOrMisc': False,
                        'isExtra': is_extra
                    }

            if asset_info:
                assets_by_department[dept].append(asset_info)

                # Categorize assets
                if asset_info['status'] == 'returned':
                    returned_assets.append(asset_info)
                elif asset_info['status'] == 'prepared':
                    prepared_assets.append(asset_info)
                else:
                    assigned_assets.append(asset_info)

        # Also process physical model-fulfilled assets that are not represented
        # directly in prepared_items. Returned regular assets are removed from
        # actually_prepared, so include returned_items as well; this keeps the
        # Return workspace history complete and makes accidental returns
        # reversible without reconstructing asset metadata in the browser.
        physical_history_refs = list(dict.fromkeys(
            list(event.actually_prepared or []) +
            list(event.returned_items or [])
        ))
        for asset_id in physical_history_refs:
            # Check if this asset was already processed above
            already_processed = False
            for dept_assets in assets_by_department.values():
                if any(existing_asset['id'] == asset_id for existing_asset in dept_assets):
                    already_processed = True
                    break

            if not already_processed:
                asset = data_manager.inventory.get(asset_id)
                if asset:
                    dept = asset.department_code
                    is_extra = asset_id in extra_asset_ids

                    # Determine status
                    if asset_id in event.returned_items:
                        status = 'returned'
                    else:
                        status = 'prepared'

                    asset_info = {
                        'id': asset.asset_id,
                        'name': f"{asset.brand} {asset.model_number} - {asset.description}",
                        'brand': asset.brand,
                        'model': asset.model_number,
                        'description': asset.description,
                        'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
                        'serial': asset.serial_number,
                        'serial2': getattr(asset, 'secondary_serial_number', ''),
                        'status': status,
                        'location': asset.current_location,
                        'isMissing': asset.is_missing,
                        'isOOC': asset.is_ooc,
                        'isUntagged': _is_untagged(asset),
                        'isLoanOrMisc': False,
                        'isExtra': is_extra
                    }

                    assets_by_department[dept].append(asset_info)

                    # Categorize assets
                    if asset_info['status'] == 'returned':
                        returned_assets.append(asset_info)
                    else:
                        prepared_assets.append(asset_info)

        # Sort departments and assets within each department
        sorted_departments = {}
        for dept in sorted(assets_by_department.keys()):
            sorted_departments[dept] = sorted(
                assets_by_department[dept], key=lambda x: x['id'])

        # Group assets by model for cleaner display
        model_groups = {}
        for asset_id in event.prepared_items:
            if asset_id.startswith('[MODEL]'):
                # Parse model assignment
                try:
                    parts = asset_id[7:].split('|')
                    if len(parts) >= 4:
                        dept = parts[0]
                        brand = parts[1]
                        model = parts[2]
                        quantity = int(parts[3])
                        description = '|'.join(parts[4:]) if len(parts) > 4 else ''

                        model_key = '|'.join(
                            _model_key_from_parts(dept, brand, model, description)
                        )

                        if model_key not in model_groups:
                            model_groups[model_key] = {
                                'department': dept,
                                'brand': brand,
                                'model': model,
                                'description': description,
                                'requiredQuantity': quantity,
                                'assignedAssets': [],
                                'status': 'pending'
                            }
                        else:
                            model_groups[model_key]['requiredQuantity'] += quantity

                        # Find assigned specific assets for this model
                        # Check both actually_prepared and all inventory assets
                        all_potential_assets = set()
                        if hasattr(event, 'actually_prepared'):
                            all_potential_assets.update(event.actually_prepared)
                        
                        # Also check returned items as they might have been assigned to this model
                        all_potential_assets.update(event.returned_items)
                        
                        logger.debug(f"Checking assets for model {brand} {model}: {all_potential_assets}")
                        
                        extra_asset_ids = set(getattr(event, 'extra_assets', []) or [])
                        for specific_asset_id in all_potential_assets:
                            is_extra_asset = specific_asset_id in extra_asset_ids
                            specific_asset = data_manager.inventory.get(specific_asset_id)
                            
                            if specific_asset:
                                logger.debug(f"Asset {specific_asset_id}: brand={specific_asset.brand}, model={specific_asset.model_number}, dept={specific_asset.department_code}")
                                logger.debug(f"Looking for: brand={brand}, model={model}, dept={dept}")
                                
                                if (specific_asset and 
                                    specific_asset.brand == brand and 
                                    specific_asset.model_number == model and
                                    specific_asset.department_code == dept and
                                    str(specific_asset.description or '').strip().casefold() ==
                                        description.strip().casefold()):

                                    # Check if this asset is returned
                                    asset_status = 'returned' if specific_asset_id in event.returned_items else 'prepared'
                                    logger.debug(f"Asset {specific_asset_id} matches model and has status: {asset_status}")

                                    model_groups[model_key]['assignedAssets'].append({
                                        'id': specific_asset_id,
                                        'serial': specific_asset.serial_number,
                                        'serial2': getattr(specific_asset, 'secondary_serial_number', ''),
                                        'tags': normalize_asset_tags(getattr(specific_asset, 'tags', [])),
                                        'status': asset_status,
                                        'location': specific_asset.current_location,
                                        'quantity': 1,
                                        'isExtra': is_extra_asset
                                    })

                        # Determine overall model status - FIXED LOGIC
                        assigned_count = len(model_groups[model_key]['assignedAssets'])
                        returned_count = len([a for a in model_groups[model_key]['assignedAssets'] if a['status'] == 'returned'])
                        prepared_count = assigned_count - returned_count

                        logger.debug(f"Model {brand} {model}: assigned={assigned_count}, returned={returned_count}, prepared={prepared_count}, required={quantity}")

                        if returned_count == assigned_count and assigned_count > 0:
                            model_groups[model_key]['status'] = 'returned'
                        elif prepared_count >= quantity:
                            model_groups[model_key]['status'] = 'ready'
                        elif prepared_count > 0:
                            model_groups[model_key]['status'] = 'partial'
                        else:
                            model_groups[model_key]['status'] = 'pending'

                        logger.debug(f"Model {brand} {model} final status: {model_groups[model_key]['status']}")

                except Exception as e:
                    logger.error(f"Error parsing model assignment {asset_id}: {e}")

        _append_bulk_assignments_to_model_groups(model_groups, event)
        _append_prepared_slots_to_model_groups(model_groups, event)
        _append_orphan_extra_assignments_to_model_groups(model_groups, event)
        _refresh_model_group_statuses(model_groups)

        # Add prepared/returned bulk quantity markers to the department asset lists.
        for bulk_value in getattr(event, 'actually_prepared', []) or []:
            marker = _parse_bulk_marker(bulk_value)
            if not marker:
                continue
            bulk_asset = data_manager.inventory.get(marker['bulkId'])
            if not bulk_asset or not _is_bulk_asset(bulk_asset):
                continue
            status = 'returned' if bulk_value in getattr(event, 'returned_items', []) else 'prepared'
            bulk_info = {
                'id': bulk_value,
                'bulkId': marker['bulkId'],
                'displayId': '',
                'name': f"{bulk_asset.brand} {bulk_asset.model_number} - {bulk_asset.description} (Qty: {marker['quantity']})",
                'brand': bulk_asset.brand,
                'model': bulk_asset.model_number,
                'description': bulk_asset.description,
                'tags': normalize_asset_tags(getattr(bulk_asset, 'tags', [])),
                'serial': '',
                'status': status,
                'location': bulk_asset.current_location or bulk_asset.default_location,
                'isMissing': bulk_asset.is_missing,
                'isOOC': bulk_asset.is_ooc,
                'isUntagged': _is_untagged(bulk_asset),
                'isLoanOrMisc': False,
                'isExtra': False,
                'isBulk': True,
                'quantity': marker['quantity']
            }
            assets_by_department[bulk_asset.department_code].append(bulk_info)
            if status == 'returned':
                returned_assets.append(bulk_info)
            else:
                prepared_assets.append(bulk_info)

        # Deployment changes an asset's workflow status to "prepared", but its
        # underlying degraded condition must still reach the Prepare cards.
        def degraded_for_event_ref(ref):
            marker = _parse_bulk_marker(ref)
            inventory_id = marker['bulkId'] if marker else ref
            inventory_asset = data_manager.inventory.get(inventory_id)
            return _is_degraded(inventory_asset) if inventory_asset else False

        for model_group in model_groups.values():
            for assigned in model_group.get('assignedAssets', []) or []:
                assigned['isDegraded'] = degraded_for_event_ref(
                    assigned.get('bulkId') or assigned.get('id')
                )
        for department_assets in assets_by_department.values():
            for asset_info in department_assets:
                asset_info['isDegraded'] = degraded_for_event_ref(
                    asset_info.get('bulkId') or asset_info.get('id')
                )

        # Re-sort departments after adding bulk markers.
        sorted_departments = {}
        for dept in sorted(assets_by_department.keys()):
            sorted_departments[dept] = sorted(
                assets_by_department[dept], key=lambda x: x.get('id', ''))

        # Calculate totals based on model requirements, direct assets, and custom item quantities.
        has_model_assignments = len(model_groups) > 0
        custom_counts = _custom_counts_for_event(event)

        if has_model_assignments:
            total_required = 0
            total_prepared = 0
            total_returned = 0

            for model_group in model_groups.values():
                required_quantity = max(0, _safe_int(model_group.get('requiredQuantity', 0), 0))
                total_required += required_quantity

                # Event/department totals must not include manual extras.
                prepared_assets_count = max(0, _safe_int(model_group.get('countablePreparedEverQuantity', 0), 0))
                returned_assets_count = max(0, _safe_int(model_group.get('countableReturnedQuantity', 0), 0))

                total_prepared += min(prepared_assets_count, required_quantity) if required_quantity > 0 else prepared_assets_count
                total_returned += min(returned_assets_count, required_quantity) if required_quantity > 0 else returned_assets_count

            total_required += custom_counts['required']
            total_prepared += custom_counts['preparedEver']
            total_returned += custom_counts['returned']
        else:
            specific_counts = _event_specific_counts(event)
            total_required = specific_counts['required'] + custom_counts['required']
            total_prepared = specific_counts['preparedEver'] + custom_counts['preparedEver']
            total_returned = specific_counts['returned'] + custom_counts['returned']

        total_extra_assets = _event_extra_asset_quantity(event)
        total_extra_prepared = _event_extra_prepared_quantity(event, model_groups)

        logger.debug(
            f"Event {event_id} final asset counts - Required: {total_required}, "
            f"Prepared: {total_prepared}, Returned: {total_returned}, "
            f"Active extras: {total_extra_assets}, Prepared extras: {total_extra_prepared}, "
            f"Extra assets in list: {len(event.extra_assets)}"
        )
            
        event_data = {
            'id': event.event_id,
            'name': event.name,
            'location': getattr(event, 'location', '') or '',
            'startDate': format_date_output(event.start_date),
            'endDate': format_date_output(event.end_date),    
            'state': event.state,
            'tag': getattr(event, 'tag', 'events'), 
            'assetModels': event.asset_models,
            'preparedItems': event.prepared_items,
            'actuallyPrepared': event.actually_prepared,
            'returnedItems': event.returned_items,
            'extraAssets': event.extra_assets,
            'customCollected': getattr(event, 'custom_collected', []),
            'assetsByDepartment': sorted_departments,
            'modelGroups': model_groups,
            'subprojects': getattr(event, 'subprojects', []) or [],
            'forceStateOverride': getattr(event, 'force_state_override', False),
            'notes': getattr(event, 'notes', '') or '',
        }

        if not workspace_view or detail_view == 'return':
            returnable_counts = _event_returnable_counts(event)
            event_data.update({
                'returnableCount': returnable_counts['returnable'],
                'returnableTotalCount': returnable_counts['total'],
                'returnableRefs': returnable_counts['refs'],
            })

        if not workspace_view:
            event_data.update({
                'assignedAssets': assigned_assets,
                'preparedAssets': prepared_assets,
                'returnedAssets': returned_assets,
                'totalAssets': total_required,
                'totalPrepared': total_prepared,
                'totalReturned': total_returned,
                'totalExtraAssets': total_extra_assets,
                'totalExtraPrepared': total_extra_prepared,
                'files': _event_files_for_response(event.event_id),
                'canDeleteFiles': _current_user_is_admin(),
                'eventLogs': _event_activity_logs_for_response(event),
                'assignedUsernames': _event_assigned_usernames_for_response(event),
                'assignedUsers': _event_assignee_payloads(event),
            })

        workflow_workforce = {}
        workflow_finance = {}
        if not workspace_view:
            try:
                workflow_workforce = load_workforce(_workforce_folder())
            except Exception as workforce_error:
                logger.warning(
                    "Unable to load workflow progress for event %s: %s",
                    event_id,
                    workforce_error,
                )
        if not workspace_view or detail_view in {'plan', 'prepare'}:
            try:
                workflow_finance = _load_finance_data()
            except Exception as finance_error:
                logger.warning(
                    "Unable to load finance progress for event %s: %s",
                    event_id,
                    finance_error,
                )

        if not workspace_view:
            event_data['workflowProgress'] = _event_workflow_progress_payload(
                event,
                total_required,
                max(0, total_prepared - custom_counts['preparedEver']
                    + _custom_counts_for_event(event, exclude_delivered=True)['preparedEver']),
                total_returned,
                workflow_workforce,
                workflow_finance,
                prepare_required=_event_prepare_required_total(
                    event,
                    total_required,
                    custom_counts,
                ),
            )

        if not workspace_view or detail_view in {'plan', 'prepare'}:
            event_data['vendorManagement'] = _event_vendor_management(event)
            try:
                linked_quotations = _finance_quotations_for_event(
                    workflow_finance,
                    event_id,
                    accessible_only=False,
                )
                if linked_quotations:
                    event_data['quotationId'] = linked_quotations[0].get('id') or ''
                    event_data['quotationNumber'] = linked_quotations[0].get('number') or ''
                    linked_costing = _linked_costing_for_quotation(
                        workflow_finance, linked_quotations[0]
                    )
                    event_data['vendorManagement'] = _event_vendor_management(
                        event, linked_costing
                    )
            except Exception as finance_error:
                logger.warning(
                    "Unable to resolve paired quotation for event %s: %s",
                    event_id,
                    finance_error,
                )

        return jsonify({'success': True, 'data': event_data})

    except Exception as e:
        logger.error(f"Error getting event {event_id}: {e}")
        return jsonify({'error': 'Failed to retrieve event'}), 500


@app.route('/api/events/<int:event_id>/logs', methods=['GET'])
@require_auth
@require_event_access
def get_event_logs(event_id):
    """Return event history only to company admins and Showbase owners."""
    if not _current_user_can_view_logs():
        return jsonify({'error': 'Admin privileges required'}), 403
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    records = data_manager.normalize_event_logs(
        getattr(event, 'event_logs', [])
    )[-MAX_LOG_LINES:]
    records = [
        _log_record_for_response(
            record,
            data_manager,
            category=_event_activity_category(record.get('action')),
        )
        for record in records
    ]
    records.reverse()
    return jsonify({
        'success': True,
        'data': {
            'eventId': event_id,
            'eventName': event.name,
            'companyCode': _current_company_code(),
            'logs': records,
        },
    })


@app.route('/api/events/<int:event_id>/notes', methods=['PUT'])
@require_auth
@require_event_access
def update_event_notes(event_id):
    """Update the plaintext notes attached to an event."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json(silent=True) or {}
        notes = str(data.get('notes', ''))
        if len(notes) > 50000:
            return jsonify({'error': 'Notes cannot exceed 50,000 characters'}), 400

        event.notes = notes
        data_manager.events[event_id] = event
        data_manager.save_event(event)

        log_action(f"Updated notes for event {event_id}: {event.name}")
        mark_realtime_change('event-notes', {'eventId': event_id})

        return jsonify({'success': True, 'message': 'Event notes updated', 'data': {'notes': event.notes}})
    except Exception as e:
        logger.error(f"Error updating notes for event {event_id}: {e}")
        return jsonify({'error': 'Failed to update event notes'}), 500


