@app.route('/api/events/<int:event_id>/files', methods=['POST'])
@require_auth
@require_event_access
def upload_event_files(event_id):
    """Upload one or more files into the event-specific folder."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        incoming_files = request.files.getlist('files')
        if not incoming_files and 'file' in request.files:
            incoming_files = request.files.getlist('file')

        if not incoming_files:
            return jsonify({'error': 'Choose at least one file to upload'}), 400

        valid_files = [
            uploaded_file
            for uploaded_file in incoming_files
            if uploaded_file and uploaded_file.filename
        ]
        incoming_size = 0
        for uploaded_file in valid_files:
            _validate_uploaded_file_size(
                uploaded_file,
                EVENT_FILE_MAX_BYTES,
                'Event file',
            )
            incoming_size += max(0, _uploaded_file_size(uploaded_file) or 0)

        with _event_file_action_locks[event_id]:
            existing_size = _event_files_total_size(event_id)
            if existing_size + incoming_size > EVENT_FILE_MAX_BYTES:
                limit_mb = EVENT_FILE_MAX_BYTES // MEBIBYTE
                used_mb = existing_size / MEBIBYTE
                raise ValueError(
                    f'Event files cannot exceed {limit_mb} MB in total '
                    f'({used_mb:.1f} MB currently used)'
                )

            folder = data_manager.get_event_folder(event_id, create=True)
            if not folder:
                return jsonify({'error': 'Event folder could not be created'}), 500

            saved_files = []
            saved_paths = []
            try:
                for uploaded_file in valid_files:
                    filename = _safe_event_upload_filename(uploaded_file.filename)
                    target_path = _unique_event_upload_path(folder, filename)
                    uploaded_file.save(target_path)
                    saved_paths.append(target_path)
                    saved_files.append(os.path.basename(target_path))
            except Exception:
                for saved_path in saved_paths:
                    try:
                        os.remove(saved_path)
                    except OSError:
                        pass
                raise

        if not saved_files:
            return jsonify({'error': 'No valid files were uploaded'}), 400

        log_action(f"Uploaded {len(saved_files)} file(s) to event {event_id}: {event.name}")
        mark_realtime_change('event-files', {'eventId': event_id})

        return jsonify({
            'success': True,
            'message': 'File upload complete',
            'data': _event_files_for_response(event_id)
        })
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error(f"Error uploading files for event {event_id}: {e}")
        return jsonify({'error': 'Failed to upload event files'}), 500


@app.route('/api/events/<int:event_id>/files/<path:filename>', methods=['GET'])
@require_auth
@require_event_access
def download_event_file(event_id, filename):
    """Download or safely preview a file attached to an event."""
    try:
        if event_id not in data_manager.events:
            return jsonify({'error': 'Event not found'}), 404

        target_path = _event_file_path(event_id, filename)
        if not target_path or not os.path.exists(target_path) or not os.path.isfile(target_path):
            return jsonify({'error': 'File not found'}), 404

        preview_requested = request.args.get('preview', '').strip() == '1'
        mime_type, preview_kind = _event_file_preview_details(target_path)
        if preview_requested and not preview_kind:
            return jsonify({'error': 'Preview is not available for this file type'}), 415

        response = send_file(
            target_path,
            as_attachment=not preview_requested,
            download_name=os.path.basename(target_path),
            mimetype=mime_type,
        )
        if preview_requested:
            response.headers['Content-Disposition'] = (
                f"inline; filename*=UTF-8''{quote(os.path.basename(target_path))}"
            )
            response.headers['X-Content-Type-Options'] = 'nosniff'
        return response
    except Exception as e:
        logger.error(f"Error downloading file {filename} for event {event_id}: {e}")
        return jsonify({'error': 'Failed to download event file'}), 500


@app.route('/api/events/<int:event_id>/files/<path:filename>', methods=['DELETE'])
@require_admin
def delete_event_file_upload(event_id, filename):
    """Delete a file attached to an event. Admin only."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        target_path = _event_file_path(event_id, filename)
        if not target_path or not os.path.exists(target_path) or not os.path.isfile(target_path):
            return jsonify({'error': 'File not found'}), 404

        with _event_file_action_locks[event_id]:
            os.remove(target_path)
            updated_files = _event_files_for_response(event_id)

        log_action(f"Deleted file '{os.path.basename(target_path)}' from event {event_id}: {event.name}")
        mark_realtime_change('event-files', {'eventId': event_id})

        return jsonify({
            'success': True,
            'message': 'Event file deleted',
            'data': updated_files
        })
    except Exception as e:
        logger.error(f"Error deleting file {filename} for event {event_id}: {e}")
        return jsonify({'error': 'Failed to delete event file'}), 500


def _workspace_availability_payload(rows, view_mode):
    if view_mode != 'plan':
        return rows
    unused_fields = {'physicalGlobal', 'unavailable', 'adjustedGlobal'}
    return [
        {
            key: value
            for key, value in row.items()
            if key not in unused_fields
        }
        for row in rows
    ]


@app.route('/api/events/<int:event_id>/availability', methods=['GET'])
@require_auth
@require_event_access
def get_event_model_availability(event_id):
    """
    Compute model availability for an event.

    Rules:
    - Group by department + brand + model + description.
    - Exclude decommissioned assets.
    - Keep OOC and Missing assets in the physical total, but do not count them as available.
    - Include Degraded assets as available because they can still be prepared with a warning.
    - Subtract current event's requested quantity.
    - Subtract the peak simultaneous quantity requested by overlapping events.
    - Still return rows with 0 availability so the frontend can show them.
    """
    try:
        view_mode = request.args.get('view', '').strip().lower()
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        availability_cache = _current_manager_cache().setdefault(
            'event_availability', {}
        )
        cache_key = (event_id, str(session.get('user') or ''))
        cached_result = availability_cache.get(cache_key)
        if isinstance(cached_result, list):
            return jsonify({
                'success': True,
                'data': _workspace_availability_payload(
                    copy.deepcopy(cached_result),
                    view_mode,
                ),
            })

        physical_by_key = defaultdict(int)
        asset_ooc_by_key = defaultdict(int)
        asset_missing_by_key = defaultdict(int)
        asset_degraded_by_key = defaultdict(int)
        maintenance_ooc_by_key = defaultdict(int)
        maintenance_missing_by_key = defaultdict(int)
        maintenance_degraded_by_key = defaultdict(int)
        degraded_details_by_key = defaultdict(list)

        # Physical inventory: exclude decommissioned assets. Missing and OOC
        # units stay in the denominator so the UI can explain why the available
        # count is lower than the total.
        for asset in data_manager.inventory.values():
            if not asset:
                continue

            if _is_disposed(asset):
                continue

            key = _event_asset_group_key(asset)
            inventory_quantity = _asset_inventory_quantity(asset)
            physical_by_key[key] += inventory_quantity

            if getattr(asset, 'is_missing', False):
                asset_missing_by_key[key] += inventory_quantity
                # A whole-asset Missing flag already makes every bulk unit
                # unavailable, so do not count its per-unit fault logs twice.
                continue

            if getattr(asset, 'is_ooc', False):
                asset_ooc_by_key[key] += inventory_quantity
                # A whole-asset OOC flag already makes every bulk unit
                # unavailable, so do not count its per-unit fault logs twice.
                continue

            if _is_bulk_asset(asset):
                counts = _bulk_maintenance_quantity_counts(asset)
                maintenance_ooc_by_key[key] += counts['ooc']
                maintenance_missing_by_key[key] += counts['missing']
                degraded_quantity = counts['degraded']
                if _is_degraded(asset):
                    degraded_quantity = max(
                        degraded_quantity,
                        max(_asset_inventory_quantity(asset) - counts['ooc'] - counts['missing'], 0)
                    )
                maintenance_degraded_by_key[key] += degraded_quantity
                if degraded_quantity > 0:
                    degraded_details_by_key[key].append({
                        'assetId': '',
                        'isBulk': True,
                        'quantity': degraded_quantity,
                        'reasons': _bulk_degraded_reasons(asset),
                    })
            elif _is_degraded(asset):
                asset_degraded_by_key[key] += inventory_quantity
                degraded_details_by_key[key].append({
                    'assetId': str(getattr(asset, 'asset_id', '') or '').strip(),
                    'isBulk': False,
                    'quantity': inventory_quantity,
                    'reasons': _asset_degraded_reasons(asset),
                })

        # Quantity already reserved/requested in this same event.  This includes
        # normal model rows plus any specific prepared bulk/individual assets.
        used_here_by_key = _event_reserved_quantities_by_key(event)

        # Peak simultaneous demand from overlapping events. Events that each
        # overlap this event may still run on different dates, allowing the
        # same inventory to be reused between them.
        demand_by_event = {
            int(other.event_id): dict(_event_reserved_quantities_by_key(other))
            for other in data_manager.events.values()
            if other
        }
        overlap_by_key = _peak_overlapping_event_demand_by_key(
            event,
            demand_by_event,
        )
        overlap_events_by_key = defaultdict(list)

        my_start = getattr(event, 'start_date', '')
        my_end = getattr(event, 'end_date', '')

        for other in data_manager.events.values():
            if not other or other.event_id == event_id:
                continue

            if not _ranges_overlap(
                my_start,
                my_end,
                getattr(other, 'start_date', ''),
                getattr(other, 'end_date', '')
            ):
                continue

            for key, quantity in demand_by_event.get(int(other.event_id), {}).items():
                if quantity <= 0:
                    continue
                if _current_user_can_access_event(other):
                    overlap_events_by_key[key].append({
                        'eventId': other.event_id,
                        'eventName': getattr(other, 'name', '') or f'Event {other.event_id}',
                        'startDate': _format_event_date_for_response(getattr(other, 'start_date', '')),
                        'endDate': _format_event_date_for_response(getattr(other, 'end_date', '')),
                        'quantity': quantity,
                    })

        result = []

        for key, physical in physical_by_key.items():
            department, brand, model, description = key

            used_here = used_here_by_key.get(key, 0)
            overlap = overlap_by_key.get(key, 0)
            asset_ooc = asset_ooc_by_key.get(key, 0)
            asset_missing = asset_missing_by_key.get(key, 0)
            asset_degraded = asset_degraded_by_key.get(key, 0)
            maintenance_ooc = maintenance_ooc_by_key.get(key, 0)
            maintenance_missing = maintenance_missing_by_key.get(key, 0)
            maintenance_degraded = maintenance_degraded_by_key.get(key, 0)
            capacity_for_this_event = max(
                physical - overlap - asset_ooc - asset_missing -
                maintenance_ooc - maintenance_missing,
                0
            )
            degraded_capacity = min(
                asset_degraded + maintenance_degraded,
                capacity_for_this_event
            )
            healthy_capacity_for_this_event = max(
                capacity_for_this_event - degraded_capacity,
                0
            )
            available = max(capacity_for_this_event - used_here, 0)
            healthy = max(healthy_capacity_for_this_event - used_here, 0)
            preparable = available

            result.append({
                'department': department,
                'brand': brand,
                'model': model,
                'description': description,
                'physical': physical,
                'physicalGlobal': physical,
                'usedInThisEvent': used_here,
                'capacityForThisEvent': capacity_for_this_event,
                'healthyCapacityForThisEvent': healthy_capacity_for_this_event,
                'overlappingDemand': overlap,
                'overlappingEvents': overlap_events_by_key.get(key, []),
                'unavailable': (
                    used_here + overlap + asset_ooc + asset_missing +
                    maintenance_ooc + maintenance_missing
                ),
                'available': available,
                'healthy': healthy,
                'preparable': preparable,
                'assetOOC': asset_ooc,
                'assetMissing': asset_missing,
                'assetDegraded': asset_degraded,
                'bulkMaintenanceOOC': maintenance_ooc,
                'bulkMaintenanceMissing': maintenance_missing,
                'bulkMaintenanceDegraded': maintenance_degraded,
                'degraded': degraded_capacity,
                'degradedDetails': degraded_details_by_key.get(key, []),
                'adjustedGlobal': available
            })

        result.sort(key=lambda x: (
            x['department'],
            x['brand'].lower(),
            x['model'].lower(),
            x['description'].lower()
        ))

        availability_cache[cache_key] = copy.deepcopy(result)

        return jsonify({
            'success': True,
            'data': _workspace_availability_payload(result, view_mode),
        })

    except Exception as e:
        logger.error(f"Error computing model availability for event {event_id}: {e}")
        return jsonify({'error': 'Failed to compute availability'}), 500
    
@app.route('/api/events', methods=['POST'])
@require_admin
def create_event():
    """Create a new event"""
    try:
        data = request.get_json()

        # Validate input data
        errors = validate_event_data(data, require_location=True)
        if errors:
            return jsonify({'success': False, 'errors': errors}), 400

        # Convert dates to internal format
        start_date = datetime.strptime(
            data['startDate'], '%Y-%m-%d').strftime('%Y%m%d')
        end_date = datetime.strptime(
            data['endDate'], '%Y-%m-%d').strftime('%Y%m%d')
        assigned_users = _normalise_event_assigned_users(
            data.get('assignedUsers', data.get('assignedUsernames', [])),
            require_known=True,
        )

        def build_event(event_id):
            event = Event(
                event_id=event_id,
                name=data['name'].strip(),
                location=str(data.get('location') or '').strip(),
                start_date=start_date,
                end_date=end_date,
                asset_models=[],
                prepared_items=[],
                state='New',
                returned_items=[],
                tag=data.get('tag', 'event'),
                assigned_users=assigned_users,
            )
            event.actually_prepared = []
            return event

        event = _create_event_with_available_id(build_event)
        event_id = event.event_id

        # Invalidate cache
        invalidate_cache()
        mark_realtime_change('events', {'eventId': event_id, 'action': 'created'})

        log_action(
            f"Created event {event_id}: {event.name}; "
            f"location={event.location or '-'}; "
            f"dates={format_date_output(event.start_date)} to {format_date_output(event.end_date)}; "
            f"type={event.tag}; assigned users={len(assigned_users)}",
            include_system_log=True,
        )
        _queue_assigned_event_notification(
            manager=data_manager,
            event=event,
            assigned_usernames=assigned_users,
        )

        return jsonify({'success': True, 'message': 'Event created successfully', 'eventId': event_id})
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error(f"Error creating event: {e}")
        return jsonify({'error': 'Failed to create event'}), 500


@app.route('/api/events/<int:event_id>', methods=['PUT'])
@require_admin
def update_event(event_id):
    """Update an existing event"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json()

        # Validate input data
        errors = validate_event_data(data)
        if errors:
            return jsonify({'success': False, 'errors': errors}), 400

        # Update event properties
        old_assigned_usernames = _event_assigned_usernames(event)
        old_details = {
            'name': event.name,
            'location': getattr(event, 'location', '') or '',
            'startDate': format_date_output(event.start_date),
            'endDate': format_date_output(event.end_date),
            'tag': getattr(event, 'tag', 'events'),
            'assignedUsers': ', '.join(_event_assigned_usernames(event)),
        }
        old_name = event.name
        if 'name' in data:
            event.name = data['name'].strip()
        if 'location' in data:
            event.location = str(data.get('location') or '').strip()
        if 'startDate' in data:
            event.start_date = datetime.strptime(
                data['startDate'], '%Y-%m-%d').strftime('%Y%m%d')
        if 'endDate' in data:
            event.end_date = datetime.strptime(
                data['endDate'], '%Y-%m-%d').strftime('%Y%m%d')
        if 'tag' in data:
            event.tag = data['tag']
        if 'assignedUsers' in data or 'assignedUsernames' in data:
            event.assigned_users = _normalise_event_assigned_users(
                data.get('assignedUsers', data.get('assignedUsernames', [])),
                require_known=True,
            )

        # Update asset locations if event name changed
        if old_name != event.name:
            for asset_id in _active_physical_asset_refs_for_event(event):
                asset = data_manager.inventory.get(asset_id)
                if asset:
                    asset.current_location = event.name
            data_manager.save_inventory()

        # Save event
        data_manager.events[event_id] = event
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()
        mark_realtime_change('events', {'eventId': event_id, 'action': 'updated'})

        new_details = {
            'name': event.name,
            'location': getattr(event, 'location', '') or '',
            'startDate': format_date_output(event.start_date),
            'endDate': format_date_output(event.end_date),
            'tag': getattr(event, 'tag', 'events'),
            'assignedUsers': ', '.join(_event_assigned_usernames(event)),
        }
        detail_labels = {
            'name': 'Name',
            'location': 'Location',
            'startDate': 'Start date',
            'endDate': 'End date',
            'tag': 'Type',
            'assignedUsers': 'Assigned users',
        }
        changes = [
            (
                f"{detail_labels[key]}: "
                f"{old_details[key] or '—'} → {new_details[key] or '—'}"
            )
            for key in old_details
            if old_details[key] != new_details[key]
        ]
        change_text = '; '.join(changes) if changes else 'No field changes'
        log_action(
            f"Updated event {event_id} details: {change_text}"
        )
        newly_assigned = [
            assigned_username
            for assigned_username in _event_assigned_usernames(event)
            if assigned_username.casefold()
            not in {value.casefold() for value in old_assigned_usernames}
        ]
        _queue_assigned_event_notification(
            manager=data_manager,
            event=event,
            assigned_usernames=newly_assigned,
        )

        return jsonify({'success': True, 'message': 'Event updated successfully'})
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error(f"Error updating event: {e}")
        return jsonify({'error': 'Failed to update event'}), 500

@app.route('/api/assets/<asset_id>/maintenance-log/<int:log_index>', methods=['DELETE'])
@require_auth
def delete_maintenance_log(asset_id, log_index):
    """Delete a specific maintenance log entry and recalculate asset status"""
    try:
        logger.info(f"Received maintenance log delete request for asset: '{asset_id}', log index: {log_index}")
        
        asset_id = unquote_plus(asset_id)
        
        asset = data_manager.inventory.get(asset_id)
        if not asset:
            return jsonify({'error': 'Asset not found'}), 404
        
        # Check if log index is valid
        if not asset.maintenance_logs or log_index < 0 or log_index >= len(asset.maintenance_logs):
            return jsonify({'error': 'Invalid log index'}), 400
        
        # Only admins may delete maintenance logs. Normal users may edit their
        # own recent logs, but deletion is intentionally admin-only.
        if not _current_user_is_admin():
            return jsonify({'error': 'Admin privileges required to delete maintenance logs'}), 403

        # Get the log entry that will be deleted for logging purposes
        deleted_log = normalize_maintenance_log(asset.maintenance_logs[log_index])
        if (deleted_log.get('source') or {}).get('kind') == CONTAINER_MAINTENANCE_SOURCE:
            return jsonify({
                'error': 'Container maintenance logs are retained as historical records and cannot be deleted from an individual asset'
            }), 409
        deleted_description = deleted_log.get('description', '')
        previous_asset_status = _asset_notification_status(asset)
        
        # Remove the log entry
        asset.maintenance_logs.pop(log_index)
        deleted_media_count = _delete_maintenance_media_files(deleted_log)
        
        # Recalculate asset status based on remaining logs
        recalculate_asset_status_from_logs(asset)
        
        # Save changes
        data_manager.save_inventory()
        invalidate_cache({
            'assetIds': [asset_id],
            'action': 'maintenance-log-deleted',
        })
        
        # Log the action
        media_text = f" and {deleted_media_count} media file(s)" if deleted_media_count else ""
        log_action(
            f"Deleted maintenance log{media_text} for asset {asset_id}: "
            f"'{deleted_description}' (deleted by {session['user']})",
            system_log_only=True,
        )
        _queue_asset_status_notification(
            manager=data_manager,
            asset=asset,
            previous_status=previous_asset_status,
            new_status=_asset_notification_status(asset),
        )
        
        logger.info(f"Successfully deleted maintenance log for asset {asset_id}")
        return jsonify({'success': True, 'message': 'Maintenance log deleted successfully'})
        
    except Exception as e:
        logger.error(f"Error deleting maintenance log for asset {asset_id}: {e}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")
        return jsonify({'error': f'Failed to delete maintenance log: {str(e)}'}), 500

def recalculate_asset_status_from_logs(asset):
    """Recalculate asset condition, serial, and location from maintenance logs."""
    try:
        deployed_event = _active_event_for_asset(asset.asset_id)
        asset.is_ooc = False
        asset.is_missing = False
        asset.is_untagged = False
        asset.is_degraded = False
        asset.is_disposed = False
        asset.current_location = ''

        sorted_logs = []
        for i, log_entry in enumerate(asset.maintenance_logs):
            record = normalize_maintenance_log(log_entry)
            date_str = record.get('date', '')
            try:
                date_obj = datetime.strptime(date_str, "%Y/%m/%d")
            except ValueError:
                logger.warning(f"Invalid date format in log: {date_str}")
                date_obj = datetime.min

            sorted_logs.append((date_obj, i, record))

        sorted_logs.sort(key=lambda x: (x[0], x[1]))

        for date_obj, log_index, log_entry in sorted_logs:
            apply_maintenance_log_changes(asset, log_entry)

        # Maintenance owns the stored/off-show location. Deployment owns the
        # live location while the asset remains active on an event.
        if deployed_event:
            asset.current_location = deployed_event.name

        logger.info(
            f"Final status for {asset.asset_id}: "
            f"OOC={asset.is_ooc}, Missing={asset.is_missing}, Untagged={_is_untagged(asset)}, "
            f"Degraded={_is_degraded(asset)}, Decommissioned={_is_disposed(asset)}, "
            f"Location='{asset.current_location}'"
        )

    except Exception as e:
        logger.error(f"Error recalculating asset status from logs for {asset.asset_id}: {e}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")

@app.route('/api/events/<int:event_id>', methods=['DELETE'])
@require_admin
def delete_event(event_id):
    """Delete an event"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        event_name = event.name
        data = request.get_json(silent=True) or {}
        has_event_content = any((
            bool(getattr(event, 'asset_models', []) or []),
            bool(getattr(event, 'prepared_items', []) or []),
            bool(getattr(event, 'actually_prepared', []) or []),
            bool(getattr(event, 'returned_items', []) or []),
            bool(getattr(event, 'extra_assets', []) or []),
            bool(getattr(event, 'notes', '') or ''),
            bool(_event_files_for_response(event_id)),
        ))

        workforce_folder = _workforce_folder()
        workforce_files_removed = 0
        workforce_rows_removed = 0
        fleet_vehicle_ids_removed = []
        workforce_snapshot = load_workforce(workforce_folder)
        event_workforce_rows = (
            len(event_assignments(workforce_snapshot, event_id)) +
            sum(
                len((rows or {}).get('invoices', []) or []) +
                len((rows or {}).get('claims', []) or [])
                for rows in (
                    (workforce_snapshot.get('submissions') or {})
                    .get(str(event_id), {})
                    .values()
                )
                if isinstance(rows, dict)
            ) +
            len(event_bookings(workforce_snapshot, event_id))
        )
        has_event_content = has_event_content or event_workforce_rows > 0

        if has_event_content:
            ok, message = _verify_current_admin_password(data.get('adminPassword'))
            if not ok:
                return jsonify({
                    'error': message,
                    'requiresPassword': True,
                }), 403

        # Return all assets to their default locations
        assets_reset = []
        
        # Reset assets from prepared_items
        for asset_id in event.prepared_items.copy():
            if not (_is_custom_ref(asset_id) or asset_id.startswith('[MODEL]')):
                asset = data_manager.inventory.get(asset_id)
                if asset:
                    old_location = asset.current_location
                    asset.current_location = asset.default_location or ""
                    assets_reset.append(f"{asset_id} (from '{old_location}' to '{asset.current_location or 'Store'}')")

        # Reset assets from actually_prepared (in case there are any not in prepared_items)
        if hasattr(event, 'actually_prepared'):
            for asset_id in event.actually_prepared.copy():
                if not _is_custom_ref(asset_id):
                    asset = data_manager.inventory.get(asset_id)
                    if asset and asset_id not in event.prepared_items:
                        old_location = asset.current_location
                        asset.current_location = asset.default_location or ""
                        assets_reset.append(f"{asset_id} (from '{old_location}' to '{asset.current_location or 'Store'}')")

        # Save inventory changes
        data_manager.save_inventory()

        with mutate_workforce(workforce_folder) as workforce:
            event_key = str(event_id)
            workforce_rows_removed += len(
                workforce.get('assignments', {}).get(event_key, []) or []
            )
            workforce.get('assignments', {}).pop(event_key, None)
            workforce.get('manualDepartments', {}).pop(event_key, None)
            workforce.get('hiddenDepartments', {}).pop(event_key, None)
            workforce.get('uploadAllowances', {}).pop(event_key, None)

            submission_subjects = (
                workforce.get('submissions', {}).pop(event_key, {}) or {}
            )
            for rows in submission_subjects.values():
                if not isinstance(rows, dict):
                    continue
                for plural in ('invoices', 'claims'):
                    for record in rows.get(plural, []) or []:
                        if isinstance(record, dict):
                            delete_upload(workforce_folder, record)
                            workforce_files_removed += 1
                            workforce_rows_removed += 1

            transport_bookings = (
                workforce.get('transportBookings', {}).pop(event_key, []) or []
            )
            workforce_rows_removed += len(transport_bookings)
            for booking in transport_bookings:
                if (
                    isinstance(booking, dict)
                    and str(booking.get('sourceType') or '').lower() == 'fleet'
                    and booking.get('vehicleId')
                ):
                    fleet_vehicle_ids_removed.append(
                        str(booking.get('vehicleId'))
                    )
                if not isinstance(booking, dict):
                    continue
                invoices = [booking.get('invoice')]
                invoices.extend(transport_company_invoices(booking))
                invoices.extend(
                    booking.get('claims', [])
                    if isinstance(booking.get('claims'), list) else []
                )
                for invoice in invoices:
                    if isinstance(invoice, dict):
                        delete_upload(workforce_folder, invoice)
                        workforce_files_removed += 1

        finance_cleanup = _finance_remove_deleted_event_references(event_id)

        # Keep the old ID occupied until all event-scoped data is gone. Once
        # deletion completes, another request can safely reuse this slot.
        manager = _current_data_manager_object()
        with _event_creation_lock:
            if manager.events.get(event_id) is not event:
                raise ConcurrentDataChangeError(
                    f'Event {event_id} changed before deletion'
                )
            del manager.events[event_id]
            try:
                manager.delete_event_file(event_id)
            except Exception:
                if event_id not in manager.events:
                    manager.events[event_id] = event
                raise

        # Invalidate cache
        invalidate_cache()

        # Log the deletion with details of reset assets. Event-specific logs were
        # stored inside the deleted event file, so they are removed with the event.
        workforce_text = (
            f" Removed {workforce_rows_removed} workforce row(s)"
            f" and {workforce_files_removed} upload file(s)."
            if workforce_rows_removed or workforce_files_removed
            else ""
        )
        if assets_reset:
            log_action(f"Deleted event {event_id}: {event_name} via web interface. Reset {len(assets_reset)} asset locations: {', '.join(assets_reset[:5])}{'...' if len(assets_reset) > 5 else ''}.{workforce_text}")
        else:
            log_action(f"Deleted event {event_id}: {event_name} via web interface. No asset locations to reset.{workforce_text}")

        mark_realtime_change('events', {'eventId': event_id, 'action': 'deleted'})
        mark_realtime_change('workforce', {'eventId': event_id, 'action': 'event-deleted'})
        if fleet_vehicle_ids_removed:
            mark_realtime_change('vehicles', {
                'eventId': event_id,
                'vehicleIds': sorted(set(fleet_vehicle_ids_removed)),
                'action': 'event-deleted',
            })
        if finance_cleanup['documentLinks'] or finance_cleanup['profitLossRows']:
            mark_realtime_change('finance', {'eventId': event_id, 'action': 'event-deleted'})

        return jsonify({
            'success': True,
            'message': 'Event deleted successfully',
            'assetsReset': len(assets_reset),
            'workforceRowsRemoved': workforce_rows_removed,
            'workforceFilesRemoved': workforce_files_removed,
            'financeLinksRemoved': finance_cleanup['documentLinks'],
            'profitLossRowsRemoved': finance_cleanup['profitLossRows'],
        })
    except Exception as e:
        logger.error(f"Error deleting event {event_id}: {e}")
        return jsonify({'error': f'Failed to delete event: {str(e)}'}), 500

@app.route('/api/events/<int:event_id>/assets', methods=['POST'])
@require_admin
def add_asset_to_event(event_id):
    """Add an asset to an event (unprepared by default)"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        asset_id = data.get('assetId', '').strip()

        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400

        # Initialize actually_prepared if it doesn't exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []

        # Check if asset is already in this event
        if asset_id in event.prepared_items:
            return jsonify({'error': 'Asset is already assigned to this event'}), 400

        # Structured/legacy custom assets are assigned only; they are not automatically prepared.
        if _is_custom_ref(asset_id):
            _ensure_event_custom_lists(event)
            if asset_id not in event.prepared_items:
                event.prepared_items.append(asset_id)
            if asset_id in event.returned_items:
                event.returned_items.remove(asset_id)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            _log_event_asset_action(
                event_id,
                'assign',
                [_event_asset_log_item(asset_id)],
            )
            return jsonify({'success': True, 'message': 'Custom asset assigned to event'})

        # For regular assets, perform additional checks
        if not _is_custom_ref(asset_id):
            asset = data_manager.inventory.get(asset_id)
            if not asset:
                return jsonify({'error': 'Asset not found'}), 404

            if _is_disposed(asset):
                return jsonify({'error': 'Cannot assign decommissioned asset'}), 400

            if asset.is_missing:
                return jsonify({'error': 'Cannot assign missing asset'}), 400

            busy_event = _find_event_using_asset(asset_id, event)
            if busy_event:
                return jsonify({
                    'error': f'Asset is already assigned to another event {busy_event.event_id}: {busy_event.name}'
                }), 400

        # Add the asset as UNPREPARED (just assigned to event)
        event.prepared_items.append(asset_id)

        # Remove from returned items if it was there
        if asset_id in event.returned_items:
            event.returned_items.remove(asset_id)

        # Update event state
        update_event_state(event)

        # Save changes
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()

        _log_event_asset_action(
            event_id,
            'assign',
            [_event_asset_log_item(asset_id)],
        )

        return jsonify({'success': True, 'message': f'Asset {asset_id} assigned to event (unprepared)'})
    except Exception as e:
        logger.error(f"Error adding asset to event {event_id}: {e}")
        return jsonify({'error': 'Failed to add asset to event'}), 500


@app.route('/api/events/<int:event_id>/subprojects', methods=['POST'])
@require_admin
def add_event_subproject(event_id):
    """Add a planning room while preserving an older aggregate event plan."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        name = str(data.get('name') or '').strip()
        if not name:
            return jsonify({'error': 'Sub-project name is required'}), 400
        if len(name) > 100:
            return jsonify({'error': 'Sub-project name must be 100 characters or fewer'}), 400

        subprojects = [
            row for row in (getattr(event, 'subprojects', []) or [])
            if isinstance(row, dict)
        ]
        if any(
            str(row.get('name') or '').strip().casefold() == name.casefold()
            for row in subprojects
        ):
            return jsonify({'error': 'A sub-project with this name already exists'}), 409

        if not subprojects:
            initial_subproject = {
                'id': 'main',
                'name': 'Main Room',
                'items': _event_initial_subproject_items(event),
            }
            _event_allocate_existing_refs_to_initial_subproject(
                event,
                initial_subproject,
            )
            subprojects.append(initial_subproject)

        existing_ids = {
            str(row.get('id') or '').strip()
            for row in subprojects
        }
        while True:
            subproject_id = f"room_{secrets.token_hex(6)}"
            if subproject_id not in existing_ids:
                break

        subprojects.append({
            'id': subproject_id,
            'name': name,
            'items': [],
        })
        event.subprojects = subprojects
        _reconcile_event_subproject_extras(event)
        data_manager.save_event(event)
        invalidate_cache()
        log_action(
            f"Added sub-project {name} to event {event_id}",
            event_meta={
                'eventId': event_id,
                'actionLabel': 'Added sub-project',
                'subprojectId': subproject_id,
                'subprojectName': name,
            },
        )
        mark_realtime_change('event-assets', {
            'eventId': event_id,
            'action': 'subproject-added',
            'subprojectId': subproject_id,
        })
        return jsonify({
            'success': True,
            'message': f'Sub-project {name} added',
            'data': {
                'subproject': subprojects[-1],
                'subprojects': subprojects,
            },
        }), 201
    except Exception as e:
        logger.error("Error adding sub-project to event %s: %s", event_id, e)
        return jsonify({'error': 'Failed to add sub-project'}), 500


@app.route('/api/events/<int:event_id>/subprojects/<subproject_id>', methods=['PATCH', 'DELETE'])
@require_admin
@with_prepare_action_lock
def manage_event_subproject(event_id, subproject_id):
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404
        source = _event_subproject(event, subproject_id)
        if not source:
            return jsonify({'error': 'Sub-project not found'}), 404

        subprojects = [
            row for row in (getattr(event, 'subprojects', []) or [])
            if isinstance(row, dict)
        ]
        if request.method == 'PATCH':
            data = request.get_json(silent=True) or {}
            name = str(data.get('name') or '').strip()
            if not name:
                return jsonify({'error': 'Sub-project name is required'}), 400
            if len(name) > 100:
                return jsonify({'error': 'Sub-project name must be 100 characters or fewer'}), 400
            if any(
                row is not source and
                str(row.get('name') or '').strip().casefold() == name.casefold()
                for row in subprojects
            ):
                return jsonify({'error': 'A sub-project with this name already exists'}), 409

            previous_name = str(source.get('name') or 'Sub-project')
            source['name'] = name
            event.subprojects = subprojects
            data_manager.save_event(event)
            invalidate_cache()
            log_action(
                f"Renamed sub-project {previous_name} to {name} for event {event_id}",
                event_meta={
                    'eventId': event_id,
                    'actionLabel': 'Renamed sub-project',
                    'subprojectId': subproject_id,
                    'previousSubprojectName': previous_name,
                    'subprojectName': name,
                },
            )
            mark_realtime_change('event-assets', {
                'eventId': event_id,
                'action': 'subproject-renamed',
                'subprojectId': subproject_id,
            })
            return jsonify({
                'success': True,
                'message': f'{previous_name} renamed to {name}',
                'data': {'subprojects': event.subprojects},
            })

        if len(subprojects) <= 1:
            return jsonify({'error': 'The only room cannot be deleted'}), 400

        data = request.get_json(silent=True) or {}
        mode = str(data.get('mode') or 'remove').strip().lower()
        if mode not in {'remove', 'merge'}:
            return jsonify({'error': 'Delete mode must be remove or merge'}), 400

        removed_refs = 0
        target = None
        if mode == 'merge':
            target = _event_subproject(event, data.get('targetSubprojectId'))
            if not target or target is source:
                return jsonify({'error': 'Choose another room to merge into'}), 400
            _event_merge_subproject(event, source, target)
        else:
            removed_refs = _event_remove_subproject_contents(event, source)

        event.subprojects = [row for row in subprojects if row is not source]
        _sync_event_model_markers_from_subprojects(event)
        _reconcile_event_subproject_extras(event)
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()

        source_name = str(source.get('name') or 'Sub-project')
        if target:
            action = (
                f"Merged sub-project {source_name} into "
                f"{target.get('name') or 'another room'} for event {event_id}"
            )
        elif removed_refs:
            action = (
                f"Deleted sub-project {source_name} and removed its assets "
                f"from event {event_id}"
            )
        else:
            action = f"Deleted sub-project {source_name} from event {event_id}"
        log_action(action, event_meta={
            'eventId': event_id,
            'actionLabel': 'Merged sub-project' if target else 'Deleted sub-project',
            'subprojectId': subproject_id,
            'subprojectName': source_name,
            'targetSubprojectId': target.get('id') if target else '',
            'removedReferences': removed_refs,
        })
        mark_realtime_change('event-assets', {
            'eventId': event_id,
            'action': 'subproject-deleted',
            'subprojectId': subproject_id,
        })
        return jsonify({
            'success': True,
            'message': (
                f'{source_name} merged into {target.get("name")}'
                if target
                else f'{source_name} deleted'
            ),
            'data': {'subprojects': event.subprojects},
        })
    except Exception as e:
        logger.error("Error managing sub-project %s for event %s: %s", subproject_id, event_id, e)
        return jsonify({'error': 'Failed to update sub-project'}), 500


@app.route('/api/events/<int:event_id>/subprojects/reorder', methods=['POST'])
@require_admin
@with_prepare_action_lock
def reorder_event_subprojects(event_id):
    """Persist the display order of every sub-project in an event."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        subprojects = [
            row for row in (getattr(event, 'subprojects', []) or [])
            if isinstance(row, dict)
        ]
        data = request.get_json(silent=True) or {}
        ordered_ids = data.get('orderedSubprojectIds')
        if not isinstance(ordered_ids, list):
            return jsonify({'error': 'Sub-project order must be a list'}), 400

        ordered_ids = [str(value or '').strip() for value in ordered_ids]
        current_ids = [str(row.get('id') or '').strip() for row in subprojects]
        if (
            any(not value for value in ordered_ids)
            or len(ordered_ids) != len(current_ids)
            or len(set(ordered_ids)) != len(ordered_ids)
            or set(ordered_ids) != set(current_ids)
        ):
            return jsonify({
                'error': 'Sub-project order must contain every room exactly once'
            }), 400

        by_id = {
            str(row.get('id') or '').strip(): row
            for row in subprojects
        }
        event.subprojects = [by_id[subproject_id] for subproject_id in ordered_ids]
        if ordered_ids != current_ids:
            data_manager.save_event(event)
            invalidate_cache()
            ordered_names = [
                str(row.get('name') or 'Room')
                for row in event.subprojects
            ]
            log_action(
                f"Reordered sub-projects for event {event_id}: "
                f"{', '.join(ordered_names)}",
                event_meta={
                    'eventId': event_id,
                    'actionLabel': 'Reordered sub-projects',
                    'subprojectOrder': ordered_ids,
                },
            )
            mark_realtime_change('event-assets', {
                'eventId': event_id,
                'action': 'subprojects-reordered',
                'subprojectOrder': ordered_ids,
            })

        return jsonify({
            'success': True,
            'message': 'Sub-project order updated',
            'data': {'subprojects': event.subprojects},
        })
    except Exception as e:
        logger.error(
            "Error reordering sub-projects for event %s: %s",
            event_id,
            e,
        )
        return jsonify({'error': 'Failed to reorder sub-projects'}), 500


@app.route('/api/events/<int:event_id>/subprojects/move', methods=['POST'])
@require_admin
@with_prepare_action_lock
def move_event_subproject_content(event_id):
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404
        data = request.get_json(silent=True) or {}
        source = _event_subproject(event, data.get('sourceSubprojectId'))
        target = _event_subproject(event, data.get('targetSubprojectId'))
        if not source or not target:
            return jsonify({'error': 'Source or destination room was not found'}), 404
        if source is target:
            return jsonify({'error': 'Choose a different destination room'}), 400

        kind = str(data.get('kind') or '').strip().lower()
        if kind == 'requirement':
            group = _group_from_request(data.get('group') or {})
            _event_move_subproject_requirement(event, source, target, group)
            moved_label = f"{group['brand']} {group['model']}".strip()
        elif kind == 'asset':
            asset_ref = str(data.get('assetRef') or '').strip()
            if not asset_ref:
                return jsonify({'error': 'Asset reference is required'}), 400
            moved_ref = _event_move_subproject_asset(
                event,
                source,
                target,
                asset_ref,
            )
            moved_label = _event_asset_log_item(moved_ref).get('label') or moved_ref
        else:
            return jsonify({'error': 'Move kind must be requirement or asset'}), 400

        _sync_event_model_markers_from_subprojects(event)
        _reconcile_event_subproject_extras(event)
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        log_action(
            f"Moved {moved_label} from {source.get('name')} to "
            f"{target.get('name')} for event {event_id}",
            event_meta={
                'eventId': event_id,
                'actionLabel': 'Moved room asset',
                'sourceSubprojectId': source.get('id'),
                'targetSubprojectId': target.get('id'),
                'item': moved_label,
            },
        )
        mark_realtime_change('event-assets', {
            'eventId': event_id,
            'action': 'subproject-content-moved',
            'sourceSubprojectId': source.get('id'),
            'targetSubprojectId': target.get('id'),
        })
        return jsonify({
            'success': True,
            'message': (
                f"Moved {moved_label} to {target.get('name') or 'destination room'}"
            ),
            'data': {'subprojects': event.subprojects},
        })
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error("Error moving sub-project content for event %s: %s", event_id, e)
        return jsonify({'error': 'Failed to move room content'}), 500


@app.route('/api/events/<int:event_id>/models', methods=['POST', 'PUT', 'DELETE'])
@require_admin
@with_prepare_action_lock
def manage_event_models(event_id):
    """Add, update, or remove model assignments on events."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        subproject = _event_subproject(event, data.get('subprojectId'))
        if str(data.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404

        # Sub-project planning keeps the aggregate model marker in sync for
        # availability, packing lists, and older integrations, while the room
        # item remains the editable source for the tabbed workspaces.
        if subproject:
            group = _group_from_request(data)
            current_room_quantity = _event_subproject_required_quantity(
                subproject,
                group,
            )
            current_total = _event_model_required_quantity(event, group)
            if request.method == 'POST':
                next_room_quantity = current_room_quantity + max(
                    1,
                    _safe_int(data.get('quantity'), 1),
                )
            elif request.method == 'PUT':
                next_room_quantity = max(1, _safe_int(data.get('quantity'), 1))
                if current_room_quantity <= 0:
                    return jsonify({'error': 'Model assignment not found'}), 404
            else:
                next_room_quantity = 0
                if current_room_quantity <= 0:
                    return jsonify({'error': 'Model assignment not found'}), 404

            projected_total = current_total - current_room_quantity + next_room_quantity

            _event_subproject_set_group_quantity(
                subproject,
                group,
                next_room_quantity,
            )
            _sync_event_model_markers_from_subprojects(event)
            room_reconciliation = _reconcile_event_subproject_extras(event)
            extra_units = sum(
                _event_subproject_ref_quantity(ref)
                for ref in room_reconciliation['demoted']
            )
            # Older/legacy room data can have a prepared bulk marker at event
            # level without the same marker persisted in the room's assetRefs.
            # The browser can still allocate it to the room for display, so a
            # requirement deletion must also reclassify global prepared surplus
            # instead of relying only on room ownership reconciliation.
            global_surplus = _reclassify_event_model_surplus(
                event,
                _event_model_group_key(group),
                projected_total,
            )
            extra_units += global_surplus['extraUnits']

            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            verb = {
                'POST': 'Added',
                'PUT': 'Updated',
                'DELETE': 'Removed',
            }[request.method]
            room_name = str(subproject.get('name') or 'sub-project')
            log_action(
                f"{verb} {group['brand']} {group['model']} in {room_name} "
                f"for event {event_id}: {current_room_quantity} -> {next_room_quantity}"
            )
            return jsonify({
                'success': True,
                'message': (
                    f"{verb} {group['brand']} {group['model']} in {room_name}"
                ),
                'data': {
                    'oldQuantity': current_room_quantity,
                    'newQuantity': next_room_quantity,
                    'eventQuantity': projected_total,
                    'unpreparedQuantity': 0,
                    'extraQuantity': extra_units,
                    'promotedExtraAssets': room_reconciliation['promoted'],
                    'subprojectId': subproject.get('id'),
                },
            })

        if request.method == 'PUT':
            # Set the planning quantity without touching any prepared, returned,
            # or extra physical references for this model. In particular, a
            # reduction may leave more units prepared than are now required;
            # those units remain deliberately attached to the event.
            brand = data.get('brand', '').strip()
            model = data.get('model', '').strip()
            department = data.get('department', '').strip().upper()
            provided_description = data.get('description', '').strip()
            new_quantity = max(1, int(data.get('quantity', 1)))

            if not brand or not model or not department:
                return jsonify({'error': 'Brand, model, and department are required'}), 400

            group_key = _model_key_from_parts(
                department, brand, model, provided_description
            )

            matching_indexes = []
            existing_quantity = 0
            display_description = provided_description

            for index, item in enumerate(getattr(event, 'prepared_items', []) or []):
                marker = _parse_model_marker(item)
                if not marker:
                    continue
                marker_key = _model_key_from_parts(
                    marker['department'],
                    marker['brand'],
                    marker['model'],
                    marker.get('description'),
                )
                if marker_key != group_key:
                    continue
                matching_indexes.append(index)
                existing_quantity += max(0, _safe_int(marker.get('quantity'), 0))
                if not display_description and marker.get('description'):
                    display_description = marker['description']

            if not matching_indexes:
                return jsonify({'error': 'Model assignment not found'}), 404

            updated_marker = _make_model_marker({
                'department': department,
                'brand': brand,
                'model': model,
                'description': display_description,
            }, new_quantity)
            first_index = matching_indexes[0]
            matching_index_set = set(matching_indexes)
            event.prepared_items = [
                updated_marker if index == first_index else item
                for index, item in enumerate(event.prepared_items)
                if index not in matching_index_set or index == first_index
            ]

            extras = _reclassify_event_model_surplus(
                event,
                group_key,
                new_quantity,
            )
            promoted = _promote_matching_extra_assets(event)

            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()

            log_action(
                f"Updated {brand} {model} model quantity for event {event_id}: "
                f"{existing_quantity} -> {new_quantity}"
            )

            return jsonify({
                'success': True,
                'message': f'Updated {brand} {model} quantity to {new_quantity}',
                'data': {
                    'oldQuantity': existing_quantity,
                    'newQuantity': new_quantity,
                    'extraQuantity': extras['extraUnits'],
                    'promotedExtraAssets': promoted,
                },
            })

        elif request.method == 'POST':
            # Add model assignment
            brand = data.get('brand', '').strip()
            model = data.get('model', '').strip()
            department = data.get('department', '').strip().upper()
            provided_description = data.get('description', '').strip()
            quantity = max(1, int(data.get('quantity', 1)))

            logger.debug(
                "Add model request: brand=%r, model=%r, department=%r, "
                "description=%r, quantity=%s",
                brand,
                model,
                department,
                provided_description,
                quantity,
            )

            if not brand or not model or not department:
                return jsonify({'error': 'Brand, model, and department are required'}), 400

            # Get the FULL description from the actual asset, not from the request if none provided
            full_description = provided_description

            # Only try to get description from inventory if none was provided
            if not full_description:
                for asset in data_manager.inventory.values():
                    if (asset.brand == brand and 
                        asset.model_number == model and 
                        asset.department_code == department):
                        full_description = asset.description
                        logger.info(f"No description provided, using from asset {asset.asset_id}: '{full_description}'")
                        break

            logger.info(f"Final description for {brand} {model}: '{full_description}' (length: {len(full_description)})")

            # Log current prepared_items
            logger.info(f"Current prepared_items: {event.prepared_items}")

            # Description is part of event-side identity: visually distinct
            # variants of the same inventory model remain separate requirements.
            existing_model_ids = []
            existing_quantity = 0
            display_description = full_description

            for item in event.prepared_items:
                logger.info(f"Checking item: '{item}'")
                if item.startswith('[MODEL]'):
                    parts = item[7:].split('|')
                    logger.info(f"Item parts: {parts}")
                    if len(parts) >= 4:  # dept|brand|model|qty|description
                        item_dept = parts[0]
                        item_brand = parts[1]
                        item_model = parts[2]
                        item_description = '|'.join(parts[4:]) if len(parts) > 4 else ''
                        
                        logger.info(f"Item details - Dept: '{item_dept}', Brand: '{item_brand}', Model: '{item_model}', Desc: '{item_description}'")
                        
                        if (item_dept == department and 
                            item_brand == brand and 
                            item_model == model and
                            item_description.strip().casefold() ==
                                display_description.strip().casefold()):
                            existing_model_ids.append(item)
                            existing_quantity += _safe_int(parts[3], 0)
                            if not display_description and item_description:
                                display_description = item_description
                            logger.info(f"FOUND EXISTING MODEL: '{item}'")

            if existing_model_ids:
                logger.info(f"Updating existing model rows, removing: {existing_model_ids}")
                for existing_model_id in existing_model_ids:
                    event.prepared_items.remove(existing_model_id)
                new_quantity = existing_quantity + quantity
            else:
                logger.info("Creating new model assignment")
                new_quantity = quantity

            # Create a consolidated marker for this exact described asset type.
            model_id = f"[MODEL]{department}|{brand}|{model}|{new_quantity}|{display_description}"
            logger.info(f"Creating model assignment: '{model_id}'")
            event.prepared_items.append(model_id)
            
            logger.info(f"Updated prepared_items: {event.prepared_items}")

            # Initialize actually_prepared if it doesn't exist
            if not hasattr(event, 'actually_prepared'):
                event.actually_prepared = []

            promoted = _promote_matching_extra_assets(event)

            # Update event state if needed
            update_event_state(event)

            # Save changes
            data_manager.save_event(event)

            # Invalidate cache
            invalidate_cache()

            log_action(
                f"Added {quantity}x {brand} {model} model to event {event_id} (total: {new_quantity})")

            return jsonify({
                'success': True,
                'message': f'Added {quantity}x {brand} {model} to event (total: {new_quantity})',
                'data': {'promotedExtraAssets': promoted},
            })

        elif request.method == 'DELETE':
            # Remove model assignment completely
            brand = data.get('brand', '').strip()
            model = data.get('model', '').strip()
            department = data.get('department', '').strip()

            if not brand or not model or not department:
                return jsonify({'error': 'Brand, model, and department are required'}), 400

            # Find matching model assignments for this dept/brand/model
            description_to_match = (data.get('description') or '').strip()

            candidates = []
            for item in event.prepared_items:
                if not item.startswith('[MODEL]'):
                    continue

                parts = item[7:].split('|')  # [MODEL]DEPT|BRAND|MODEL|QUANTITY|DESCRIPTION
                if len(parts) < 4:
                    continue

                item_dept = parts[0]
                item_brand = parts[1]
                item_model = parts[2]
                item_description = '|'.join(parts[4:]) if len(parts) > 4 else ''

                if item_dept == department and item_brand == brand and item_model == model:
                    candidates.append((item, item_description))

            if not candidates:
                return jsonify({'error': 'Model assignment not found'}), 404

            if description_to_match:
                items_to_remove = [
                    item for item, description in candidates
                    if description.strip().casefold() == description_to_match.casefold()
                ]
                if not items_to_remove:
                    return jsonify({'error': 'Model assignment not found'}), 404
            else:
                descriptions = {
                    description.strip().casefold() for _item, description in candidates
                }
                if len(descriptions) > 1:
                    return jsonify({
                        'error': 'Description is required to identify this model assignment'
                    }), 400
                items_to_remove = [item for item, _description in candidates]

            group_key = _model_key_from_parts(
                department, brand, model, description_to_match
            )

            for item in items_to_remove:
                event.prepared_items.remove(item)

            extras = _reclassify_event_model_surplus(event, group_key, 0)

            # Update event state
            update_event_state(event)

            # Save changes
            data_manager.save_event(event)

            # Invalidate cache
            invalidate_cache()

            log_action(
                f"Removed {brand} {model} requirement from event {event_id}; "
                f"kept {extras['extraUnits']} prepared unit(s) as extra"
            )

            return jsonify({
                'success': True,
                'message': f'Removed {brand} {model} from event',
                'data': {
                    'unpreparedQuantity': 0,
                    'extraQuantity': extras['extraUnits'],
                    'referencesMarkedExtra': extras['referencesMarked'],
                },
            })

    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error(f"Error managing event models: {e}")
        return jsonify({'error': 'Failed to manage event models'}), 500


@app.route('/api/events/<int:event_id>/models/replace', methods=['POST'])
@require_admin
@with_prepare_action_lock
def replace_event_model_requirement(event_id):
    """Replace part of one planned model requirement with another atomically."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        payload = request.get_json() or {}
        source = payload.get('source') or {}
        replacement = payload.get('replacement') or {}
        quantity = max(1, _safe_int(payload.get('quantity'), 1))

        def model_details(value):
            department = str(value.get('department') or '').strip().upper()
            brand = str(value.get('brand') or '').strip()
            model = str(value.get('model') or '').strip()
            description = str(value.get('description') or '').strip()
            if not department or not brand or not model:
                raise ValueError('Department, brand, and model are required')
            return department, brand, model, description

        source_department, source_brand, source_model, source_description = model_details(source)
        target_department, target_brand, target_model, target_description = model_details(replacement)
        source_key = _model_key_from_parts(
            source_department, source_brand, source_model, source_description
        )
        target_key = _model_key_from_parts(
            target_department, target_brand, target_model, target_description
        )
        if source_key == target_key:
            return jsonify({'error': 'Choose a different replacement model'}), 400

        subproject = _event_subproject(event, payload.get('subprojectId'))
        if str(payload.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        if subproject:
            source_group = {
                'department': source_department,
                'brand': source_brand,
                'model': source_model,
                'description': source_description,
            }
            target_group = {
                'department': target_department,
                'brand': target_brand,
                'model': target_model,
                'description': target_description,
            }
            room_source = _event_subproject_required_quantity(subproject, source_group)
            room_target = _event_subproject_required_quantity(subproject, target_group)
            if quantity > room_source:
                return jsonify({'error': 'Replacement quantity exceeds this sub-project requirement'}), 400
            aggregate_target = _event_model_required_quantity(event, target_group)
            physical_target = sum(
                _asset_inventory_quantity(asset)
                for asset in data_manager.inventory.values()
                if asset and not _is_disposed(asset) and _event_asset_group_key(asset) == target_key
            )
            if aggregate_target + quantity > physical_target:
                return jsonify({'error': f'Only {physical_target} total {target_brand} {target_model} unit(s) exist'}), 400
            _event_subproject_set_group_quantity(subproject, source_group, room_source - quantity)
            _event_subproject_set_group_quantity(subproject, target_group, room_target + quantity)
            _sync_event_model_markers_from_subprojects(event)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            log_action(
                f'Replaced {quantity}x {source_brand} {source_model} with '
                f'{target_brand} {target_model} in {subproject.get("name") or "sub-project"} '
                f'for event {event_id}'
            )
            mark_realtime_change('event-assets', {
                'eventId': event_id,
                'action': 'replace-model-requirement',
            })
            return jsonify({
                'success': True,
                'message': f'Replaced {quantity} item(s)',
                'data': {
                    'sourceQuantity': room_source - quantity,
                    'replacementQuantity': room_target + quantity,
                    'subprojectId': subproject.get('id'),
                },
            })

        source_quantity = 0
        target_quantity = 0
        source_indexes = []
        target_indexes = []
        for index, item in enumerate(getattr(event, 'prepared_items', []) or []):
            marker = _parse_model_marker(item)
            if not marker:
                continue
            marker_key = _model_key_from_parts(
                marker.get('department'), marker.get('brand'), marker.get('model'),
                marker.get('description')
            )
            marker_quantity = max(0, _safe_int(marker.get('quantity'), 0))
            if marker_key == source_key:
                source_quantity += marker_quantity
                source_indexes.append(index)
                source_description = source_description or str(marker.get('description') or '')
            elif marker_key == target_key:
                target_quantity += marker_quantity
                target_indexes.append(index)
                target_description = target_description or str(marker.get('description') or '')

        if source_quantity <= 0:
            return jsonify({'error': 'Original model requirement not found'}), 404
        if quantity > source_quantity:
            return jsonify({'error': 'Replacement quantity exceeds the original requirement'}), 400

        physical_target_quantity = sum(
            _asset_inventory_quantity(asset)
            for asset in data_manager.inventory.values()
            if asset and not _is_disposed(asset) and _event_asset_group_key(asset) == target_key
        )
        if target_quantity + quantity > physical_target_quantity:
            return jsonify({
                'error': (
                    f'Only {physical_target_quantity} total {target_brand} {target_model} '
                    f'unit(s) exist; {target_quantity} are already requested here.'
                )
            }), 400

        removed_indexes = set(source_indexes + target_indexes)
        updated_items = [
            item for index, item in enumerate(event.prepared_items)
            if index not in removed_indexes
        ]
        remaining_source = source_quantity - quantity
        if remaining_source > 0:
            updated_items.append(_make_model_marker({
                'department': source_department,
                'brand': source_brand,
                'model': source_model,
                'description': source_description,
            }, remaining_source))
        updated_items.append(_make_model_marker({
            'department': target_department,
            'brand': target_brand,
            'model': target_model,
            'description': target_description,
        }, target_quantity + quantity))

        event.prepared_items = updated_items
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        log_action(
            f'Replaced {quantity}x {source_brand} {source_model} with '
            f'{target_brand} {target_model} for event {event_id}'
        )
        mark_realtime_change('event-assets', {
            'eventId': event_id,
            'action': 'replace-model-requirement',
        })
        return jsonify({
            'success': True,
            'message': f'Replaced {quantity} item(s)',
            'data': {
                'sourceQuantity': remaining_source,
                'replacementQuantity': target_quantity + quantity,
            },
        })
    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400
    except Exception as exc:
        logger.error('Failed to replace event model requirement: %s', exc, exc_info=True)
        return jsonify({'error': 'Failed to replace model requirement'}), 500


@app.route('/api/events/<int:event_id>/models/loan', methods=['POST'])
@require_admin
@with_prepare_action_lock
def convert_event_model_requirement_to_loan(event_id):
    """Convert part of a planned model requirement into a sourced loan item."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        payload = request.get_json() or {}
        source = payload.get('source') or {}
        quantity = max(1, _safe_int(payload.get('quantity'), 1))
        company = str(payload.get('company') or '').strip()
        source_department = str(source.get('department') or '').strip().upper()
        source_brand = str(source.get('brand') or '').strip()
        source_model = str(source.get('model') or '').strip()
        source_description = str(source.get('description') or '').strip()

        if not source_department or not source_brand or not source_model:
            return jsonify({'error': 'Department, brand, and model are required'}), 400
        if not company:
            return jsonify({'error': 'Loan company/source is required'}), 400

        source_key = _model_key_from_parts(
            source_department, source_brand, source_model, source_description
        )
        subproject = _event_subproject(event, payload.get('subprojectId'))
        if str(payload.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        if subproject:
            source_group = {
                'department': source_department,
                'brand': source_brand,
                'model': source_model,
                'description': source_description,
            }
            room_source = _event_subproject_required_quantity(subproject, source_group)
            if quantity > room_source:
                return jsonify({'error': 'Loan quantity exceeds this sub-project requirement'}), 400
            loan_name = ' '.join(part for part in (source_brand, source_model) if part).strip()
            loan_marker = _make_custom_marker(
                'LOAN', loan_name, quantity, source_department, company
            )
            _event_subproject_set_group_quantity(subproject, source_group, room_source - quantity)
            subproject.setdefault('items', []).append({
                'lineId': f"plan_{secrets.token_hex(8)}",
                'department': source_department,
                'departmentCode': source_department,
                'brand': '',
                'model': '',
                'description': loan_name,
                'quantity': quantity,
                'isCustom': True,
                'assetRefs': [loan_marker],
            })
            _sync_event_model_markers_from_subprojects(event)
            event.prepared_items.append(loan_marker)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            log_action(
                f'Converted {quantity}x {loan_name} to loan from {company} in '
                f'{subproject.get("name") or "sub-project"} for event {event_id}'
            )
            mark_realtime_change('event-assets', {
                'eventId': event_id,
                'action': 'convert-model-requirement-to-loan',
            })
            return jsonify({
                'success': True,
                'message': f'Converted {quantity} item(s) to loan',
                'data': {
                    'sourceQuantity': room_source - quantity,
                    'loanAssetId': loan_marker,
                    'subprojectId': subproject.get('id'),
                },
            })
        source_quantity = 0
        source_indexes = []
        for index, item in enumerate(getattr(event, 'prepared_items', []) or []):
            marker = _parse_model_marker(item)
            if not marker:
                continue
            marker_key = _model_key_from_parts(
                marker.get('department'), marker.get('brand'), marker.get('model'),
                marker.get('description')
            )
            if marker_key != source_key:
                continue
            source_quantity += max(0, _safe_int(marker.get('quantity'), 0))
            source_indexes.append(index)
            source_description = source_description or str(marker.get('description') or '')

        if source_quantity <= 0:
            return jsonify({'error': 'Original model requirement not found'}), 404
        if quantity > source_quantity:
            return jsonify({'error': 'Loan quantity exceeds the original requirement'}), 400

        removed_indexes = set(source_indexes)
        updated_items = [
            item for index, item in enumerate(event.prepared_items)
            if index not in removed_indexes
        ]
        remaining_source = source_quantity - quantity
        if remaining_source > 0:
            updated_items.append(_make_model_marker({
                'department': source_department,
                'brand': source_brand,
                'model': source_model,
                'description': source_description,
            }, remaining_source))

        loan_name = ' '.join(part for part in (source_brand, source_model) if part).strip()
        loan_marker = _make_custom_marker(
            'LOAN', loan_name, quantity, source_department, company
        )
        updated_items.append(loan_marker)

        event.prepared_items = updated_items
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        log_action(
            f'Converted {quantity}x {loan_name} to loan from {company} for event {event_id}'
        )
        mark_realtime_change('event-assets', {
            'eventId': event_id,
            'action': 'convert-model-requirement-to-loan',
        })
        return jsonify({
            'success': True,
            'message': f'Converted {quantity} item(s) to loan',
            'data': {
                'sourceQuantity': remaining_source,
                'loanAssetId': loan_marker,
            },
        })
    except Exception as exc:
        logger.error(
            'Failed to convert event model requirement to loan: %s', exc, exc_info=True
        )
        return jsonify({'error': 'Failed to convert model requirement to loan'}), 500


@app.route('/api/planning-templates', methods=['GET', 'POST'])
@require_admin
def planning_templates_collection():
    """List or create company-wide event planning templates."""
    try:
        with _planning_templates_lock:
            templates = _load_planning_templates()
            if request.method == 'GET':
                return jsonify({'success': True, 'data': templates})

            data = request.get_json(silent=True) or {}
            name = str(data.get('name') or '').strip()
            if not name:
                return jsonify({'error': 'Template name is required'}), 400

            source = {
                'id': secrets.token_hex(8),
                'name': name,
                'models': data.get('models') or [],
                'customAssets': data.get('customAssets') or [],
                'createdAt': datetime.now().isoformat(timespec='seconds'),
                'updatedAt': datetime.now().isoformat(timespec='seconds'),
            }
            template = _normalise_planning_template(source)
            templates.append(template)
            templates = _save_planning_templates(templates)
            template = next(
                item for item in templates
                if item['id'] == template['id']
            )

        log_action(f"Created planning template '{template['name']}'")
        mark_realtime_change('planning-templates', {'templateId': template['id']})
        return jsonify({'success': True, 'data': template}), 201
    except Exception as exc:
        logger.error("Failed to process planning templates: %s", exc, exc_info=True)
        return jsonify({'error': 'Failed to process planning templates'}), 500


@app.route('/api/planning-templates/<template_id>', methods=['PUT', 'DELETE'])
@require_admin
def planning_template_resource(template_id):
    """Edit or delete one company-wide planning template."""
    try:
        clean_id = re.sub(r'[^a-zA-Z0-9_-]+', '', str(template_id or ''))[:80]
        with _planning_templates_lock:
            templates = _load_planning_templates()
            index = next(
                (
                    position
                    for position, item in enumerate(templates)
                    if item['id'] == clean_id
                ),
                None,
            )
            if index is None:
                return jsonify({'error': 'Planning template not found'}), 404

            existing = templates[index]
            if request.method == 'DELETE':
                templates.pop(index)
                _save_planning_templates(templates)
                deleted_name = existing['name']
            else:
                data = request.get_json(silent=True) or {}
                name = str(data.get('name') or existing['name']).strip()
                if not name:
                    return jsonify({'error': 'Template name is required'}), 400
                updated = _normalise_planning_template({
                    **existing,
                    'name': name,
                    'models': data.get('models', existing['models']),
                    'customAssets': data.get(
                        'customAssets',
                        existing['customAssets'],
                    ),
                    'updatedAt': datetime.now().isoformat(timespec='seconds'),
                })
                templates[index] = updated
                templates = _save_planning_templates(templates)
                updated = next(
                    item for item in templates
                    if item['id'] == clean_id
                )

        if request.method == 'DELETE':
            log_action(f"Deleted planning template '{deleted_name}'")
            mark_realtime_change('planning-templates', {'templateId': clean_id})
            return jsonify({'success': True})

        log_action(f"Updated planning template '{updated['name']}'")
        mark_realtime_change('planning-templates', {'templateId': clean_id})
        return jsonify({'success': True, 'data': updated})
    except Exception as exc:
        logger.error(
            "Failed to update planning template %s: %s",
            template_id,
            exc,
            exc_info=True,
        )
        return jsonify({'error': 'Failed to update planning template'}), 500


@app.route('/api/events/<int:event_id>/apply-planning-template', methods=['POST'])
@require_admin
@with_prepare_action_lock
def apply_planning_template(event_id):
    """Merge or replace an event's model/custom requirements from a template."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json(silent=True) or {}
        template_id = str(data.get('templateId') or '').strip()
        mode = str(data.get('mode') or 'merge').strip().lower()
        if mode not in {'merge', 'replace'}:
            return jsonify({'error': 'Mode must be merge or replace'}), 400

        with _planning_templates_lock:
            template = next(
                (
                    item for item in _load_planning_templates()
                    if item['id'] == template_id
                ),
                None,
            )
        if not template:
            return jsonify({'error': 'Planning template not found'}), 404

        subproject = _event_subproject(event, data.get('subprojectId'))
        if str(data.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        if subproject:
            if mode == 'replace':
                removed_custom_refs = [
                    ref
                    for item in subproject.get('items') or []
                    if isinstance(item, dict) and item.get('isCustom')
                    for ref in item.get('assetRefs') or []
                ]
                subproject['items'] = []
                for list_name in (
                    'prepared_items',
                    'actually_prepared',
                    'returned_items',
                    'extra_assets',
                    'custom_collected',
                ):
                    values = getattr(event, list_name, []) or []
                    setattr(event, list_name, [
                        ref for ref in values if ref not in removed_custom_refs
                    ])

            for source_row in template.get('models') or []:
                row = _normalise_planning_template_model(source_row)
                if not row:
                    continue
                current_quantity = _event_subproject_required_quantity(
                    subproject,
                    row,
                )
                _event_subproject_set_group_quantity(
                    subproject,
                    row,
                    current_quantity + row['quantity'],
                )

            for source_row in template.get('customAssets') or []:
                row = _normalise_planning_template_custom(source_row)
                if not row:
                    continue
                marker = _make_custom_marker(
                    row['type'],
                    row['name'],
                    row['quantity'],
                    row['department'],
                    row['company'],
                    description=row.get('description') or '',
                )
                event.prepared_items.append(marker)
                subproject.setdefault('items', []).append({
                    'lineId': f"plan_{secrets.token_hex(8)}",
                    'department': row['department'],
                    'departmentCode': row['department'],
                    'brand': '',
                    'model': '',
                    'description': row['name'],
                    'customDescription': row.get('description') or '',
                    'company': row.get('company') or '',
                    'quantity': row['quantity'],
                    'isCustom': True,
                    'assetRefs': [marker],
                })

            _sync_event_model_markers_from_subprojects(event)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            log_action(
                f"{mode.title()}d planning template '{template['name']}' in "
                f"{subproject.get('name') or 'sub-project'} for event {event_id}"
            )
            mark_realtime_change(
                'event-assets',
                {'eventId': event_id, 'action': f'template-{mode}'},
            )
            return jsonify({
                'success': True,
                'data': _event_planning_template_contents(event),
                'message': f"Template '{template['name']}' applied",
            })

        result = _apply_planning_template_to_event(event, template, mode)
        log_action(
            f"{mode.title()}d planning template '{template['name']}' "
            f"for event {event_id}"
        )
        mark_realtime_change(
            'event-assets',
            {'eventId': event_id, 'action': f'template-{mode}'},
        )
        return jsonify({
            'success': True,
            'data': result,
            'message': f"Template '{template['name']}' applied",
        })
    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400
    except Exception as exc:
        logger.error(
            "Failed to apply planning template to event %s: %s",
            event_id,
            exc,
            exc_info=True,
        )
        return jsonify({'error': 'Failed to apply planning template'}), 500


@app.route('/api/events/<int:event_id>/container-models', methods=['POST'])
@require_admin
@with_prepare_action_lock
def add_container_models_to_event(event_id):
    """Add a container's model quantities without assigning its physical IDs."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json(silent=True) or {}
        container_id = str(data.get('containerId') or '').strip()
        container = _find_container_by_lookup(container_id)
        if not container:
            return jsonify({'error': 'Container not found'}), 404

        grouped = {}
        skipped = []
        for asset_id in getattr(container, 'asset_ids', []) or []:
            asset = data_manager.inventory.get(asset_id)
            if (
                not asset
                or getattr(asset, 'is_missing', False)
                or _is_disposed(asset)
                or _is_bulk_asset(asset)
            ):
                skipped.append(asset_id)
                continue

            key = _event_asset_group_key(asset)
            if key not in grouped:
                grouped[key] = {
                    'department': asset.department_code,
                    'brand': asset.brand,
                    'model': asset.model_number,
                    'description': asset.description or '',
                    'quantity': 0,
                }
            grouped[key]['quantity'] += 1

        for asset_id, quantity in _container_bulk_item_map(container).items():
            asset = data_manager.inventory.get(asset_id)
            if not asset or getattr(asset, 'is_missing', False) or _is_disposed(asset):
                skipped.append(asset_id)
                continue
            key = _event_asset_group_key(asset)
            if key not in grouped:
                grouped[key] = {
                    'department': asset.department_code,
                    'brand': asset.brand,
                    'model': asset.model_number,
                    'description': asset.description or '',
                    'quantity': 0,
                }
            grouped[key]['quantity'] += quantity

        if not grouped:
            return jsonify({
                'error': 'Container has no available model contents to add'
            }), 400

        subproject = _event_subproject(event, data.get('subprojectId'))
        if str(data.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        if subproject:
            for row in grouped.values():
                room_quantity = _event_subproject_required_quantity(
                    subproject,
                    row,
                )
                _event_subproject_set_group_quantity(
                    subproject,
                    row,
                    room_quantity + row['quantity'],
                )
            _sync_event_model_markers_from_subprojects(event)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            log_action(
                f"Added model contents of container {container.container_id} "
                f"to {subproject.get('name') or 'sub-project'} for event {event_id}"
            )
            mark_realtime_change(
                'event-assets',
                {'eventId': event_id, 'action': 'add-container-models'},
            )
            return jsonify({
                'success': True,
                'message': 'Container model contents added',
                'data': {
                    'containerId': container.container_id,
                    'assetCount': sum(row['quantity'] for row in grouped.values()),
                    'modelCount': len(grouped),
                    'skippedAssetIds': skipped,
                    'subprojectId': subproject.get('id'),
                },
            })

        for row in grouped.values():
            existing_refs = []
            existing_quantity = 0
            key = _model_key_from_parts(
                row['department'],
                row['brand'],
                row['model'],
                row.get('description'),
            )
            for ref in list(event.prepared_items):
                marker = _parse_model_marker(ref)
                if not marker:
                    continue
                marker_key = _model_key_from_parts(
                    marker['department'],
                    marker['brand'],
                    marker['model'],
                    marker.get('description'),
                )
                if marker_key == key:
                    existing_refs.append(ref)
                    existing_quantity += max(
                        1,
                        _safe_int(marker.get('quantity'), 1),
                    )
                    if not row['description'] and marker.get('description'):
                        row['description'] = marker['description']

            for ref in existing_refs:
                event.prepared_items.remove(ref)
            event.prepared_items.append(
                _make_model_marker(
                    row,
                    existing_quantity + row['quantity'],
                )
            )

        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        log_action(
            f"Added model contents of container {container.container_id} "
            f"to event {event_id}"
        )
        mark_realtime_change(
            'event-assets',
            {'eventId': event_id, 'action': 'add-container-models'},
        )
        return jsonify({
            'success': True,
            'data': {
                'containerId': container.container_id,
                'modelCount': len(grouped),
                'assetCount': sum(
                    row['quantity'] for row in grouped.values()
                ),
                'skippedCount': len(skipped),
            },
        })
    except Exception as exc:
        logger.error(
            "Failed to add container models to event %s: %s",
            event_id,
            exc,
            exc_info=True,
        )
        return jsonify({'error': 'Failed to add container contents'}), 500


@app.route('/api/events/<int:event_id>/prepare', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def prepare_event_asset(event_id):
    """Mark an asset as prepared for an event"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        asset_id = data.get('assetId', '').strip()
        subproject = _event_subproject(event, data.get('subprojectId'))
        if str(data.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        scan_options = _prepare_scan_options(data)
        add_scanned_assets_to_event = scan_options['addScannedAssetsToEvent']

        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400

        scanned_asset = _find_inventory_asset_by_identifier(asset_id)
        if scanned_asset:
            asset_id = scanned_asset.asset_id

        # Initialize lists if they don't exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []
        if not hasattr(event, 'extra_assets'):
            event.extra_assets = []

        # Check if already prepared
        if asset_id in event.actually_prepared:
            if add_scanned_assets_to_event and asset_id in event.extra_assets:
                asset = data_manager.inventory.get(asset_id)
                if asset:
                    added_requirement_units = _ensure_event_model_requirement_covers_asset(event, asset, 1)
                    if subproject and added_requirement_units:
                        asset_group = _asset_group_from_item(asset)
                        room_quantity = _event_subproject_required_quantity(
                            subproject,
                            asset_group,
                        )
                        _event_subproject_set_group_quantity(
                            subproject,
                            asset_group,
                            room_quantity + added_requirement_units,
                        )
                        _sync_event_model_markers_from_subprojects(event)
                    _remove_direct_asset_ref_from_prepared_items(event, asset_id)
                    if asset_id in event.extra_assets:
                        event.extra_assets.remove(asset_id)
                    if subproject:
                        _reconcile_event_subproject_extras(event)
                    update_event_state(event)
                    data_manager.save_event(event)
                    invalidate_cache()
                    log_action(f"Promoted prepared extra asset {asset_id} into event {event_id}")
                    return jsonify({
                        'success': True,
                        'message': f'Asset {asset_id} added into event requirements',
                        'data': {
                            'assetId': asset_id,
                            'isExtra': False,
                            'addedToEvent': True,
                            'addedRequirementUnits': added_requirement_units,
                        }
                    })
            return jsonify({'error': 'Asset is already prepared'}), 400

        custom = _parse_custom_marker(asset_id)
        if custom:
            _ensure_event_custom_lists(event)
            if asset_id not in event.prepared_items:
                return jsonify({'error': 'Custom asset is not assigned to this event'}), 400
            if asset_id in event.returned_items:
                event.returned_items.remove(asset_id)
            if custom['type'] == 'LOAN' and asset_id not in event.custom_collected:
                return jsonify({'error': 'Loan/Rental item must be collected before it can be prepared'}), 400
            event.actually_prepared.append(asset_id)
            if subproject:
                _event_subproject_assign_custom_ref(
                    subproject,
                    custom,
                    asset_id,
                )
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            _log_event_asset_action(
                event_id,
                'prepare',
                [_event_asset_log_item(asset_id)],
            )
            return jsonify({'success': True, 'message': f"{_custom_display_name(custom)} prepared for event"})

        # For regular assets, perform additional checks
        if not _is_custom_ref(asset_id):
            asset = data_manager.inventory.get(asset_id)
            if not asset:
                return jsonify({'error': 'Asset not found'}), 404

            block_reason = _asset_prepare_block_reason(asset)
            if block_reason:
                return jsonify({'error': block_reason}), 400

            busy_event = _find_event_using_asset(asset_id, event)
            if busy_event:
                return jsonify({
                    'error': f'Asset is already assigned to another event {busy_event.event_id}: {busy_event.name}'
                }), 400

            if add_scanned_assets_to_event:
                added_requirement_units = _ensure_quick_add_model_requirement(
                    event,
                    subproject,
                    asset,
                    1,
                )
                fulfills_model_requirement = True
            else:
                # A manual/individual prepare only fills an existing open model slot.
                # If the matching model requirement is already full, or if this asset
                # was not originally required, keep it as an extra asset instead of
                # increasing the event requirement.
                added_requirement_units = 0
                if subproject:
                    prepared_group = _asset_group_from_item(asset)
                    fulfills_model_requirement = (
                        _event_subproject_required_quantity(
                            subproject,
                            prepared_group,
                        )
                        > _event_subproject_prepared_quantity(
                            event,
                            subproject,
                            prepared_group,
                        )
                    )
                else:
                    fulfills_model_requirement = _event_model_requirement_remaining_for_asset(event, asset) > 0
            logger.info(
                f"Manual prepare {asset_id}: addToEvent={add_scanned_assets_to_event}; "
                f"fillsExistingRequirement={fulfills_model_requirement}; addedUnits={added_requirement_units}"
            )
            
            if fulfills_model_requirement:
                removed_refs = _remove_direct_asset_ref_from_prepared_items(event, asset_id)
                if removed_refs:
                    logger.info(f"Removed {asset_id} from prepared_items because it fulfills a model requirement")
                if asset_id in event.extra_assets:
                    event.extra_assets.remove(asset_id)
                    logger.info(f"Removed {asset_id} from extra_assets (fills open model requirement). Extra assets: {event.extra_assets}")
            else:
                # Loose extras and direct specific-asset events still need an
                # explicit prepared_items row so they remain part of the packing list.
                if asset_id not in event.prepared_items:
                    event.prepared_items.append(asset_id)
                if asset_id not in event.extra_assets:
                    event.extra_assets.append(asset_id)
                    logger.info(f"Added manual extra asset {asset_id} to event {event_id}. Extra assets: {event.extra_assets}")

            # Update asset location now that it's prepared
            asset.current_location = event.name
            data_manager.save_inventory()

        # Mark as prepared
        event.actually_prepared.append(asset_id)
        if subproject:
            prepared_asset = data_manager.inventory.get(asset_id)
            if prepared_asset:
                prepared_group = _asset_group_from_item(prepared_asset)
                if not _event_subproject_assign_ref(
                    subproject,
                    prepared_group,
                    asset_id,
                ):
                    refs = subproject.setdefault('extraRefs', [])
                    if asset_id not in refs:
                        refs.append(asset_id)

        # Update event state
        update_event_state(event)

        # Save changes
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()

        _log_event_asset_action(
            event_id,
            'prepare',
            [_event_asset_log_item(asset_id)],
        )

        response_payload = {
            'success': True,
            'message': f'Asset {asset_id} prepared for event',
            'data': {
                'assetId': asset_id,
                'isExtra': asset_id in getattr(event, 'extra_assets', []),
                'addedToEvent': add_scanned_assets_to_event,
                'addedRequirementUnits': locals().get('added_requirement_units', 0),
            }
        }
        prepared_asset = data_manager.inventory.get(asset_id)
        if prepared_asset and _is_degraded(prepared_asset):
            response_payload['warning'] = _degraded_asset_warning(prepared_asset, asset_id)
        return jsonify(response_payload)
    except Exception as e:
        logger.error(f"Error preparing asset for event {event_id}: {e}")
        return jsonify({'error': 'Failed to prepare asset'}), 500
@app.route('/api/events/<int:event_id>/custom-assets', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def add_custom_asset_to_event(event_id):
    """Add a structured custom asset (LOAN/MISC) to an event without auto-preparing it."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        subproject = _event_subproject(event, data.get('subprojectId'))
        if str(data.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        name = str(data.get('name', '')).strip()
        quantity = max(1, _safe_int(data.get('quantity'), 1))
        asset_type = _normalise_custom_type(data.get('type', 'MISC'))
        department = _normalise_department_code(data.get('department')) or 'UN'
        company = str(data.get('company') or '').strip()
        description = str(data.get('description') or '').strip()

        if not name:
            return jsonify({'error': 'Asset name is required'}), 400
        if asset_type == 'LOAN' and not company:
            # Keep this as a warning-level validation so the data remains useful on the DO and prep screen.
            return jsonify({'error': 'Loan/Rental company is required'}), 400

        _ensure_event_custom_lists(event)
        requested_custom = {
            'type': asset_type,
            'name': name,
            'quantity': quantity,
            'department': department,
            'company': company,
            'description': description,
        }
        matching_refs = _event_custom_refs_matching_identity(
            event, requested_custom, subproject
        )
        merged = bool(matching_refs)
        if matching_refs:
            existing_quantity = sum(
                max(1, _safe_int(_parse_custom_marker(ref).get('quantity'), 1))
                for ref in matching_refs
            )
            quantity += existing_quantity
            first_custom = _parse_custom_marker(matching_refs[0]) or {}
            custom_asset_id = _make_custom_marker(
                asset_type,
                name,
                quantity,
                department,
                company,
                uid=first_custom.get('uid') or None,
                description=description,
            )
            requested_custom['quantity'] = quantity
            _merge_event_custom_markers(
                event,
                matching_refs,
                custom_asset_id,
                requested_custom,
                quantity,
                target_subproject=subproject,
                # Newly added units have not yet been prepared or collected.
                preserve_state=False,
            )
        else:
            custom_asset_id = _make_custom_marker(
                asset_type,
                name,
                quantity,
                department,
                company,
                description=description
            )
            event.prepared_items.append(custom_asset_id)

        if subproject and not merged:
            subproject.setdefault('items', []).append({
                'lineId': f"plan_{secrets.token_hex(8)}",
                'department': department,
                'departmentCode': department,
                'brand': '',
                'model': '',
                'description': name,
                'customDescription': description,
                'company': company,
                'quantity': quantity,
                'isCustom': True,
                'assetRefs': [custom_asset_id],
            })

        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()

        log_action(
            f"{'Merged into' if merged else 'Added'} "
            f"{_custom_asset_log_label(_parse_custom_marker(custom_asset_id))} "
            f"for event {event_id}; quantity={quantity}; department={department}"
        )
        mark_realtime_change('event-assets', {'eventId': event_id, 'action': 'custom-asset-added'})

        return jsonify({
            'success': True,
            'message': (
                f'Custom asset "{name}" quantity increased to {quantity}'
                if merged else f'Custom asset "{name}" added to event'
            ),
            'data': {
                'assetId': custom_asset_id,
                'quantity': quantity,
                'merged': merged,
            }
        })

    except Exception as e:
        logger.error(f"Error adding custom asset to event {event_id}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to add custom asset'}), 500

@app.route('/api/events/<int:event_id>/custom-assets/collect', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def collect_custom_asset(event_id):
    """Mark a loan/rental custom item as collected."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        requested_ids = data.get('assetIds')
        if not isinstance(requested_ids, list):
            requested_ids = [data.get('assetId')]
        asset_ids = list(dict.fromkeys(
            str(asset_id or '').strip()
            for asset_id in requested_ids
            if str(asset_id or '').strip()
        ))
        if not asset_ids:
            return jsonify({'error': 'Custom asset not found'}), 400

        custom_assets = []
        for asset_id in asset_ids:
            custom = _parse_custom_marker(asset_id)
            if not custom:
                return jsonify({'error': 'Custom asset not found'}), 400
            if custom['type'] != 'LOAN':
                return jsonify({'error': 'Only loan/rental items can be collected'}), 400
            custom_assets.append((asset_id, custom))

        _ensure_event_custom_lists(event)
        for asset_id, _custom in custom_assets:
            if asset_id not in event.prepared_items:
                return jsonify({'error': 'Custom asset is not assigned to this event'}), 400
            if asset_id in event.returned_items:
                return jsonify({'error': 'Returned items cannot be collected'}), 400

        newly_collected = []
        for asset_id, custom in custom_assets:
            if asset_id not in event.custom_collected:
                event.custom_collected.append(asset_id)
                newly_collected.append((asset_id, custom))

        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        _log_event_asset_action(
            event_id,
            'collect',
            [_event_asset_log_item(asset_id) for asset_id, _custom in newly_collected],
        )
        return jsonify({
            'success': True,
            'message': 'Loan/Rental item collected',
            'data': {
                'assetIds': [asset_id for asset_id, _custom in custom_assets],
                'collectedCount': len(newly_collected),
            },
        })
    except Exception as e:
        logger.error(f"Error collecting custom asset for event {event_id}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to collect custom asset'}), 500

@app.route('/api/events/<int:event_id>/custom-assets/uncollect', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def uncollect_custom_asset(event_id):
    """Undo collection for loan/rental items that have not been prepared."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        requested_ids = data.get('assetIds')
        if not isinstance(requested_ids, list):
            requested_ids = [data.get('assetId')]
        asset_ids = list(dict.fromkeys(
            str(asset_id or '').strip()
            for asset_id in requested_ids
            if str(asset_id or '').strip()
        ))
        if not asset_ids:
            return jsonify({'error': 'Custom asset not found'}), 400

        custom_assets = []
        for asset_id in asset_ids:
            custom = _parse_custom_marker(asset_id)
            if not custom:
                return jsonify({'error': 'Custom asset not found'}), 400
            if custom['type'] != 'LOAN':
                return jsonify({'error': 'Only loan/rental items can be uncollected'}), 400
            custom_assets.append((asset_id, custom))

        _ensure_event_custom_lists(event)
        for asset_id, _custom in custom_assets:
            if asset_id not in event.prepared_items:
                return jsonify({'error': 'Custom asset is not assigned to this event'}), 400
            if asset_id in event.actually_prepared:
                return jsonify({'error': 'Unprepare the loan/rental item before uncollecting it'}), 400
            if asset_id in event.returned_items:
                return jsonify({'error': 'Returned items cannot be uncollected'}), 400

        newly_uncollected = []
        for asset_id, custom in custom_assets:
            if asset_id in event.custom_collected:
                event.custom_collected.remove(asset_id)
                newly_uncollected.append((asset_id, custom))

        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        _log_event_asset_action(
            event_id,
            'uncollect',
            [_event_asset_log_item(asset_id) for asset_id, _custom in newly_uncollected],
        )
        return jsonify({
            'success': True,
            'message': 'Loan/Rental item uncollected',
            'data': {
                'assetIds': [asset_id for asset_id, _custom in custom_assets],
                'uncollectedCount': len(newly_uncollected),
            },
        })
    except Exception as e:
        logger.error(f"Error uncollecting custom asset for event {event_id}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to uncollect custom asset'}), 500

@app.route('/api/events/<int:event_id>/unprepare', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def unprepare_event_asset(event_id):
    """Remove a specific asset completely from the event"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        asset_id = data.get('assetId', '').strip()

        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400

        if _is_bulk_ref(asset_id):
            if not hasattr(event, 'actually_prepared'):
                event.actually_prepared = []
            if asset_id in event.actually_prepared:
                event.actually_prepared.remove(asset_id)
            if asset_id in event.returned_items:
                event.returned_items.remove(asset_id)
            if hasattr(event, 'extra_assets') and asset_id in event.extra_assets:
                event.extra_assets.remove(asset_id)
            _event_subproject_remove_ref(event, asset_id)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            _log_event_asset_action(
                event_id,
                'unprepare',
                [_event_asset_log_item(asset_id)],
            )
            return jsonify({'success': True, 'message': 'Bulk quantity asset unprepared'})

        custom = _parse_custom_marker(asset_id)
        if custom:
            _ensure_event_custom_lists(event)
            if asset_id not in event.prepared_items:
                return jsonify({'error': 'Custom asset is not assigned to this event'}), 400
            if asset_id in event.actually_prepared:
                event.actually_prepared.remove(asset_id)
            if asset_id in event.returned_items:
                event.returned_items.remove(asset_id)
            _event_subproject_remove_ref(event, asset_id)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            _log_event_asset_action(
                event_id,
                'unprepare',
                [_event_asset_log_item(asset_id)],
            )
            return jsonify({'success': True, 'message': 'Custom item unprepared'})

        _ensure_event_custom_lists(event)

        asset_is_attached = (
            asset_id in event.prepared_items or
            asset_id in event.actually_prepared or
            asset_id in event.returned_items or
            asset_id in event.extra_assets
        )

        # Check if asset is attached to this event first
        if not asset_is_attached:
            return jsonify({'error': 'Asset is not assigned to this event'}), 400

        # LOG THE UNPREPARE ACTION
        log_asset_change(event_id, asset_id, "UNPREPARING", "completely removing asset from event [unprepare_event_asset]")

        # Remove from prepared list if this was a loose extra/direct asset. Model-
        # fulfilled physical assets may now live only in actually_prepared.
        if asset_id in event.prepared_items:
            event.prepared_items.remove(asset_id)
        
        # Remove from actually_prepared if it's there
        if asset_id in event.actually_prepared:
            event.actually_prepared.remove(asset_id)

        # Remove from returned_items if it's there. Leaving this behind forces the
        # event into Returning even after the asset was removed from the event.
        if asset_id in event.returned_items:
            event.returned_items.remove(asset_id)
        
        # Remove from extra_assets if it's there
        if hasattr(event, 'extra_assets') and asset_id in event.extra_assets:
            event.extra_assets.remove(asset_id)
        _event_subproject_remove_ref(event, asset_id)

        promoted_extra_assets = _promote_matching_extra_assets(event)
        if promoted_extra_assets:
            logger.info(
                "Promoted extra asset(s) after removing %s from event %s: %s",
                asset_id,
                event_id,
                promoted_extra_assets,
            )

        # For regular assets, reset location to default
        if not _is_custom_ref(asset_id):
            asset = data_manager.inventory.get(asset_id)
            if asset:
                asset.current_location = asset.default_location or ''
                data_manager.save_inventory()

        # Update event state
        update_event_state(event)

        # Save changes
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()

        _log_event_asset_action(
            event_id,
            'unprepare',
            [_event_asset_log_item(asset_id)],
        )

        return jsonify({'success': True, 'message': f'Asset {asset_id} removed from event'})
    except Exception as e:
        logger.error(f"Error removing asset from event {event_id}: {e}")
        return jsonify({'error': 'Failed to remove asset'}), 500

@app.route('/api/events/<int:event_id>/return-prepared-quantity', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def return_event_prepared_quantity(event_id):
    """Return part or all of an anonymously prepared model quantity."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        group = _group_from_request(data)
        quantity = max(0, _safe_int(data.get('quantity'), 0))
        if quantity <= 0:
            return jsonify({'error': 'Quantity must be greater than 0'}), 400

        subproject_id = str(data.get('subprojectId') or '').strip()
        subproject = _event_subproject(event, subproject_id)
        if subproject_id and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404

        available = _event_prepared_slot_quantity(event, group)
        if subproject:
            available = min(
                available,
                _event_subproject_anonymous_prepared_quantity(subproject, group),
            )
        if quantity > available:
            return jsonify({
                'error': f'Only {available} unassigned prepared unit(s) can be returned'
            }), 409

        removed = _decrement_prepared_model_slot(event, group, quantity)
        if removed != quantity:
            return jsonify({'error': 'Prepared quantity changed; please try again'}), 409
        _increment_returned_prepared_model_slot(event, group, quantity)
        if subproject:
            _event_subproject_adjust_prepared(subproject, group, -quantity)
            _event_subproject_adjust_returned_prepared(subproject, group, quantity)
        if getattr(event, 'subprojects', []) or []:
            _reconcile_event_subproject_extras(event)

        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        _log_event_asset_action(
            event_id,
            'return',
            [_event_asset_log_item(quantity=quantity, group=group)],
        )
        return jsonify({
            'success': True,
            'message': f'Returned {quantity}x {_asset_log_label(SimpleNamespace(brand=group["brand"], model_number=group["model"], description=group.get("description", "")))}',
            'data': {
                'returnedQuantity': _event_returned_prepared_slot_quantity(event, group),
                'outstandingQuantity': _event_prepared_slot_quantity(event, group),
            },
        })
    except ValueError as error:
        return jsonify({'error': str(error)}), 400
    except Exception as error:
        logger.error(
            f'Error returning prepared model quantity for event {event_id}: {error}',
            exc_info=True,
        )
        return jsonify({'error': 'Failed to return prepared quantity'}), 500


@app.route('/api/events/<int:event_id>/unreturn-prepared-quantity', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def unreturn_event_prepared_quantity(event_id):
    """Undo part or all of an anonymous prepared-model return."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        group = _group_from_request(data)
        quantity = max(0, _safe_int(data.get('quantity'), 0))
        if quantity <= 0:
            return jsonify({'error': 'Quantity must be greater than 0'}), 400

        subproject_id = str(data.get('subprojectId') or '').strip()
        subproject = _event_subproject(event, subproject_id)
        if subproject_id and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404

        available = _event_returned_prepared_slot_quantity(event, group)
        if subproject:
            available = min(
                available,
                _event_subproject_returned_prepared_quantity(subproject, group),
            )
        if quantity > available:
            return jsonify({
                'error': f'Only {available} returned unit(s) can be restored'
            }), 409

        removed = _decrement_returned_prepared_model_slot(event, group, quantity)
        if removed != quantity:
            return jsonify({'error': 'Returned quantity changed; please try again'}), 409
        _increment_prepared_model_slot(event, group, quantity)
        if subproject:
            _event_subproject_adjust_returned_prepared(subproject, group, -quantity)
            _event_subproject_adjust_prepared(subproject, group, quantity)
        if getattr(event, 'subprojects', []) or []:
            _reconcile_event_subproject_extras(event)

        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        _log_event_asset_action(
            event_id,
            'restore',
            [_event_asset_log_item(quantity=quantity, group=group)],
        )
        return jsonify({
            'success': True,
            'message': f'Restored {quantity} prepared unit(s) to the event',
            'data': {
                'returnedQuantity': _event_returned_prepared_slot_quantity(event, group),
                'outstandingQuantity': _event_prepared_slot_quantity(event, group),
            },
        })
    except ValueError as error:
        return jsonify({'error': str(error)}), 400
    except Exception as error:
        logger.error(
            f'Error restoring prepared model quantity for event {event_id}: {error}',
            exc_info=True,
        )
        return jsonify({'error': 'Failed to restore prepared quantity'}), 500


@app.route('/api/events/<int:event_id>/return', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def return_event_asset(event_id):
    """Return an asset from an event"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json()
        asset_id = data.get('assetId', '').strip()

        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400

        scanned_asset = _find_inventory_asset_by_identifier(asset_id)
        if scanned_asset:
            asset_id = scanned_asset.asset_id

        if _is_bulk_ref(asset_id):
            if asset_id not in getattr(event, 'actually_prepared', []) and asset_id not in getattr(event, 'prepared_items', []):
                return jsonify({'error': 'Bulk asset is not prepared for this event'}), 400
            if asset_id in event.returned_items:
                return jsonify({'error': 'Asset is already returned'}), 400
            event.returned_items.append(asset_id)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            _log_event_asset_action(
                event_id,
                'return',
                [_event_asset_log_item(asset_id)],
            )
            return jsonify({'success': True, 'message': 'Bulk quantity asset returned successfully'})

        custom = _parse_custom_marker(asset_id)
        if custom:
            _ensure_event_custom_lists(event)
            if asset_id not in event.prepared_items:
                return jsonify({'error': 'Custom asset is not assigned to this event'}), 400
            if asset_id in event.returned_items:
                return jsonify({'error': 'Asset is already returned'}), 400
            is_prepared = asset_id in event.actually_prepared
            is_collected_loan = custom.get('type') == 'LOAN' and asset_id in getattr(event, 'custom_collected', [])
            if not (is_prepared or is_collected_loan):
                return jsonify({'error': 'Custom asset must be prepared before it can be returned'}), 400

            event.returned_items.append(asset_id)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            _log_event_asset_action(
                event_id,
                'return',
                [_event_asset_log_item(asset_id)],
            )
            return jsonify({'success': True, 'message': f"{_custom_display_name(custom)} returned successfully"})

        _ensure_event_custom_lists(event)

        # Check if asset is prepared/assigned for this event. Model-fulfilled
        # physical assets are tracked in actually_prepared, not prepared_items.
        if asset_id not in event.prepared_items and asset_id not in event.actually_prepared:
            return jsonify({'error': 'Asset is not assigned to this event'}), 400

        # Check if asset is already returned
        if asset_id in event.returned_items:
            return jsonify({'error': 'Asset is already returned'}), 400

        # Return the asset
        event.returned_items.append(asset_id)

        # Initialize actually_prepared if it doesn't exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []

        # For regular assets, remove from actually_prepared when returned
        if asset_id in event.actually_prepared:
            event.actually_prepared.remove(asset_id)

        # For regular assets, update location
        if not _is_custom_ref(asset_id):
            asset = data_manager.inventory.get(asset_id)
            if asset:
                asset.current_location = asset.default_location or ''
                data_manager.save_inventory()

        # Update event state
        update_event_state(event)

        # Save changes
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()

        _log_event_asset_action(
            event_id,
            'return',
            [_event_asset_log_item(asset_id)],
        )

        return jsonify({'success': True, 'message': f'Asset {asset_id} returned successfully'})
    except Exception as e:
        logger.error(f"Error returning asset from event {event_id}: {e}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")
        return jsonify({'error': 'Failed to return asset'}), 500


@app.route('/api/events/<int:event_id>/unreturn', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def unreturn_event_asset(event_id):
    """Undo an accidental event return and restore the asset's deployed state."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        asset_id = str(data.get('assetId') or '').strip()
        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400

        scanned_asset = _find_inventory_asset_by_identifier(asset_id)
        if scanned_asset:
            asset_id = scanned_asset.asset_id

        _ensure_event_custom_lists(event)
        if asset_id not in event.returned_items:
            return jsonify({'error': 'Asset is no longer marked as returned'}), 409

        custom = _parse_custom_marker(asset_id)
        bulk = _parse_bulk_marker(asset_id)

        if bulk:
            if asset_id not in event.actually_prepared:
                event.actually_prepared.append(asset_id)
        elif not custom:
            asset = data_manager.inventory.get(asset_id)
            if not asset:
                return jsonify({'error': 'Asset not found'}), 404

            busy_event = _find_event_using_asset(asset_id, event)
            if busy_event:
                return jsonify({
                    'error': (
                        f'Asset is now assigned to event {busy_event.event_id}: '
                        f'{busy_event.name}'
                    )
                }), 409

            block_reason = _asset_prepare_block_reason(asset)
            if block_reason:
                return jsonify({'error': block_reason}), 409

            if asset_id not in event.actually_prepared:
                event.actually_prepared.append(asset_id)
            asset.current_location = event.name
            data_manager.save_inventory()

        event.returned_items.remove(asset_id)
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        _log_event_asset_action(
            event_id,
            'restore',
            [_event_asset_log_item(asset_id)],
        )

        return jsonify({
            'success': True,
            'message': f'Asset {asset_id} restored to event',
            'data': {
                'assetId': asset_id,
                'eventId': event_id,
                'state': event.state,
            },
        })
    except Exception as e:
        logger.error(
            f"Error undoing return of asset for event {event_id}: {e}",
            exc_info=True,
        )
        return jsonify({'error': 'Failed to undo asset return'}), 500


@app.route('/api/events/<int:event_id>/close-return', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def close_return_event(event_id):
    """Confirm completion of a return after every deployed item is back."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        counts = _event_returnable_counts(event)
        if counts['returnable'] > 0:
            return jsonify({
                'error': f"{counts['returnable']} asset(s) still need to be returned"
            }), 409
        if counts['total'] <= 0:
            return jsonify({'error': 'This event has no returned assets to close'}), 409

        event.force_state_override = False
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        log_action(
            f"Completed asset return for event {event_id}; "
            f"state is now {event.state}"
        )
        return jsonify({
            'success': True,
            'message': (
                f'Event {event_id} closed'
                if event.state == 'Closed'
                else (
                    f'Event {event_id} is pending closure until all worker '
                    'and vendor payments are confirmed received'
                )
            ),
            'data': {'eventId': event_id, 'state': event.state},
        })
    except Exception as e:
        logger.error(f"Error closing returned event {event_id}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to close event'}), 500
    
@app.route('/api/events/<int:event_id>/return-department', methods=['POST'])
@require_admin
@with_prepare_action_lock
def return_department_assets(event_id):
    """Return all unreturned assets for a given department in this event.
    Includes regular inventory assets from actually_prepared that match the department,
    any specifically prepared assets from prepared_items in that department,
    and custom assets ([LOAN]/[MISC]) if department is LOAN or MISC.
    """
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        department = _normalise_department_code(data.get('department')) or ''
        if not department:
            return jsonify({'error': 'Department is required'}), 400

        # Ensure lists exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []
        if not hasattr(event, 'extra_assets'):
            event.extra_assets = []

        already_returned = set(event.returned_items or [])
        targets = []
        prepared_quantity_targets = {}

        for ref in list(event.actually_prepared):
            marker = _parse_prepared_model_marker(ref)
            if not marker or marker['department'] != department:
                continue
            key = _event_model_group_key(marker)
            row = prepared_quantity_targets.setdefault(
                key,
                {'group': marker, 'quantity': 0},
            )
            row['quantity'] += marker['quantity']

        # 1) Regular inventory assets (match department)
        specific_ids_in_prepared = [
            aid for aid in event.prepared_items
            if not (_is_custom_ref(aid) or aid.startswith('[MODEL]'))
        ]
        for asset_id in set(event.actually_prepared + specific_ids_in_prepared):
            if asset_id in already_returned:
                continue

            if _is_bulk_ref(asset_id):
                marker = _parse_bulk_marker(asset_id)
                bulk_asset = data_manager.inventory.get(marker['bulkId']) if marker else None
                if bulk_asset and _is_bulk_asset(bulk_asset) and bulk_asset.department_code == department:
                    targets.append(asset_id)
                continue

            asset = data_manager.inventory.get(asset_id)
            if not asset:
                continue
            if asset.department_code == department:
                targets.append(asset_id)

        # 2) Custom assets now belong to their tagged department.
        for item in event.prepared_items:
            custom = _parse_custom_marker(item)
            if not custom or item in already_returned:
                continue
            is_prepared = item in event.actually_prepared
            is_collected_loan = custom.get('type') == 'LOAN' and item in getattr(event, 'custom_collected', [])
            if custom.get('department') == department and (is_prepared or is_collected_loan):
                targets.append(item)

        if not targets and not prepared_quantity_targets:
            return jsonify({'success': True, 'message': f'No pending items for department {department}', 'returned': []})

        returned_now = []

        for asset_id in targets:
            if asset_id in event.returned_items:
                continue

            # Mark returned
            event.returned_items.append(asset_id)
            returned_now.append(asset_id)

            # Bulk quantity assets: keep the prepared marker for history/state math.
            if _is_bulk_ref(asset_id):
                continue

            # Regular assets: remove from actually_prepared + reset location
            if not _is_custom_ref(asset_id):
                if asset_id in event.actually_prepared:
                    event.actually_prepared.remove(asset_id)
                asset = data_manager.inventory.get(asset_id)
                if asset:
                    asset.current_location = asset.default_location or ''

            # For custom assets, DO NOT remove from actually_prepared (to match single-return semantics)

        returned_log_items = [
            _event_asset_log_item(asset_id) for asset_id in returned_now
        ]
        for target in prepared_quantity_targets.values():
            group = target['group']
            quantity = target['quantity']
            removed = _decrement_prepared_model_slot(event, group, quantity)
            if removed <= 0:
                continue
            _increment_returned_prepared_model_slot(event, group, removed)
            returned_now.append(_prepared_model_marker(group, removed))
            returned_log_items.append(
                _event_asset_log_item(quantity=removed, group=group)
            )

        if getattr(event, 'subprojects', []) or []:
            _reconcile_event_subproject_extras(event)

        # Persist
        data_manager.save_inventory()
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()

        _log_event_asset_action(
            event_id,
            'return',
            returned_log_items,
        )

        return jsonify({'success': True, 'message': f'Returned {len(returned_now)} items for {department}', 'returned': returned_now})
    except Exception as e:
        logger.error(f"Error returning all assets for department {department} in event {event_id}: {e}")
        return jsonify({'error': 'Failed to return department assets'}), 500


@app.route('/api/events/<int:event_id>/assign-specific', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def assign_specific_asset_to_model(event_id):
    """Assign a specific asset to fulfill a model requirement"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json() or {}
        asset_id = data.get('assetId', '').strip()
        subproject = _event_subproject(event, data.get('subprojectId'))
        if str(data.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        scan_options = _prepare_scan_options(data)
        add_scanned_assets_to_event = scan_options['addScannedAssetsToEvent']

        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400

        scanned_asset = _find_inventory_asset_by_identifier(asset_id)
        if scanned_asset:
            asset_id = scanned_asset.asset_id

        bulk_asset = data_manager.inventory.get(asset_id)
        if bulk_asset and _is_bulk_asset(bulk_asset):
            if _is_disposed(bulk_asset):
                return jsonify({'error': 'Bulk asset is decommissioned and cannot be prepared'}), 400

            if getattr(bulk_asset, 'is_ooc', False):
                return jsonify({'error': 'Bulk asset is out of commission'}), 400

            if getattr(bulk_asset, 'is_missing', False):
                return jsonify({'error': 'Bulk asset is marked as missing'}), 400

            if not hasattr(event, 'actually_prepared'):
                event.actually_prepared = []
            if not hasattr(event, 'extra_assets'):
                event.extra_assets = []

            bulk_group = _asset_group_from_item(bulk_asset)
            required_before = (
                _event_subproject_required_quantity(subproject, bulk_group)
                if subproject
                else _event_model_required_quantity(event, bulk_group)
            )
            prepared_before = (
                _event_subproject_prepared_quantity(event, subproject, bulk_group)
                if subproject
                else _event_active_prepared_quantity_for_group(
                    event,
                    bulk_group,
                    include_extra=True,
                )
            )

            quantity = _safe_int(data.get('quantity'), 0)
            if quantity <= 0:
                quantity = _bulk_remaining_for_event_group(event, bulk_asset)
            if quantity <= 0:
                quantity = 1

            healthy_quantity = _bulk_available_quantity_for_event(
                bulk_asset,
                event,
                include_degraded=False
            )
            available_quantity = _bulk_available_quantity_for_event(
                bulk_asset,
                event,
                include_degraded=True
            )
            if available_quantity <= 0:
                return jsonify({'error': 'No quantity is available for this event date range'}), 400

            quantity = min(
                quantity,
                max(1, _safe_int(getattr(bulk_asset, 'quantity', 1), 1)),
                available_quantity
            )

            marker = _bulk_marker(
                asset_id,
                quantity,
                subproject.get('id') if subproject else '',
            )
            if marker in event.actually_prepared and marker not in event.returned_items:
                return jsonify({'error': 'Bulk asset is already prepared for this event'}), 400

            if marker in event.returned_items:
                event.returned_items.remove(marker)
            if marker not in event.actually_prepared:
                event.actually_prepared.append(marker)

            added_requirement_units = 0
            if add_scanned_assets_to_event:
                added_requirement_units = _ensure_quick_add_model_requirement(
                    event,
                    subproject,
                    bulk_asset,
                    quantity,
                )

            if subproject:
                room_required = _event_subproject_required_quantity(
                    subproject,
                    bulk_group,
                )
                room_prepared = _event_subproject_prepared_quantity(
                    event,
                    subproject,
                    bulk_group,
                )
                assigned_to_requirement = bool(
                    room_prepared < room_required
                    and _event_subproject_assign_ref(
                        subproject,
                        bulk_group,
                        marker,
                    )
                )
                if not assigned_to_requirement:
                    room_extras = subproject.setdefault('extraRefs', [])
                    if marker not in room_extras:
                        room_extras.append(marker)
                _reconcile_event_subproject_extras(event)

            update_event_state(event)
            _log_event_asset_action(
                event_id,
                'prepare',
                [_event_asset_log_item(marker, quantity=quantity)],
                persist_event=False,
            )
            data_manager.save_event(event)
            invalidate_cache()
            is_extra = bool(
                not add_scanned_assets_to_event
                and prepared_before + quantity > required_before
            )
            response_payload = {
                'success': True,
                'message': f'Prepared {quantity}x {bulk_asset.brand} {bulk_asset.model_number}',
                'data': {
                    'assetId': marker,
                    'isExtra': is_extra,
                    'addedToEvent': add_scanned_assets_to_event,
                    'addedRequirementUnits': added_requirement_units,
                    'preparedQuantity': quantity,
                    'healthyQuantityUsed': min(quantity, healthy_quantity),
                    'degradedQuantityUsed': max(quantity - healthy_quantity, 0),
                }
            }
            degraded_quantity_used = max(quantity - healthy_quantity, 0)
            if degraded_quantity_used > 0:
                reasons = _bulk_degraded_reasons(bulk_asset, limit=degraded_quantity_used)
                response_payload['warning'] = (
                    f"There are not enough fully working {bulk_asset.brand} {bulk_asset.model_number} assets for this preparation. "
                    f"{degraded_quantity_used} degraded unit{'s' if degraded_quantity_used != 1 else ''} will be used."
                    f"{_warning_reason_text(reasons)} "
                    "Please verify the limitation before show."
                )
            return jsonify(response_payload)

        # Initialize lists if they don't exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []
        if not hasattr(event, 'extra_assets'):
            event.extra_assets = []

        # Check if asset is already assigned
        if asset_id in event.actually_prepared:
            if add_scanned_assets_to_event and asset_id in event.extra_assets:
                asset = data_manager.inventory.get(asset_id)
                if asset:
                    added_requirement_units = _ensure_event_model_requirement_covers_asset(event, asset, 1)
                    _remove_direct_asset_ref_from_prepared_items(event, asset_id)
                    event.extra_assets.remove(asset_id)
                    update_event_state(event)
                    log_action(
                        f"Promoted prepared extra asset {asset_id} into event {event_id}",
                        persist_event=False,
                    )
                    data_manager.save_event(event)
                    invalidate_cache()
                    return jsonify({
                        'success': True,
                        'message': f'Asset {asset_id} added into event requirements',
                        'data': {
                            'assetId': asset_id,
                            'isExtra': False,
                            'addedToEvent': True,
                            'addedRequirementUnits': added_requirement_units,
                        }
                    })
            return jsonify({'error': 'Asset is already assigned to this event'}), 400

        consumed_prepared_slot = False
        consumed_returned_prepared_slot = False
        reconciles_returned_slot = False
        fills_existing_requirement = False

        # For regular assets, perform checks
        if not _is_custom_ref(asset_id):
            asset = data_manager.inventory.get(asset_id)
            if not asset:
                return jsonify({'error': 'Asset not found'}), 404

            if asset_id in event.returned_items:
                return jsonify({'error': 'Asset is already assigned to this event'}), 400

            asset_group = _asset_group_from_item(asset)
            active_slot_quantity = _event_prepared_slot_quantity(event, asset_group)
            returned_slot_quantity = _event_returned_prepared_slot_quantity(event, asset_group)
            if subproject:
                active_slot_quantity = min(
                    active_slot_quantity,
                    _event_subproject_anonymous_prepared_quantity(subproject, asset_group),
                )
                returned_slot_quantity = min(
                    returned_slot_quantity,
                    _event_subproject_returned_prepared_quantity(subproject, asset_group),
                )
            replaces_prepared_slot = active_slot_quantity > 0
            reconciles_returned_slot = bool(
                not add_scanned_assets_to_event
                and active_slot_quantity <= 0
                and returned_slot_quantity > 0
            )

            logger.info(f"Assigning asset {asset_id} - Brand: {asset.brand}, Model: {asset.model_number}, Dept: {asset.department_code}")

            clear_missing_for_prepare = bool(
                data.get('markFound') or
                data.get('clearMissing') or
                data.get('markMissingFound')
            )
            if getattr(asset, 'is_missing', False) and clear_missing_for_prepare:
                maintenance_result, maintenance_status, maintenance_changed = _apply_standard_maintenance_request(
                    asset_id,
                    asset,
                    {
                        'logEntry': (
                            f"Marked found while preparing event {event_id}"
                            f"{f' - {event.name}' if getattr(event, 'name', '') else ''}"
                        ),
                        'targetStatus': 'ok',
                        'maintenanceDate': datetime.now().strftime('%Y-%m-%d'),
                        'clientRequestId': f'prepare-found:{event_id}:{asset_id}',
                    },
                    uploaded_files=[],
                )
                if maintenance_status >= 400:
                    return jsonify({'error': maintenance_result.get('error') or 'Failed to mark asset as found'}), maintenance_status
                if maintenance_changed:
                    log_action(f"Marked missing asset {asset_id} as found while preparing event {event_id}")

            # A returned anonymous slot may be identified after the equipment is
            # already back in inventory. This is historical reconciliation, not
            # a new deployment, so current availability/condition must not block it.
            block_reason = None if reconciles_returned_slot else _asset_prepare_block_reason(asset)
            if block_reason:
                return jsonify({'error': block_reason}), 400

            busy_event = None if reconciles_returned_slot else _find_event_using_asset(asset_id, event)
            if busy_event:
                return jsonify({
                    'error': f'Asset is already assigned to another event {busy_event.event_id}: {busy_event.name}'
                }), 400

            if add_scanned_assets_to_event:
                # An anonymous prepared slot is a temporary placeholder for an
                # exact asset ID. Identifying that asset must consume the slot
                # even when Quick-add is enabled; otherwise the scan grows the
                # requirement and leaves the placeholder behind as a phantom
                # prepared unit in the room.
                added_requirement_units = 0
                if not replaces_prepared_slot:
                    # With no placeholder to replace, Quick-add may raise the
                    # requirement so a genuine surplus scan becomes demand.
                    added_requirement_units = _ensure_quick_add_model_requirement(
                        event,
                        subproject,
                        asset,
                        1,
                    )
                fills_existing_requirement = True

                if added_requirement_units:
                    logger.info(
                        f"Added {added_requirement_units} model requirement unit(s) for scanned asset {asset_id}: "
                        f"[{asset.department_code}] {asset.brand} {asset.model_number} {asset.description}"
                    )
            else:
                # Assigning an exact asset is itself a prepare action. Anonymous
                # prepared slots are optional; when present, the exact ID replaces
                # one of them so the prepared count is not doubled.
                added_requirement_units = 0
                required_for_group = _event_model_required_quantity(event, asset_group)
                non_extra_specific = _event_specific_asset_quantity(
                    event,
                    asset_group,
                    include_returned=False,
                    include_extra=False,
                )
                bulk_prepared = _event_bulk_quantity_for_group(event, asset_group, include_returned=False)
                fills_existing_requirement = (
                    reconciles_returned_slot
                    or (non_extra_specific + bulk_prepared) < required_for_group
                )
                if subproject:
                    room_required = _event_subproject_required_quantity(
                        subproject,
                        asset_group,
                    )
                    room_prepared = _event_subproject_prepared_quantity(
                        event,
                        subproject,
                        asset_group,
                    )
                    fills_existing_requirement = (
                        reconciles_returned_slot
                        or active_slot_quantity > 0
                        or room_prepared < room_required
                    )

            logger.info(
                f"Asset {asset_id}: fromContainer={scan_options['fromContainer']}; "
                f"addToEvent={add_scanned_assets_to_event}; "
                f"fillsExistingRequirement={fills_existing_requirement}; addedUnits={added_requirement_units}"
            )
            
            if fills_existing_requirement:
                if not add_scanned_assets_to_event or replaces_prepared_slot:
                    consumed_prepared_slot = bool(
                        _decrement_prepared_model_slot(event, asset_group, 1)
                    )
                    if not consumed_prepared_slot and reconciles_returned_slot:
                        consumed_returned_prepared_slot = bool(
                            _decrement_returned_prepared_model_slot(event, asset_group, 1)
                        )
                removed_refs = _remove_direct_asset_ref_from_prepared_items(event, asset_id)
                if removed_refs:
                    logger.info(f"Removed {asset_id} from prepared_items because it fulfills a model requirement")
                if asset_id in event.extra_assets:
                    event.extra_assets.remove(asset_id)
                    logger.info(f"Removed {asset_id} from extra_assets. Extra assets: {event.extra_assets}")
            else:
                if not add_scanned_assets_to_event:
                    consumed_prepared_slot = bool(
                        _decrement_prepared_model_slot(event, asset_group, 1)
                    )
                    if not consumed_prepared_slot and reconciles_returned_slot:
                        consumed_returned_prepared_slot = bool(
                            _decrement_returned_prepared_model_slot(event, asset_group, 1)
                        )
                # Loose extras and direct specific-asset events still need an
                # explicit prepared_items row so they remain part of the packing list.
                if asset_id not in event.prepared_items:
                    event.prepared_items.append(asset_id)
                    logger.info(f"Added {asset_id} to prepared_items")
                if asset_id not in event.extra_assets:
                    event.extra_assets.append(asset_id)
                    logger.info(f"Added individual extra asset {asset_id}. Extra assets: {event.extra_assets}")

            if not consumed_returned_prepared_slot:
                asset.current_location = event.name
                data_manager.save_inventory()

        # A late asset-ID assignment can replace an already-returned anonymous
        # unit. Keep that exact asset returned instead of reopening the return.
        if consumed_returned_prepared_slot:
            if asset_id not in event.returned_items:
                event.returned_items.append(asset_id)
        elif asset_id not in event.actually_prepared:
            event.actually_prepared.append(asset_id)
            logger.info(f"Added {asset_id} to actually_prepared. List now: {event.actually_prepared}")

        if subproject:
            assigned_group = None
            assigned_asset = data_manager.inventory.get(asset_id)
            if assigned_asset:
                assigned_group = _asset_group_from_item(assigned_asset)
            assigned_to_requirement = bool(
                assigned_group
                and fills_existing_requirement
                and _event_subproject_assign_ref(
                    subproject,
                    assigned_group,
                    asset_id,
                    consume_slot=consumed_prepared_slot,
                )
            )
            if assigned_group and not assigned_to_requirement:
                refs = subproject.setdefault('extraRefs', [])
                if asset_id not in refs:
                    refs.append(asset_id)
            if assigned_group and consumed_returned_prepared_slot:
                _event_subproject_adjust_returned_prepared(
                    subproject,
                    assigned_group,
                    -1,
                )
            _reconcile_event_subproject_extras(event)
        elif getattr(event, 'subprojects', []) or []:
            # All-requirements scans have no room ID. Reconcile the aggregate
            # slot change and attach the exact ID to the newly opened room slot.
            _reconcile_event_subproject_extras(event)

        # Update event state
        update_event_state(event)
        
        _log_event_asset_action(
            event_id,
            'assign',
            [_event_asset_log_item(asset_id)],
            persist_event=False,
        )

        # Persist the state and its audit entry together. Previously the event
        # file was written once here and again by the audit logger per scan.
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()

        response_payload = {
            'success': True,
            'message': f'Asset {asset_id} assigned to event',
            'data': {
                'assetId': asset_id,
                'isExtra': asset_id in getattr(event, 'extra_assets', []),
                'addedToEvent': add_scanned_assets_to_event,
                'addedRequirementUnits': locals().get('added_requirement_units', 0),
            }
        }
        assigned_asset = data_manager.inventory.get(asset_id)
        if assigned_asset and _is_degraded(assigned_asset):
            response_payload['warning'] = _degraded_asset_warning(assigned_asset, asset_id)
        return jsonify(response_payload)

    except Exception as e:
        logger.error(f"Error assigning specific asset to event {event_id}: {e}")
        return jsonify({'error': 'Failed to assign asset'}), 500


@app.route('/api/events/<int:event_id>/prepare-model-quantity', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def prepare_event_model_quantity(event_id):
    """Prepare or unprepare a model line by quantity before exact asset IDs are assigned."""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        _ensure_event_custom_lists(event)
        data = request.get_json(silent=True) or {}
        group = _group_from_request(data)
        subproject = _event_subproject(event, data.get('subprojectId'))
        if str(data.get('subprojectId') or '').strip() and not subproject:
            return jsonify({'error': 'Sub-project not found'}), 404
        action = str(data.get('action') or 'prepare').strip().lower()
        requested_quantity = _safe_int(data.get('quantity'), 0)
        prepare_all = bool(data.get('all') or data.get('prepareAll'))

        required = (
            _event_subproject_required_quantity(subproject, group)
            if subproject
            else _event_model_required_quantity(event, group)
        )
        if required <= 0 and action == 'prepare':
            return jsonify({'error': 'Model requirement not found for this event'}), 404

        is_bulk = _event_group_is_bulk_quantity(group)
        current_prepared = (
            _event_subproject_prepared_quantity(event, subproject, group)
            if subproject
            else _event_active_prepared_quantity_for_group(
                event,
                group,
                include_extra=True,
            )
        )

        if action == 'prepare':
            quantity = max(0, required - current_prepared) if prepare_all else requested_quantity
            if quantity <= 0:
                return jsonify({
                    'success': True,
                    'message': 'This line item is already prepared',
                    'data': {
                        'preparedQuantity': current_prepared,
                        'requiredQuantity': required,
                        'preparedNow': 0,
                    },
                })

            capacity = _event_prepare_capacity_for_group(event, group)
            capacity_used = _event_active_prepared_quantity_for_group(
                event,
                group,
                include_extra=True,
            )
            if capacity_used + quantity > capacity:
                return jsonify({
                    'error': (
                        f"Only {max(0, capacity - capacity_used)} more unit"
                        f"{'' if max(0, capacity - capacity_used) == 1 else 's'} can be prepared for this event date range"
                    )
                }), 400

            if is_bulk:
                prepared_now = _add_bulk_prepared_quantity(
                    event,
                    group,
                    quantity,
                    subproject.get('id') if subproject else None,
                )
                if prepared_now != quantity:
                    return jsonify({'error': 'Not enough bulk quantity is available'}), 400
            else:
                prepared_now = _increment_prepared_model_slot(event, group, quantity)

            if subproject:
                if is_bulk:
                    active_refs = set(getattr(event, 'actually_prepared', []) or [])
                    for item in _event_subproject_group_items(subproject, group):
                        item['assetRefs'] = [
                            ref for ref in item.get('assetRefs') or []
                            if ref in active_refs
                        ]
                    for ref in getattr(event, 'actually_prepared', []) or []:
                        marker = _parse_bulk_marker(ref)
                        if (
                            marker
                            and marker.get('subprojectId') == str(subproject.get('id') or '')
                            and _event_physical_ref_group_key(ref) == _event_model_group_key(group)
                        ):
                            _event_subproject_assign_ref(subproject, group, ref)
                else:
                    _event_subproject_adjust_prepared(
                        subproject,
                        group,
                        prepared_now,
                    )

            if getattr(event, 'subprojects', []) or []:
                _reconcile_event_subproject_extras(event)

            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()

            _log_event_asset_action(
                event_id,
                'prepare',
                [_event_asset_log_item(quantity=prepared_now, group=group)],
            )

            return jsonify({
                'success': True,
                'message': f"Prepared {prepared_now}x {group['brand']} {group['model']}",
                'data': {
                    'preparedNow': prepared_now,
                    'requiredQuantity': required,
                    'preparedQuantity': current_prepared + prepared_now,
                    'isBulk': is_bulk,
                },
            })

        if action in {'unprepare', 'unprepared'}:
            quantity = requested_quantity
            if quantity <= 0:
                return jsonify({'error': 'Quantity is required'}), 400

            if is_bulk:
                removable = (
                    _event_bulk_quantity_for_group(
                        event,
                        group,
                        include_returned=False,
                        subproject_id=subproject.get('id'),
                    )
                    if subproject
                    else _event_bulk_quantity_for_group(
                        event,
                        group,
                        include_returned=False,
                    )
                )
                if quantity > removable:
                    return jsonify({'error': f'Only {removable} prepared unit(s) can be unprepared'}), 400
                removed_now = _remove_bulk_prepared_quantity(
                    event,
                    group,
                    quantity,
                    subproject.get('id') if subproject else None,
                )
            else:
                removable = (
                    _event_subproject_anonymous_prepared_quantity(subproject, group)
                    if subproject
                    else _event_prepared_slot_quantity(event, group)
                )
                if quantity > removable:
                    assigned = _event_specific_asset_quantity(event, group, include_returned=False, include_extra=True)
                    if assigned > 0:
                        return jsonify({
                            'error': (
                                f"Only {removable} unassigned prepared unit(s) can be unprepared. "
                                "Unassign specific assets to unprepare those units."
                            )
                        }), 400
                    return jsonify({'error': f'Only {removable} prepared unit(s) can be unprepared'}), 400
                removed_now = _decrement_prepared_model_slot(event, group, quantity)

            if subproject and not is_bulk:
                _event_subproject_adjust_prepared(
                    subproject,
                    group,
                    -removed_now,
                )
            elif subproject:
                active_refs = set(getattr(event, 'actually_prepared', []) or [])
                for item in _event_subproject_group_items(subproject, group):
                    item['assetRefs'] = [
                        ref for ref in item.get('assetRefs') or []
                        if ref in active_refs
                    ]

            if getattr(event, 'subprojects', []) or []:
                _reconcile_event_subproject_extras(event)

            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()

            _log_event_asset_action(
                event_id,
                'unprepare',
                [_event_asset_log_item(quantity=removed_now, group=group)],
            )

            return jsonify({
                'success': True,
                'message': f"Unprepared {removed_now}x {group['brand']} {group['model']}",
                'data': {
                    'unpreparedNow': removed_now,
                    'requiredQuantity': required,
                    'preparedQuantity': max(0, current_prepared - removed_now),
                    'isBulk': is_bulk,
                },
            })

        return jsonify({'error': 'Unsupported prepare action'}), 400

    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400
    except Exception as exc:
        logger.error("Error preparing model quantity for event %s: %s", event_id, exc, exc_info=True)
        return jsonify({'error': 'Failed to update prepared quantity'}), 500

@app.route('/api/events/<int:event_id>/unassign-specific', methods=['POST'])
@require_auth
@require_event_access
@with_prepare_action_lock
def unassign_specific_asset_from_model(event_id):
    """Unassign a specific asset from a model requirement"""
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        data = request.get_json()
        asset_id = data.get('assetId', '').strip()

        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400

        if _is_bulk_ref(asset_id):
            if not hasattr(event, 'actually_prepared'):
                event.actually_prepared = []
            if asset_id in event.actually_prepared:
                event.actually_prepared.remove(asset_id)
            if asset_id in event.returned_items:
                event.returned_items.remove(asset_id)
            if hasattr(event, 'extra_assets') and asset_id in event.extra_assets:
                event.extra_assets.remove(asset_id)
            _event_subproject_remove_ref(event, asset_id)
            _reconcile_event_subproject_extras(event)
            update_event_state(event)
            data_manager.save_event(event)
            invalidate_cache()
            _log_event_asset_action(
                event_id,
                'unassign',
                [_event_asset_log_item(asset_id)],
            )
            return jsonify({'success': True, 'message': 'Bulk quantity asset unassigned from event'})

        # Initialize actually_prepared if it doesn't exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []

        # Check if asset is assigned
        if asset_id not in event.actually_prepared:
            return jsonify({'error': 'Asset is not currently prepared for this event'}), 400

        # Remove from actually_prepared
        event.actually_prepared.remove(asset_id)
        if asset_id in getattr(event, 'prepared_items', []) or []:
            event.prepared_items.remove(asset_id)
        if hasattr(event, 'extra_assets') and asset_id in event.extra_assets:
            event.extra_assets.remove(asset_id)
        if asset_id in getattr(event, 'returned_items', []) or []:
            event.returned_items.remove(asset_id)
        _event_subproject_remove_ref(event, asset_id)

        promoted_extra_assets = _promote_matching_extra_assets(event)
        if promoted_extra_assets:
            logger.info(
                "Promoted extra asset(s) after unassigning %s from event %s: %s",
                asset_id,
                event_id,
                promoted_extra_assets,
            )

        # For regular assets, reset location
        if not _is_custom_ref(asset_id):
            asset = data_manager.inventory.get(asset_id)
            if asset:
                asset.current_location = asset.default_location or ''
                data_manager.save_inventory()

        # Update event state
        update_event_state(event)

        # Save changes
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()

        _log_event_asset_action(
            event_id,
            'unassign',
            [_event_asset_log_item(asset_id)],
        )

        return jsonify({'success': True, 'message': f'Asset {asset_id} unassigned and unprepared from event'})

    except Exception as e:
        logger.error(
            f"Error unassigning specific asset from event {event_id}: {e}")
        return jsonify({'error': 'Failed to unassign asset'}), 500
    
@app.route('/api/events/<int:event_id>/remove-asset', methods=['POST'])
@require_admin
def remove_asset_from_event(event_id):
    """Remove an asset from every assignment list associated with an event."""
    try:
        data = request.get_json(silent=True) or {}
        asset_id = data.get('assetId', '').strip()
        
        if not asset_id:
            return jsonify({'error': 'Asset ID is required'}), 400
        
        logger.info(f"Remove asset request: Event {event_id}, Asset: '{asset_id}'")
        
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        # Initialize lists if they don't exist
        if not hasattr(event, 'actually_prepared'):
            event.actually_prepared = []
        if not hasattr(event, 'extra_assets'):
            event.extra_assets = []

        # Check if asset is in this event (check ALL possible locations)
        asset_is_assigned = (asset_id in event.prepared_items or 
                            asset_id in event.actually_prepared or
                            asset_id in event.extra_assets)

        if not asset_is_assigned:
            logger.warning(f"Asset '{asset_id}' not found in event {event_id}")
            logger.info(f"  prepared_items: {event.prepared_items}")
            logger.info(f"  actually_prepared: {event.actually_prepared}")
            logger.info(f"  extra_assets: {event.extra_assets}")
            return jsonify({'error': 'Asset is not assigned to this event'}), 400

        # Remove the asset from ALL possible locations
        if asset_id in event.prepared_items:
            event.prepared_items.remove(asset_id)
            logger.info(f"Removed '{asset_id}' from prepared_items")

        if asset_id in event.returned_items:
            event.returned_items.remove(asset_id)
            logger.info(f"Removed '{asset_id}' from returned_items")

        if asset_id in event.actually_prepared:
            event.actually_prepared.remove(asset_id)
            logger.info(f"Removed '{asset_id}' from actually_prepared")

        if asset_id in event.extra_assets:
            event.extra_assets.remove(asset_id)
            logger.info(f"Removed '{asset_id}' from extra_assets")
        _event_subproject_remove_ref(event, asset_id)

        # For regular assets, update location
        if not _is_custom_ref(asset_id):
            asset = data_manager.inventory.get(asset_id)
            if asset:
                asset.current_location = asset.default_location or ''
                data_manager.save_inventory()
                logger.info(f"Reset location for asset '{asset_id}'")

        # Update event state
        update_event_state(event)

        # Save changes
        data_manager.save_event(event)

        # Invalidate cache
        invalidate_cache()

        _log_event_asset_action(
            event_id,
            'remove',
            [_event_asset_log_item(asset_id)],
        )

        return jsonify({'success': True, 'message': f'Asset {asset_id} removed from event'})
    except Exception as e:
        logger.error(f"Error removing asset from event {event_id}: {e}")
        return jsonify({'error': 'Failed to remove asset from event'}), 500

# ---------------- Transfer Assets helpers and routes ----------------

def _ensure_event_lists(event):
    """Make old event files safe to work with."""
    if not hasattr(event, 'prepared_items') or event.prepared_items is None:
        event.prepared_items = []
    if not hasattr(event, 'returned_items') or event.returned_items is None:
        event.returned_items = []
    if not hasattr(event, 'actually_prepared') or event.actually_prepared is None:
        event.actually_prepared = []
    if not hasattr(event, 'extra_assets') or event.extra_assets is None:
        event.extra_assets = []


def _event_summary_for_transfer(event):
    _ensure_event_lists(event)
    unreturned_count = len(_get_unreturned_real_asset_ids(event))
    required_count = 0
    for item in getattr(event, 'prepared_items', []) or []:
        requirement = _model_marker_to_requirement(item)
        if requirement:
            required_count += int(requirement.get('quantity', 0) or 0)
    return {
        'id': event.event_id,
        'name': event.name,
        'startDate': format_date_output(event.start_date),
        'endDate': format_date_output(event.end_date),
        'location': getattr(event, 'location', '') or '',
        'state': event.state,
        'tag': getattr(event, 'tag', 'events'),
        'unreturnedCount': unreturned_count,
        'requiredCount': required_count,
        'assetCount': len([x for x in event.prepared_items if isinstance(x, str) and not x.startswith('[MODEL]')]),
        'subprojects': [
            {
                'id': str(row.get('id') or ''),
                'name': str(row.get('name') or 'Unnamed room'),
            }
            for row in (getattr(event, 'subprojects', []) or [])
            if isinstance(row, dict) and str(row.get('id') or '').strip()
        ],
    }


def _norm(value, uppercase=False):
    value = str(value or '').strip()
    return value.upper() if uppercase else value.casefold()


def _asset_match_key(asset):
    return (
        _norm(getattr(asset, 'department_code', ''), True),
        _norm(getattr(asset, 'brand', '')),
        _norm(getattr(asset, 'model_number', '')),
        _norm(getattr(asset, 'description', '')),
    )


def _model_marker_to_requirement(marker):
    parsed = _parse_model_marker(marker)
    if not parsed:
        return None

    try:
        quantity = int(parsed.get('quantity') or 0)
    except Exception:
        quantity = 0

    if quantity <= 0:
        return None

    return {
        'department': parsed['department'],
        'brand': parsed['brand'],
        'model': parsed['model'],
        'description': parsed.get('description', ''),
        'quantity': quantity,
        'key': (
            _norm(parsed['department'], True),
            _norm(parsed['brand']),
            _norm(parsed['model']),
            _norm(parsed.get('description', '')),
        )
    }


def _get_unreturned_real_asset_ids(event):
    """Return real inventory asset IDs that are still physically out for an event."""
    _ensure_event_lists(event)
    returned = set(event.returned_items)

    # Most current web workflows put prepared physical assets in actually_prepared.
    # Keep prepared_items as a fallback for older event files.
    candidates = []
    for asset_id in list(event.actually_prepared) + list(event.prepared_items):
        if not _is_real_asset_ref(asset_id):
            continue
        if asset_id in returned:
            continue
        if asset_id not in data_manager.inventory:
            continue
        if asset_id not in candidates:
            candidates.append(asset_id)

    return candidates


def _transfer_target_subproject(event, subproject_id):
    rooms = [
        row for row in (getattr(event, 'subprojects', []) or [])
        if isinstance(row, dict) and str(row.get('id') or '').strip()
    ]
    if not rooms:
        return None

    clean_id = str(subproject_id or '').strip()
    if clean_id:
        room = _event_subproject(event, clean_id)
        if room:
            return room
        raise ValueError('Destination sub-project was not found')
    if len(rooms) == 1:
        return rooms[0]
    raise ValueError('Choose a destination sub-project')


def _target_model_requirements(event, subproject=None):
    """Return target [MODEL] requirements with already-prepared counts and remaining counts."""
    _ensure_event_lists(event)

    requirements = {}
    if subproject:
        for item in subproject.get('items') or []:
            group = _event_subproject_item_group(item)
            if not group:
                continue
            quantity = max(0, _safe_int(item.get('quantity'), 0))
            if quantity <= 0:
                continue
            key = (
                _norm(group['department'], True),
                _norm(group['brand']),
                _norm(group['model']),
                _norm(group.get('description', '')),
            )
            if key not in requirements:
                requirements[key] = {
                    'department': group['department'],
                    'brand': group['brand'],
                    'model': group['model'],
                    'description': group.get('description', ''),
                    'required': 0,
                    'prepared': 0,
                    'remaining': 0,
                }
            requirements[key]['required'] += quantity

        for key, requirement in requirements.items():
            group = {
                'department': requirement['department'],
                'brand': requirement['brand'],
                'model': requirement['model'],
                'description': requirement['description'],
            }
            requirement['prepared'] = _event_subproject_prepared_quantity(
                event,
                subproject,
                group,
            )
            requirement['remaining'] = max(
                requirement['required'] - requirement['prepared'],
                0,
            )
        return requirements

    for item in event.prepared_items:
        requirement = _model_marker_to_requirement(item)
        if not requirement:
            continue

        key = requirement['key']
        if key not in requirements:
            requirements[key] = {
                'department': requirement['department'],
                'brand': requirement['brand'],
                'model': requirement['model'],
                'description': requirement['description'],
                'required': 0,
                'prepared': 0,
                'remaining': 0,
            }
        requirements[key]['required'] += requirement['quantity']

    # Count real assets that are already prepared for the target and not returned.
    for asset_id in _get_unreturned_real_asset_ids(event):
        asset = data_manager.inventory.get(asset_id)
        if not asset:
            continue
        key = _asset_match_key(asset)
        if key in requirements:
            requirements[key]['prepared'] += 1

    for requirement in requirements.values():
        requirement['remaining'] = max(requirement['required'] - requirement['prepared'], 0)

    return requirements


def _destination_requirements_payload(event, subproject=None):
    """Return destination requirements in a frontend-friendly list."""
    requirements = []
    for requirement in _target_model_requirements(event, subproject).values():
        requirements.append({
            'department': requirement.get('department', ''),
            'brand': requirement.get('brand', ''),
            'model': requirement.get('model', ''),
            'description': requirement.get('description', ''),
            'required': int(requirement.get('required', 0) or 0),
            'prepared': int(requirement.get('prepared', 0) or 0),
            'remaining': int(requirement.get('remaining', 0) or 0),
        })

    requirements.sort(key=lambda item: (
        item['department'],
        item['brand'].casefold(),
        item['model'].casefold(),
        item['description'].casefold(),
    ))
    return requirements


def _transfer_office_candidate_payload(asset):
    return {
        'assetId': asset.asset_id,
        'id': asset.asset_id,
        'department': asset.department_code,
        'brand': asset.brand,
        'model': asset.model_number,
        'version': getattr(asset, 'version', ''),
        'description': asset.description or '',
        'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
        'serial': asset.serial_number,
        'serial2': getattr(asset, 'secondary_serial_number', ''),
        'status': _asset_status_value(asset),
        'currentLocation': asset.current_location or asset.default_location or 'Office',
        'isUntagged': _is_untagged(asset),
        'isDegraded': _is_degraded(asset),
        'isDisposed': _is_disposed(asset),
    }


def _get_available_office_candidates_for_transfer(to_event, requirement_key):
    """Return available exact asset IDs that can be prepared for the destination."""
    _ensure_event_lists(to_event)
    current_event_refs = _active_physical_asset_refs_for_event(to_event)
    busy_elsewhere = set()

    for other in data_manager.events.values():
        if not other or other.event_id == to_event.event_id:
            continue
        busy_elsewhere.update(_active_physical_asset_refs_for_event(other))

    candidates = []
    for asset_id, asset in sorted(data_manager.inventory.items(), key=lambda pair: pair[0]):
        if not asset or _is_bulk_asset(asset):
            continue
        if getattr(asset, 'is_missing', False) or getattr(asset, 'is_ooc', False) or _is_disposed(asset):
            continue
        if asset_id in current_event_refs or asset_id in busy_elsewhere:
            continue
        if _asset_match_key(asset) != requirement_key:
            continue
        candidates.append(_transfer_office_candidate_payload(asset))

    return candidates


def _asset_fulfills_event_model_requirement(event, asset, subproject=None):
    requirements = _target_model_requirements(event, subproject)
    return _asset_match_key(asset) in requirements


def _transfer_asset_payload(asset, state='', from_event=None, to_event=None, reason='', requirement=None, source_quantity=0, return_quantity=0):
    """Build a transfer-page asset payload.

    state is intentionally server-side so multiple browser/device sessions see
    the same action result after refreshing the comparison.
    """
    requirement = requirement or {}
    target_remaining = int(requirement.get('remaining', 0) or 0)
    return {
        'assetId': asset.asset_id,
        'department': asset.department_code,
        'brand': asset.brand,
        'model': asset.model_number,
        'description': asset.description,
        'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
        'serial': asset.serial_number,
        'serial2': getattr(asset, 'secondary_serial_number', ''),
        'status': _asset_status_value(asset),
        'isUntagged': _is_untagged(asset),
        'isDegraded': _is_degraded(asset),
        'isDisposed': _is_disposed(asset),
        'currentLocation': asset.current_location or (getattr(from_event, 'name', '') if from_event else ''),
        'matchLabel': f"[{asset.department_code}] {asset.brand} {asset.model_number} {asset.description}".strip(),
        'targetRequired': int(requirement.get('required', 0) or 0),
        'targetPrepared': int(requirement.get('prepared', 0) or 0),
        'targetRemainingBeforeThisAsset': target_remaining,
        'targetRemaining': target_remaining,
        'sourceQuantity': int(source_quantity or 0),
        'returnQuantity': int(return_quantity or 0),
        'reason': reason,
        'transferState': state,
    }


def _real_source_asset_ids_including_returned(event):
    """Return real inventory asset IDs connected to a source event.

    Unlike _get_unreturned_real_asset_ids(), this intentionally keeps returned
    IDs so the transfer page can keep showing already-transferred / returned-to-
    office assets with an Undo button after the server-side refresh.
    """
    _ensure_event_lists(event)
    ids = []
    for asset_id in list(event.actually_prepared) + list(event.prepared_items):
        if not _is_real_asset_ref(asset_id):
            continue
        if asset_id not in data_manager.inventory:
            continue
        if asset_id not in ids:
            ids.append(asset_id)
    return ids


def _asset_is_active_on_destination(asset_id, to_event, to_subproject=None):
    _ensure_event_lists(to_event)
    active = (
        asset_id in (getattr(to_event, 'actually_prepared', []) or [])
        and asset_id not in (getattr(to_event, 'returned_items', []) or [])
    )
    if not active or not to_subproject:
        return active
    return asset_id in _event_subproject_refs(to_subproject)


def _get_transfer_candidates(from_event, to_event, to_subproject=None):
    """
    Find source assets that can fill the destination event's remaining model
    requirements. Already-transferred assets are included too, marked with
    transferState='transferred', so every device can show them with Undo instead
    of disappearing after refresh.
    """
    _ensure_event_lists(from_event)
    _ensure_event_lists(to_event)

    requirements = _target_model_requirements(to_event, to_subproject)
    remaining_by_key = {key: req['remaining'] for key, req in requirements.items() if req['remaining'] > 0}

    candidates = []
    seen = set()

    # 1) Active source assets that may still be transferred.
    if remaining_by_key:
        for asset_id in _get_unreturned_real_asset_ids(from_event):
            asset = data_manager.inventory.get(asset_id)
            if not asset:
                continue
            if getattr(asset, 'is_missing', False) or getattr(asset, 'is_ooc', False) or _is_disposed(asset):
                continue

            key = _asset_match_key(asset)
            if remaining_by_key.get(key, 0) <= 0:
                continue

            req = requirements[key]
            candidates.append(_transfer_asset_payload(
                asset,
                state='',
                from_event=from_event,
                to_event=to_event,
                requirement=req,
            ))
            seen.add(asset.asset_id)

    # 2) Assets already moved from this source to this destination. These must
    # stay visible in Common / Transferable with an Undo button, and must not be
    # available in Return to Office.
    for asset_id in _real_source_asset_ids_including_returned(from_event):
        if asset_id in seen:
            continue
        if asset_id not in (getattr(from_event, 'returned_items', []) or []):
            continue
        if not _asset_is_active_on_destination(asset_id, to_event, to_subproject):
            continue

        asset = data_manager.inventory.get(asset_id)
        if not asset:
            continue

        key = _asset_match_key(asset)
        req = requirements.get(key, {
            'required': 0,
            'prepared': 0,
            'remaining': 0,
        })
        candidates.append(_transfer_asset_payload(
            asset,
            state='transferred',
            from_event=from_event,
            to_event=to_event,
            requirement=req,
            reason='Already transferred to destination event',
        ))
        seen.add(asset.asset_id)

    candidates.sort(key=lambda x: (x['department'], x['brand'], x['model'], x['description'], x['assetId']))
    return candidates



def _get_transfer_needed_from_office_assets(from_event, to_event, to_subproject=None):
    """Return destination event model quantities that still need to be packed from office.

    This compares the destination event's remaining model requirements against
    the source event's currently unreturned, transferable matching assets. If
    the destination still needs 12 of a type and the source event can provide 9,
    this view returns 3x for that type as still needed from office.
    """
    _ensure_event_lists(from_event)
    _ensure_event_lists(to_event)

    requirements = _target_model_requirements(to_event, to_subproject)

    # Count how many active, transferable source assets can still satisfy each
    # destination requirement. Already-transferred assets are not in this list,
    # and they are already counted as prepared in _target_model_requirements().
    source_available_by_key = defaultdict(int)
    for asset_id in _get_unreturned_real_asset_ids(from_event):
        asset = data_manager.inventory.get(asset_id)
        if not asset:
            continue
        if getattr(asset, 'is_missing', False) or getattr(asset, 'is_ooc', False):
            continue
        source_available_by_key[_asset_match_key(asset)] += 1

    needed = []
    for key, req in requirements.items():
        target_remaining = max(0, int(req.get('remaining', 0) or 0))
        if target_remaining <= 0:
            continue

        source_available = max(0, int(source_available_by_key.get(key, 0) or 0))
        office_quantity = max(0, target_remaining - source_available)
        if office_quantity <= 0:
            continue

        office_candidates = _get_available_office_candidates_for_transfer(to_event, key)
        needed.append({
            'assetId': '',
            'department': req.get('department', ''),
            'brand': req.get('brand', ''),
            'model': req.get('model', ''),
            'description': req.get('description', ''),
            'serial': '',
            'currentLocation': 'Office',
            'matchLabel': f"[{req.get('department', '')}] {req.get('brand', '')} {req.get('model', '')} {req.get('description', '')}".strip(),
            'targetRequired': int(req.get('required', 0) or 0),
            'targetPrepared': int(req.get('prepared', 0) or 0),
            'targetRemainingBeforeThisAsset': target_remaining,
            'targetRemaining': target_remaining,
            'sourceQuantity': source_available,
            'officeQuantity': office_quantity,
            'officeCandidateCount': len(office_candidates),
            'officeCandidates': office_candidates,
            'returnQuantity': 0,
            'reason': (
                f"Destination still needs {target_remaining}; "
                f"source can provide {source_available}; {office_quantity} should be packed from office"
            ),
            'transferState': 'neededFromOffice',
        })

    needed.sort(key=lambda x: (x['department'], x['brand'], x['model'], x['description']))
    return needed


def _get_transfer_return_to_office_assets(from_event, to_event, to_subproject=None):
    """Return source assets that should go back to office.

    This is quantity-based by asset type and server-state aware:
    - transferred assets are excluded from this view
    - already-returned-to-office assets remain visible with transferState
      'returnedOffice' so users can Undo from any device
    - the grouped quantity remains the true excess count, e.g. source has 15
      and destination only needs 12 => 3x should go back, even after one of the
      three has already been marked returned.
    """
    _ensure_event_lists(from_event)
    _ensure_event_lists(to_event)

    target_requirements = _target_model_requirements(to_event, to_subproject)

    source_groups = defaultdict(list)
    for asset_id in _real_source_asset_ids_including_returned(from_event):
        asset = data_manager.inventory.get(asset_id)
        if not asset:
            continue
        # If this exact unit was transferred to the destination, it belongs only
        # in Common / Transferable with Undo, not in Return to Office.
        if _asset_is_active_on_destination(asset_id, to_event):
            continue
        source_groups[_asset_match_key(asset)].append(asset)

    going_back = []

    for key, group_assets in source_groups.items():
        group_assets.sort(key=lambda asset: asset.asset_id)
        source_quantity = len(group_assets)
        requirement = target_requirements.get(key)

        if requirement:
            target_remaining = max(0, int(requirement.get('remaining', 0) or 0))
            return_quantity = max(0, source_quantity - target_remaining)
            if return_quantity <= 0:
                continue
            reason = (
                f"Destination needs {target_remaining}; "
                f"source has {source_quantity}; {return_quantity} should return to office"
            )
            target_required = int(requirement.get('required', 0) or 0)
            target_prepared = int(requirement.get('prepared', 0) or 0)
        else:
            target_remaining = 0
            return_quantity = source_quantity
            reason = 'Not required by destination event'
            target_required = 0
            target_prepared = 0

        req_payload = {
            'required': target_required,
            'prepared': target_prepared,
            'remaining': target_remaining,
        }

        for asset in group_assets:
            state = 'returnedOffice' if asset.asset_id in (getattr(from_event, 'returned_items', []) or []) else ''
            going_back.append(_transfer_asset_payload(
                asset,
                state=state,
                from_event=from_event,
                to_event=to_event,
                requirement=req_payload,
                reason=reason,
                source_quantity=source_quantity,
                return_quantity=return_quantity,
            ))

    going_back.sort(key=lambda x: (x['department'], x['brand'], x['model'], x['description'], x['assetId']))
    return going_back

def _transfer_one_asset(from_event, to_event, asset_id, to_subproject=None):
    _ensure_event_lists(from_event)
    _ensure_event_lists(to_event)

    if not _is_real_asset_ref(asset_id):
        raise ValueError('Only real inventory assets can be transferred here')

    asset = data_manager.inventory.get(asset_id)
    if not asset:
        raise ValueError(f'Asset {asset_id} not found')

    if asset_id in from_event.returned_items:
        raise ValueError(f'Asset {asset_id} has already been returned from the source event')

    if asset_id not in from_event.prepared_items and asset_id not in from_event.actually_prepared:
        raise ValueError(f'Asset {asset_id} is not currently prepared for the source event')

    # Return it from the source event.
    if asset_id not in from_event.returned_items:
        from_event.returned_items.append(asset_id)
    if asset_id in from_event.actually_prepared:
        from_event.actually_prepared.remove(asset_id)

    # Prepare it immediately for the destination event. If the destination did
    # not already have this asset type as a model requirement, add it so it shows
    # together with the rest of the event assets.
    if not _asset_fulfills_event_model_requirement(to_event, asset, to_subproject):
        _ensure_event_has_model_requirement_for_asset(to_event, asset, 1)

    _remove_direct_asset_ref_from_prepared_items(to_event, asset_id)
    if asset_id in to_event.returned_items:
        to_event.returned_items.remove(asset_id)
    if asset_id not in to_event.actually_prepared:
        to_event.actually_prepared.append(asset_id)

    if to_subproject:
        group = _asset_group_from_item(asset)
        _event_subproject_remove_ref(to_event, asset_id)
        if not _event_subproject_assign_ref(to_subproject, group, asset_id):
            raise ValueError(
                f'{asset_id} is not required by the selected destination sub-project'
            )

    # The asset has a model row now, so it should not be displayed as a loose extra.
    if asset_id in to_event.extra_assets:
        to_event.extra_assets.remove(asset_id)

    # The physical location should now show the destination event.
    asset.current_location = to_event.name

    return {
        'assetId': asset.asset_id,
        'brand': asset.brand,
        'model': asset.model_number,
        'description': asset.description,
        'department': asset.department_code,
        'serial': asset.serial_number,
        'serial2': getattr(asset, 'secondary_serial_number', ''),
    }


@app.route('/api/transfers/options', methods=['GET'])
@require_auth
def get_transfer_options():
    """Return valid source and destination events for the Transfer Assets page."""
    try:
        visible_events = [
            event for event in data_manager.events.values()
            if _current_user_can_access_event(event)
        ]
        refresh_event_states_for_read(visible_events)
        visible_events.sort(
            key=lambda event: (str(getattr(event, 'start_date', '') or ''), event.event_id)
        )

        total = len(visible_events)
        offset = max(0, request.args.get('offset', type=int) or 0)
        requested_limit = request.args.get('limit', type=int)
        limit = min(max(1, requested_limit), 500) if requested_limit else None
        page_events = visible_events[
            offset:offset + limit if limit is not None else None
        ] if (offset or limit is not None) else visible_events
        event_summaries = [_event_summary_for_transfer(event) for event in page_events]

        return jsonify({
            'success': True,
            'data': {
                'events': event_summaries,
                'sourceEvents': event_summaries,
                'targetEvents': event_summaries,
            },
            'meta': {
                'total': total,
                'offset': offset,
                'limit': limit,
                'hasMore': offset + len(event_summaries) < total,
                'nextOffset': (
                    offset + len(event_summaries)
                    if offset + len(event_summaries) < total
                    else None
                ),
            },
        })
    except Exception as e:
        logger.error(f"Error getting transfer options: {e}")
        return jsonify({'error': 'Failed to load transfer options'}), 500


@app.route('/api/transfers/candidates', methods=['GET'])
@require_auth
def get_transfer_candidates():
    """Return assets from the source event that match the destination event's remaining requirements."""
    try:
        from_event_id = request.args.get('fromEventId', type=int)
        to_event_id = request.args.get('toEventId', type=int)
        to_subproject_id = request.args.get('toSubprojectId', type=str)

        if not from_event_id or not to_event_id:
            return jsonify({'error': 'Source and destination events are required'}), 400
        if from_event_id == to_event_id:
            return jsonify({'error': 'Source and destination events cannot be the same'}), 400

        from_event = data_manager.events.get(from_event_id)
        to_event = data_manager.events.get(to_event_id)

        if not from_event or not to_event:
            return jsonify({'error': 'Event not found'}), 404
        if not _current_user_can_access_event(from_event) or not _current_user_can_access_event(to_event):
            return _event_access_denied_response()

        try:
            to_subproject = _transfer_target_subproject(to_event, to_subproject_id)
        except ValueError as error:
            return jsonify({'error': str(error)}), 400

        candidates = _get_transfer_candidates(from_event, to_event, to_subproject)
        return_to_office = _get_transfer_return_to_office_assets(
            from_event,
            to_event,
            to_subproject,
        )
        needed_from_office = _get_transfer_needed_from_office_assets(
            from_event,
            to_event,
            to_subproject,
        )

        return jsonify({
            'success': True,
            'data': {
                'fromEvent': _event_summary_for_transfer(from_event),
                'toEvent': _event_summary_for_transfer(to_event),
                'targetSubproject': (
                    {
                        'id': str(to_subproject.get('id') or ''),
                        'name': str(to_subproject.get('name') or 'Unnamed room'),
                    }
                    if to_subproject else None
                ),
                'candidates': candidates,
                'candidateCount': len(candidates),
                'returnToOffice': return_to_office,
                'returnToOfficeCount': len(return_to_office),
                'neededFromOffice': needed_from_office,
                'neededFromOfficeCount': len(needed_from_office),
                'neededFromOfficeQuantity': sum(int(item.get('officeQuantity', 0) or 0) for item in needed_from_office),
                'destinationRequirements': _destination_requirements_payload(
                    to_event,
                    to_subproject,
                ),
            }
        })
    except Exception as e:
        logger.error(f"Error getting transfer candidates: {e}")
        return jsonify({'error': 'Failed to load transfer candidates'}), 500


@app.route('/api/transfers/execute', methods=['POST'])
@require_auth
@with_transfer_action_lock
def execute_transfer_assets():
    """Bulk transfer selected matching assets from one event to another."""
    try:
        data = request.get_json() or {}
        from_event_id = data.get('fromEventId')
        to_event_id = data.get('toEventId')
        to_subproject_id = data.get('toSubprojectId')
        asset_ids = data.get('assetIds') or []

        if not from_event_id or not to_event_id:
            return jsonify({'error': 'Source and destination events are required'}), 400
        if int(from_event_id) == int(to_event_id):
            return jsonify({'error': 'Source and destination events cannot be the same'}), 400
        if not isinstance(asset_ids, list) or not asset_ids:
            return jsonify({'error': 'Select at least one asset to transfer'}), 400

        from_event = data_manager.events.get(int(from_event_id))
        to_event = data_manager.events.get(int(to_event_id))

        if not from_event or not to_event:
            return jsonify({'error': 'Event not found'}), 404
        if not _current_user_can_access_event(from_event) or not _current_user_can_access_event(to_event):
            return _event_access_denied_response()

        try:
            to_subproject = _transfer_target_subproject(
                to_event,
                to_subproject_id,
            )
        except ValueError as error:
            return jsonify({'error': str(error)}), 400

        transferred = []
        skipped = []

        for raw_asset_id in asset_ids:
            asset_id = str(raw_asset_id or '').strip()
            if not asset_id:
                continue

            asset = data_manager.inventory.get(asset_id)
            if not asset:
                skipped.append({'assetId': asset_id, 'reason': 'Asset not found'})
                continue

            requirements = _target_model_requirements(to_event, to_subproject)
            requirement = requirements.get(_asset_match_key(asset))
            if not requirement or requirement.get('remaining', 0) <= 0:
                skipped.append({'assetId': asset_id, 'reason': 'Destination event no longer needs this asset type'})
                continue

            try:
                transferred.append(_transfer_one_asset(
                    from_event,
                    to_event,
                    asset_id,
                    to_subproject,
                ))
            except ValueError as e:
                skipped.append({'assetId': asset_id, 'reason': str(e)})

        if not transferred:
            return jsonify({'error': 'No assets were transferred', 'skipped': skipped}), 400

        data_manager.save_inventory()
        update_event_state(from_event)
        update_event_state(to_event)
        data_manager.save_event(from_event)
        data_manager.save_event(to_event)
        invalidate_cache()

        log_action(
            f"Transferred {len(transferred)} asset(s) from event {from_event.event_id} to event {to_event.event_id}: "
            f"{', '.join([item['assetId'] for item in transferred])}"
        )

        return jsonify({
            'success': True,
            'message': f"Transferred {len(transferred)} asset(s)",
            'data': {
                'transferred': transferred,
                'skipped': skipped,
                'fromEvent': _event_summary_for_transfer(from_event),
                'toEvent': _event_summary_for_transfer(to_event),
                'targetSubproject': (
                    {
                        'id': str(to_subproject.get('id') or ''),
                        'name': str(to_subproject.get('name') or 'Unnamed room'),
                    }
                    if to_subproject else None
                ),
            }
        })
    except Exception as e:
        logger.error(f"Error executing transfer: {e}")
        import traceback
        logger.error(f"Transfer traceback: {traceback.format_exc()}")
        return jsonify({'error': 'Failed to transfer assets'}), 500


def _undo_transfer_one_asset(from_event, to_event, asset_id):
    _ensure_event_lists(from_event)
    _ensure_event_lists(to_event)

    if not _is_real_asset_ref(asset_id):
        raise ValueError('Only real inventory assets can be undone here')

    asset = data_manager.inventory.get(asset_id)
    if not asset:
        raise ValueError(f'Asset {asset_id} not found')

    if asset_id not in getattr(to_event, 'actually_prepared', []):
        raise ValueError(f'Asset {asset_id} is not currently prepared for the destination event')

    # Remove from destination event's active prepared assets.
    if asset_id in to_event.actually_prepared:
        to_event.actually_prepared.remove(asset_id)
    if asset_id in to_event.prepared_items:
        to_event.prepared_items.remove(asset_id)
    if asset_id in to_event.extra_assets:
        to_event.extra_assets.remove(asset_id)
    if asset_id in to_event.returned_items:
        to_event.returned_items.remove(asset_id)
    _event_subproject_remove_ref(to_event, asset_id)

    # Put it back as active on the source event.
    if asset_id in from_event.returned_items:
        from_event.returned_items.remove(asset_id)
    if not _asset_fulfills_event_model_requirement(from_event, asset) and asset_id not in from_event.prepared_items:
        from_event.prepared_items.append(asset_id)
    if asset_id not in from_event.actually_prepared:
        from_event.actually_prepared.append(asset_id)

    asset.current_location = from_event.name

    return {
        'assetId': asset.asset_id,
        'brand': asset.brand,
        'model': asset.model_number,
        'description': asset.description,
        'department': asset.department_code,
        'serial': asset.serial_number,
        'serial2': getattr(asset, 'secondary_serial_number', ''),
    }


def _return_source_asset_to_office(from_event, asset_id):
    _ensure_event_lists(from_event)

    if not _is_real_asset_ref(asset_id):
        raise ValueError('Only real inventory assets can be returned to office here')

    asset = data_manager.inventory.get(asset_id)
    if not asset:
        raise ValueError(f'Asset {asset_id} not found')

    if asset_id in from_event.returned_items:
        raise ValueError(f'Asset {asset_id} has already been returned from the source event')

    if asset_id not in from_event.prepared_items and asset_id not in from_event.actually_prepared:
        raise ValueError(f'Asset {asset_id} is not currently prepared for the source event')

    if asset_id in from_event.actually_prepared:
        from_event.actually_prepared.remove(asset_id)
    if asset_id not in from_event.returned_items:
        from_event.returned_items.append(asset_id)

    asset.current_location = asset.default_location or 'Store'

    return {
        'assetId': asset.asset_id,
        'brand': asset.brand,
        'model': asset.model_number,
        'description': asset.description,
        'department': asset.department_code,
        'serial': asset.serial_number,
        'serial2': getattr(asset, 'secondary_serial_number', ''),
    }


def _undo_return_source_asset_to_office(from_event, asset_id):
    _ensure_event_lists(from_event)

    if not _is_real_asset_ref(asset_id):
        raise ValueError('Only real inventory assets can be restored here')

    asset = data_manager.inventory.get(asset_id)
    if not asset:
        raise ValueError(f'Asset {asset_id} not found')

    if asset_id not in from_event.returned_items:
        raise ValueError(f'Asset {asset_id} is not marked as returned from the source event')

    from_event.returned_items.remove(asset_id)
    if not _asset_fulfills_event_model_requirement(from_event, asset) and asset_id not in from_event.prepared_items:
        from_event.prepared_items.append(asset_id)
    if asset_id not in from_event.actually_prepared:
        from_event.actually_prepared.append(asset_id)

    asset.current_location = from_event.name

    return {
        'assetId': asset.asset_id,
        'brand': asset.brand,
        'model': asset.model_number,
        'description': asset.description,
        'department': asset.department_code,
        'serial': asset.serial_number,
        'serial2': getattr(asset, 'secondary_serial_number', ''),
    }


@app.route('/api/transfers/undo', methods=['POST'])
@require_auth
@with_transfer_action_lock
def undo_transfer_assets():
    """Undo one or more direct transfers from a destination event back to the source event."""
    try:
        data = request.get_json() or {}
        from_event_id = data.get('fromEventId')
        to_event_id = data.get('toEventId')
        asset_ids = data.get('assetIds') or []

        if not from_event_id or not to_event_id:
            return jsonify({'error': 'Source and destination events are required'}), 400
        if not isinstance(asset_ids, list) or not asset_ids:
            return jsonify({'error': 'Select at least one asset to undo'}), 400

        from_event = data_manager.events.get(int(from_event_id))
        to_event = data_manager.events.get(int(to_event_id))
        if not from_event or not to_event:
            return jsonify({'error': 'Event not found'}), 404
        if not _current_user_can_access_event(from_event) or not _current_user_can_access_event(to_event):
            return _event_access_denied_response()

        undone = []
        skipped = []
        for raw_asset_id in asset_ids:
            asset_id = str(raw_asset_id or '').strip()
            if not asset_id:
                continue
            try:
                undone.append(_undo_transfer_one_asset(from_event, to_event, asset_id))
            except ValueError as e:
                skipped.append({'assetId': asset_id, 'reason': str(e)})

        if not undone:
            return jsonify({'error': 'No transfers were undone', 'skipped': skipped}), 400

        data_manager.save_inventory()
        update_event_state(from_event)
        update_event_state(to_event)
        data_manager.save_event(from_event)
        data_manager.save_event(to_event)
        invalidate_cache()

        log_action(
            f"Undid {len(undone)} transfer(s) from event {to_event.event_id} back to event {from_event.event_id}: "
            f"{', '.join([item['assetId'] for item in undone])}"
        )

        return jsonify({'success': True, 'message': f"Undid {len(undone)} transfer(s)", 'data': {'undone': undone, 'skipped': skipped}})
    except Exception as e:
        logger.error(f"Error undoing transfer: {e}", exc_info=True)
        return jsonify({'error': 'Failed to undo transfer'}), 500


