@app.route('/api/assets', methods=['GET'])
@require_auth
def get_assets():
    """Get all assets"""
    try:
        summary_view = request.args.get('view', '').strip().lower() == 'summary'
        query = request.args.get('query', '').strip().lower()
        query_groups = [term.split() for term in query.split('+') if term.strip()]
        department_filter = request.args.get('department', '').strip().lower()
        status_filter = request.args.get('status', '').strip().lower()
        offset = max(0, request.args.get('offset', type=int) or 0)
        requested_limit = request.args.get('limit', type=int)
        limit = min(max(1, requested_limit), 1000) if requested_limit else None
        assets_data = []
        assigned_assets = get_assigned_assets()
        deployments_by_asset = _inventory_deployments_by_asset()
        departments = _load_departments()

        inventory_rows = list(data_manager.inventory.values())
        if query_groups:
            matching_rows = []
            for asset in inventory_rows:
                searchable_text = ' '.join(str(value or '').lower() for value in (
                    '' if _is_bulk_asset(asset) else asset.asset_id,
                    asset.asset_id,
                    asset.brand,
                    asset.model_number,
                    getattr(asset, 'version', ''),
                    asset.serial_number,
                    getattr(asset, 'secondary_serial_number', ''),
                    asset.description,
                    ' '.join(normalize_asset_tags(getattr(asset, 'tags', []))),
                ))
                if any(
                    all(word in searchable_text for word in words)
                    for words in query_groups
                ):
                    matching_rows.append(asset)
            inventory_rows = matching_rows
        if department_filter:
            inventory_rows = [
                asset for asset in inventory_rows
                if str(asset.department_code or '').lower() == department_filter
            ]
        unfiltered_total = len(inventory_rows)
        # The normal inventory and maintenance screens do not request a status
        # filter. Slice domain objects before serializing histories and media so
        # the first progressive page is genuinely cheap to produce.
        if not status_filter and (offset or limit is not None):
            inventory_rows = inventory_rows[
                offset:offset + limit if limit is not None else None
            ]

        for asset in inventory_rows:
            maintenance_records = [] if summary_view else [
                _maintenance_log_for_response(log)
                for log in (getattr(asset, 'maintenance_logs', []) or [])
            ]
            is_bulk = _is_bulk_asset(asset)
            total_quantity = max(1, _safe_int(getattr(asset, 'quantity', 1), 1)) if is_bulk else 1
            asset_deployments = deployments_by_asset.get(asset.asset_id, [])
            bulk_deployments = asset_deployments if is_bulk else []
            deployed_quantity = (
                sum(item['quantity'] for item in bulk_deployments)
                if is_bulk else (1 if asset.asset_id in assigned_assets else 0)
            )
            bulk_fault_counts = _bulk_maintenance_quantity_counts(asset) if is_bulk else {
                'ooc': 0,
                'missing': 0,
                'degraded': 0,
                'unavailable': 0,
                'total': 0,
            }
            unavailable_fault_quantity = bulk_fault_counts['ooc'] + bulk_fault_counts['missing']
            available_quantity = (
                0 if (
                    _is_disposed(asset)
                    or getattr(asset, 'is_missing', False)
                    or getattr(asset, 'is_ooc', False)
                    or (not is_bulk and deployed_quantity > 0)
                )
                else max(0, total_quantity - deployed_quantity - unavailable_fault_quantity) if is_bulk
                else 1
            )
            preparable_quantity = (
                0 if (_is_disposed(asset) or getattr(asset, 'is_missing', False) or getattr(asset, 'is_ooc', False))
                else max(0, total_quantity - deployed_quantity - unavailable_fault_quantity) if is_bulk
                else available_quantity
            )
            healthy_quantity = (
                0 if (is_bulk and _is_degraded(asset))
                else max(0, preparable_quantity - bulk_fault_counts['degraded'])
                if is_bulk else available_quantity
            )

            # Determine current status
            status = _asset_status_value(asset, assigned_assets)
            if is_bulk and status not in ('decommissioned', 'missing', 'ooc'):
                if deployed_quantity > 0:
                    status = 'deployed'
                elif bulk_fault_counts['missing'] > 0:
                    status = 'missing'
                elif bulk_fault_counts['ooc'] > 0:
                    status = 'ooc'
                elif bulk_fault_counts['degraded'] > 0 or _is_degraded(asset):
                    status = 'degraded'
                else:
                    status = 'available'

            asset_payload = {
                'id': '' if is_bulk else asset.asset_id,
                'internalId': asset.asset_id,
                'bulkId': asset.asset_id if is_bulk else '',
                'displayId': '' if is_bulk else asset.asset_id,
                'brand': asset.brand,
                'model': asset.model_number,
                'version': getattr(asset, 'version', ''),
                'serial': asset.serial_number,
                'serial2': getattr(asset, 'secondary_serial_number', ''),
                'description': asset.description,
                'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
                'dateOfPurchase': getattr(asset, 'date_of_purchase', ''),
                'purchaseDate': getattr(asset, 'date_of_purchase', ''),
                'purchaseBatches': _bulk_purchase_batches_for_response(asset),
                'dateAdded': getattr(asset, 'date_added', ''),
                'dateModified': getattr(asset, 'date_modified', ''),
                'department': asset.department_code,
                'departmentName': _department_payload(asset.department_code, departments)['name'],
                'departmentColor': _department_payload(asset.department_code, departments)['color'],
                'departmentTextColor': _department_payload(asset.department_code, departments)['textColor'],
                'status': status,
                'location': asset.current_location or asset.default_location,
                'isMissing': asset.is_missing,
                'isOOC': asset.is_ooc,
                'isUntagged': _is_untagged(asset),
                'isDegraded': _is_degraded(asset),
                'isDisposed': _is_disposed(asset),
                'defaultLocation': asset.default_location,
                'currentLocation': asset.current_location,
                'isBulk': is_bulk,
                'quantity': total_quantity,
                'availableQuantity': available_quantity,
                'preparableQuantity': preparable_quantity,
                'healthyQuantity': healthy_quantity,
                'deployedQuantity': deployed_quantity,
                'deployments': asset_deployments,
                'bulkDeployments': bulk_deployments if is_bulk else [],
                'bulkOOCQuantity': bulk_fault_counts['ooc'] if is_bulk else 0,
                'bulkMissingQuantity': bulk_fault_counts['missing'] if is_bulk else 0,
                'bulkDegradedQuantity': bulk_fault_counts['degraded'] if is_bulk else 0,
                'bulkFaultQuantity': bulk_fault_counts['total'] if is_bulk else 0,
                'degradedReasons': _asset_degraded_reasons(asset),
                'bulkDegradedReasons': _bulk_degraded_reasons(asset) if is_bulk else [],
                'conditionDetails': {
                    status_name: detail
                    for status_name in ('ooc', 'degraded')
                    if (detail := _active_asset_condition_detail(asset, status_name))
                },
                # Notes are needed by the inventory editor even in progressive
                # summary mode; omitting them made a saved note appear to vanish.
                'notes': getattr(asset, 'notes', ''),
            }
            if not summary_view:
                asset_payload.update({
                    'changeHistory': getattr(asset, 'change_history', []),
                    'maintenanceLogs': [
                        maintenance_log_to_display_string(log, include_changes=False)
                        for log in maintenance_records
                    ],
                    'maintenanceLogRecords': maintenance_records,
                    'bulkMaintenanceLogbook': (
                        _bulk_maintenance_logbook_for_response(asset)
                        if is_bulk else []
                    ),
                })
            assets_data.append(asset_payload)

        if status_filter:
            assets_data = [
                asset for asset in assets_data
                if str(asset.get('status') or '').lower() == status_filter
            ]

        total = len(assets_data) if status_filter else unfiltered_total
        if status_filter and (offset or limit is not None):
            assets_data = assets_data[offset:offset + limit if limit else None]

        return jsonify({
            'success': True,
            'data': assets_data,
            'meta': {
                'total': total,
                'offset': offset,
                'limit': limit,
                'hasMore': offset + len(assets_data) < total,
                'nextOffset': (
                    offset + len(assets_data)
                    if offset + len(assets_data) < total
                    else None
                ),
                'view': 'summary' if summary_view else 'full',
            },
        })
    except Exception as e:
        logger.error(f"Error getting assets: {e}")
        return jsonify({'error': 'Failed to retrieve assets'}), 500


