@app.route('/api/assets/import-preview', methods=['POST'])
@require_admin
def preview_asset_import():
    uploaded = request.files.get('file')
    if not uploaded or not uploaded.filename:
        return jsonify({'error': 'Choose a CSV or Excel file to upload'}), 400
    extension = os.path.splitext(uploaded.filename)[1].lower()
    if extension not in ASSET_IMPORT_FILE_EXTENSIONS:
        return jsonify({'error': 'Upload a CSV or Excel file (.csv, .xlsx, .xlsm, or .xls)'}), 400
    file_bytes = uploaded.read(ASSET_IMPORT_MAX_BYTES + 1)
    if len(file_bytes) > ASSET_IMPORT_MAX_BYTES:
        return jsonify({'error': 'The import file must be 5 MB or smaller'}), 413
    try:
        parsed = _parse_asset_import_file(file_bytes, uploaded.filename)
        parsed.update(_asset_import_plan_response(parsed['rows']))
        existing_rejected_rows = {
            _safe_int(item.get('sourceRow'), 0)
            for item in parsed['rejected']
        }
        parsed['rejected'].extend(
            {
                'sourceRow': row.get('sourceRow', 0),
                'error': row['departmentIssue'],
            }
            for row in parsed['rows']
            if row.get('departmentIssue')
            and _safe_int(row.get('sourceRow'), 0) not in existing_rejected_rows
        )
        departments = _load_departments()
        parsed['departments'] = [
            _department_payload(code, departments)
            for code in sorted(departments.keys())
        ]
        return jsonify({'success': True, 'data': parsed})
    except (RuntimeError, ValueError) as error:
        return jsonify({'error': str(error)}), 400
    except Exception as error:
        logger.error('Error previewing asset import: %s', error, exc_info=True)
        return jsonify({'error': 'Could not read the asset import file'}), 500


@app.route('/api/assets/import-plan', methods=['POST'])
@require_admin
def plan_asset_import():
    data = request.get_json() or {}
    rows = data.get('rows')
    if not isinstance(rows, list) or not rows:
        return jsonify({'error': 'The import does not contain any assets'}), 400
    if len(rows) > ASSET_IMPORT_MAX_ROWS:
        return jsonify({'error': f'An import can contain at most {ASSET_IMPORT_MAX_ROWS} rows'}), 400
    try:
        planned = _asset_import_plan_response(rows)
    except ValueError as error:
        return jsonify({'error': str(error)}), 400
    return jsonify({'success': True, 'data': planned})


@app.route('/api/assets/import', methods=['POST'])
@require_admin
def import_assets_from_workbook():
    data = request.get_json() or {}
    raw_rows = data.get('rows')
    plan_token = str(data.get('planToken') or '')
    if not isinstance(raw_rows, list) or not raw_rows:
        return jsonify({'error': 'The import does not contain any assets'}), 400
    if len(raw_rows) > ASSET_IMPORT_MAX_ROWS:
        return jsonify({'error': f'An import can contain at most {ASSET_IMPORT_MAX_ROWS} rows'}), 400

    with _inventory_action_lock:
        try:
            plan = _verify_asset_import_plan(raw_rows, plan_token)
        except ValueError as error:
            return jsonify({'error': str(error), 'code': 'asset_import_plan_required'}), 409

        inventory_changed = (
            plan.get('revision') != _asset_import_inventory_revision()
        )
        departments_changed = (
            plan.get('departmentRevision')
            != _asset_import_department_revision()
        )
        if inventory_changed or departments_changed:
            refreshed = _asset_import_plan_response(raw_rows)
            return jsonify({
                'error': (
                    'Inventory or departments changed after this import was '
                    'previewed. Review the refreshed matches and Asset IDs, '
                    'then confirm again.'
                ),
                'code': 'asset_import_plan_stale',
                'data': refreshed,
            }), 409

        normalized_rows = []
        row_errors = []
        departments = _load_departments()
        try:
            new_departments = _asset_import_proposed_departments(raw_rows, departments)
        except ValueError as error:
            return jsonify({'error': str(error)}), 400
        planning_departments = {**departments, **new_departments}
        for index, raw_row in enumerate(raw_rows):
            try:
                normalized_rows.append(_normalise_asset_import_payload(
                    raw_row,
                    departments=planning_departments,
                ))
            except ValueError as error:
                row_errors.append({
                    'index': index,
                    'sourceRow': _safe_int((raw_row or {}).get('sourceRow'), 0) if isinstance(raw_row, dict) else 0,
                    'error': str(error),
                })
        if row_errors:
            return jsonify({'error': 'Some imported assets need attention', 'rowErrors': row_errors}), 400

        expanded_record_count = sum(
            1 if row['isBulk'] else row['quantity']
            for row in normalized_rows
        )
        if expanded_record_count > ASSET_IMPORT_MAX_RECORDS:
            return jsonify({
                'error': (
                    f'This import would create {expanded_record_count:,} inventory records. '
                    f'The safe limit is {ASSET_IMPORT_MAX_RECORDS:,} records per import.'
                ),
                'code': 'asset_import_too_large',
            }), 413

        departments_before = copy.deepcopy(departments)
        audit_timestamp = _asset_audit_timestamp()
        audit_user = _asset_audit_user()
        results = []
        staged_inventory = {}
        try:
            for index, payload in enumerate(normalized_rows):
                planned_ids = list((raw_rows[index] or {}).get('assetIdsPreview') or [])
                if any(
                    asset_id in data_manager.inventory or asset_id in staged_inventory
                    for asset_id in planned_ids
                ):
                    raise ValueError(
                        'A planned Asset ID is no longer available; refresh the import preview'
                    )
                created_ids = _create_asset_import_row(
                    payload,
                    audit_timestamp,
                    audit_user,
                    created_asset_ids=planned_ids,
                    inventory_target=staged_inventory,
                )
                results.append({
                    'index': index,
                    'sourceRow': payload.get('sourceRow', 0),
                    'assetIds': created_ids,
                    'quantity': payload['quantity'],
                    'isBulk': payload['isBulk'],
                })
            if new_departments:
                departments.update(new_departments)
                _save_departments(departments)
            data_manager.inventory.update(staged_inventory)
            data_manager.save_inventory()
        except Exception as error:
            for asset_id in staged_inventory:
                data_manager.inventory.pop(asset_id, None)
            if new_departments:
                try:
                    _save_departments(departments_before)
                except Exception:
                    logger.error(
                        'Failed to roll back departments after an asset import error',
                        exc_info=True,
                    )
            if isinstance(error, ValueError):
                return jsonify({'error': str(error)}), 400
            logger.error('Error importing assets: %s', error, exc_info=True)
            return jsonify({'error': 'Failed to save the imported assets'}), 500

        mark_data_snapshot_current()

    if new_departments:
        mark_realtime_change('departments', {
            'action': 'created-from-asset-import',
            'departments': list(new_departments.values()),
        })

    invalidate_cache()
    created_record_count = sum(len(result['assetIds']) for result in results)
    bulk_unit_count = sum(
        result['quantity'] for result in results if result['isBulk']
    )
    log_action(
        f'Imported {len(results)} asset row(s) from a template file: '
        f'{created_record_count} inventory record(s), {bulk_unit_count} bulk unit(s)',
        system_log_only=True,
    )
    return jsonify({
        'success': True,
        'message': f'Imported {len(results)} asset row(s)',
        'data': {
            'rows': results,
            'inventoryRecordsCreated': created_record_count,
            'bulkUnitsCreated': bulk_unit_count,
        },
    })


@app.route('/api/assets', methods=['POST'])
@require_admin
def create_asset():
    """Create one or more assets."""
    try:
        data = request.get_json() or {}
        purchase_date = _normalise_asset_purchase_date(
            data.get('dateOfPurchase', data.get('purchaseDate', ''))
        )
        version = str(data.get('version') or '').strip()
        notes = str(data.get('notes', '') or '').strip()
        tags = normalize_asset_tags(data.get('tags', []))
        tags_to_apply_to_similar = normalize_asset_tags(data.get('tagsToApplyToSimilar', []))

        with _inventory_action_lock:
            plan = _asset_id_plan_for_request(data)
            similar_tag_targets = []
            similar_tag_audit_before = []
            if tags_to_apply_to_similar:
                requested_group = {
                    'department': plan['department'],
                    'brand': plan['brand'],
                    'model': plan['model'],
                    'description': plan['description'],
                }
                similar_tag_targets = [
                    item for item in data_manager.inventory.values()
                    if _asset_matches_group(item, requested_group)
                ]
                similar_tag_audit_before = [
                    (target, _asset_audit_snapshot(target))
                    for target in similar_tag_targets
                ]
            serial_mismatches = _asset_serial_count_mismatches(
                data,
                plan['quantity'],
                plan['isBulk'],
            )
            if serial_mismatches and not _request_bool(data.get('confirmSerialMismatch')):
                mismatch_summary = ', '.join(
                    f"{item['type']} {item['count']}/{item['quantity']}"
                    for item in serial_mismatches
                )
                return jsonify({
                    'error': f'Serial number count does not match asset quantity ({mismatch_summary})',
                    'requiresSerialMismatchConfirmation': True,
                    'data': {
                        'quantity': plan['quantity'],
                        'mismatches': serial_mismatches,
                    },
                }), 409
            duplicate_serials = _asset_duplicate_serial_details([
                candidate
                for index, asset_id in enumerate(plan['ids'])
                for candidate in _asset_duplicate_serial_candidates(
                    asset_id,
                    plan['brand'],
                    plan['model'],
                    plan['description'],
                    plan['serials'][index],
                    plan['secondarySerials'][index],
                )
            ]) if not plan['isBulk'] else []
            if duplicate_serials and not _request_bool(data.get('confirmDuplicateSerial')):
                return jsonify({
                    'error': 'One or more primary serial numbers are already in use for this asset type',
                    'requiresDuplicateSerialConfirmation': True,
                    'duplicateSerials': duplicate_serials,
                }), 409
            audit_timestamp = _asset_audit_timestamp()
            audit_user = _asset_audit_user()

            if plan['isBulk']:
                existing_bulk_numbers = []
                for item_id in data_manager.inventory.keys():
                    if str(item_id).startswith('BULK-'):
                        existing_bulk_numbers.append(_safe_int(str(item_id).replace('BULK-', ''), 0))
                created_asset_ids = [f"BULK-{(max(existing_bulk_numbers, default=0) + 1):04d}"]
                asset = InventoryItem(
                    asset_id=created_asset_ids[0],
                    brand=plan['brand'],
                    model_number=plan['model'],
                    version=version,
                    serial_number='',
                    secondary_serial_number='',
                    description=plan['description'],
                    is_missing=False,
                    is_ooc=False,
                    is_untagged=bool(data.get('isUntagged', False)),
                    is_degraded=bool(data.get('isDegraded', False)),
                    is_disposed=bool(data.get('isDisposed', False) or data.get('isDecommissioned', False)),
                    maintenance_logs=[],
                    department_code=plan['department'],
                    default_location=plan['defaultLocation'],
                    current_location='',
                    is_bulk=True,
                    quantity=plan['quantity'],
                    date_of_purchase=purchase_date,
                    notes=notes,
                    tags=tags,
                )
                _mark_asset_created(asset, timestamp=audit_timestamp, user=audit_user)
                data_manager.inventory[created_asset_ids[0]] = asset
            else:
                created_asset_ids = []
                for index, asset_id in enumerate(plan['ids']):
                    asset = InventoryItem(
                        asset_id=asset_id,
                        brand=plan['brand'],
                        model_number=plan['model'],
                        version=version,
                        serial_number=plan['serials'][index],
                        secondary_serial_number=plan['secondarySerials'][index],
                        description=plan['description'],
                        is_missing=False,
                        is_ooc=False,
                        is_untagged=bool(data.get('isUntagged', False)),
                        is_degraded=bool(data.get('isDegraded', False)),
                        is_disposed=bool(data.get('isDisposed', False) or data.get('isDecommissioned', False)),
                        maintenance_logs=[],
                        department_code=plan['department'],
                        default_location=plan['defaultLocation'],
                        current_location='',
                        is_bulk=False,
                        quantity=1,
                        date_of_purchase=purchase_date,
                        notes=notes,
                        tags=tags,
                    )
                    _mark_asset_created(asset, timestamp=audit_timestamp, user=audit_user)
                    data_manager.inventory[asset_id] = asset
                    created_asset_ids.append(asset_id)

            matching_assets_tagged = 0
            for target, before_snapshot in similar_tag_audit_before:
                target.tags = normalize_asset_tags(
                    normalize_asset_tags(getattr(target, 'tags', [])) + tags_to_apply_to_similar
                )
                changes = _asset_audit_changes(
                    before_snapshot,
                    _asset_audit_snapshot(target),
                    fields=('tags',),
                )
                if _append_asset_change_history(
                    target,
                    changes,
                    timestamp=audit_timestamp,
                    user=audit_user,
                    action='updated',
                ):
                    matching_assets_tagged += 1

            data_manager.save_inventory()

        # Auto-register the asset's department if it is new.
        departments = _load_departments()
        dept_code = _normalise_department_code(plan['department']) or 'UN'
        if dept_code not in departments:
            departments[dept_code] = _department_record(dept_code)
            _save_departments(departments)

        # Invalidate cache
        invalidate_cache()

        created_log_assets = [
            data_manager.inventory[created_id]
            for created_id in created_asset_ids
            if created_id in data_manager.inventory
        ]
        created_model = ' '.join(
            value for value in (plan['brand'], plan['model']) if value
        )
        created_detail = (
            f"{created_model or 'Unnamed model'}; department={plan['department']}; "
            f"description={plan['description'] or '-'}"
        )
        if plan['isBulk']:
            created_detail += f"; quantity={plan['quantity']}"
        else:
            serial_count = sum(
                1 for item in created_log_assets
                if str(getattr(item, 'serial_number', '') or '').strip()
            )
            created_detail += f"; serial numbers recorded={serial_count}/{len(created_asset_ids)}"

        if len(created_asset_ids) == 1:
            log_action(
                f"Created asset {created_asset_ids[0]}: {created_detail}",
                system_log_only=True,
            )
            message = 'Asset created successfully'
        else:
            log_action(
                f"Created {len(created_asset_ids)} assets "
                f"{created_asset_ids[0]} to {created_asset_ids[-1]}: {created_detail}",
                system_log_only=True,
            )
            message = f'{len(created_asset_ids)} assets created successfully'

        return jsonify({
            'success': True,
            'message': message,
            'assetId': created_asset_ids[0],
            'assetIds': created_asset_ids,
            'prefix': plan.get('prefix', ''),
            'count': len(created_asset_ids),
            'matchingAssetsTagged': matching_assets_tagged,
        })
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error(f"Error creating asset: {e}", exc_info=True)
        return jsonify({'error': 'Failed to create asset'}), 500


