def _finance_compare_identity_key(identity):
    clean = {
        key: (
            _normalise_department_code(value)
            if key == 'department'
            else re.sub(r'\s+', ' ', str(value or '').strip()).casefold()
        )
        for key, value in (identity or {}).items()
        if key in {
            'kind', 'department', 'brand', 'model', 'description',
            'name', 'type', 'company'
        }
    }
    return hashlib.sha1(
        json.dumps(clean, sort_keys=True, separators=(',', ':')).encode('utf-8')
    ).hexdigest()[:18]


def _finance_compare_model_identity(department='', brand='', model='', description=''):
    return {
        'kind': 'model',
        'department': _normalise_department_code(department) or 'UN',
        'brand': str(brand or '').strip(),
        'model': str(model or '').strip(),
        'description': str(description or '').strip(),
    }


def _finance_compare_custom_identity(asset_type='MISC', name='', department='UN', company=''):
    return {
        'kind': 'custom',
        'type': _normalise_custom_type(asset_type),
        'name': str(name or '').strip(),
        'department': _normalise_department_code(department) or 'UN',
        'company': str(company or '').strip(),
    }


def _finance_compare_department_name(code):
    code = _normalise_department_code(code) or 'UN'
    row = _load_departments().get(code)
    return str((row or {}).get('name') or code)


def _finance_compare_add_item(items, identity, quantity, details=None, line_id=None, ref=None):
    quantity = max(0, _safe_int(round(_safe_float(quantity, 0)), 0))
    if quantity <= 0:
        return
    key = _finance_compare_identity_key(identity)
    row = items.setdefault(key, {
        'key': key,
        'identity': dict(identity),
        'quantity': 0,
        'lineIds': [],
        'refs': [],
        'title': '',
        'subtitle': '',
        'department': '',
        'departmentCode': identity.get('department') or 'UN',
        'uom': 'units',
        'description': '',
    })
    row['quantity'] += quantity
    if line_id and line_id not in row['lineIds']:
        row['lineIds'].append(str(line_id))
    if ref and ref not in row['refs']:
        row['refs'].append(str(ref))
    for field, value in (details or {}).items():
        if value not in (None, '') and not row.get(field):
            row[field] = value


def _finance_compare_item_from_line(line):
    if not isinstance(line, dict) or _finance_line_is_non_prepare_department(line):
        return None
    is_custom_group = bool(line.get('groupId') and line.get('groupCustomText'))
    quantity = max(0, _safe_int(round(
        _safe_float(line.get('quantity'), 0)
        if is_custom_group
        else _finance_group_requirement_quantity(line)
        if line.get('groupId')
        else _safe_float(line.get('quantity'), 0)
    ), 0))
    if quantity <= 0:
        return None
    group = _finance_inventory_group_from_line(line)
    if group:
        identity = _finance_compare_model_identity(
            group.get('department'),
            group.get('brand'),
            group.get('model'),
            group.get('description'),
        )
        title = _finance_display_description(
            group.get('brand'),
            group.get('model'),
            group.get('description'),
        ) or str(line.get('description') or '').strip()
        details = {
            'title': title,
            'subtitle': str(group.get('description') or '').strip(),
            'department': _finance_compare_department_name(group.get('department')),
            'departmentCode': group.get('department') or 'UN',
            'uom': str(line.get('uom') or 'units'),
            'description': str(group.get('description') or line.get('description') or '').strip(),
        }
        return identity, quantity, details
    description = str(
        (line.get('groupTitle') if is_custom_group else line.get('description'))
        or ''
    ).strip()
    if not description:
        return None
    department = _normalise_department_code(line.get('departmentCode')) or 'UN'
    department_name = _finance_compare_department_name(department)
    system_name = _finance_system_name(
        line.get('department'), line.get('systemName')
    )
    default_system_name = _finance_system_name(line.get('department'))
    generic_department = department in {'UN', 'GENERAL'}
    if (
        generic_department
        and system_name
        and system_name.casefold() != default_system_name.casefold()
    ):
        department = _normalise_department_code(system_name) or department
        department_name = system_name
    identity = _finance_compare_custom_identity(
        line.get('customType') or 'MISC',
        description,
        department,
        line.get('customCompany') or '',
    )
    return identity, quantity, {
        'title': description,
        'subtitle': 'Custom item',
        'department': department_name,
        'departmentCode': department,
        'uom': str(line.get('uom') or 'units'),
        'description': description,
    }


_FINANCE_COMPARE_ALL_SUBPROJECTS = object()


def _finance_compare_quote_items(
    document,
    subproject_id=_FINANCE_COMPARE_ALL_SUBPROJECTS,
):
    items = {}
    if subproject_id is None:
        return items
    custom_groups = set()
    for line in (document or {}).get('lineItems') or []:
        if (
            subproject_id is not _FINANCE_COMPARE_ALL_SUBPROJECTS
            and str(line.get('subprojectId') or 'main') != str(subproject_id)
        ):
            continue
        custom_group_key = (
            str(line.get('subprojectId') or 'main'),
            str(line.get('groupId') or ''),
        ) if line.get('groupCustomText') and line.get('groupId') else None
        if custom_group_key and custom_group_key in custom_groups:
            continue
        if custom_group_key:
            custom_groups.add(custom_group_key)
        parsed = _finance_compare_item_from_line(line)
        if not parsed:
            continue
        identity, quantity, details = parsed
        _finance_compare_add_item(
            items,
            identity,
            quantity,
            details,
            line_id=(line or {}).get('id'),
        )
    return items


def _finance_compare_item_from_event_ref(ref):
    marker = _parse_model_marker(ref)
    if marker:
        identity = _finance_compare_model_identity(
            marker.get('department'),
            marker.get('brand'),
            marker.get('model'),
            marker.get('description'),
        )
        description = str(marker.get('description') or '').strip()
        return identity, max(1, _safe_int(marker.get('quantity'), 1)), {
            'title': _finance_display_description(marker.get('brand'), marker.get('model'), description),
            'subtitle': description,
            'department': _finance_compare_department_name(marker.get('department')),
            'departmentCode': marker.get('department') or 'UN',
            'uom': 'units',
            'description': description,
        }
    custom = _parse_custom_marker(ref)
    if custom:
        identity = _finance_compare_custom_identity(
            custom.get('type'),
            custom.get('name'),
            custom.get('department'),
            custom.get('company'),
        )
        return identity, max(1, _safe_int(custom.get('quantity'), 1)), {
            'title': str(custom.get('name') or '').strip(),
            'subtitle': str(custom.get('company') or custom.get('type') or 'Custom item'),
            'department': _finance_compare_department_name(custom.get('department')),
            'departmentCode': custom.get('department') or 'UN',
            'uom': 'units',
            'description': str(custom.get('name') or '').strip(),
        }
    bulk = _parse_bulk_marker(ref)
    if bulk:
        asset = data_manager.inventory.get(bulk.get('bulkId')) if data_manager else None
        quantity = max(1, _safe_int(bulk.get('quantity'), 1))
    else:
        asset = data_manager.inventory.get(str(ref or '')) if data_manager else None
        quantity = 1
    if not asset:
        return None
    group = _asset_group_from_item(asset)
    identity = _finance_compare_model_identity(
        group.get('department'),
        group.get('brand'),
        group.get('model'),
        group.get('description'),
    )
    return identity, quantity, {
        'title': _finance_display_description(group.get('brand'), group.get('model'), group.get('description')),
        'subtitle': str(group.get('description') or '').strip(),
        'department': _finance_compare_department_name(group.get('department')),
        'departmentCode': group.get('department') or 'UN',
        'uom': 'units',
        'description': str(group.get('description') or '').strip(),
    }


def _finance_compare_main_subproject(event, create=False):
    """Return the event's Main Room, creating it from legacy requirements if needed."""
    subprojects = [
        row for row in (getattr(event, 'subprojects', []) or [])
        if isinstance(row, dict)
    ]
    main = next((
        row for row in subprojects
        if str(row.get('id') or '').strip().casefold() == 'main'
    ), None)
    if not main:
        main = next((
            row for row in subprojects
            if str(row.get('name') or '').strip().casefold() == 'main room'
        ), None)
    if not main and subprojects:
        main = subprojects[0]
    if main or not create:
        if main:
            main.setdefault('items', [])
        return main

    main = {
        'id': 'main',
        'name': 'Main Room',
        'items': _event_initial_subproject_items(event),
    }
    _event_allocate_existing_refs_to_initial_subproject(event, main)
    event.subprojects = [main]
    return main


def _finance_compare_item_from_subproject_item(item):
    if not isinstance(item, dict):
        return None
    quantity = max(0, _safe_int(round(_safe_float(item.get('quantity'), 0)), 0))
    if quantity <= 0:
        return None

    group = _event_subproject_item_group(item)
    if group:
        identity = _finance_compare_model_identity(
            group.get('department'),
            group.get('brand'),
            group.get('model'),
            group.get('description'),
        )
        description = str(group.get('description') or '').strip()
        return identity, quantity, {
            'title': _finance_display_description(
                group.get('brand'), group.get('model'), description
            ),
            'subtitle': description,
            'department': _finance_compare_department_name(group.get('department')),
            'departmentCode': group.get('department') or 'UN',
            'uom': str(item.get('uom') or 'units'),
            'description': description,
        }

    if not item.get('isCustom'):
        return None
    custom = next((
        parsed for parsed in (
            _parse_custom_marker(ref) for ref in (item.get('assetRefs') or [])
        )
        if parsed
    ), None)
    department = _normalise_department_code(
        item.get('departmentCode') or item.get('department')
    ) or (custom or {}).get('department') or 'UN'
    name = str(item.get('description') or (custom or {}).get('name') or '').strip()
    if not name:
        return None
    asset_type = (
        (custom or {}).get('type')
        or item.get('customType')
        or item.get('type')
        or 'MISC'
    )
    company = str(
        (custom or {}).get('company')
        or item.get('company')
        or item.get('customCompany')
        or ''
    ).strip()
    identity = _finance_compare_custom_identity(
        asset_type, name, department, company
    )
    return identity, quantity, {
        'title': name,
        'subtitle': company or _normalise_custom_type(asset_type),
        'department': _finance_compare_department_name(department),
        'departmentCode': department,
        'uom': str(item.get('uom') or 'units'),
        'description': str(item.get('customDescription') or name).strip(),
    }


def _finance_compare_event_items(
    event,
    subproject_id=_FINANCE_COMPARE_ALL_SUBPROJECTS,
):
    items = {}
    if subproject_id is None:
        return items
    subprojects = [
        row for row in (getattr(event, 'subprojects', []) or [])
        if isinstance(row, dict)
    ]
    if subprojects:
        for subproject in subprojects:
            if (
                subproject_id is not _FINANCE_COMPARE_ALL_SUBPROJECTS
                and str(subproject.get('id') or '') != str(subproject_id)
            ):
                continue
            for item in subproject.get('items') or []:
                parsed = _finance_compare_item_from_subproject_item(item)
                if not parsed:
                    continue
                identity, quantity, details = parsed
                _finance_compare_add_item(
                    items,
                    identity,
                    quantity,
                    details,
                    line_id=(item or {}).get('lineId'),
                )
        return items

    if subproject_id not in (_FINANCE_COMPARE_ALL_SUBPROJECTS, 'main'):
        return items
    for ref in getattr(event, 'prepared_items', []) or []:
        parsed = _finance_compare_item_from_event_ref(ref)
        if not parsed:
            continue
        identity, quantity, details = parsed
        _finance_compare_add_item(items, identity, quantity, details, ref=ref)
    return items


def _finance_compare_display_item(item):
    if not item:
        return {
            'key': '',
            'title': 'Not included',
            'subtitle': '',
            'department': '',
            'departmentCode': '',
            'quantity': 0,
            'uom': '',
            'identity': {},
            'lineIds': [],
            'refs': [],
        }
    return {
        'key': item.get('key') or _finance_compare_identity_key(item.get('identity') or {}),
        'title': item.get('title') or item.get('description') or 'Untitled item',
        'subtitle': item.get('subtitle') or '',
        'department': item.get('department') or _finance_compare_department_name(item.get('departmentCode')),
        'departmentCode': item.get('departmentCode') or (item.get('identity') or {}).get('department') or 'UN',
        'quantity': max(0, _safe_int(item.get('quantity'), 0)),
        'uom': item.get('uom') or 'units',
        'identity': item.get('identity') or {},
        'lineIds': item.get('lineIds') or [],
        'refs': item.get('refs') or [],
        'description': item.get('description') or '',
    }


def _finance_compare_rows(
    event,
    quotation,
    quote_subproject_id=_FINANCE_COMPARE_ALL_SUBPROJECTS,
    event_subproject_id=_FINANCE_COMPARE_ALL_SUBPROJECTS,
):
    quote_items = _finance_compare_quote_items(quotation, quote_subproject_id)
    event_items = _finance_compare_event_items(event, event_subproject_id)
    rows = []
    counts = {
        'matched': 0,
        'missingInEvent': 0,
        'extraInEvent': 0,
        'qtyMismatch': 0,
    }
    for key in sorted(set(quote_items) | set(event_items), key=lambda value: (
        (quote_items.get(value) or event_items.get(value) or {}).get('departmentCode', ''),
        (quote_items.get(value) or event_items.get(value) or {}).get('title', ''),
    )):
        quote_item = _finance_compare_display_item(quote_items.get(key))
        event_item = _finance_compare_display_item(event_items.get(key))
        quote_qty = quote_item.get('quantity') or 0
        event_qty = event_item.get('quantity') or 0
        if quote_qty and event_qty and quote_qty == event_qty:
            status = 'matched'
            counts['matched'] += 1
        elif quote_qty and not event_qty:
            status = 'missing_in_event'
            counts['missingInEvent'] += 1
        elif event_qty and not quote_qty:
            status = 'extra_in_event'
            counts['extraInEvent'] += 1
        else:
            status = 'qty_mismatch'
            counts['qtyMismatch'] += 1
        rows.append({
            'key': key,
            'status': status,
            'quotationItem': quote_item,
            'eventItem': event_item,
            'quantityDelta': event_qty - quote_qty,
        })
    return rows, counts, quote_items, event_items


def _finance_compare_subproject_rows(event, quotation):
    """Pair quotation projects with event rooms without dropping one-sided rooms."""
    quote_subprojects = [
        {
            'id': str(row.get('id') or 'main'),
            'name': str(row.get('name') or 'Room').strip() or 'Room',
        }
        for row in (quotation or {}).get('subprojects') or []
        if isinstance(row, dict)
    ]
    if quotation and not quote_subprojects:
        quote_subprojects = [{'id': 'main', 'name': 'Main Room'}]

    event_subprojects = [
        {
            'id': str(row.get('id') or 'main'),
            'name': str(row.get('name') or 'Room').strip() or 'Room',
        }
        for row in (getattr(event, 'subprojects', []) or [])
        if isinstance(row, dict)
    ]
    if not event_subprojects:
        event_subprojects = [{'id': 'main', 'name': 'Main Room'}]

    unmatched_event_ids = {row['id'] for row in event_subprojects}
    event_by_id = {row['id']: row for row in event_subprojects}
    result = []
    for quote_row in quote_subprojects:
        event_row = event_by_id.get(quote_row['id'])
        if not event_row:
            quote_name = quote_row['name'].casefold()
            event_row = next((
                row for row in event_subprojects
                if row['id'] in unmatched_event_ids
                and row['name'].casefold() == quote_name
            ), None)
        if event_row:
            unmatched_event_ids.discard(event_row['id'])
        result.append({
            'quoteSubprojectId': quote_row['id'],
            'eventSubprojectId': event_row['id'] if event_row else None,
            'quoteName': quote_row['name'],
            'eventName': event_row['name'] if event_row else '',
            'scope': 'paired' if event_row else 'quotation_only',
        })

    for event_row in event_subprojects:
        if event_row['id'] not in unmatched_event_ids:
            continue
        result.append({
            'quoteSubprojectId': None,
            'eventSubprojectId': event_row['id'],
            'quoteName': '',
            'eventName': event_row['name'],
            'scope': 'event_only',
        })

    for row in result:
        raw_id = '|'.join((
            row.get('quoteSubprojectId') or '',
            row.get('eventSubprojectId') or '',
        ))
        row['id'] = 'room_' + hashlib.sha1(raw_id.encode('utf-8')).hexdigest()[:12]
        quote_name = row.get('quoteName') or ''
        event_name = row.get('eventName') or ''
        row['name'] = (
            quote_name
            if quote_name and quote_name == event_name
            else ' / '.join(value for value in (quote_name, event_name) if value)
        ) or 'Room'
        rows, counts, quote_items, event_items = _finance_compare_rows(
            event,
            quotation or {},
            row.get('quoteSubprojectId'),
            row.get('eventSubprojectId'),
        )
        row['rows'] = rows
        row['counts'] = {
            **counts,
            'quotationItems': len(quote_items),
            'eventItems': len(event_items),
        }
    return result


def _finance_compare_subproject_scope(event, quotation, view_id):
    clean_view_id = str(view_id or '').strip()
    if not clean_view_id or clean_view_id == 'all':
        return None
    return next((
        row for row in _finance_compare_subproject_rows(event, quotation)
        if row.get('id') == clean_view_id
    ), None)


def _finance_compare_ensure_event_subproject(event, scope):
    """Return the event room for a quotation-room comparison, creating it if absent."""
    if not scope or not scope.get('quoteSubprojectId'):
        return scope.get('eventSubprojectId') if scope else None

    event_subproject_id = str(scope.get('eventSubprojectId') or '').strip()
    if event_subproject_id and _event_subproject(event, event_subproject_id):
        return event_subproject_id

    quotation_subproject_id = str(scope.get('quoteSubprojectId') or '').strip()
    if not quotation_subproject_id:
        return None

    # Materialise the event's legacy Main Room before adding another room so
    # existing requirements retain their current room assignment.
    _finance_compare_main_subproject(event, create=True)
    if _event_subproject(event, quotation_subproject_id):
        return quotation_subproject_id

    room_name = str(scope.get('quoteName') or 'Room').strip() or 'Room'
    event.subprojects.append({
        'id': quotation_subproject_id,
        'name': room_name,
        'items': [],
    })
    return quotation_subproject_id


def _finance_compare_can_read_quotation(document, event_id):
    if not document or document.get('type') != 'quotation':
        return False
    if _safe_int(document.get('eventId'), 0) != int(event_id):
        return False
    return _current_user_effective_is_admin() or _finance_user_can_access(document)


def _finance_compare_quotations_for_event(finance_data, event_id):
    rows = []
    for document in finance_data.get('documents') or []:
        if _finance_compare_can_read_quotation(document, event_id):
            normalised = _normalise_finance_document(document, 'quotation', document)
            rows.append({
                'id': normalised.get('id'),
                'number': normalised.get('number'),
                'projectName': normalised.get('projectName'),
                'client': normalised.get('client') or {},
                'updatedAt': normalised.get('updatedAt'),
            })
    rows.sort(key=lambda row: (row.get('updatedAt', ''), row.get('number', '')), reverse=True)
    return rows


def _finance_compare_payload(event, finance_data, quotation_id=''):
    quotation = None
    if quotation_id:
        candidate = _finance_find_document(finance_data, quotation_id, 'quotation')
        if candidate and _finance_compare_can_read_quotation(candidate, event.event_id):
            quotation = _normalise_finance_document(candidate, 'quotation', candidate)
    if quotation is None:
        candidates = [
            row for row in finance_data.get('documents') or []
            if _finance_compare_can_read_quotation(row, event.event_id)
        ]
        candidates.sort(key=lambda row: (row.get('updatedAt', ''), row.get('number', '')), reverse=True)
        if candidates:
            quotation = _normalise_finance_document(candidates[0], 'quotation', candidates[0])
    rows, counts, quote_items, event_items = _finance_compare_rows(event, quotation or {})
    subproject_views = _finance_compare_subproject_rows(event, quotation or {})
    return {
        'event': _finance_event_brief(event),
        'quotation': ({
            'id': quotation.get('id'),
            'number': quotation.get('number'),
            'projectName': quotation.get('projectName'),
            'client': quotation.get('client') or {},
        } if quotation else None),
        'quotations': _finance_compare_quotations_for_event(finance_data, event.event_id),
        'rows': rows,
        'subprojectViews': subproject_views,
        'counts': {
            **counts,
            'quotationItems': len(quote_items),
            'eventItems': len(event_items),
        },
        'permissions': {
            'canEditEvent': _current_user_effective_is_admin(),
            'canEditQuotation': bool(quotation and _current_user_has_sales_access() and _finance_user_can_access(quotation)),
        },
    }


def _finance_compare_ref_matches_identity(ref, identity):
    parsed = _finance_compare_item_from_event_ref(ref)
    if not parsed:
        return False
    ref_identity, _quantity, _details = parsed
    return _finance_compare_identity_key(ref_identity) == _finance_compare_identity_key(identity)


def _finance_compare_set_event_quantity(
    event,
    identity,
    target_quantity,
    display_item=None,
    target_subproject_id=None,
):
    target_quantity = max(0, _safe_int(round(_safe_float(target_quantity, 0)), 0))
    _ensure_event_custom_lists(event)
    kind = (identity or {}).get('kind')
    all_subprojects = [
        row for row in (getattr(event, 'subprojects', []) or [])
        if isinstance(row, dict)
    ]
    target_subproject = (
        _event_subproject(event, target_subproject_id)
        if target_subproject_id
        else None
    )
    subprojects = [target_subproject] if target_subproject else all_subprojects
    if subprojects:
        identity_key = _finance_compare_identity_key(identity)
        matching_by_room = []
        for subproject in subprojects:
            matches = []
            for item in subproject.get('items') or []:
                parsed = _finance_compare_item_from_subproject_item(item)
                if parsed and _finance_compare_identity_key(parsed[0]) == identity_key:
                    matches.append(item)
            matching_by_room.append((subproject, matches))

        current_quantity = sum(
            max(0, _safe_int(item.get('quantity'), 0))
            for _subproject, matches in matching_by_room
            for item in matches
        )
        main = target_subproject or _finance_compare_main_subproject(event, create=True)
        if kind != 'custom':
            group = {
                'department': identity.get('department') or 'UN',
                'brand': identity.get('brand') or '',
                'model': identity.get('model') or '',
                'description': (
                    identity.get('description')
                    or (display_item or {}).get('description')
                    or (display_item or {}).get('subtitle')
                    or ''
                ),
            }
            if target_quantity >= current_quantity:
                main_quantity = _event_subproject_required_quantity(main, group)
                _event_subproject_set_group_quantity(
                    main,
                    group,
                    main_quantity + target_quantity - current_quantity,
                )
            else:
                remaining = current_quantity - target_quantity
                ordered_rooms = [main] + [
                    row for row in reversed(subprojects) if row is not main
                ]
                for subproject in ordered_rooms:
                    if remaining <= 0:
                        break
                    room_quantity = _event_subproject_required_quantity(subproject, group)
                    reduction = min(room_quantity, remaining)
                    if reduction:
                        _event_subproject_set_group_quantity(
                            subproject, group, room_quantity - reduction
                        )
                        remaining -= reduction
            _sync_event_model_markers_from_subprojects(event)
            _reconcile_event_subproject_extras(event)
            return

        # Custom markers are the unit of preparation/collection. Rebuild the
        # affected planned markers so the room quantities and legacy totals agree.
        matching_refs = (
            {
                ref
                for _subproject, matches in matching_by_room
                for item in matches
                for ref in (item.get('assetRefs') or [])
                if _finance_compare_ref_matches_identity(ref, identity)
            }
            if target_subproject
            else {
                ref for ref in list(event.prepared_items or [])
                if _finance_compare_ref_matches_identity(ref, identity)
            }
        )
        for values in (
            event.prepared_items,
            event.actually_prepared,
            event.returned_items,
            event.extra_assets,
            event.custom_collected,
        ):
            values[:] = [ref for ref in values if ref not in matching_refs]
        for _subproject, matches in matching_by_room:
            for item in matches:
                item['assetRefs'] = [
                    ref for ref in (item.get('assetRefs') or [])
                    if ref not in matching_refs
                ]

        if target_quantity >= current_quantity:
            if not matching_by_room or not any(matches for _room, matches in matching_by_room):
                main.setdefault('items', []).append({
                    'lineId': f"compare_{secrets.token_hex(8)}",
                    'department': identity.get('department') or 'UN',
                    'departmentCode': identity.get('department') or 'UN',
                    'brand': '',
                    'model': '',
                    'description': identity.get('name') or (display_item or {}).get('title') or 'Custom item',
                    'customType': identity.get('type') or 'MISC',
                    'company': identity.get('company') or '',
                    'quantity': target_quantity,
                    'isCustom': True,
                    'assetRefs': [],
                })
                matching_by_room = [(main, [main['items'][-1]])]
            else:
                first_item = next(
                    item for _room, matches in matching_by_room for item in matches
                )
                first_item['quantity'] = max(
                    0, _safe_int(first_item.get('quantity'), 0)
                ) + target_quantity - current_quantity
        else:
            remaining = current_quantity - target_quantity
            ordered_rooms = [main] + [
                row for row in reversed(subprojects) if row is not main
            ]
            for subproject in ordered_rooms:
                if remaining <= 0:
                    break
                for item in next((
                    matches for room, matches in matching_by_room
                    if room is subproject
                ), []):
                    item_quantity = max(0, _safe_int(item.get('quantity'), 0))
                    reduction = min(item_quantity, remaining)
                    item['quantity'] = item_quantity - reduction
                    remaining -= reduction
                    if remaining <= 0:
                        break

        for subproject, matches in matching_by_room:
            retained_items = []
            for item in subproject.get('items') or []:
                if item not in matches:
                    retained_items.append(item)
                    continue
                item_quantity = max(0, _safe_int(item.get('quantity'), 0))
                if item_quantity <= 0:
                    continue
                marker = _make_custom_marker(
                    identity.get('type') or 'MISC',
                    identity.get('name') or item.get('description') or 'Custom item',
                    item_quantity,
                    identity.get('department') or 'UN',
                    identity.get('company') or '',
                    description=item.get('customDescription') or '',
                )
                item['assetRefs'] = [marker]
                event.prepared_items.append(marker)
                retained_items.append(item)
            subproject['items'] = retained_items
        _reconcile_event_subproject_extras(event)
        return

    if kind == 'custom':
        matching_refs = {
            ref for ref in list(event.prepared_items or [])
            if _finance_compare_ref_matches_identity(ref, identity)
        }
        event.prepared_items = [
            ref for ref in event.prepared_items
            if ref not in matching_refs
        ]
        event.actually_prepared = [
            ref for ref in event.actually_prepared
            if ref not in matching_refs
        ]
        event.returned_items = [
            ref for ref in event.returned_items
            if ref not in matching_refs
        ]
        event.extra_assets = [
            ref for ref in event.extra_assets
            if ref not in matching_refs
        ]
        event.custom_collected = [
            ref for ref in event.custom_collected
            if ref not in matching_refs
        ]
        if target_quantity > 0:
            event.prepared_items.append(_make_custom_marker(
                identity.get('type') or 'MISC',
                identity.get('name') or (display_item or {}).get('title') or 'Custom item',
                target_quantity,
                identity.get('department') or 'UN',
                identity.get('company') or '',
            ))
        return

    matching_physical_refs = set()
    for ref in list(event.prepared_items or []):
        if _finance_compare_ref_matches_identity(ref, identity):
            matching_physical_refs.add(ref)
    for ref in list(event.extra_assets or []):
        if _finance_compare_ref_matches_identity(ref, identity):
            matching_physical_refs.add(ref)
    event.prepared_items = [
        ref for ref in event.prepared_items
        if ref not in matching_physical_refs
    ]
    if target_quantity > 0:
        group = {
            'department': identity.get('department') or 'UN',
            'brand': identity.get('brand') or '',
            'model': identity.get('model') or '',
            'description': (display_item or {}).get('description') or (display_item or {}).get('subtitle') or '',
        }
        event.prepared_items.append(_make_model_marker(group, target_quantity))
    if target_quantity == 0:
        event.actually_prepared = [
            ref for ref in event.actually_prepared
            if ref not in matching_physical_refs
        ]
        event.returned_items = [
            ref for ref in event.returned_items
            if ref not in matching_physical_refs
        ]
        event.extra_assets = [
            ref for ref in event.extra_assets
            if ref not in matching_physical_refs
        ]


def _finance_compare_add_to_event(event, row, target_subproject_id=None):
    quote_item = row.get('quotationItem') or {}
    event_item = row.get('eventItem') or {}
    quote_qty = max(0, _safe_int(quote_item.get('quantity'), 0))
    event_qty = max(0, _safe_int(event_item.get('quantity'), 0))
    if quote_qty <= event_qty:
        raise ValueError('This item is already covered in the event')
    identity = quote_item.get('identity') or {}
    if not identity:
        raise ValueError('Quotation item cannot be added to the event')
    quantity_to_add = quote_qty - event_qty
    main = _finance_compare_main_subproject(event, create=True)
    target_subproject = (
        _event_subproject(event, target_subproject_id)
        if target_subproject_id
        else None
    ) or main
    if identity.get('kind') == 'custom':
        marker = _make_custom_marker(
            identity.get('type') or 'MISC',
            identity.get('name') or quote_item.get('title') or 'Custom item',
            quantity_to_add,
            identity.get('department') or quote_item.get('departmentCode') or 'UN',
            identity.get('company') or '',
            description=quote_item.get('description') or '',
        )
        event.prepared_items.append(marker)
        identity_key = _finance_compare_identity_key(identity)
        matching_item = next((
            item for item in target_subproject.get('items') or []
            if (
                (parsed := _finance_compare_item_from_subproject_item(item))
                and _finance_compare_identity_key(parsed[0]) == identity_key
            )
        ), None)
        if matching_item:
            matching_item['quantity'] = (
                max(0, _safe_int(matching_item.get('quantity'), 0))
                + quantity_to_add
            )
            matching_item.setdefault('assetRefs', []).append(marker)
        else:
            department = (
                identity.get('department')
                or quote_item.get('departmentCode')
                or 'UN'
            )
            target_subproject.setdefault('items', []).append({
                'lineId': f"compare_{secrets.token_hex(8)}",
                'department': department,
                'departmentCode': department,
                'brand': '',
                'model': '',
                'description': identity.get('name') or quote_item.get('title') or 'Custom item',
                'customDescription': quote_item.get('description') or '',
                'customType': identity.get('type') or 'MISC',
                'company': identity.get('company') or '',
                'quantity': quantity_to_add,
                'isCustom': True,
                'assetRefs': [marker],
            })
    else:
        group = {
            'department': identity.get('department') or quote_item.get('departmentCode') or 'UN',
            'brand': identity.get('brand') or '',
            'model': identity.get('model') or '',
            'description': quote_item.get('description') or quote_item.get('subtitle') or '',
        }
        current_main_quantity = _event_subproject_required_quantity(
            target_subproject, group
        )
        _event_subproject_set_group_quantity(
            target_subproject,
            group,
            current_main_quantity + quantity_to_add,
        )
        _sync_event_model_markers_from_subprojects(event)
    _reconcile_event_subproject_extras(event)


def _finance_compare_line_from_event_item(event_item, quantity, event, finance_data=None):
    identity = event_item.get('identity') or {}
    department_name, department_code = _finance_department_details(
        event_item.get('departmentCode') or identity.get('department') or 'UN',
        event_item.get('departmentCode') or identity.get('department') or 'UN',
    )
    days = _finance_date_days(
        _event_date_for_input(getattr(event, 'start_date', '')),
        _event_date_for_input(getattr(event, 'end_date', '')),
    )
    raw_description = event_item.get('description') or event_item.get('title') or 'Event item'
    description = str(raw_description).strip()
    remembered = {}
    if identity.get('kind') == 'custom':
        for document in reversed((finance_data or {}).get('documents') or []):
            remembered = next((
                line for line in reversed(document.get('lineItems') or [])
                if str(line.get('description') or '').strip().casefold() == description.casefold()
                and _safe_float(line.get('unitPrice'), 0) > 0
            ), {})
            if remembered:
                break
        return _normalise_finance_line({
            'id': secrets.token_hex(6),
            'catalogKey': '',
            'description': description,
            'department': department_name,
            'departmentCode': department_code,
            'days': days,
            'quantity': quantity,
            'uom': event_item.get('uom') or 'units',
            'unitPrice': _safe_float(remembered.get('unitPrice'), 0),
            'discountPercent': 0,
            'isCustom': True,
            'customType': identity.get('type') or 'MISC',
            'customCompany': identity.get('company') or '',
        })
    brand = identity.get('brand') or ''
    model = identity.get('model') or ''
    description = _finance_display_description(brand, model, description)
    catalog_key = _finance_catalog_key(department_code, brand, model, description)
    remembered = _finance_remembered_price(
        (finance_data or {}).get('priceBook') or {},
        catalog_key,
        event_item.get('sourceAssetIds') or [],
    )
    return _normalise_finance_line({
        'id': secrets.token_hex(6),
        'catalogKey': catalog_key,
        'sourceAssetIds': [],
        'brand': brand,
        'model': model,
        'description': description,
        'department': department_name,
        'departmentCode': department_code,
        'days': days,
        'quantity': quantity,
        'uom': 'units',
        'unitPrice': _safe_float(remembered.get('unitPrice'), 0),
        'discountPercent': 0,
        'isCustom': False,
    })


def _finance_category_for_department(document, department, department_code, subproject_id):
    identity = _finance_department_identity(department, department_code)
    for line in (document or {}).get('lineItems') or []:
        if str(line.get('subprojectId') or 'main') != str(subproject_id or 'main'):
            continue
        if _finance_department_identity(
            line.get('department'), line.get('departmentCode')
        ) == identity:
            return _finance_system_name(
                line.get('department'), line.get('systemName')
            )
    return ''


def _finance_compare_apply_to_quotation(
    finance_data,
    quotation,
    event,
    row,
    target_subproject_id=None,
):
    event_item = row.get('eventItem') or {}
    quote_item = row.get('quotationItem') or {}
    event_qty = max(0, _safe_int(event_item.get('quantity'), 0))
    quote_qty = max(0, _safe_int(quote_item.get('quantity'), 0))
    delta = event_qty - quote_qty
    if delta <= 0:
        raise ValueError('The quotation already covers this item')
    line_ids = quote_item.get('lineIds') or []
    if line_ids:
        target_line_id = str(line_ids[0])
        for line in quotation.get('lineItems') or []:
            if str(line.get('id')) == target_line_id:
                if line.get('groupId'):
                    package_quantity = max(
                        0, _safe_float(line.get('quantity'), 0)
                    )
                    child_delta = (
                        delta / package_quantity if package_quantity else 0
                    )
                    if package_quantity and abs(child_delta - round(child_delta)) < 0.0001:
                        line['groupItemQuantity'] = round(
                            max(0, _safe_float(
                                line.get('groupItemQuantity'), 0
                            )) + child_delta,
                            4,
                        )
                    else:
                        new_line = _finance_compare_line_from_event_item(
                            event_item, delta, event, finance_data
                        )
                        new_line['subprojectId'] = str(
                            line.get('subprojectId')
                            or target_subproject_id
                            or 'main'
                        )
                        new_line['systemName'] = _finance_system_name(
                            line.get('department'), line.get('systemName')
                        )
                        quotation.setdefault('lineItems', []).append(new_line)
                        return
                else:
                    line['quantity'] = round(
                        _safe_float(line.get('quantity'), 0) + delta, 4
                    )
                identity = event_item.get('identity') or {}
                if identity.get('kind') == 'model':
                    brand = str(identity.get('brand') or '').strip()
                    model = str(identity.get('model') or '').strip()
                    raw_description = str(
                        event_item.get('description')
                        or event_item.get('subtitle')
                        or line.get('description')
                        or ''
                    ).strip()
                    description = _finance_display_description(
                        brand, model, raw_description
                    )
                    department_code = _normalise_department_code(
                        event_item.get('departmentCode')
                        or identity.get('department')
                        or line.get('departmentCode')
                    ) or 'UN'
                    department_name, department_code = _finance_department_details(
                        event_item.get('department') or department_code,
                        department_code,
                    )
                    line.update({
                        'brand': brand,
                        'model': model,
                        'description': description,
                        'department': department_name,
                        'departmentCode': department_code,
                        'catalogKey': _finance_catalog_key(
                            department_code, brand, model, description
                        ),
                        'isCustom': False,
                    })
                break
    else:
        new_line = _finance_compare_line_from_event_item(
            event_item, delta, event, finance_data
        )
        new_line['subprojectId'] = str(target_subproject_id or 'main')
        inherited_category = _finance_category_for_department(
            quotation,
            new_line.get('department'),
            new_line.get('departmentCode'),
            new_line['subprojectId'],
        )
        if inherited_category:
            new_line['systemName'] = inherited_category
        quotation.setdefault('lineItems', []).append(new_line)


def _finance_revision_list_summary(revision):
    revision = revision if isinstance(revision, dict) else {}
    snapshot = revision.get('snapshot')
    if not isinstance(snapshot, dict):
        return None
    return {
        'revision': max(
            1,
            _safe_int(revision.get('revision'), _safe_int(snapshot.get('revision'), 1)),
        ),
        'number': str(revision.get('number') or snapshot.get('number') or ''),
        'status': _finance_revision_status(revision),
        'sentAt': str(revision.get('sentAt') or snapshot.get('sentAt') or ''),
        'acceptedAt': str(
            revision.get('acceptedAt') or snapshot.get('acceptedAt') or ''
        ),
        'validUntil': str(
            revision.get('validUntil') or snapshot.get('validUntil') or ''
        ),
        'validityDays': max(
            0,
            _safe_int(
                revision.get('validityDays'),
                _safe_int(snapshot.get('validityDays'), 0),
            ),
        ),
        # The list only needs to know that an archived snapshot exists.
        'snapshot': True,
    }


def _finance_document_list_summary(document):
    document = document if isinstance(document, dict) else {}
    schedule_dates = [
        document.get('setupDate'),
        document.get('rehearsalDate'),
        document.get('showDate'),
        document.get('teardownDate'),
        *[
            row.get('date')
            for key in (
                'additionalSetups',
                'additionalRehearsals',
                'additionalShows',
                'additionalTeardowns',
            )
            for row in document.get(key) or []
            if isinstance(row, dict)
        ],
        *[
            row.get('date')
            for group in document.get('customScheduleGroups') or []
            if isinstance(group, dict)
            for row in group.get('dates') or []
            if isinstance(row, dict)
        ],
    ]
    start_date, end_date = (
        _finance_event_date_range(document)
        if any(schedule_dates)
        else ('', '')
    )
    stored_totals = document.get('totals')
    totals = (
        dict(stored_totals)
        if isinstance(stored_totals, dict) and 'total' in stored_totals
        else _finance_totals(document)
    )
    revisions = [
        summary
        for summary in (
            _finance_revision_list_summary(row)
            for row in document.get('revisions') or []
        )
        if summary
    ]
    created_by = str(document.get('createdBy') or '')
    salesperson_username = str(document.get('salespersonUsername') or '')
    salesperson = (
        _user_display_name(salesperson_username)
        if salesperson_username
        else str(document.get('salesperson') or '')
    )
    return {
        'id': str(document.get('id') or ''),
        'type': str(document.get('type') or 'quotation'),
        'number': str(document.get('number') or ''),
        'revision': max(1, _safe_int(document.get('revision'), 1)),
        'status': str(document.get('status') or 'draft'),
        'client': _normalise_finance_client(document.get('client')),
        'projectName': str(
            document.get('projectName') or document.get('title') or ''
        ),
        'title': str(document.get('title') or document.get('projectName') or ''),
        'reference': str(document.get('reference') or ''),
        'salesperson': salesperson,
        'salespersonUsername': salesperson_username,
        'createdBy': created_by,
        'createdByName': _user_display_name(created_by) if created_by else '',
        'createdAt': str(document.get('createdAt') or ''),
        'updatedAt': str(document.get('updatedAt') or ''),
        'documentVersion': max(1, _safe_int(document.get('documentVersion'), 1)),
        'sentAt': str(document.get('sentAt') or ''),
        'acceptedAt': str(document.get('acceptedAt') or ''),
        'invoicedAt': str(document.get('invoicedAt') or ''),
        'invoiceSentDate': str(document.get('invoiceSentDate') or ''),
        'paymentDueDate': _finance_invoice_due_date(document),
        'paymentTerms': str(document.get('paymentTerms') or ''),
        'paymentTermDays': max(
            0, min(3650, _safe_int(document.get('paymentTermDays'), 30))
        ),
        'invoiceDate': str(document.get('invoiceDate') or ''),
        'dueDate': str(document.get('dueDate') or ''),
        'invoiceLabel': str(document.get('invoiceLabel') or ''),
        'invoiceAmount': round(max(0, _safe_float(
            document.get('invoiceAmount'), totals.get('total', 0)
        )), 2),
        'sourceQuotationId': str(document.get('sourceQuotationId') or ''),
        'sourceQuotationNumber': str(
            document.get('sourceQuotationNumber') or ''
        ),
        'invoicePlanPayments': [
            copy.deepcopy(row)
            for row in document.get('invoicePlanPayments') or []
            if isinstance(row, dict)
        ],
        'paidAt': str(document.get('paidAt') or ''),
        'statusChangedAt': str(document.get('statusChangedAt') or ''),
        'validUntil': str(document.get('validUntil') or ''),
        'validityDays': max(1, _safe_int(document.get('validityDays'), 30)),
        'eventId': _safe_int(document.get('eventId'), 0) or None,
        'eventStartDate': start_date,
        'eventEndDate': end_date,
        'totals': totals,
        'revisions': revisions,
    }


def _finance_list_search_text(document, linked_invoice=None):
    document = document if isinstance(document, dict) else {}
    client = document.get('client') if isinstance(document.get('client'), dict) else {}
    event = data_manager.events.get(_safe_int(document.get('eventId'), 0))
    salesperson_username = str(document.get('salespersonUsername') or '')
    created_by = str(document.get('createdBy') or '')
    return ' '.join((
        str(document.get('number') or ''),
        str(document.get('title') or document.get('projectName') or ''),
        str(document.get('reference') or ''),
        str((linked_invoice or {}).get('number') or ''),
        str(getattr(event, 'state', '') or ''),
        str(getattr(event, 'name', '') or ''),
        str(document.get('salesperson') or ''),
        _user_display_name(salesperson_username) if salesperson_username else '',
        created_by,
        _user_display_name(created_by) if created_by else '',
        str(client.get('name') or ''),
        str(client.get('company') or ''),
    )).lower()


def _finance_enrich_quotation_list_row(row, linked_invoice=None):
    row['invoiceId'] = str((linked_invoice or {}).get('id') or '')
    row['invoiceNumber'] = str((linked_invoice or {}).get('number') or '')
    event = data_manager.events.get(_safe_int(row.get('eventId'), 0))
    row['eventState'] = str(getattr(event, 'state', '') or '')
    row['eventName'] = str(getattr(event, 'name', '') or '')
    row['eventMissing'] = bool(row.get('eventId') and not event)
    return row


def _finance_list_or_create(document_type):
    with _finance_lock:
        finance_data = _load_finance_data()
        if document_type == 'quotation':
            _backfill_finance_clients(finance_data)
        if _finance_expire_sent_documents(finance_data):
            _save_finance_data(finance_data)
        if request.method == 'GET':
            query = str(request.args.get('query') or '').strip().lower()
            sort_by = str(request.args.get('sort') or 'updated').strip().lower()
            status_filters = {
                status
                for value in request.args.getlist('status')
                for status in str(value or '').lower().split(',')
                if status
            }
            allowed_statuses = (
                set(FINANCE_QUOTATION_STATUSES)
                if document_type == 'quotation'
                else set(FINANCE_INVOICE_STATUSES)
            )
            if status_filters and not status_filters.issubset(allowed_statuses):
                return jsonify({
                    'error': f'Invalid {document_type} status filter'
                }), 400
            summary_view = (
                str(request.args.get('view') or '').strip().lower() == 'summary'
            )
            mine_only = str(request.args.get('mine') or '').strip().lower() in {
                '1', 'true', 'yes', 'on',
            }
            linked_invoices = {}
            for document in finance_data.get('documents') or []:
                if document.get('type') != 'invoice':
                    continue
                quotation_id = str(document.get('sourceQuotationId') or '').strip()
                if quotation_id and _finance_user_can_access(document):
                    linked_invoices[quotation_id] = document

            source_rows = [
                row
                for row in finance_data.get('documents') or []
                if row.get('type') == document_type and _finance_user_can_access(row)
            ]
            if mine_only:
                current_username = _finance_current_username().lower()
                source_rows = [
                    row for row in source_rows
                    if _finance_document_owner_username(row).lower() == current_username
                ]
            if query:
                source_rows = [
                    row for row in source_rows
                    if query in _finance_list_search_text(
                        row,
                        linked_invoices.get(str(row.get('id') or '')),
                    )
                ]
            status_counts = {
                status: sum(
                    1 for row in source_rows
                    if str(row.get('status') or 'draft').strip().lower() == status
                )
                for status in allowed_statuses
            }
            status_total = sum(status_counts.values())
            if status_filters:
                source_rows = [
                    row for row in source_rows
                    if str(row.get('status') or 'draft').strip().lower() in status_filters
                ]
            if sort_by == 'number':
                source_rows.sort(
                    key=lambda row: (
                        str(row.get('number') or '').casefold(),
                        str(row.get('updatedAt') or ''),
                    ),
                    reverse=True,
                )
            else:
                source_rows.sort(
                    key=lambda row: (row.get('updatedAt', ''), row.get('number', '')),
                    reverse=True,
                )

            if summary_view:
                total = len(source_rows)
                offset = max(0, request.args.get('offset', type=int) or 0)
                requested_limit = request.args.get('limit', type=int)
                limit = min(max(1, requested_limit or 40), 100)
                page_rows = source_rows[offset:offset + limit]
                rows = [_finance_document_list_summary(row) for row in page_rows]
                if document_type == 'quotation':
                    for row in rows:
                        _finance_enrich_quotation_list_row(
                            row,
                            linked_invoices.get(str(row.get('id') or '')),
                        )
                next_offset = offset + len(rows)
                has_more = next_offset < total
                return jsonify({
                    'success': True,
                    'data': rows,
                    'meta': {
                        'view': 'summary',
                        'total': total,
                        'offset': offset,
                        'limit': limit,
                        'hasMore': has_more,
                        'nextOffset': next_offset if has_more else None,
                        'statusTotal': status_total,
                        'statusCounts': status_counts,
                    },
                })

            rows = [
                _normalise_finance_document(row, document_type, row)
                for row in source_rows
            ]
            if document_type == 'quotation':
                for row in rows:
                    _finance_enrich_quotation_list_row(
                        row,
                        linked_invoices.get(str(row.get('id') or '')),
                    )
            return jsonify({'success': True, 'data': rows})

        document = _normalise_finance_document(request.get_json() or {}, document_type)
        document['number'] = _next_finance_number(finance_data.get('documents') or [], document_type)
        if document_type == 'quotation':
            _prefix, year, sequence, revision = _finance_parse_number(document['number'])
            document['baseSequence'] = sequence
            document['revision'] = revision
            document['number'] = _finance_format_number(
                str(_load_pdf_settings().get('quotationPrefix') or 'QT').upper(),
                year,
                sequence,
                revision,
            )
            _sync_finance_client_record(document)
            _remember_finance_prices(finance_data, document)
        finance_data.setdefault('documents', []).append(document)
        _save_finance_data(finance_data)
        log_action(f"Created {document_type} {document['number']}")
        return jsonify({'success': True, 'data': document}), 201


def _finance_get_update_delete(document_id, document_type):
    with _finance_lock:
        finance_data = _load_finance_data()
        if _finance_expire_sent_documents(finance_data):
            _save_finance_data(finance_data)
        existing = _finance_find_document(finance_data, document_id, document_type)
        if not existing or not _finance_user_can_access(existing):
            return jsonify({'error': f'{document_type.title()} not found'}), 404
        if request.method == 'GET':
            return jsonify({'success': True, 'data': _normalise_finance_document(existing, document_type, existing)})
        if request.method == 'DELETE':
            if document_type == 'invoice':
                delete_data = request.get_json(silent=True) or {}
                if 'documentVersion' in delete_data and _safe_int(
                    delete_data.get('documentVersion'), 0
                ) != max(1, _safe_int(existing.get('documentVersion'), 1)):
                    return jsonify({
                        'error': 'This invoice changed while deletion was being confirmed. Review it before deleting it.',
                        'code': 'document_version_conflict',
                    }), 409
            finance_data['documents'] = [
                row for row in finance_data.get('documents') or []
                if str(row.get('id')) != str(document_id)
            ]
            if document_type == 'invoice':
                quotation_id = str(existing.get('sourceQuotationId') or '')
                stored_plan = (finance_data.get('invoicePlans') or {}).get(quotation_id)
                quotation = _finance_find_document(
                    finance_data, quotation_id, 'quotation'
                ) if quotation_id else None
                if isinstance(stored_plan, dict) and quotation:
                    plan = _normalise_invoice_plan(
                        stored_plan, quotation, stored_plan
                    )
                    for installment in plan.get('installments') or []:
                        if str(installment.get('invoiceId') or '') != str(document_id):
                            continue
                        installment.update({
                            'invoiceId': '',
                            'invoiceNumber': '',
                            'issuedAt': '',
                            'status': 'planned',
                        })
                    plan['payments'] = [
                        payment for payment in plan.get('payments') or []
                        if str(payment.get('invoiceId') or '') != str(document_id)
                    ]
                    plan['history'].append(_invoice_plan_history_entry(
                        'invoice-deleted',
                        f"Deleted invoice {existing.get('number') or document_id}",
                    ))
                    plan['summary'] = _invoice_plan_summary(
                        plan, (quotation.get('totals') or {}).get('total', 0)
                    )
                    plan['status'] = _invoice_plan_summary_status(plan)
                    plan['documentVersion'] = max(
                        1, _safe_int(plan.get('documentVersion'), 1)
                    ) + 1
                    plan['updatedAt'] = datetime.now().isoformat(
                        timespec='seconds'
                    )
                    plan['updatedBy'] = _finance_current_username()
                    finance_data['invoicePlans'][quotation_id] = plan
                    _invoice_plan_sync_documents(finance_data, plan, quotation)
            _save_finance_data(finance_data)
            log_action(f"Deleted {document_type} {existing.get('number', document_id)}")
            if document_type == 'invoice':
                mark_realtime_change('finance', {
                    'quotationId': str(existing.get('sourceQuotationId') or ''),
                    'invoiceId': document_id,
                    'action': 'invoice-deleted',
                })
            return jsonify({'success': True})

        request_data = request.get_json() or {}
        base_document = request_data.pop('_baseDocument', None)
        requested_subproject_deletions = request_data.pop(
            '_deletedSubprojectIds', []
        )
        current_document_version = max(
            1, _safe_int(existing.get('documentVersion'), 1)
        )
        if 'documentVersion' in request_data:
            expected_document_version = max(
                1, _safe_int(request_data.get('documentVersion'), 1)
            )
            if expected_document_version != current_document_version:
                can_merge = (
                    isinstance(base_document, dict)
                    and str(base_document.get('id') or '') == str(document_id)
                    and max(
                        1, _safe_int(base_document.get('documentVersion'), 1)
                    ) == expected_document_version
                )
                if can_merge:
                    try:
                        request_data = three_way_merge(
                            base_document,
                            request_data,
                            _normalise_finance_document(
                                existing, document_type, existing
                            ),
                        )
                        request_data['documentVersion'] = current_document_version
                    except FinanceMergeConflict:
                        can_merge = False
                if not can_merge:
                    return jsonify({
                        'error': f'This {document_type} was updated by another user',
                        'code': 'document_version_conflict',
                        'expectedVersion': expected_document_version,
                        'actualVersion': current_document_version,
                        'data': _normalise_finance_document(
                            existing, document_type, existing
                        ),
                    }), 409
        raw_requested_status = str(request_data.get('status') or '').strip().lower()
        if document_type == 'quotation' and raw_requested_status == 'declined':
            return jsonify({'error': 'Declined is no longer a quotation status'}), 400
        if (
            document_type == 'quotation'
            and raw_requested_status == 'expired'
            and str(existing.get('status') or '').strip().lower() != 'expired'
        ):
            return jsonify({'error': 'Expired status is set automatically'}), 400
        if document_type == 'invoice':
            existing_status = str(
                existing.get('status') or 'draft'
            ).strip().lower()
            if (
                existing_status in {'paid', 'void'}
                and raw_requested_status
                and raw_requested_status not in {existing_status, 'draft'}
            ):
                return jsonify({
                    'error': f"A {existing_status} invoice status cannot be changed"
                }), 409
            lifecycle_fields = {'status'}
            if existing_status == 'draft' and raw_requested_status == 'sent':
                lifecycle_fields.update({
                    'invoiceSentDate', 'sentDate', 'paymentTermDays',
                })
            changed_detail_fields = {
                key for key in request_data
                if key not in lifecycle_fields
                and key not in {'documentVersion', '_baseDocument'}
            }
            if (
                existing_status != 'draft'
                and raw_requested_status != 'draft'
                and changed_detail_fields
            ):
                return jsonify({
                    'error': 'Invoice details can only be edited while the invoice is a draft'
                }), 409
            if 'number' in request_data and not str(
                request_data.get('number') or ''
            ).strip():
                return jsonify({'error': 'Invoice number is required'}), 400
            if raw_requested_status == 'sent' and existing_status == 'draft':
                try:
                    request_data.update(_invoice_sent_timing(request_data))
                except ValueError as exc:
                    return jsonify({'error': str(exc)}), 400
        if document_type == 'quotation':
            try:
                _finance_validate_subproject_update(
                    request_data,
                    existing,
                    requested_subproject_deletions,
                )
            except FinanceSubprojectStructureConflict as exc:
                return jsonify({
                    'error': (
                        'An unsafe sub-project change was blocked. '
                        'The latest saved quotation has been kept.'
                    ),
                    'code': 'subproject_structure_conflict',
                    'reason': exc.reason,
                    'removedSubprojectIds': exc.removed_ids,
                    'data': _normalise_finance_document(
                        existing, document_type, existing
                    ),
                }), 409
        updated = _normalise_finance_document(request_data, document_type, existing)
        previous_document = _normalise_finance_document(
            existing,
            document_type,
            existing,
        )
        if any(
            str(row.get('id')) != str(document_id)
            and row.get('type') == document_type
            and (
                _finance_number_base(row.get('number'))
                == _finance_number_base(updated.get('number'))
                if document_type == 'quotation'
                else str(row.get('number') or '').strip().casefold()
                == str(updated.get('number') or '').strip().casefold()
            )
            for row in finance_data.get('documents') or []
            if isinstance(row, dict)
        ):
            return jsonify({'error': f'{document_type.title()} number is already in use'}), 409
        if document_type == 'quotation':
            # Optimistic concurrency metadata does not turn a status change
            # into a content edit requiring a new draft revision.
            status_workflow_fields = {'status', 'documentVersion'}
            if raw_requested_status == 'sent':
                status_workflow_fields.update({
                    'sentDate', 'validityAmount', 'validityUnit', 'validityDays',
                })
            elif raw_requested_status == 'invoiced':
                status_workflow_fields.update({
                    'invoiceSentDate', 'paymentTerms',
                    'paymentTermDays', 'paymentDueDate',
                })
            status_workflow_only = (
                raw_requested_status in FINANCE_QUOTATION_STATUSES
                and set(request_data).issubset(status_workflow_fields)
            )
            existing_normalised = previous_document
            automatic_draft_date_refresh = (
                request_data.get('_automaticDraftDateRefresh') is True
                and existing_normalised.get('status') == 'draft'
                and updated.get('status') == 'draft'
                and updated.get('quotationDate')
                == datetime.now().strftime('%Y-%m-%d')
                and _finance_document_update_fingerprint(
                    updated, {'quotationDate'}
                )
                == _finance_document_update_fingerprint(
                    existing_normalised, {'quotationDate'}
                )
            )
            missing_link_cleared = False
            if updated.get('eventId') and ('eventId' in request_data or str(request_data.get('status') or '').strip().lower() == 'accepted'):
                linked_event = data_manager.events.get(_safe_int(updated.get('eventId'), 0))
                if not linked_event:
                    _finance_clear_event_link(updated)
                    missing_link_cleared = True
                elif not _current_user_can_access_event(linked_event):
                    return jsonify({'error': 'You are not assigned to this event'}), 403
            if (
                not missing_link_cleared
                and not status_workflow_only
                and _finance_document_update_fingerprint(updated)
                == _finance_document_update_fingerprint(existing_normalised)
            ):
                return jsonify({
                    'success': True,
                    'data': existing_normalised,
                    'unchanged': True,
                })

            content_changed = (
                _finance_revision_fingerprint(updated)
                != _finance_revision_fingerprint(existing_normalised)
            )
            revision_locked = (
                existing_normalised.get('status') == 'sent'
                or _finance_revision_is_snapshotted(existing_normalised)
            )
            if content_changed and revision_locked and not status_workflow_only:
                if _safe_int(existing_normalised.get('revision'), 1) >= 99:
                    return jsonify({
                        'error': 'This quotation has reached the maximum of 99 revisions'
                    }), 409
                updated['revision'] = _safe_int(existing_normalised.get('revision'), 1) + 1
                if updated.get('customNumber'):
                    updated['number'] = _finance_number_with_revision(
                        updated.get('number'),
                        updated['revision'],
                    )
                else:
                    prefix, year, sequence, _revision = _finance_parse_number(
                        existing_normalised.get('number')
                    )
                    updated['number'] = _finance_format_number(
                        prefix,
                        year,
                        sequence,
                        updated['revision'],
                    )
                updated['status'] = 'draft'
                updated['sentAt'] = ''
                updated['quotationDate'] = datetime.now().strftime('%Y-%m-%d')

            requested_status = str(request_data.get('status') or '').strip().lower()
            # The linked costing is the canonical source for Plan demand. Keep it
            # current before any accepted quotation refreshes its managed event.
            _sync_costing_from_quotation(finance_data, updated)
            if requested_status == 'sent' and updated.get('status') == 'sent':
                sent_date_value = str(
                    request_data.get('sentDate')
                    or updated.get('sentAt')
                    or datetime.now().strftime('%Y-%m-%d')
                )[:10]
                try:
                    selected_sent_date = datetime.strptime(sent_date_value, '%Y-%m-%d').date()
                except ValueError:
                    return jsonify({'error': 'Enter a valid quotation sent date'}), 400
                now = datetime.now()
                sent_at = datetime.combine(selected_sent_date, now.time().replace(microsecond=0))
                updated['sentAt'] = sent_at.isoformat(timespec='seconds')
                updated['quotationDate'] = selected_sent_date.strftime('%Y-%m-%d')
                updated['statusChangedAt'] = updated['sentAt']
                updated['validUntil'] = (
                    sent_at + timedelta(days=max(1, _safe_int(updated.get('validityDays'), 30)))
                ).strftime('%Y-%m-%d')
                _finance_snapshot_revision(updated)
            elif requested_status == 'accepted' and updated.get('status') == 'accepted':
                export_error = _finance_export_error(updated)
                if export_error:
                    return jsonify({'error': export_error}), 400
                updated['acceptedAt'] = (
                    updated.get('acceptedAt')
                    if existing_normalised.get('status') == 'accepted' and updated.get('acceptedAt')
                    else datetime.now().isoformat(timespec='seconds')
                )
                updated['statusChangedAt'] = updated['acceptedAt']
                if (
                    existing_normalised.get('status') == 'draft'
                    and not _finance_revision_is_snapshotted(updated)
                ):
                    _finance_snapshot_revision(updated)
                if not missing_link_cleared:
                    _finance_create_event(updated, finance_data)
            elif requested_status == 'invoiced' and updated.get('status') == 'invoiced':
                invoice_sent_date = str(
                    request_data.get('invoiceSentDate')
                    or updated.get('invoiceSentDate')
                    or datetime.now().strftime('%Y-%m-%d')
                )[:10]
                try:
                    invoice_sent = datetime.strptime(invoice_sent_date, '%Y-%m-%d')
                except ValueError:
                    return jsonify({'error': 'Enter a valid invoice sent date'}), 400
                payment_terms = str(
                    request_data.get('paymentTerms')
                    if 'paymentTerms' in request_data
                    else updated.get('paymentTerms')
                    or _load_pdf_settings().get('defaultPaymentTerms', '30 Days')
                ).strip()[:300]
                payment_due_date, payment_term_days = _finance_payment_due_date(
                    invoice_sent_date,
                    payment_terms,
                )
                updated['paymentTerms'] = payment_terms
                updated['paymentTermDays'] = payment_term_days
                updated['invoiceSentDate'] = invoice_sent_date
                updated['paymentDueDate'] = payment_due_date
                updated['invoicedAt'] = invoice_sent.isoformat(timespec='seconds')
                updated['statusChangedAt'] = updated['invoicedAt']
            elif requested_status == 'paid' and updated.get('status') == 'paid':
                updated['paidAt'] = (
                    updated.get('paidAt')
                    if existing_normalised.get('status') == 'paid' and updated.get('paidAt')
                    else datetime.now().isoformat(timespec='seconds')
                )
                updated['statusChangedAt'] = updated['paidAt']
            elif requested_status in FINANCE_QUOTATION_STATUSES:
                updated['statusChangedAt'] = datetime.now().isoformat(timespec='seconds')
            elif updated.get('eventId') and not automatic_draft_date_refresh:
                _finance_sync_managed_event(updated, finance_data)
            _finance_update_revision_status(updated)
            if (
                updated.get('status') in {'draft', 'sent'}
                and updated.get('eventId')
                and not automatic_draft_date_refresh
            ):
                _finance_sync_managed_event(updated, finance_data)
            _sync_finance_client_record(updated, previous_document)
            if automatic_draft_date_refresh:
                updated['updatedAt'] = existing_normalised.get('updatedAt', '')
                updated['updatedBy'] = existing_normalised.get('updatedBy', '')
                if existing_normalised.get('updatedByName'):
                    updated['updatedByName'] = existing_normalised['updatedByName']
                else:
                    updated.pop('updatedByName', None)

        if document_type == 'invoice':
            if raw_requested_status == 'draft':
                updated.pop('invoiceSentSnapshot', None)
                updated['invoiceSentDate'] = ''
                updated['sentDate'] = ''
                updated['paymentDueDate'] = ''
                updated['paidAt'] = ''
                updated['statusChangedAt'] = datetime.now().isoformat(
                    timespec='seconds'
                )
            else:
                _ensure_invoice_sent_snapshot(updated)
        updated['documentVersion'] = current_document_version + 1
        for index, row in enumerate(finance_data.get('documents') or []):
            if str(row.get('id')) == str(document_id):
                finance_data['documents'][index] = updated
                break
        if document_type == 'invoice':
            quotation_id = str(updated.get('sourceQuotationId') or '')
            stored_plan = (finance_data.get('invoicePlans') or {}).get(quotation_id)
            quotation = _finance_find_document(
                finance_data, quotation_id, 'quotation'
            ) if quotation_id else None
            if isinstance(stored_plan, dict) and quotation:
                plan = _normalise_invoice_plan(
                    stored_plan, quotation, stored_plan
                )
                # The invoice plan owns the editable invoicing details. Keep a
                # reference edited from the issued-invoice directory in that
                # canonical record so the following document sync cannot
                # replace it with the previous value.
                if (
                    'reference' in request_data
                    and str(updated.get('status') or 'draft').strip().lower()
                    == 'draft'
                ):
                    plan.setdefault('invoiceDetails', {})['reference'] = str(
                        updated.get('reference') or ''
                    ).strip()[:300]
                returning_to_draft = (
                    str(existing.get('status') or 'draft').strip().lower()
                    != 'draft'
                    and str(updated.get('status') or '').strip().lower()
                    == 'draft'
                )
                if returning_to_draft:
                    plan['payments'] = [
                        payment for payment in plan.get('payments') or []
                        if str(payment.get('invoiceId') or '')
                        != str(document_id)
                    ]
                for installment in plan.get('installments') or []:
                    if str(installment.get('invoiceId') or '') != str(document_id):
                        continue
                    installment.update({
                        'label': (
                            updated.get('invoiceLabel')
                            if 'invoiceLabel' in updated
                            else installment.get('label')
                        ),
                        'dueDate': updated.get('dueDate') or '',
                        'status': updated.get('status') or 'draft',
                        'invoiceFrozen': isinstance(
                            updated.get('invoiceSentSnapshot'), dict
                        ),
                        'invoiceNumber': updated.get('number') or installment.get('invoiceNumber'),
                    })
                action_detail = (
                    f"Changed {existing.get('number') or document_id} status "
                    f"to {updated.get('status')}"
                    if str(existing.get('status') or 'draft')
                    != str(updated.get('status') or 'draft')
                    else f"Updated draft invoice {updated.get('number') or document_id}"
                )
                plan['history'].append(_invoice_plan_history_entry(
                    'invoice-updated', action_detail
                ))
                plan['summary'] = _invoice_plan_summary(
                    plan, (quotation.get('totals') or {}).get('total', 0)
                )
                plan['status'] = _invoice_plan_summary_status(plan)
                plan['documentVersion'] = max(
                    1, _safe_int(plan.get('documentVersion'), 1)
                ) + 1
                plan['updatedAt'] = datetime.now().isoformat(
                    timespec='seconds'
                )
                plan['updatedBy'] = _finance_current_username()
                finance_data.setdefault('invoicePlans', {})[quotation_id] = plan
                _invoice_plan_sync_documents(finance_data, plan, quotation)
        if document_type == 'quotation':
            _sync_costing_from_quotation(finance_data, updated)
            _finance_expire_sent_documents(finance_data, notify=False)
        if document_type == 'quotation':
            _remember_finance_prices(finance_data, updated, previous_document)
            _remember_invoice_payment_strategy(
                finance_data, updated.get('paymentTerms')
            )
        _save_finance_data(finance_data)
        updated = _finance_find_document(
            finance_data, document_id, document_type
        ) or updated
        if document_type == 'quotation':
            previous_status = str(existing_normalised.get('status') or 'draft')
            current_status = str(updated.get('status') or 'draft')
            linked_costing = _linked_costing_for_quotation(
                finance_data, updated
            )
            _queue_quotation_status_notification(
                manager=_current_data_manager_object(),
                quotation=updated,
                previous_status=previous_status,
                new_status=current_status,
                changed_by=_finance_current_username(),
            )
            previous_revision = _safe_int(existing_normalised.get('revision'), 1)
            current_revision = _safe_int(updated.get('revision'), 1)
            significant_changes = []
            if str(updated.get('number') or '') != str(existing_normalised.get('number') or ''):
                significant_changes.append(
                    f"number changed from {existing_normalised.get('number')} to {updated.get('number')}"
                )
            if current_revision != previous_revision:
                significant_changes.append(
                    f"created version {current_revision:02d} from version {previous_revision:02d}"
                )
            if current_status != previous_status:
                significant_changes.append(
                    f"status changed from {previous_status.title()} to {current_status.title()}"
                )
            if significant_changes:
                log_action(
                    f"Updated quotation {updated['number']}: "
                    f"{'; '.join(significant_changes)}"
                )
            mark_realtime_change('finance', {
                'action': 'quotation-updated',
                'quotationId': str(updated.get('id') or ''),
                'costingId': str((linked_costing or {}).get('id') or ''),
            })
        else:
            log_action(f"Updated {document_type} {updated['number']}")
            if document_type == 'invoice':
                mark_realtime_change('finance', {
                    'quotationId': str(updated.get('sourceQuotationId') or ''),
                    'invoiceId': document_id,
                    'action': 'invoice-updated',
                })
        return jsonify({'success': True, 'data': updated})


def _finance_catalog_price_book():
    """Read search pricing without hydrating every linked finance line."""
    manager = _current_data_manager_object()
    try:
        if manager is not None and hasattr(
            manager, 'load_company_document_with_version'
        ):
            stored, _storage_version = manager.load_company_document_with_version(
                'finance', None
            )
        elif manager is not None and hasattr(manager, 'load_company_document'):
            stored = manager.load_company_document('finance', None)
        else:
            filepath = _finance_path()
            if not os.path.isfile(filepath):
                return None
            with open(filepath, 'r', encoding='utf-8') as finance_file:
                stored = json.load(finance_file)
    except Exception:
        return None
    if not isinstance(stored, dict) or _safe_int(stored.get('version'), 0) < FINANCE_VERSION:
        # Older files still need the normal migration/backfill path.
        return None
    price_book = stored.get('priceBook')
    return copy.deepcopy(price_book) if isinstance(price_book, dict) else {}


@app.route('/api/finance/catalog', methods=['GET'])
@require_sales
def finance_catalog():
    query = str(request.args.get('query') or '').strip().lower()
    with _finance_lock:
        search_price_book = _finance_catalog_price_book()
        finance_data = (
            {'priceBook': search_price_book}
            if search_price_book is not None else _load_finance_data()
        )
        needs_price_backfill = any(
            isinstance(payload, dict)
            and str(stored_key or '').split('::', 1)[-1].casefold().startswith('custom:')
            and _safe_float(payload.get('unitPrice'), 0) <= 0
            and not payload.get('priceBackfillCheckedAt')
            for stored_key, payload in (finance_data.get('priceBook') or {}).items()
        )
        if needs_price_backfill and search_price_book is not None:
            finance_data = _load_finance_data()
        backfilled = (
            _finance_backfill_custom_product_prices(finance_data)
            if needs_price_backfill else 0
        )
        rate_card_rows = _finance_rate_card_rows(finance_data)
        removed = _finance_prune_unavailable_inventory_products(
            finance_data, rate_card_rows
        )
        if removed and search_price_book is not None:
            # Pruning is rare, but it must still persist through the validated
            # finance save path rather than writing a search-only projection.
            finance_data = _load_finance_data()
            rate_card_rows = _finance_rate_card_rows(finance_data)
            removed = _finance_prune_unavailable_inventory_products(
                finance_data, rate_card_rows
            )
        if removed or backfilled:
            _save_finance_data(finance_data)
            rate_card_rows = _finance_rate_card_rows(finance_data)
        price_book = finance_data.get('priceBook') or {}
        products_by_catalog_key = {
            str(row.get('catalogKey') or '').casefold(): row
            for row in rate_card_rows
            if str(row.get('catalogKey') or '').strip()
        }
        visible_catalog_keys = set(products_by_catalog_key)

    department_cache = {}

    def catalog_department(value, code_hint=''):
        cache_key = (str(value or ''), str(code_hint or ''))
        if cache_key not in department_cache:
            department_cache[cache_key] = _finance_department_details(value, code_hint)
        return department_cache[cache_key]

    query_tokens = query.split()

    def matches_query(*values):
        if not query_tokens:
            return True
        haystack = ' '.join(str(value or '') for value in values).casefold()
        return all(token in haystack for token in query_tokens)

    grouped = {}
    # The rate-card builder has already grouped inventory assets and applied
    # product overrides. Reusing those rows avoids scanning the full inventory
    # a second time for every quotation keystroke.
    for product in rate_card_rows:
        if product.get('isCustom') or product.get('isContainer'):
            continue
        key = str(product.get('catalogKey') or '').strip()
        if not key:
            continue
        brand = str(product.get('brand') or '').strip()
        model = str(product.get('model') or '').strip()
        description = str(product.get('description') or '').strip()
        display = ' '.join(value for value in (brand, model, description) if value)
        department = str(product.get('department') or 'General').strip() or 'General'
        department_code = str(product.get('departmentCode') or '').strip()
        product_label = str(product.get('productLabel') or display).strip()
        product_category = str(
            product.get('productCategory') or department
        ).strip() or department
        if not matches_query(
            brand, model, description, product_label, product_category,
            department, department_code, *(product.get('searchTags') or []),
        ):
            continue
        grouped[key] = {
            **product,
            'productId': str(product.get('productId') or key.lower()),
            'productKey': str(product.get('productKey') or key),
            'catalogKey': key,
            'description': display or model or description or 'Inventory item',
            'productLabel': product_label or display or model or description or 'Inventory item',
            'productCategory': product_category,
            'systemName': product_category,
            'isCustom': False,
        }

    for container in getattr(data_manager, 'containers', {}).values():
        container_id = str(getattr(container, 'container_id', '') or '').strip()
        if not container_id:
            continue
        container_key = f"container:{container_id.lower()}"
        if container_key not in visible_catalog_keys:
            continue
        serial_number = _container_serial_number(container)
        container_product = (
            products_by_catalog_key.get(container_key)
            or {}
        )
        container_product_label = str(
            container_product.get('productLabel') or f"Container {container_id}"
        )
        container_product_category = str(
            container_product.get('productCategory') or 'Container'
        ).strip() or 'Container'
        haystack_parts = [
            container_id, serial_number, container_product_label,
            container_product_category,
        ]
        if query_tokens and not matches_query(*haystack_parts):
            # Container searches match metadata or asset tags, not the child
            # description. Avoid expanding/pricing every nonmatching case.
            for asset_id in getattr(container, 'asset_ids', []) or []:
                asset = data_manager.inventory.get(asset_id)
                if asset and not _is_disposed(asset):
                    haystack_parts.extend(
                        normalize_asset_tags(getattr(asset, 'tags', []))
                    )
            for asset_id in _container_bulk_item_map(container):
                asset = data_manager.inventory.get(asset_id)
                if asset and not _is_disposed(asset):
                    haystack_parts.extend(
                        normalize_asset_tags(getattr(asset, 'tags', []))
                    )
            if not matches_query(*haystack_parts):
                continue
        container_items = {}
        for asset_id in getattr(container, 'asset_ids', []) or []:
            asset = data_manager.inventory.get(asset_id)
            if not asset or _is_disposed(asset):
                continue
            department_code = _normalise_department_code(getattr(asset, 'department_code', 'UN')) or 'UN'
            department, department_code = catalog_department(department_code, department_code)
            brand = str(getattr(asset, 'brand', '') or '').strip()
            model = str(getattr(asset, 'model_number', '') or '').strip()
            description = str(getattr(asset, 'description', '') or '').strip()
            display = _finance_display_description(brand, model, description) or model or description or asset_id
            catalog_key = _finance_catalog_key(
                department_code, brand, model, description
            )
            if catalog_key.casefold() not in visible_catalog_keys:
                continue
            item_product = products_by_catalog_key.get(catalog_key.casefold()) or {}
            item_product_category = str(
                item_product.get('productCategory') or department
            ).strip() or department
            key = _finance_container_item_key(catalog_key, description)
            if key not in container_items:
                container_items[key] = {
                    'catalogKey': catalog_key,
                    'containerItemKey': key,
                    'description': display or 'Container item',
                    'department': department,
                    'departmentCode': department_code,
                    'productCategory': item_product_category,
                    'systemName': item_product_category,
                    'brand': brand,
                    'model': model,
                    'availableQuantity': 0,
                    'sourceAssetIds': [],
                    'unitPrice': 0,
                    'uom': 'units',
                    'isCustom': False,
                    'containerId': container_id,
                    'containerSerial': serial_number,
                    'containerQuantity': 0,
                }
            container_items[key]['sourceAssetIds'].append(asset_id)
            quantity = _asset_inventory_quantity(asset)
            container_items[key]['availableQuantity'] += quantity
            container_items[key]['containerQuantity'] += quantity

        for asset_id, quantity in _container_bulk_item_map(container).items():
            asset = data_manager.inventory.get(asset_id)
            if not asset or _is_disposed(asset):
                continue
            department_code = _normalise_department_code(
                getattr(asset, 'department_code', 'UN')
            ) or 'UN'
            department, department_code = catalog_department(
                department_code,
                department_code,
            )
            brand = str(getattr(asset, 'brand', '') or '').strip()
            model = str(getattr(asset, 'model_number', '') or '').strip()
            description = str(getattr(asset, 'description', '') or '').strip()
            display = (
                _finance_display_description(brand, model, description)
                or model or description or 'Bulk item'
            )
            catalog_key = _finance_catalog_key(
                department_code, brand, model, description
            )
            if catalog_key.casefold() not in visible_catalog_keys:
                continue
            item_product = products_by_catalog_key.get(catalog_key.casefold()) or {}
            item_product_category = str(
                item_product.get('productCategory') or department
            ).strip() or department
            key = _finance_container_item_key(catalog_key, description)
            if key not in container_items:
                container_items[key] = {
                    'catalogKey': catalog_key,
                    'containerItemKey': key,
                    'description': display,
                    'department': department,
                    'departmentCode': department_code,
                    'productCategory': item_product_category,
                    'systemName': item_product_category,
                    'brand': brand,
                    'model': model,
                    'availableQuantity': 0,
                    'sourceAssetIds': [],
                    'unitPrice': 0,
                    'uom': 'units',
                    'isCustom': False,
                    'containerId': container_id,
                    'containerSerial': serial_number,
                    'containerQuantity': 0,
                }
            container_items[key]['sourceAssetIds'].append(asset_id)
            container_items[key]['availableQuantity'] += quantity
            container_items[key]['containerQuantity'] += quantity

        if not container_items:
            continue
        item_rows = sorted(
            container_items.values(),
            key=lambda row: (row['department'], row['description'].lower()),
        )
        for row in item_rows:
            remembered = _finance_remembered_price(
                price_book,
                row['catalogKey'],
                row['sourceAssetIds'],
            )
            row['unitPrice'] = _safe_float(remembered.get('unitPrice'), 0)
            row['uom'] = remembered.get('uom') if remembered.get('uom') in ('units', 'sets', 'pax', 'lot', 'sqm') else 'units'
        grouped[container_key] = {
            'productId': container_key,
            'productKey': f"container:{container_id}",
            'catalogKey': f"container:{container_id}",
            'description': f"Container {container_id}",
            'productLabel': container_product_label,
            'department': 'Container',
            'departmentCode': 'CONTAINER',
            'productCategory': container_product_category,
            'systemName': container_product_category,
            'brand': '',
            'model': '',
            'availableQuantity': sum(_safe_float(row.get('containerQuantity'), 0) for row in item_rows),
            'sourceAssetIds': [],
            'unitPrice': 0,
            'uom': 'units',
            'isCustom': False,
            'isContainer': True,
            'containerId': container_id,
            'containerSerial': serial_number,
            'containerItems': item_rows,
        }

    custom_seen = set()
    for source in rate_card_rows:
        if not source.get('isCustom'):
            continue
        description = str(source.get('description') or '').strip()
        if not description:
            continue
        department, department_code = catalog_department(
            source.get('department'),
            source.get('departmentCode'),
        )
        if not matches_query(
            source.get('brand'), source.get('model'), description,
            source.get('productLabel'), source.get('productCategory'),
            department,
        ):
            continue
        custom_key = _finance_custom_price_key(description)
        if custom_key in custom_seen:
            continue
        custom_seen.add(custom_key)
        grouped[f"rate-card:{custom_key}"] = {
            'productId': str(source.get('id') or custom_key).lower(),
            'productKey': str(source.get('productKey') or custom_key),
            'catalogKey': '',
            'description': description,
            'productLabel': str(source.get('productLabel') or description),
            'department': department,
            'departmentCode': department_code,
            'productCategory': str(
                source.get('productCategory') or department
            ).strip() or department,
            'systemName': str(
                source.get('productCategory') or department
            ).strip() or department,
            'brand': str(source.get('brand') or '').strip(),
            'model': str(source.get('model') or '').strip(),
            'availableQuantity': None,
            'sourceAssetIds': [],
            'unitPrice': _safe_float(source.get('unitPrice'), 0),
            'uom': source.get('uom') if source.get('uom') in ('units', 'sets', 'pax', 'lot', 'sqm') else 'units',
            'isCustom': True,
        }

    rows = sorted(
        grouped.values(),
        key=lambda row: (
            # Container names often contain the model they carry (for
            # example, "Esprite Case #01"). Keep actual products ahead of
            # those matches so the product is not buried or cut off by the
            # result limit.
            1 if row.get('isContainer') else 0,
            row['department'],
            row['description'].lower(),
        ),
    )[:30]
    for row in rows:
        if row.get('isCustom') or row.get('isContainer'):
            continue
        remembered = _finance_remembered_price(
            price_book,
            row['catalogKey'],
            row['sourceAssetIds'],
        )
        row['unitPrice'] = _safe_float(remembered.get('unitPrice'), 0)
        row['uom'] = remembered.get('uom') if remembered.get('uom') in ('units', 'sets', 'pax', 'lot', 'sqm') else 'units'
        row['productLabel'] = str(
            remembered.get('productLabel') or row.get('productLabel')
            or row.get('description') or ''
        )
        row['productCategory'] = str(
            remembered.get('productCategory') or row.get('productCategory')
            or row.get('department') or 'General'
        ).strip() or 'General'
        row['systemName'] = row['productCategory']
    return jsonify({'success': True, 'data': rows})


@app.route('/api/finance/products', methods=['GET', 'POST', 'DELETE'])
@app.route('/api/finance/rate-card', methods=['GET', 'POST', 'DELETE'])
@require_client_access
def finance_rate_card():
    with _finance_lock:
        finance_data = _load_finance_data()
        backfilled = _finance_backfill_custom_product_prices(finance_data)
        rows = _finance_rate_card_rows(finance_data)
        if (
            _finance_prune_unavailable_inventory_products(finance_data, rows)
            or backfilled
        ):
            _save_finance_data(finance_data)
        if request.method == 'GET':
            query = str(request.args.get('query') or '').strip().casefold()
            if query:
                rows = [
                    row for row in rows
                    if query in ' '.join((
                        str(row.get('productCategory') or ''),
                        str(row.get('department') or ''),
                        str(row.get('brand') or ''),
                        str(row.get('model') or ''),
                        str(row.get('description') or ''),
                        str(row.get('productLabel') or ''),
                        ' '.join(normalize_asset_tags(row.get('searchTags') or [])),
                    )).casefold()
                ]
            return jsonify({'success': True, 'data': rows})

        payload = request.get_json(silent=True) or {}
        description = str(payload.get('description') or '').strip()[:1000]
        product_label = str(
            payload.get('productLabel') or payload.get('label') or description
        ).strip()[:1000]
        product_category = str(
            payload.get('productCategory') or payload.get('systemName')
            or payload.get('department')
            or 'Unknown Department'
        ).strip()[:240] or 'Unknown Department'
        department, department_code = _finance_department_details(
            payload.get('department'), payload.get('departmentCode')
        )
        catalog_key = str(
            payload.get('catalogKey') or payload.get('productKey') or ''
        ).strip()[:500]
        if not catalog_key:
            catalog_key = _finance_custom_price_key(description)
        matched_assets = []
        if payload.get('brand') and payload.get('model'):
            target_department = _normalise_department_code(
                payload.get('departmentCode') or payload.get('department')
            )
            target_brand = str(payload.get('brand') or '').strip().casefold()
            target_model = str(payload.get('model') or '').strip().casefold()
            matched_assets = [
                (asset_id, asset)
                for asset_id, asset in (data_manager.inventory.items() if data_manager else [])
                if asset and not _is_disposed(asset)
                and _normalise_department_code(getattr(asset, 'department_code', '')) == target_department
                and str(getattr(asset, 'brand', '') or '').strip().casefold() == target_brand
                and str(getattr(asset, 'model_number', '') or '').strip().casefold() == target_model
            ]
        if matched_assets:
            _, canonical_asset = matched_assets[0]
            canonical_department, canonical_department_code = _finance_department_details(
                getattr(canonical_asset, 'department_code', ''),
                getattr(canonical_asset, 'department_code', ''),
            )
            payload = {
                **payload,
                'brand': str(getattr(canonical_asset, 'brand', '') or '').strip(),
                'model': str(getattr(canonical_asset, 'model_number', '') or '').strip(),
                'description': str(getattr(canonical_asset, 'description', '') or '').strip(),
                'department': canonical_department,
                'departmentCode': canonical_department_code,
                'sourceAssetIds': [str(asset_id) for asset_id, _ in matched_assets],
            }
            description = payload['description']
            catalog_key = _finance_catalog_key(
                canonical_department_code,
                payload['brand'],
                payload['model'],
                description,
            )
        if not description and not matched_assets:
            return jsonify({'error': 'Description is required'}), 400
        owner = _finance_current_username().lower()
        price_book = finance_data.setdefault('priceBook', {})
        # Products are company-wide. Legacy remembered rates retain their old
        # per-user keys, while every explicit Products edit uses this namespace.
        owner_prefix = 'product::'
        target_key = f'{owner_prefix}{catalog_key}'
        source_asset_ids = {
            str(asset_id).strip().lower()
            for asset_id in (payload.get('sourceAssetIds') or [])
            if str(asset_id or '').strip()
        }

        if request.method == 'DELETE':
            for stored_key in list(price_book):
                base_key = str(stored_key).split('::', 1)[-1].casefold()
                if base_key == catalog_key.casefold() or (
                    base_key.startswith('asset:')
                    and base_key.rsplit(':', 1)[-1] in source_asset_ids
                ):
                    price_book.pop(stored_key, None)
            price_book[target_key] = {
                'deleted': True,
                'description': description,
                'productLabel': product_label,
                'productCategory': product_category,
                'department': str(payload.get('department') or 'Unknown Department').strip(),
                'departmentCode': str(payload.get('departmentCode') or '').strip(),
                'brand': str(payload.get('brand') or '').strip()[:240],
                'model': str(payload.get('model') or '').strip()[:240],
                'owner': owner,
                'updatedAt': datetime.now().isoformat(timespec='seconds'),
            }
            _save_finance_data(finance_data)
            rows = _finance_rate_card_rows(finance_data)
            action = f"Deleted rate card item {description}"
        else:
            unit_price = round(max(0, _safe_float(payload.get('unitPrice'), 0)), 2)
            uom = str(payload.get('uom') or 'units').strip().lower()
            if uom not in {'units', 'sets', 'pax', 'lot', 'sqm'}:
                uom = 'units'
            department, department_code = _finance_department_details(
                payload.get('department'), payload.get('departmentCode')
            )
            stored = {
                'description': description,
                'productLabel': product_label or description,
                'productCategory': product_category,
                'department': department,
                'departmentCode': department_code,
                'brand': str(payload.get('brand') or '').strip()[:240],
                'model': str(payload.get('model') or '').strip()[:240],
                'unitPrice': unit_price,
                'uom': uom,
                'owner': owner,
                'updatedAt': datetime.now().isoformat(timespec='seconds'),
            }
            for stored_key in list(price_book):
                if str(stored_key).split('::', 1)[-1].casefold() == catalog_key.casefold():
                    price_book.pop(stored_key, None)
            price_book[target_key] = stored
            for asset_id in source_asset_ids:
                price_book[f'{owner_prefix}asset:{asset_id}'] = stored
            _save_finance_data(finance_data)
            rows = _finance_rate_card_rows(finance_data)
            action = f"Updated rate card item {description}"

    log_action(action)
    return jsonify({'success': True, 'data': rows})


@app.route('/api/finance/products/category', methods=['DELETE', 'PATCH'])
@require_client_access
def finance_delete_product_category():
    payload = request.get_json(silent=True) or {}
    category = str(payload.get('category') or '').strip()[:240]
    if not category:
        return jsonify({'error': 'Category is required'}), 400

    with _finance_lock:
        finance_data = _load_finance_data()
        all_rows = _finance_rate_card_rows(finance_data)
        targets = [
            row for row in all_rows
            if str(
                row.get('productCategory') or row.get('department') or ''
            ).strip().casefold() == category.casefold()
        ]
        if not targets:
            return jsonify({'error': 'Product category not found'}), 404

        if request.method == 'PATCH':
            new_category = str(
                payload.get('newCategory') or payload.get('name') or ''
            ).strip()[:240]
            if not new_category:
                return jsonify({'error': 'New category name is required'}), 400
            if new_category.casefold() == category.casefold():
                return jsonify({'success': True, 'data': all_rows, 'merged': False})

            existing_categories = {
                str(
                    row.get('productCategory') or row.get('department') or ''
                ).strip().casefold()
                for row in all_rows
            }
            merged = new_category.casefold() in existing_categories
            price_book = finance_data.setdefault('priceBook', {})
            category_mappings = _finance_product_category_mappings(finance_data)
            now = datetime.now().isoformat(timespec='seconds')

            # Move explicit product overrides and custom products together.
            for stored_key, stored in price_book.items():
                if not isinstance(stored, dict):
                    continue
                if str(stored.get('productCategory') or '').strip().casefold() == category.casefold():
                    stored['productCategory'] = new_category
                    stored['updatedAt'] = now

            # A mapping is kept per inventory department so newly added assets
            # inherit the renamed category without rewriting inventory data.
            mapped_codes = set()
            for row in targets:
                if row.get('isCustom') or row.get('isContainer'):
                    continue
                department_code = _normalise_department_code(
                    row.get('departmentCode') or row.get('department')
                )
                if not department_code or department_code in mapped_codes:
                    continue
                effective_default = category_mappings.get(
                    department_code,
                    str(row.get('department') or '').strip(),
                )
                if effective_default.casefold() != category.casefold():
                    continue
                mapped_codes.add(department_code)
                price_book[f'product-category:{department_code.lower()}'] = {
                    'departmentCode': department_code,
                    'productCategory': new_category,
                    'updatedAt': now,
                    'updatedBy': _finance_current_username(),
                }

            _save_finance_data(finance_data)
            rows = _finance_rate_card_rows(finance_data)
            log_action(
                f"Renamed product category {category} to {new_category}"
            )
            return jsonify({
                'success': True,
                'data': rows,
                'renamedCount': len(targets),
                'merged': merged,
            })

        deletable = [row for row in targets if row.get('isCustom')]
        retained_count = len(targets) - len(deletable)
        if not deletable:
            return jsonify({
                'error': 'Inventory products cannot be deleted',
            }), 409

        owner = _finance_current_username().lower()
        price_book = finance_data.setdefault('priceBook', {})
        now = datetime.now().isoformat(timespec='seconds')
        for row in deletable:
            product_key = str(
                row.get('productKey') or row.get('catalogKey')
                or _finance_custom_price_key(row.get('description'))
            ).strip()[:500]
            source_asset_ids = {
                str(asset_id).strip().casefold()
                for asset_id in (row.get('sourceAssetIds') or [])
                if str(asset_id or '').strip()
            }
            for stored_key in list(price_book):
                base_key = str(stored_key).split('::', 1)[-1].casefold()
                if base_key == product_key.casefold() or (
                    base_key.startswith('asset:')
                    and base_key.rsplit(':', 1)[-1] in source_asset_ids
                ):
                    price_book.pop(stored_key, None)
            price_book[f'product::{product_key}'] = {
                'hidden': True,
                'description': str(row.get('description') or '').strip()[:1000],
                'productLabel': str(
                    row.get('productLabel') or row.get('description') or ''
                ).strip()[:1000],
                'productCategory': category,
                'department': str(
                    row.get('department') or 'Unknown Department'
                ).strip(),
                'departmentCode': str(row.get('departmentCode') or '').strip(),
                'brand': str(row.get('brand') or '').strip()[:240],
                'model': str(row.get('model') or '').strip()[:240],
                'owner': owner,
                'updatedAt': now,
            }

        _save_finance_data(finance_data)
        rows = _finance_rate_card_rows(finance_data)

    log_action(
        f"Deleted product category {category} ({len(deletable)} added products)"
    )
    return jsonify({
        'success': True,
        'data': rows,
        'deletedCount': len(deletable),
        'retainedInventoryCount': retained_count,
    })


