@app.route('/api/finance/compare/<int:event_id>/add-to-event', methods=['POST'])
@require_admin
@with_prepare_action_lock
def finance_compare_add_to_event(event_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()
    payload = request.get_json(silent=True) or {}
    quotation_id = str(payload.get('quotationId') or '').strip()
    row_keys = [
        str(key or '').strip()
        for key in (payload.get('keys') or [payload.get('key')])
        if str(key or '').strip()
    ]
    if not row_keys:
        return jsonify({'error': 'At least one comparison row is required'}), 400
    view_id = str(payload.get('viewId') or 'all').strip() or 'all'
    with _finance_lock:
        finance_data = _load_finance_data()
        quotation = _finance_find_document(finance_data, quotation_id, 'quotation')
        if not quotation or not _finance_compare_can_read_quotation(quotation, event_id):
            return jsonify({'error': 'Quotation not found'}), 404
        normalised = _normalise_finance_document(quotation, 'quotation', quotation)
        scope = _finance_compare_subproject_scope(event, normalised, view_id)
        rows, _counts, _quote_items, _event_items = _finance_compare_rows(
            event,
            normalised,
            scope.get('quoteSubprojectId') if scope else _FINANCE_COMPARE_ALL_SUBPROJECTS,
            scope.get('eventSubprojectId') if scope else _FINANCE_COMPARE_ALL_SUBPROJECTS,
        )
        rows_by_key = {row.get('key'): row for row in rows}
        selected_rows = []
        for row_key in dict.fromkeys(row_keys):
            row = rows_by_key.get(row_key)
            if not row:
                return jsonify({'error': 'Comparison row not found'}), 404
            selected_rows.append(row)
        try:
            target_subproject_id = _finance_compare_ensure_event_subproject(
                event, scope
            )
            for row in selected_rows:
                _finance_compare_add_to_event(
                    event,
                    row,
                    target_subproject_id,
                )
        except ValueError as exc:
            return jsonify({'error': str(exc)}), 400
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        refreshed = _finance_compare_payload(event, finance_data, quotation_id)
    item_count = len(selected_rows)
    log_action(
        f"Added {item_count} quotation item{'s' if item_count != 1 else ''} "
        f"to event {event_id} from compare"
    )
    mark_realtime_change('event-assets', {'eventId': event_id, 'action': 'compare-add-to-event'})
    return jsonify({'success': True, 'data': refreshed})


@app.route('/api/finance/compare/<int:event_id>/remove-extra', methods=['POST'])
@require_admin
@with_prepare_action_lock
def finance_compare_remove_extra(event_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()
    payload = request.get_json(silent=True) or {}
    quotation_id = str(payload.get('quotationId') or '').strip()
    row_keys = [
        str(key or '').strip()
        for key in (payload.get('keys') or [payload.get('key')])
        if str(key or '').strip()
    ]
    if not row_keys:
        return jsonify({'error': 'At least one comparison row is required'}), 400
    view_id = str(payload.get('viewId') or 'all').strip() or 'all'
    with _finance_lock:
        finance_data = _load_finance_data()
        quotation = _finance_find_document(finance_data, quotation_id, 'quotation') if quotation_id else None
        if quotation_id and (not quotation or not _finance_compare_can_read_quotation(quotation, event_id)):
            return jsonify({'error': 'Quotation not found'}), 404
        normalised = _normalise_finance_document(quotation, 'quotation', quotation) if quotation else {}
        scope = _finance_compare_subproject_scope(event, normalised, view_id)
        rows, _counts, _quote_items, _event_items = _finance_compare_rows(
            event,
            normalised,
            scope.get('quoteSubprojectId') if scope else _FINANCE_COMPARE_ALL_SUBPROJECTS,
            scope.get('eventSubprojectId') if scope else _FINANCE_COMPARE_ALL_SUBPROJECTS,
        )
        rows_by_key = {row.get('key'): row for row in rows}
        selected_rows = []
        for row_key in dict.fromkeys(row_keys):
            row = rows_by_key.get(row_key)
            if not row:
                return jsonify({'error': 'Comparison row not found'}), 404
            event_item = row.get('eventItem') or {}
            quote_item = row.get('quotationItem') or {}
            event_qty = max(0, _safe_int(event_item.get('quantity'), 0))
            quote_qty = max(0, _safe_int(quote_item.get('quantity'), 0))
            if event_qty <= quote_qty:
                return jsonify({'error': 'There is no extra event quantity to remove'}), 400
            selected_rows.append(row)
        for row in selected_rows:
            event_item = row.get('eventItem') or {}
            quote_item = row.get('quotationItem') or {}
            quote_qty = max(0, _safe_int(quote_item.get('quantity'), 0))
            identity = event_item.get('identity') or quote_item.get('identity') or {}
            _finance_compare_set_event_quantity(
                event,
                identity,
                quote_qty,
                quote_item if quote_qty else event_item,
                scope.get('eventSubprojectId') if scope else None,
            )
        update_event_state(event)
        data_manager.save_event(event)
        invalidate_cache()
        refreshed = _finance_compare_payload(event, finance_data, quotation_id)
    item_count = len(selected_rows)
    log_action(
        f"Removed {item_count} extra event item{'s' if item_count != 1 else ''} "
        f"from event {event_id} via compare"
    )
    mark_realtime_change('event-assets', {'eventId': event_id, 'action': 'compare-remove-extra'})
    return jsonify({'success': True, 'data': refreshed})


@app.route('/api/finance/compare/<int:event_id>/add-to-quotation', methods=['POST'])
@require_admin
def finance_compare_add_to_quotation(event_id):
    if not _current_user_has_sales_access():
        return jsonify({'error': 'Sales access required'}), 403
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()
    payload = request.get_json(silent=True) or {}
    quotation_id = str(payload.get('quotationId') or '').strip()
    view_id = str(payload.get('viewId') or 'all').strip() or 'all'
    row_keys = [
        str(key or '').strip()
        for key in (payload.get('keys') or [payload.get('key')])
        if str(key or '').strip()
    ]
    if not row_keys:
        return jsonify({'error': 'At least one comparison row is required'}), 400
    with _finance_lock:
        finance_data = _load_finance_data()
        quotation = _finance_find_document(finance_data, quotation_id, 'quotation')
        if not quotation or not _finance_compare_can_read_quotation(quotation, event_id):
            return jsonify({'error': 'Quotation not found'}), 404
        if not _finance_user_can_access(quotation):
            return jsonify({'error': 'Quotation access required'}), 403
        normalised = _normalise_finance_document(quotation, 'quotation', quotation)
        previous = copy.deepcopy(normalised)
        scope = _finance_compare_subproject_scope(event, normalised, view_id)
        if view_id != 'all' and not scope:
            return jsonify({'error': 'Comparison sub-project not found'}), 404
        rows, _counts, _quote_items, _event_items = _finance_compare_rows(
            event,
            normalised,
            scope.get('quoteSubprojectId') if scope else _FINANCE_COMPARE_ALL_SUBPROJECTS,
            scope.get('eventSubprojectId') if scope else _FINANCE_COMPARE_ALL_SUBPROJECTS,
        )
        rows_by_key = {row.get('key'): row for row in rows}
        selected_rows = []
        for row_key in dict.fromkeys(row_keys):
            row = rows_by_key.get(row_key)
            if not row:
                return jsonify({'error': 'Comparison row not found'}), 404
            selected_rows.append(row)
        try:
            for row in selected_rows:
                _finance_compare_apply_to_quotation(
                    finance_data,
                    normalised,
                    event,
                    row,
                    scope.get('quoteSubprojectId') if scope and scope.get('eventSubprojectId') else None,
                )
        except ValueError as exc:
            return jsonify({'error': str(exc)}), 400
        updated = _normalise_finance_document(normalised, 'quotation', normalised)
        _remember_finance_prices(finance_data, updated, previous)
        for index, document in enumerate(finance_data.get('documents') or []):
            if str(document.get('id')) == str(updated.get('id')):
                finance_data['documents'][index] = updated
                break
        else:
            return jsonify({'error': 'Quotation not found'}), 404
        _sync_costing_from_quotation(finance_data, updated)
        _save_finance_data(finance_data)
        refreshed = _finance_compare_payload(event, finance_data, updated.get('id'))
    item_count = len(selected_rows)
    log_action(
        f"Added {item_count} event item{'s' if item_count != 1 else ''} "
        f"to quotation {updated.get('number')} from compare for event {event_id}"
    )
    mark_realtime_change('finance', {'eventId': event_id, 'quotationId': updated.get('id'), 'action': 'compare-add-to-quotation'})
    return jsonify({'success': True, 'data': refreshed, 'quotation': updated})


@app.route('/api/finance/departments', methods=['GET'])
@require_client_access
def finance_departments():
    query = str(request.args.get('query') or '').strip().lower()
    values = []
    for row in _load_departments().values():
        if not _is_selectable_company_department(
            row.get('code'), row.get('name')
        ):
            continue
        name, _code = _finance_department_details(row.get('name'), row.get('code'))
        name = _finance_system_name(name)
        if name not in values:
            values.append(name)
    for value in FINANCE_DEFAULT_DEPARTMENTS:
        if value not in values:
            values.append(value)
    with _finance_lock:
        for document in _load_finance_data().get('documents') or []:
            if document.get('type') != 'quotation' or not _finance_user_can_access(document):
                continue
            for line in document.get('lineItems') or []:
                name = _finance_system_name(
                    (line or {}).get('department'),
                    (line or {}).get('systemName'),
                )
                if _is_selectable_company_department(name) and name not in values:
                    values.append(name)
    if query:
        values = [value for value in values if query in value.lower()]
    return jsonify({'success': True, 'data': values[:30]})


@app.route('/api/finance/salespeople', methods=['GET'])
@require_sales
def finance_salespeople():
    current_company = _normalise_company_code(
        _current_company_code(), DEFAULT_COMPANY_CODE
    )
    rows = []
    for user in data_manager.users.values():
        if not getattr(user, 'is_active', True):
            continue
        if _owner_identity_is_hidden(user.username):
            continue
        if _normalise_company_code(
            _user_assigned_company_code(user.username), DEFAULT_COMPANY_CODE
        ) != current_company:
            continue
        rows.append({
            'username': user.username,
            'name': getattr(user, 'name', '') or user.username,
            'phone': getattr(user, 'phone', '') or '',
        })
    rows.sort(key=lambda row: (row['name'].casefold(), row['username'].casefold()))
    return jsonify({'success': True, 'data': rows})


def _finance_reassign_document_salesperson(document_id, document_type):
    payload = request.get_json(silent=True) or {}
    salesperson = str(payload.get('salesperson') or '').strip()[:160]
    salesperson_username = str(
        payload.get('salespersonUsername') or ''
    ).strip()[:160]
    if not salesperson:
        return jsonify({'error': 'Choose a salesperson'}), 400

    current_company = _normalise_company_code(
        _current_company_code(), DEFAULT_COMPANY_CODE
    )
    eligible_users = [
        user for user in data_manager.users.values()
        if getattr(user, 'is_active', True)
        and not _owner_identity_is_hidden(user.username)
        and _normalise_company_code(
            _user_assigned_company_code(user.username),
            DEFAULT_COMPANY_CODE,
        ) == current_company
    ]
    if salesperson_username:
        selected_user = next((
            user for user in eligible_users
            if str(user.username).casefold() == salesperson_username.casefold()
        ), None)
    else:
        salesperson_key = salesperson.casefold()
        matches = [
            user for user in eligible_users
            if salesperson_key in {
                str(user.username or '').strip().casefold(),
                str(getattr(user, 'name', '') or '').strip().casefold(),
            }
        ]
        selected_user = matches[0] if len(matches) == 1 else None
    if not selected_user:
        return jsonify({'error': 'Choose an active user in this company'}), 400
    salesperson_username = str(selected_user.username).strip()[:160]
    salesperson = str(
        getattr(selected_user, 'name', '') or selected_user.username
    ).strip()[:160]

    with _finance_lock:
        finance_data = _load_finance_data()
        stored = _finance_find_document(
            finance_data, document_id, document_type
        )
        if not stored or not _finance_user_can_access(stored):
            return jsonify({
                'error': f'{document_type.title()} not found'
            }), 404

        if document_type == 'costing':
            primary = _normalise_costing_document(stored, stored)
            linked = _linked_quotation_for_costing(finance_data, primary)
            linked_type = 'quotation'
        else:
            primary = _normalise_finance_document(
                stored, 'quotation', stored
            )
            linked = _linked_costing_for_quotation(finance_data, primary)
            linked_type = 'costing'

        now = datetime.now().isoformat(timespec='seconds')
        username = _finance_current_username()

        def update_owner(document, kind):
            if not document:
                return None
            if kind == 'costing':
                updated = _normalise_costing_document(document, document)
            else:
                updated = _normalise_finance_document(
                    document, 'quotation', document
                )
            updated['salesperson'] = salesperson
            updated['salespersonUsername'] = salesperson_username
            updated['documentVersion'] = max(
                1, _safe_int(updated.get('documentVersion'), 1)
            ) + 1
            updated['updatedAt'] = now
            updated['updatedBy'] = username
            for index, row in enumerate(finance_data.get('documents') or []):
                if str(row.get('id') or '') == str(updated.get('id') or ''):
                    finance_data['documents'][index] = updated
                    break
            return updated

        primary = update_owner(primary, document_type)
        linked = update_owner(linked, linked_type)
        quotation = primary if document_type == 'quotation' else linked
        costing = primary if document_type == 'costing' else linked
        if quotation and quotation.get('eventId'):
            _finance_sync_managed_event(quotation, finance_data)
        _save_finance_data(finance_data)

    mark_realtime_change('finance', {
        'action': 'salesperson-updated',
        'quotationId': str((quotation or {}).get('id') or ''),
        'costingId': str((costing or {}).get('id') or ''),
    })
    log_action(
        f"Changed salesperson for {document_type} {document_id} to "
        f"{salesperson}"
    )
    return jsonify({
        'success': True,
        'data': primary,
        'quotationId': str((quotation or {}).get('id') or ''),
        'costingId': str((costing or {}).get('id') or ''),
    })


